-- English texts of the regional pack kalimdor_orgrimmar (#102). The rules are in AzerothUnspoken_Kalimdor/Orgrimmar.lua.
local AU = AzerothUnspoken

AU:RegisterRegionalTexts("durotar", "enUS", "kalimdor_orgrimmar", [==[
	["org.dawn.01"] = {
		"watches the first light of dawn spill over the canyon rim and run down the red stone.",
		"hears the first hammers of the day start up as the sky over the canyon pales into dawn.",
		"stands still while the dawn reaches the spikes on the walls one by one, as if counting them.",
	},
	["org.dusk.01"] = {
		"Dusk fills the canyon first; the sky above stays bright long after the streets go red with torch fire.",
		"The torch fires go up along the walls as the light drains out of the valley at dusk.",
		"Dusk in Orgrimmar: the forge fires glow brighter, the voices go lower.",
	},
	["org.dusk.02"] = {
		"Dusk, and the day's done. Somebody point me at food.",
		"Sun's going down behind the walls. Good. Time to find a fire and a bowl while the dusk lasts.",
		"Dusk already? I've haggled away the whole day.",
	},
	["org.farewell.01"] = {
		"Mind the spikes on the way out.",
		"Off I go. Keep the forges hot.",
		"Until the city drags me in once more.",
	},
	["org.farewell.02"] = {
		"May the walls stand till our roads cross again.",
		"Go well. The canyon will be here at the end of the road.",
		"Safe roads beyond the gate.",
	},
	["org.greet.01"] = {
		"Good to see a friendly face inside these walls.",
		"Hail! Strong walls, and stronger company.",
		"Greetings. Let's find some shade, if there's any to be had.",
	},
	["org.greet.02"] = {
		"Well met beneath the banners of the Horde.",
		"Greetings, between these red walls and under these banners.",
		"May the road that brought you here have been short, and your stay be long.",
	},
	["org.jest.01"] = {
		"In Orgrimmar even the furniture has spikes. I sat down once. Once.",
		"How do you find a goblin in the Drag? Say the word discount.",
		"The grunts don't laugh at jokes. I've tested this. At length.",
	},
	["org.journey.arrival.01"] = {
		"slides down from the wind rider at the tower, legs stiff from the flight, and shakes the dust off over the Valley of Strength.",
		"lands at the flight tower with dust in both eyes and the city's noise rising to meet the landing.",
		"steps off the wind rider's back in a puff of dust and pats its neck, not too close to the teeth.",
	},
	["org.journey.arrival.02"] = {
		"Wind riders are fine beasts, but my legs prefer the earth of home after a flight.",
		"Down at last on solid earth. From up there the city looked like a crack in red rock; down here it smells of supper.",
		"The tower, the drums, the crowd below, solid earth underfoot. Landed, and glad of it.",
	},
	["org.journey.start.01"] = {
		"Up we go. Don't drop me over the cactus.",
		"Hold steady, beast. I've paid for the whole flight.",
		"So long, Orgrimmar. Keep the noise up till I'm home.",
	},
	["org.levelup.01"] = {
		"Another step up. Time to visit my trainer before the feeling wears off.",
		"A little stronger, and in the right city to show it. The trainers will be pleased, or at least less disappointed.",
		"The canyon walls do not change, but I do. One more mark scratched on the long climb.",
	},
	["org.lore.drag.song.01"] = {
		"A hawker's song from the Drag, sung over the hammering:\nLeather, iron, salt and string,\nall a wanderer could need;\nhaggle if you like, my friend:\nI can haggle twice your speed.",
		"A stall-keeper in the Drag sings this one at passing grunts:\nBuy a blade and buy a belt,\nbuy a buckle, buy a strap;\nif your purse is feeling light,\nI will gladly take the scrap.",
	},
	["org.lore.honor.formula.01"] = {
		"Barked by the trainers in the Valley of Honor, loud enough to carry:\nKeep low the shield and high the eye;\nlet louder fools go rushing by.\nThe patient blade will find the seam\nwhile braggarts still are building steam.",
		"What the recruits shout back across the yard, when the trainers ask:\nA dummy never hits you back,\nthen find the gap, then find the knack;\nthe foe outside is not so kind:\nso keep the lesson in your mind.",
	},
	["org.muse.alliance.01"] = {
		"Every eye here could raise the alarm. I keep walking as if I belong, and hope nobody asks.",
		"Haggling sounds the same in any language, even one I can't follow. I keep an eye on the hands, not the words.",
		"Smoke, iron, hide. Under the noise it's just a city, and I'm the only one here with an eye on every exit.",
	},
	["org.muse.canyon.01"] = {
		"Look up and there is only a strip of sky. The rest is stone.",
		"The wind finds its way down into the canyon, but it arrives tired, and the sky above is just a ribbon between red stone.",
		"The canyon holds the city in a red cupped hand of stone, with a little sky poured on top. It is easy to feel small here, and safe anyway.",
	},
	["org.muse.dawn.01"] = {
		"Dawn on the canyon rim, and the first hammers already going below.",
		"The first wolves led out, the first stalls unshuttered. At dawn the city yawns and stretches.",
		"Early light, cold stone, the smell of bread somewhere. Dawn is the only quiet hour Orgrimmar has.",
	},
	["org.muse.drag.01"] = {
		"A smith down the Drag is arguing with a customer about the price of a nail. Both are enjoying it.",
		"Someone has hung hides across the street to dry. I duck under the third one and get slapped by the fourth.",
		"The Drag at work: sparks, shouting, and a wolf asleep under a stall.",
	},
	["org.muse.drums.01"] = {
		"listens for a moment to a drum somewhere in the city, steady as a heartbeat.",
		"taps two fingers in time with a distant drum, without seeming to notice.",
		"stops to let a roll of drums tumble down the canyon walls and fade.",
	},
	["org.muse.errands.01"] = {
		"Right. Bank, food, a whetstone, then trouble. In that order.",
		"Orgrimmar has everything. Except quiet.",
		"Somebody here sells everything. I just have to find who.",
	},
	["org.muse.forge.01"] = {
		"The forge fires in this city never seem to rest. Somebody, somewhere, is always hitting something.",
		"Iron, fire and the ring of hammers. Orgrimmar works the way it fights: loudly.",
		"I've stopped hearing the anvils by the forge fires. That's how I know I've been here a while.",
	},
	["org.muse.heat.01"] = {
		"Midday in the canyon: the stone walls give back every bit of sun they've swallowed.",
		"The sun-baked heat sits in the valleys like a fat cat. Even the grunts move slower over the hot stone.",
		"Sun on red stone. I'd trade a gold coin for one patch of real cool.",
	},
	["org.muse.honor.01"] = {
		"Practice dummies, battered past all recognition. They have had a hard life, and not a shield among them.",
		"Recruits are drilling in the yard. Somebody's going to have a bruise the size of a shield by supper.",
		"The clang of practice blades on shields makes my own arm itch.",
	},
	["org.muse.market.01"] = {
		"Smoked meat, cactus fruit, wolf hide and somebody's burnt stew. I could find the market blind, coin in hand.",
		"The market hums like a hive. Everyone selling, everyone counting coin, everyone sure they're winning.",
		"A merchant just called me friend. That will cost me a coin or two.",
	},
	["org.muse.night.01"] = {
		"Night here is never dark, only red with fire.",
		"The torch fires on the walls stretch the spikes into long teeth across the road tonight.",
		"The city quiets at night, but somewhere a forge fire keeps glowing like an eye that will not close.",
	},
	["org.muse.patrol.01"] = {
		"The grunts walk their rounds in pairs, never hurried, never late. There's a comfort in that.",
		"A patrol passes, axes on shoulders. Nobody steps aside for them; nobody needs to.",
		"Somebody keeps watch so the rest of us can haggle. I should thank a grunt one day.",
	},
	["org.muse.peoples.01"] = {
		"Orcs, trolls, tauren, the Forsaken: all of us in one city, all of us raising our voices. It shouldn't work, and it does, mostly.",
		"I hear four accents in one breath at the bank. The Horde is a noisy kind of household.",
		"We don't agree on much here except the walls, and we say so in loud voices. Maybe that's enough.",
	},
	["org.muse.spikes.01"] = {
		"Spikes on the walls, spikes on the roofs, spikes on the grunts. Somebody here really likes spikes.",
		"I bumped a fence post earlier. Still have the hole to prove it.",
		"Orgrimmar decor: if it doesn't stab, it's on fire.",
	},
	["org.muse.spirits.01"] = {
		"The smoke from the huts drifts uphill and takes the smell of herbs with it. Somebody is singing under their breath.",
		"Quiet here. Even the drums seem to think before they speak, and the smoke hangs low.",
		"A troll is carving something by a smoky fire. He doesn't look up, and I don't ask.",
	},
	["org.muse.wisdom.01"] = {
		"The tauren here speak in low voices, as if every word cost them a step. I find myself listening.",
		"Shamans pass with totems at their belts, their voices hushed, and the air seems to make room for them.",
		"Somewhere in that great hall the Horde is being decided. Out here, an old orc in a gravelly voice is scolding a wolf.",
	},
	["org.muse.wolves.01"] = {
		"steps aside as a rider on a great wolf trots past, the beast's claws clicking on the stone.",
		"watches a wolf rider go by, the animal's ears turning at every shout from the stalls.",
		"makes room for a pair of wolves on the road; one of them sniffs, considers, and moves on.",
	},
	["org.muse.zeppelin.01"] = {
		"They say the goblin zeppelins outside the gates fly as far as the Undercity and Grom'gol. I'll believe it when I'm standing on one.",
		"A grunt swears the zeppelins never fall. A goblin swore the same, and laughed.",
		"Somewhere out past the gates a zeppelin is leaving, full of people trusting goblin rope.",
	},
	["org.npc.banker.01"] = {
		"Everything I own, please. Carefully. Some of it bites, and the coin is counted.",
		"Here to deposit my fortune in coin. Don't laugh.",
		"I'll leave my coin with you. You've got bigger locks than I do.",
	},
	["org.npc.flightmaster.01"] = {
		"looks up at the wind riders on the tower while the flight master checks a list, cloaks stirring in the wind.",
		"nods to the flight master; overhead, a wind rider shakes out its wings in the wind.",
		"waits by the flight tower as a wind rider lands in a gust of wind and dust.",
	},
	["org.npc.guard.01"] = {
		"An Orgrimmar grunt: arms like posts, a blade at the hip, eyes that have seen a lot of travelers and trusted few.",
		"The grunt looks me over the way a smith looks over a blade.",
		"Big, scarred, patient, a blade within easy reach. The kind of guard you're glad is on your side.",
	},
	["org.npc.guard.02"] = {
		"A grunt. If he decides I'm trouble, there will be a great many more grunts very soon. Hands still.",
		"The guard's eyes stop on me a heartbeat too long. I keep my hands loose and my pace even.",
		"Don't stare. Don't hurry. Hands in sight. Grunts notice all three.",
	},
	["org.npc.innkeeper.01"] = {
		"nods to the innkeeper, who has the look of someone who has broken up a hundred brawls and started a few.",
		"catches the innkeeper's eye across the crowded room and gets a short nod in return.",
		"is greeted by the innkeeper with a look that already knows the order.",
	},
	["org.npc.merchant.01"] = {
		"A merchant with a smile that has teeth in it, and an eye on my coin. We'll see.",
		"The vendor spreads both arms over the goods like a proud parent, then names a price in coin.",
		"Prices chalked on a board, and every coin of them open to discussion.",
	},
	["org.npc.questgiver.01"] = {
		"Someone in this city always has work for idle hands. Mine look idle, apparently.",
		"The look of someone with a task and not enough hands to do it.",
		"Here it comes: you look capable. It's never a small thing after that, and never with clean hands.",
	},
	["org.npc.trainer.01"] = {
		"The trainer watches me the way an old warrior watches a new blade: looking for the flaw first.",
		"A trainer of the Horde. Short words, long lessons, and a blade's edge in both.",
		"I can tell already: this one teaches by making you do it again, until the blade goes where it should.",
	},
	["org.npcd.flight.route.01"] = {
		"From here the wind riders go south over Durotar and out across the Barrens. Long flight in a hard wind; hold on tight.",
		"The Crossroads is the usual hop. After that the Barrens go on forever, but the wind rider doesn't mind the wind.",
		"Where to? Pick a place I know, pay, and keep your hands off the reins, whatever the wind does.",
	},
	["org.npcd.flight.route.02"] = {
		"Thunder Bluff is a long way southwest, against the wind. Bring something to eat; the wind rider won't share.",
		"My riders know every Horde tower they've flown to, in any wind. You'll have to have found that tower on foot first, though.",
		"The wind's fair today. Can't promise tomorrow.",
	},
	["org.npcd.guard.danger.01"] = {
		"The deep caves under the city, down past the Cleft of Shadow, aren't for the green. Things crawl up from there.",
		"Stay out of the caves below the Cleft unless you've friends at your back. Cultists down there, and worse.",
		"Trouble inside the walls is rare. Trouble under them is another matter.",
	},
	["org.npcd.guard.danger.02"] = {
		"Out in Durotar the land is harsh, and so are the raiders. Carry water, keep watch.",
		"Inside, the grunts keep the peace. Past the gates, you keep your own.",
		"Watch the Cleft for pickpockets. They're quicker than the cultists, and friendlier, which is worse.",
	},
	["org.npcd.guard.dir.01"] = {
		"The bank, the auction house and the inn are all in the Valley of Strength, by the main gate. Can't miss them.",
		"Coin and beds? Valley of Strength, right behind the main gate.",
		"Bank's in the Valley of Strength, if it's coin you're after. So is half the city, most days.",
	},
	["org.npcd.guard.dir.02"] = {
		"Crafts and shops are along the Drag, the long crooked road through the middle. Follow the hammering.",
		"Need a tanner, a smith, an alchemist? Walk the Drag. Ask at every door.",
		"The Drag winds like a road that changed its mind. If it's made by hand, it's sold there.",
	},
	["org.npcd.guard.dir.03"] = {
		"Warriors and hunters train in the Valley of Honor. Mages and priests are down in the Valley of Spirits.",
		"Shamans, look for the Valley of Wisdom. Warlocks and rogues, the Cleft of Shadow: you'll know it, it's the dark one.",
		"Every trade has its valley here. Tell me yours, and I'll point.",
	},
	["org.npcd.guard.dir.04"] = {
		"The Warchief holds court in Grommash Hold, in the Valley of Wisdom. Mind your manners there.",
		"Wind riders leave from the tower in the Valley of Strength. Pay the flight master; don't feed the beasts.",
		"The zeppelins? Outside the gates, out in Durotar. Mind the goblins' fees.",
	},
	["org.npcd.guard.open.01"] = {
		"Keep moving, keep it civil, and we'll get along.",
		"Orgrimmar welcomes those who mind its rules. Mind them.",
		"You've the look of someone with business. Get to it.",
	},
	["org.npcd.guard.open.02"] = {
		"Inside these walls the Warchief's peace holds. See that it stays that way.",
		"Strong walls, fair rules. Break neither.",
		"Inside, you stand among the Horde. Carry yourself like it.",
	},
	["org.npcd.inn.news.01"] = {
		"The zeppelin's late again. The goblins blame the wind; the wind blames nobody.",
		"A caravan came in from the Barrens with half its kodos and all its complaints.",
		"Word is the grunts doubled the watch at the gate. Nobody says why, so everybody guesses.",
	},
	["org.npcd.inn.news.02"] = {
		"The smiths of the Drag are feuding over a price again. Good for business: they both drink here.",
		"Somebody in the Valley of Honor broke a practice dummy clean in half. Third this month.",
		"Tauren from Thunder Bluff came through, polite as ever. Ate everything, broke nothing. Best guests I've had.",
	},
	["org.npcd.inn.news.03"] = {
		"A trader swears the deep caves under the city are busier than they ought to be. I tell him to drink and stop jumping at noises.",
		"Rumor says a load of iron went missing between the gate and the Drag. Funny, how iron walks.",
		"They say a troll in the Valley of Spirits read someone's future in a soup bowl. It said: more soup.",
	},
	["org.npcd.merchant.news.01"] = {
		"Leather's dear this week, a pretty coin. The hunters are all out in the Barrens chasing something bigger.",
		"Prices? Up. Always up. The wind blows in through the gate and takes the coin with it.",
		"Iron's cheap, salt's dear, and the goblins want a coin of both.",
	},
	["org.npcd.merchant.news.02"] = {
		"A caravan from the coast should be in soon. Fish, salt, rumors. I'll sell you all three.",
		"The zeppelin brought a crate of something from across the sea. Nobody's opened it. Tempting.",
		"Word in the Drag is the smiths will raise their prices before the next muster. Buy now, complain later.",
	},
	["org.npcd.merchant.wares.01"] = {
		"Rope, waterskins, dried meat, a good knife. Everything you need to leave this city and walk in again on your own feet.",
		"Look, touch, but don't drool on the leather.",
		"Hide tanned in Durotar, stitched in the Drag. You won't find tougher.",
	},
	["org.npcd.merchant.wares.02"] = {
		"Cactus fruit, fresh today, or near enough. Or a blade to peel it with.",
		"Arrows, bowstrings, a whetstone or three for your blade. Pick quickly; there's a line.",
		"That blade? Good orcish steel. Good orcish price, too.",
	},
	["org.npcd.trainer.advice.01"] = {
		"Learn it slow, then do it fast. Not the other way round.",
		"Every trainer in this city will tell you the same: practice on dummies, not on friends.",
		"The Valley of Honor is full of strong fools. Be the other kind.",
	},
	["org.npcd.trainer.advice.02"] = {
		"Out in the wilds, nobody waits for you to remember the lesson. Remember it now.",
		"Train often. Coin comes back; lost chances don't.",
		"Come see me when you've grown a little. I'll have something new for you.",
	},
	["org.pray.01"] = {
		"Ancestors, the city is loud and my thoughts are louder. Lend me a little of your patience.",
		"Spirits of earth and stone, you hold up these walls. Hold me steady too.",
		"You who walked before me: I stand in the great city of stone now. See that I don't shame you.",
	},
	["org.quest.done.01"] = {
		"Done. Orgrimmar can stop worrying about that one.",
		"Job finished. Somebody in this city owes me a meal.",
		"Another errand for the capital, paid and done.",
	},
	["org.quest.done.02"] = {
		"Small work for a big city, and a few coins for it. Still, the Horde runs on small work.",
		"One more thing set right inside these walls. Nobody will sing about it, and the coin is enough.",
		"The coin is good; the nod from the grunt at the door is better.",
	},
	["org.rest.01"] = {
		"A roof somewhere, a bench, a bowl of something hot. The city can roar without me for a while.",
		"Inside the walls at last. My boots can stop being careful.",
		"Rest. Orgrimmar's noise is easier to love sitting down.",
	},
	["org.rest.02"] = {
		"slows down inside the walls, the dust of the road finally sliding off both shoulders.",
		"lets out a long breath, the kind that only comes at the end of a road, inside city walls.",
		"finds a quiet corner out of the crowd, sets the road aside, and sits for a moment.",
	},
	["org.rest.03"] = {
		"Safe walls, hot food, and nobody trying to eat me. Good day.",
		"I could sleep for a week in this city.",
		"Tell the Warchief I'm off duty for a while.",
	},
	["org.rest.serene.01"] = {
		"The forges, the drums, the shouting from the bank. Strange, how restful it all sounds today.",
		"I sit and watch the city go about its business, and for once none of it is mine.",
		"Nothing to chase, nothing chasing me. Just the city, breathing.",
	},
	["org.ret.bad.01"] = {
		"Last time this city saw me at my worst. I walk in a little straighter.",
		"Things went badly last time. The walls don't care, and I have decided I won't either.",
		"The same gate. I remember what came after it last time, and I keep moving anyway.",
	},
	["org.ret.habit.01"] = {
		"walks through the gate without looking up at the spikes this time.",
		"steps around the same rut by the gate as last time, out of habit.",
		"nods to the grunts at the gate as to old acquaintances; they do not nod back.",
	},
	["org.ret.home.01"] = {
		"Orgrimmar again. The same smoke, the same noise, and somehow I missed both.",
		"Back between the red walls. The forge smoke hits me, and my shoulders drop before I notice.",
		"The gate, the drums, the smoke of the forges. Some things are worth coming back to.",
	},
	["org.ret.long.01"] = {
		"It has been a while. A new stall in the Drag, a new crack in the stone, and the same drums underneath.",
		"Weeks on the road, and the city went on without me. It always does. I find I don't mind.",
		"Long away, and the canyon has not moved an inch. That is what stone is for: to stay, so the rest of us can leave.",
	},
	["org.ret.often.01"] = {
		"I could walk this city with my eyes shut by now. Wouldn't advise it, with the wolves on the road.",
		"Bank, inn, the Drag. My feet know the road better than I do.",
		"Orgrimmar. By now even the dust on the road knows me.",
	},
	["org.ret.wry.01"] = {
		"Orgrimmar! Did anyone miss me? No? The grunts never do.",
		"Still standing, I see. Good. So am I.",
		"Same grunt at the gate. I swear he hasn't blinked since I left.",
	},
	["org.sub.cleft.01"] = {
		"steps down into the cleft beneath the city, where the torchlight thins on the stone and conversations stop as one passes.",
		"descends into the dim crevice under the city, past doorways cut in the stone where nobody is quite looking.",
		"enters the narrow cleft, and the noise of the city above drops away to dripping stone and low voices.",
	},
	["org.sub.cleft.02"] = {
		"Warlocks and rogues keep their trainers down here. Sensible: neither trade enjoys an audience.",
		"They say the deep caves under the city go further down than anyone likes, and that not everything down there is a trogg.",
		"Hooded sellers, cheap candles, prices nobody writes down. I keep my purse closer.",
	},
	["org.sub.cleft.03"] = {
		"Lovely spot. Very cozy. Who's behind me?",
		"Nobody down here meets my eye. I'll take that as a compliment.",
		"Mind the drip. Mind the hood. Mind the knife under the hood.",
	},
	["org.sub.drag.01"] = {
		"turns into the Drag, a crooked street of stalls where every doorway has a craft and an opinion.",
		"follows the winding {subzone} past tanners, smiths and a cook with an alarming knife.",
		"walks the Drag slowly, between hides drying on racks and hammers ringing from open workshops.",
	},
	["org.sub.drag.02"] = {
		"Leather, hot iron, roasting meat, something sour from a tannery door. The Drag never smells of one thing at a time.",
		"Every trade of the city has a door on this street, and behind every door someone who knows better.",
		"The Drag twists so much, from door to door, that I'm never sure whether I've walked it once or twice.",
	},
	["org.sub.drag.03"] = {
		"The Drag. One hand on your purse and the other on your patience.",
		"Ten stalls, ten prices, one cracked pot. Ah, the Drag.",
		"If you can't find it in the Drag, you didn't haggle hard enough.",
	},
	["org.sub.hold.01"] = {
		"enters Grommash Hold, where the air smells of smoke and hide and every grunt by the door is watching.",
		"steps under the high roof of {subzone}, and the noise of the valley stays outside the door.",
		"crosses the threshold of the Warchief's hall slowly, as one does at the door of a place that matters.",
	},
	["org.sub.hold.02"] = {
		"The Warchief's own hall. I stand at the back, hands folded, and let those with business go first.",
		"Grom Hellscream's name on the hall. He freed his people and paid with his life. I'd rather earn a name like that than just walk under it.",
		"Much of what the Horde decides is decided under this roof. I keep my hands where they can be seen.",
	},
	["org.sub.hold.03"] = {
		"The heart of the Horde, and I am standing in it. Breathe slowly. Find the door.",
		"If anyone here takes a proper look at me, this goes badly. Eyes down, feet steady, the door behind me.",
		"Every grunt in this hall could end my errand with one swing. I'm counting the steps to the door.",
	},
	["org.sub.honor.01"] = {
		"enters the Valley of Honor to the clang of practice blades and trainers barking at recruits in the dust.",
		"walks into the {subzone}, where hunters, warriors and their beasts share the dust of the yard and the ring of blades.",
		"crosses the Valley of Honor, where one voice in two gives orders, the other obeys, and blades clatter in the dust.",
	},
	["org.sub.honor.02"] = {
		"The Valley of Honor. Everyone here walks like they have something to prove. Most of them do.",
		"Somewhere in this valley the bravest of the Horde have their names kept. I would not mind that, one day.",
		"Honor is earned in mud and given back in stone. Here, at least, someone is keeping count.",
	},
	["org.sub.honor.03"] = {
		"My trainer's in this valley somewhere. Probably shouting.",
		"Time to learn something that hurts. Preferably someone else.",
		"Valley of Honor. Mind the beasts, mind the blades, and mind the trainers most of all.",
	},
	["org.sub.legends.01"] = {
		"pauses at the door of the Hall of Legends, where only the Horde's most decorated soldiers are let in.",
		"looks up at {subzone} and the grunts posted by its door, who look back without warmth.",
		"stands a moment before the Hall of Legends, the way one stands before a door not yet earned.",
	},
	["org.sub.legends.02"] = {
		"Legends. A few earned it in one great day, most in a thousand ugly ones, scar by scar.",
		"The ones inside earned their place battle after battle, and wear the scars to prove it. I have a long way to go.",
		"Rank by rank, scar by scar, they climbed to that door. Glory here is not a gift; it is a ledger.",
	},
	["org.sub.legends.03"] = {
		"One day they'll let me in there. Probably to sweep.",
		"Hall of Legends. I'll wave from out here, then.",
		"Not today, legends. But save me a seat.",
	},
	["org.sub.spirits.01"] = {
		"walks down into the Valley of Spirits, among low huts and the smoke of burning herbs.",
		"passes into the {subzone}, where the smoke smells of herbs and the drums keep a slower beat.",
		"enters the troll quarter quietly; a pot bubbles somewhere in the smoke, and nobody explains what is in it.",
	},
	["org.sub.spirits.02"] = {
		"Mages and priests down here, among the trolls. Odd neighbors, but the quiet suits them both, and nobody raises a voice.",
		"Here, of all the city, the spirits are said to listen. I lower my voice, just in case.",
		"Smoke and old songs in low voices. The trolls keep their corner of the city the way they want it, and it shows.",
	},
	["org.sub.spirits.03"] = {
		"Smells like someone's cooking. I won't ask what.",
		"Valley of Spirits. Polite nods to everyone, spirits included.",
		"If something in here winks at me, I'm leaving.",
	},
	["org.sub.strength.01"] = {
		"steps into the Valley of Strength, where half the Horde seems to be queuing at the bank to count its coin.",
		"threads through the crowd of the {subzone}: bankers, hagglers, and someone loudly selling a sword nobody wants.",
		"enters the busy valley by the gate, into a din of coin, wolves and shouted prices.",
	},
	["org.sub.strength.02"] = {
		"The Valley of Strength. The bank on one side, the inn ahead, and my purse lighter in coin than I'd like.",
		"Here the Horde counts its coin and rests its feet. Not glorious, but somebody has to.",
		"The flight tower rises over the valley. Every wind rider that leaves it carries someone's errand.",
	},
	["org.sub.strength.03"] = {
		"Strength, they called it. Mostly it's the strength to stand in line.",
		"Valley of Strength. I see a lot of shopping and not much lifting.",
		"A strong valley. Strong smells, too.",
	},
	["org.sub.wisdom.01"] = {
		"enters the Valley of Wisdom, where Grommash Hold rises above the stone and the grunts stand straighter.",
		"walks into the {subzone}; the Warchief's hall looms ahead, and even the wind seems to keep its voice down.",
		"slows in the Valley of Wisdom, among tauren and shamans, with the great hall at its head.",
	},
	["org.sub.wisdom.02"] = {
		"Shamans speak to the elements here. Fire, earth, water and air, all asked politely inside one valley.",
		"Tauren voices, low and patient, carry across the valley. Wisdom sounds unhurried, it seems.",
		"The Valley of Wisdom. A fine name. I'll try not to say anything foolish while I'm in it.",
	},
	["org.sub.wisdom.03"] = {
		"The Warchief holds court in there. Clean boots, low voice.",
		"Grommash Hold. Every orc knows the name over that door, and what it stands for.",
		"Wisdom, the valley says. I'll take a little, if there's any going spare.",
	},
	["org.thanks.01"] = {
		"Thanks. I owe you one, and in this city debts get remembered.",
		"My thanks. You'd make a fine grunt, if you ever stood still.",
		"Thank you. That's worth more than a fair price in the Drag.",
	},
	["org.toast.01"] = {
		"To the forge fires that never go out!",
		"To Orgrimmar: loud, fiery, and ours!",
		"Drink up. The grunts out there get thirsty just watching, and the fires are hot.",
	},
	["org.toast.02"] = {
		"To the walls, and to whoever keeps them standing.",
		"To the grunts on the walls, who never get one of these.",
		"To good iron and a cold drink.",
	},
	["org.travel.hearth.01"] = {
		"The stone warms in my hand. Orgrimmar's drums are already fading.",
		"One more look at the red walls, then the world folds away around the stone.",
		"Leaving the capital by stone. The grunts won't even notice I'm gone.",
	},
	["org.weather.sand.01"] = {
		"pulls a cloth over nose and mouth as the wind starts hissing sand down the canyon.",
		"turns away from a gust of red sand that rattles against every spike on the walls.",
		"blinks grit from both eyes as the sand comes up on the wind and the stalls hurry to cover their wares.",
	},
	["org.weather.storm.01"] = {
		"The storm turns the banners into whips. The grunts don't even look up.",
		"Thunder in a canyon: it rolls from wall to wall over the snapping banners and never seems to finish.",
		"Lightning over the rim, and for one heartbeat every spike and every banner in the city stands out white against the storm.",
	},
	["org.zone.alliance.01"] = {
		"Every grunt here would know my face for what it is. Slow steps. Quiet hands. Lowered eyes.",
		"Enemy walls on every side, and one way out. I keep that gate in the corner of my eye.",
		"I walk into the heart of the Horde as one walks onto thin ice: lightly, eyes open, counting every sound.",
	},
	["org.zone.alliance.02"] = {
		"keeps to the edge of the road, hood low, past spiked walls that were never built for visitors.",
		"moves through the gate with care, weighing every grunt in sight and the distance to each.",
		"enters the enemy capital without a word, both hands kept well clear of any weapon.",
	},
	["org.zone.first.02"] = {
		"stops beneath the great gate and tilts back to take in the canyon walls for the first time.",
		"slows at the threshold, eyes climbing the red rock all the way to the spiked rim of the canyon.",
		"takes a first long look at the city in the canyon: smoke, stone and a great deal of noise.",
	},
	["org.zone.first.horde.01"] = {
		"Orgrimmar. I have heard it named a hundred times, and still the stone walls take me by surprise.",
		"Red stone, iron spikes and banners as far up as I can see. So this is the city they talk about at every fire.",
		"Here the Horde set down its axe and built in stone. Named for a fallen warchief, raised by living hands: I walk in for the first time, and it feels like being counted.",
	},
	["org.zone.horde.01"] = {
		"Orgrimmar. Smells of smoke and leather. Smells like home.",
		"Orgrimmar! Somebody start a fire and somebody else bring meat.",
		"Walls, grunts, drums. Good. Everything where it should be.",
	},
	["org.zone.horde.02"] = {
		"Between these walls the wind loses its teeth. Few places let me sleep this well.",
		"Nobody handed us this canyon. Every stone of these walls was hauled and hammered into place.",
		"Stone that once held nothing now holds a people. I like to think the canyon was waiting for us.",
	},
	["org.zone.horde.03"] = {
		"walks in under the red banners, and somewhere above a drum picks up the step.",
		"passes the spiked palisade at an easy pace, banners snapping overhead and drums beating deep in the city.",
		"enters Orgrimmar to the sound of distant drums, under banners the color of hot iron.",
	},
	["org.zone.horde.04"] = {
		"Orgrimmar. Loud, crowded, and every second face looks ready for a brawl. Perfect.",
		"Mind the spikes. Mind the grunts. Mind the wolves. Then you can mind your business.",
		"The capital! Where even the doorways look like they want to arm-wrestle you.",
	},
	["org.zone.night.01"] = {
		"At night the canyon fills with torchlight, and the walls glow as if still warm from the forge.",
		"Night in Orgrimmar: the forges never quite go out, and the grunts' torches pace the walls.",
		"Dark sky, red walls, a hundred small fires. The city does not sleep tonight; it only lowers its voice.",
	},
	["org.zone.orc.01"] = {
		"An orc city, built by orc hands. I still like the sound of that.",
		"Named for the Doomhammer. I touch the wall as I pass, the way you touch the shoulder of an elder.",
		"No camp, no cage, no borrowed field. A city of our own, and the stone remembers whose hands set it.",
	},
	["org.zone.sand.01"] = {
		"squints against the sand blowing through the gate, mouth covered against the wind.",
		"walks in with sand hissing along the canyon walls and grit settling in every fold of cloth.",
		"shakes the red sand from both sleeves under the gate, to no great effect.",
	},
	["org.zone.scourge.01"] = {
		"The grunts look twice at me, then once more. Fair. I would look twice at me too.",
		"So much warmth in this city: forges, bodies, breath. I walk through it like a draft through a full room.",
		"They let us in. Not everyone smiles about it, but the gate opened, and that counts for something.",
	},
	["org.zone.tauren.01"] = {
		"Not a blade of grass anywhere. The orcs have made a mountain into a house. I miss the open sky a little.",
		"Stone underfoot, stone overhead, stone on every side. The Earth Mother is here too, only harder to hear.",
		"Our friends build with axes and fire. On the plains we would have asked the grass and the land first. Still, they built well.",
	},
	["org.zone.troll.01"] = {
		"Too much stone, not enough sea. Still, the drums here keep a good rhythm.",
		"The orcs build tall. Down in the Valley of Spirits, at least, somebody keeps the fires the old way.",
		"The Darkspear have a corner here, and a corner is more than we had after the islands.",
	},
	["org.journey.w01.01"] = {
		"rises from the tower above the Valley of Strength, and the city's drums fade beneath the beat of the wind rider's wings.",
		"lifts away from Orgrimmar, the canyon walls sliding down and the smoke of the forges thinning to threads.",
		"climbs into the hot air over the city, the great gate and the red road beyond it shrinking fast.",
	},
	["org.journey.w01.02"] = {
		"Orgrimmar drops behind, loud to the last. The wind takes over the shouting from here.",
		"From the air the city is just a crease in the rock, and all its noise fits in one breath of wind.",
		"The Warchief's city, smaller with every heartbeat. It looked bigger from the gate.",
	},
	["org.journey.w01.03"] = {
		"Lok'tar, Orgrimmar. Keep the fires lit.",
		"Off to wherever the Horde needs a hand. Fly on.",
	},
	["org.journey.w01.04"] = {
		"Down. Somebody point me at food and a bench, in that order.",
		"Feet on the ground. Orgrimmar, try not to shout all at once.",
	},
	["org.journey.w01.05"] = {
		"lands on the tower in the dark, the city below lit by forge-glow and torches, red on red.",
		"comes down out of the night sky into Orgrimmar, where the fires never quite go out and the drums only soften.",
	},
	["org.journey.w01.06"] = {
		"Flying is fine. Landing is fine. It's the part after, when the Valley of Strength keeps turning gently, that I mind.",
		"Legs, wake up. Orgrimmar won't cross itself.",
	},
	["org.quest_complete.w01.01"] = {
		"delivers what was asked over the din of the Drag, and gets a grunt that counts as warm thanks in this city.",
		"takes the reward and steps aside to let a wolf rider pass, coin already tucked away.",
		"receives a short nod and a heavier purse, while a hammer somewhere close keeps time.",
	},
	["org.quest_complete.w01.02"] = {
		"Finished. In Orgrimmar that earns you a nod and a new problem, usually in the same breath.",
		"Done, and nobody shouted at me. In this city, that's a medal.",
	},
	["org.quest_complete.w01.03"] = {
		"Done, for the Horde. Tell me if there's more.",
		"Another debt paid to the Horde. Gladly.",
	},
	["org.quest_complete.w02.01"] = {
		"accepts the reward and a gruff word of thanks, while the wind carries red dust down the Valley of Strength.",
		"steps back into the heat and noise of the city, the task done and the purse heavier.",
		"pockets the reward beneath the great red cliffs that wall the city in, and moves on.",
	},
	["org.quest_complete.w02.02"] = {
		"Done. Orgrimmar has a long memory for those who pull their weight, and a short one for excuses.",
		"Finished. In this city respect is paid in small coins, and I've just earned one more.",
	},
	["org.dawn.w04.001"] = {
		"watches the watch change at the gate as the dawn comes up, the grunts who kept watch through the dark giving way to fresh ones with a single muttered word.",
		"sees the dawn turn the smoke over the canyon from gray to gold, while the first peons trudge out with their tools.",
	},
	["org.farewell.w04.001"] = {
		"Time I went. Mind the crush at the gate.",
		"Farewell. Don't let the Drag take all your coin.",
	},
	["org.farewell.w04.002"] = {
		"Go well. Orgrimmar will keep your place in the crowd.",
		"Take care out there. In here, at least, the walls do it for us.",
	},
	["org.greet.w04.001"] = {
		"Well met. You picked a loud city to cross my path in.",
		"Hail! Shout if you want to be heard in here; everyone else does.",
		"Good to see you. Let's talk before the drums drown us out.",
	},
	["org.greet.w04.002"] = {
		"Strong walls and an open gate to you.",
		"May your business in the city be short, and the gate open when you want it.",
	},
	["org.greet.w04.003"] = {
		"Ah, a face that isn't selling me anything. Hello.",
		"Hello! You're not a merchant, are you? Good.",
	},
	["org.jest.w04.001"] = {
		"Orgrimmar has a valley for strength, one for honor, one for wisdom and one for spirits. I'm still looking for the one for naps.",
		"I asked a tauren in the Valley of Wisdom how to get rich. He said: patience. I asked a goblin. He said: your purse.",
	},
	["org.journey.w04.001"] = {
		"leans forward as the wind rider drops off the edge of the tower, wings snapping open over the crowded streets below.",
		"holds on as the beast beats upward out of the canyon, the noise of the city falling away in one long breath.",
		"rises past the canyon rim, and the city behind its walls turns into a red bowl of smoke and roofs.",
	},
	["org.journey.w04.002"] = {
		"The wind rider groans at every wingbeat. I choose to believe it's the climb and not me.",
		"Below, a grunt at the gate looks up. I wave. He doesn't. Some things don't change at any height.",
		"Up and out of the canyon. Now the beast and I find out which of us trusts the other less.",
	},
	["org.journey.w04.003"] = {
		"passes high over the zeppelin towers outside the gate, where a goblin airship is being coaxed into the wind.",
		"looks down as the flight clears the walls; out past the gate the zeppelin towers stand up out of the red ground like two tall wooden fingers.",
		"watches a goblin zeppelin creak away from its tower beyond the gate, slow and fat, as the wind rider overtakes it without effort.",
	},
	["org.journey.w04.004"] = {
		"Every speck down there in the Valley of Strength is someone in a hurry. From up here, none of it looks urgent.",
		"The bank, the inn, the Drag: down there they were the whole world. Now I could cover them with one hand.",
		"The city shrinks, and the worries I carried inside it shrink with it. That is the best part of flying.",
	},
	["org.journey.w04.005"] = {
		"Higher! No, not that much higher. There. Stay there.",
		"Don't look down, they said. Nobody said how lovely it is. I'm looking.",
		"Farewell, noise. Hello, wind in the ears.",
	},
	["org.journey.w04.006"] = {
		"sees Durotar open out beyond the walls as the beast climbs: red ridges, dry gullies, and a thin road winding south.",
		"gains height until the canyon is only a crack in the red earth, and the far line of the sea shows to the east.",
		"leaves the canyon behind, the hot air off the rocks lifting the wind rider over the red earth in long, easy surges.",
	},
	["org.journey.w04.007"] = {
		"Somewhere at the end of this flight there's work with my name on it. The city can keep its noise without me.",
		"The city gave me rest. Now the road gets its turn.",
		"Up, and away from the walls. In there I'm one face among many; out on the road I have work.",
	},
	["org.journey.w04.008"] = {
		"lifts off into the dawn, the first light touching the wind rider's wings long before it reaches the streets below.",
		"rises over the waking city at dawn, cook smoke climbing in thin lines out of the valleys.",
	},
	["org.journey.w04.009"] = {
		"Leaving by night. Behind me the city glows like a bed of embers; ahead, the dark has no edges at all.",
		"The torches on the walls slide away under the wings, and then there are only the stars and the wind rider's breathing in the night.",
	},
	["org.journey.w04.010"] = {
		"Easy, now. We both want to arrive in one piece.",
		"Steady, beast. I know what you eat; don't make me regret this.",
		"Off we go. You fly, I'll do the worrying.",
	},
	["org.journey.w04.011"] = {
		"grips the saddle a little harder than strictly needed as the tower falls away beneath.",
		"keeps both eyes on the horizon, and not on the long drop to the Valley of Strength.",
	},
	["org.journey.w04.012"] = {
		"Taking off into blowing sand. The wind rider narrows its eyes to slits; I'd do the same if I could still see.",
		"Sand in the teeth before we've even cleared the walls. Durotar sends me off the way it greets me.",
	},
	["org.journey.w04.013"] = {
		"From the air the choice makes sense: one gate, high walls of stone, and the whole of Durotar spread out to keep an eye on.",
		"A city built in a crack of the earth, hidden until you're right above it. Whoever chose this stone chose well.",
	},
	["org.journey.w04.014"] = {
		"glances back once at the tower, where the handlers are already leading out the next wind rider.",
		"leaves the tower in a gust of wingbeats, scattering a pair of peons who were resting in its shadow.",
	},
	["org.journey.w04.015"] = {
		"Leaving a city always feels lighter by air. Probably because the Drag emptied my purse.",
		"Goodbye, bank queue. Goodbye, auction house shouting. Hello, sky.",
		"Nothing down there can reach me for a while: no errands, no hawkers, no grunts with questions.",
	},
	["org.journey.w04.016"] = {
		"climbs past the banners on the highest spikes of the wall, close enough to hear them snap.",
		"sweeps out over the walls of Orgrimmar, the red banners straining on their poles just below.",
		"rises until the drums of the city are only a pulse felt through the saddle, then not even that.",
	},
	["org.journey.w04.017"] = {
		"comes in low over the great gate, and the noise of the city rises to meet the wings like heat off a forge.",
		"circles once above the Valley of Strength while the wind rider picks its spot, then drops onto the tower with a thump.",
		"touches down on the tower platform, where a handler takes the reins without a word and points the way down.",
	},
	["org.journey.w04.018"] = {
		"My ears are still full of wind. Three steps into the city and the shouting will clear them out.",
		"Solid ground. Well, solid tower, with the wind still in it. I'll take it.",
		"Eyes watering, legs humming, mouth full of grit. Hello, Orgrimmar.",
	},
	["org.journey.w04.019"] = {
		"walks down from the tower with one hand on the rail, while the ground stops swaying a turn at a time.",
		"takes the way down from the landing slowly, the bank and the inn coming up to eye level step by step.",
		"follows the handler off the platform, legs relearning the ground with every step down.",
	},
	["org.journey.w04.020"] = {
		"The walls hold the day's heat even up here on the tower. After the cold of the high air, it feels like a hand on the back.",
		"Up there the wind was the only voice. Down here there are a thousand, and none of them is talking to me. Restful, in its way.",
	},
	["org.journey.w04.021"] = {
		"Good flight. Off you go, and don't eat the next passenger.",
		"Thanks, beast. I'd tip you, but you'd take the hand with it.",
		"Down safe. I'll speak well of you to your handler, beast.",
	},
	["org.journey.w04.022"] = {
		"climbs down after the long flight with knees that have forgotten how to bend, and leans on the saddle until they remember.",
		"lands at the end of a long flight, and for a moment the solid tower seems to rock under both boots.",
	},
	["org.journey.w04.023"] = {
		"Long flight. Every part of me that touched the saddle has something to say about it.",
		"Too long in the air. My legs belong to someone else now, and they want to lie down.",
	},
	["org.journey.w04.024"] = {
		"follows the line of torches along the walls down through the night, as if the city had lit the way on purpose.",
		"lands under a sky full of stars in the night, and the handler on the tower holds up a lantern to see who has arrived.",
	},
	["org.journey.w04.025"] = {
		"Down at dawn. The streets half empty, the cook fires half lit. For once I'm early to Orgrimmar.",
		"A dawn landing. The handler yawns, the wind rider yawns, and I try very hard not to.",
	},
	["org.journey.w04.026"] = {
		"steps off into a hard glare, the red stone of the valley throwing the sun's heat straight back up.",
		"lands in the heat of the day under a high sun, and shades both eyes to look down over the crowded stone valley.",
	},
	["org.journey.w04.027"] = {
		"lands in a haze of red grit, and the wind rider shakes the sand out of its mane before anyone can reach the reins.",
		"comes down blind through the blowing sand, trusting the beast to know where the tower is.",
	},
	["org.journey.w04.028"] = {
		"Landed, and the city hasn't noticed. I'll give it a moment before I start asking it for things.",
		"Nobody down here knows I was in the sky a moment ago. I keep the secret a little longer before joining the crowd.",
		"The sky was simple. Down here, someone already wants a word with me. I can feel it.",
	},
	["org.journey.w04.029"] = {
		"Red stone underfoot once more. The air smells of iron again.",
		"Orgrimmar, I've returned. Try to contain your joy.",
		"Landed under the banners of the Horde. Whatever the road did to me, it can't follow me in here.",
	},
	["org.journey.w04.030"] = {
		"lands to the howl of a wolf somewhere below, as if the city kept a beast just to announce arrivals.",
		"touches down and hands over the reins of the beast, while below a kodo caravan grinds its way in through the gate.",
	},
	["org.journey.w04.031"] = {
		"Already I miss the quiet up there. Down here everything has a price and a voice.",
		"The wind rider is led away and doesn't look back. Not a sentimental creature. I envy it a little.",
	},
	["org.journey.w04.032"] = {
		"lands and looks down from the tower on the crowd in the Valley of Strength, a slow river of heads, packs and wolves.",
		"steps from the saddle to the stone and stops at the tower's edge, picking out the inn, the bank and the gate below.",
		"comes down in a flurry of wings that sends a peon's load of firewood tumbling, and a stream of curses after it.",
	},
	["org.journey.w04.033"] = {
		"If anyone saw that landing: no, you didn't.",
		"We're down. I'll unclench my hands in a moment.",
		"My thanks to the wind rider, the saddle straps, and whatever kept me on.",
	},
	["org.muse.w04.001"] = {
		"Half the Horde keeps its savings at the bank by the gate, and the other half keeps asking the first half for loans.",
		"There must be more gold stacked under the Valley of Strength than in every hill of Durotar. Not one coin of it is mine.",
		"The bankers here have the calmest faces in the city. Counting other people's coin must be restful.",
	},
	["org.muse.w04.002"] = {
		"Somebody at the auction house just paid good gold for a cracked pot. Proudly.",
		"Every day the auction house sells for a fortune what I let go for a handful of copper.",
		"The auction house: where a rusty buckle finds the one buyer in Kalimdor who wanted it.",
	},
	["org.muse.w04.003"] = {
		"I check the mailbox out of habit. Nobody writes much to someone who never stays in one place.",
		"The mailbox by the bank has swallowed a hundred letters today, and none of them were for me. That's the road for you.",
	},
	["org.muse.w04.004"] = {
		"follows the shadow of a wind rider as it slides over the crowd and climbs the canyon wall.",
		"looks up as a wind rider banks above the city, its wingbeats lost under the shouting from the streets.",
		"shades both eyes to watch a wind rider circle the tower twice before it deigns to land.",
	},
	["org.muse.w04.005"] = {
		"The inn by the gate never empties. Somebody always has a story, and nobody ever has a free stool.",
		"To get a stool at the inn I'd have to win a staring match with a tauren. I would lose.",
		"The inn is full of travelers telling each other how far they've walked. The road gets longer with every mug.",
	},
	["org.muse.w04.006"] = {
		"Somewhere in the bank there's a box of mine full of things I'll never use. The safest junk in Kalimdor.",
		"The bank keeps my things safe from thieves, and from me, which is the harder job.",
		"I could empty my bank box today and start over lighter. I won't. That cracked horn might matter one day.",
	},
	["org.muse.w04.007"] = {
		"Every crafter in the Drag has burn scars on their hands and a lecture ready. I could learn a trade here, if I could stand the lectures.",
		"A tanner, a tailor, an alchemist breathing his own fumes: the Drag will teach any trade, for a fee and a few burns on the hands.",
		"In the Drag even the apprentices have hard hands. Nobody there learned a craft by watching.",
	},
	["org.muse.w04.008"] = {
		"If the Drag ran straight, it would be half as long and twice as dull.",
		"Whoever laid out the Drag was following a drunk kodo down the road.",
		"The Drag has more bends than a goblin's sales pitch.",
	},
	["org.muse.w04.009"] = {
		"A puff of green smoke from some workshop off the Drag, a curse, then laughter. Somebody's potion has had its say.",
		"An alchemist somewhere has made a mistake that smells of rotten eggs and singed hair, and the smoke is telling the whole city.",
	},
	["org.muse.w04.010"] = {
		"weighs the coin purse in one hand, then decides the shops of the Drag can wait until it is heavier.",
		"counts the coins in one palm, sighs, and puts half of them aside for the repair bill.",
		"pats every pocket in turn, finds the purse in the last one, and lets out a breath, the way everyone learns to in the crowds of Orgrimmar.",
	},
	["org.muse.w04.011"] = {
		"My armor squeaks. Half the smiths in this city could fix it, and every one of them would tell me how I broke it.",
		"A smith looked over my gear as I passed and shook his head. Not angry. Just disappointed. Worse.",
		"There's a dent in my armor that every smith in the Drag would love to discuss at length, for a price.",
	},
	["org.muse.w04.012"] = {
		"The Cleft of Shadow sits right under the Warchief's city, full of warlocks and their pets. Thrall must know. I suppose someone is always watching.",
		"Down in the Cleft they trade in curses and poisons, a stone's throw from the bank. Every great house has a cellar it doesn't show to guests.",
		"Warlocks, poisoners, cutpurses with good manners: the Cleft keeps the trades the city needs and won't name aloud.",
	},
	["org.muse.w04.013"] = {
		"The grunts talk of a chasm of fire under the Cleft, and of cultists hiding in it. The whole city sleeps on top of that.",
		"Ragefire Chasm, right under the streets. Every capital keeps something burning below that it would rather not look at.",
	},
	["org.muse.w04.014"] = {
		"Somebody's imp has got loose again. Mind your eyebrows.",
		"An imp just said something to me in a language I'm very glad I don't speak.",
		"Whose imp is this? It's eating my bootlace and looking proud of it.",
	},
	["org.muse.w04.015"] = {
		"The trolls talk to their loa the way you'd talk to a neighbor over a fence: politely, and keeping count of favors.",
		"Loa, charms, the old troll ways, kept alive in one valley of an orc city. The Darkspear brought their gods along, and nobody asked them to leave them at the gate.",
	},
	["org.muse.w04.016"] = {
		"The Horde's mages learn their spells a few steps from troll shrines. The arcane doesn't seem to mind the company.",
		"Mages and priests, trained in the troll valley among charms and smoke. A scholar of Dalaran would have a lot to say about it. Nobody here would listen.",
	},
	["org.muse.w04.017"] = {
		"Thrall was raised in a cage and grew up fighting in a ring. Now he sits in a hall without bars, and hears out whoever comes to the door.",
		"A Warchief who was once a slave. Maybe that is why the doors of his hall stand open.",
		"The Warchief knows what a locked door feels like from the wrong side. You can see it in how he keeps his own.",
	},
	["org.muse.w04.018"] = {
		"Orgrim's black armor and Orgrim's hammer, worn now by the one he chose. The city carries the old Warchief's name; the new one carries his weight.",
		"The Doomhammer hangs at Thrall's side and the city bears Orgrim's name. Between the two of them, the old orc is still keeping watch.",
	},
	["org.muse.w04.019"] = {
		"Strength to the Warchief. He carries more of us than he lets on.",
		"The Warchief's peace holds another day. Good. Let's keep it that way.",
		"Whatever the Warchief is deciding in that hall, I hope he's had a decent meal first.",
	},
	["org.muse.w04.020"] = {
		"Thrall speaks of peace with the humans of Theramore. Half the city grumbles, half sharpens its axes and keeps quiet. I'm still working out which half I belong to.",
		"Peace, the Warchief says. Not everyone in these streets wants it, but nobody wants to be the one who tells him.",
		"A truce with Theramore, and a grunt at every gate anyway. The Warchief hopes, and keeps the walls manned. Both seem wise.",
	},
	["org.muse.w04.021"] = {
		"glances toward the Valley of Wisdom, where the Warchief's hall stands, then turns back to the business at hand.",
		"falls quiet for a moment when the talk nearby turns to the Warchief, as most people here do.",
	},
	["org.muse.w04.022"] = {
		"Grommash Hellscream's name is on the Warchief's hall. Not because he was gentle, but because at the end he broke the chain the rest of his people could not.",
		"Grom was no gentle soul. He drank first and paid last, and that last payment broke his people's chains. The hall keeps his name for that.",
	},
	["org.muse.w04.023"] = {
		"The guards of Grommash Hold are the finest in the city. You can tell: none of them has smiled since the walls went up.",
		"The Warchief's own guards could stare down a mountain. With travelers it's even easier for them.",
	},
	["org.muse.w04.024"] = {
		"A shaman mutters to a brazier and the flame leans toward her, like a hound toward its master's hand.",
		"A shaman is talking to the fire, and the fire, by the look of it, is listening.",
		"The shamans of this city ask the fire before they light it. The smiths just light it. The fire seems to know the difference.",
	},
	["org.muse.w04.025"] = {
		"The Horde was a war band once. Here it learned to be a people: bank, school, market and hall. Thrall built that, more than the walls.",
		"An army can live in tents. A people needs a city. Orgrimmar is the day the Horde decided to be both.",
	},
	["org.muse.w04.026"] = {
		"Somewhere in the Valley of Honor a hunter is explaining to a bear that the trainer is not food.",
		"Hunters walk their beasts through the city like it's nothing. A cat, a raptor, a boar with opinions, all waiting outside the same bank.",
		"A hunter's cat is asleep across the road, and the whole crowd walks around it. Nobody in Orgrimmar argues with a beast that size.",
	},
	["org.muse.w04.027"] = {
		"Warriors come out of the Valley of Honor walking as if the whole city were a dueling ring. Some of them are right.",
		"In this city a fresh scar is worn like a new cloak, and shown off the same way.",
		"Every recruit in the city dreams of the Hall of Legends. Most of them will settle, happily, for a good axe and a full belly.",
	},
	["org.muse.w04.028"] = {
		"A trainer in this city will charge you silver to be told you're doing it wrong. The annoying part is that it's worth it.",
		"In one of these valleys a trainer is waiting to tell me I hold my weapon the way a peon holds a broom.",
		"Every trainer in Orgrimmar starts a lesson the same way: with a sigh.",
	},
	["org.muse.w04.029"] = {
		"Out of the way, out of the way. Some of us have trainers to disappoint.",
		"Make room. I've got an appointment with a trainer and a fresh set of bruises.",
		"Mind your backs! Coming through, with all my gear and none of my patience.",
	},
	["org.muse.w04.030"] = {
		"Past the gate, the road runs south through the red country toward Razor Hill. Every road starts here, and every one of them is dusty.",
		"From the gate Durotar looks like a land someone set on fire and left to cool. And still the roads leave it in every direction.",
		"Out there, beyond the walls, the dust of the road is waiting. It always waits for me longer than the city does.",
	},
	["org.muse.w04.031"] = {
		"listens to two travelers arguing over whether the zeppelin to Grom'gol is worth the fare.",
		"hears someone complain loudly that the zeppelin left early, for the first time since goblins learned to fly.",
		"catches a scrap of talk about the zeppelins: one more traveler swearing never again, and buying a ticket anyway.",
	},
	["org.muse.w04.032"] = {
		"Zeppelin or wind rider? One was built by goblins. The other bites. Hard choice.",
		"I'd take the zeppelin, but I've met the goblins who fly it.",
		"A wind rider at least lands where you paid for. Usually.",
	},
	["org.muse.w04.033"] = {
		"Undercity is one zeppelin ride from here. Leave this red dust and step down into those damp cellars: I can hardly picture it.",
		"Grom'gol, Undercity: from the towers outside the gate, a goblin balloon goes almost anywhere. The canyon is only the doorstep.",
	},
	["org.muse.w04.034"] = {
		"Red dust in my boots, in my collar, in my bread. I'll be finding Orgrimmar in my pockets for a week.",
		"Shake out a cloak in this city and you raise a little red cloud of your own.",
		"Everything I own has turned the color of the canyon. Orgrimmar paints you whether you ask or not.",
	},
	["org.muse.w04.035"] = {
		"This red rock was here long before any of the peoples walking on it. It wears our walls and spikes the way an old dog wears a collar: patiently.",
		"The canyon doesn't care who rules it. Whoever sits in the hall, the rock goes on being red, and it will go on after us.",
	},
	["org.muse.w04.036"] = {
		"rubs a pinch of red grit from the wall between two fingers, as if reading it.",
		"runs a hand along the rough red rock and studies the dust it leaves on the palm.",
	},
	["org.muse.w04.037"] = {
		"Everything here is red. The rock, the dust, the banners, the tempers.",
		"Red walls, red road, red dust. Somebody here only owned the one pot of paint.",
		"Red rock, red road, red faces at the bank. Even my boots have gone over to the cause.",
	},
	["org.muse.w04.038"] = {
		"Woodsmoke, wolf, scorched fat and leather. Orgrimmar smells like a camp that decided to stay.",
		"Under the forge smoke there's always something roasting. In this city you're never more than a few steps from a meal.",
		"Tannery, wolf pen, cookfire, smithy: four smokes and four stinks, and somehow they add up to one city.",
	},
	["org.muse.w04.039"] = {
		"Nobody in Orgrimmar whispers. Even the secrets get told at the top of the voice.",
		"Two orcs are having a friendly chat across the street. From here it sounds like a declaration of war.",
		"I just heard a grunt say something tender to a wolf. It was louder than most battle cries.",
	},
	["org.muse.w04.040"] = {
		"In a city this loud, a moment of quiet feels like something stolen. I keep it a while before anyone notices.",
		"Between two drumbeats there's a gap no wider than a breath. I've learned to live in it.",
	},
	["org.muse.w04.041"] = {
		"winces as a drum starts up somewhere far too close, loud enough to rattle teeth, and waits it out.",
		"flinches at a sudden roll of drums from the next street, then pretends the flinch never happened.",
	},
	["org.muse.w04.042"] = {
		"Every shout in this canyon comes back twice. Orgrimmar never has to say anything only once.",
		"The red walls throw every voice back at the street. It's a city that answers itself.",
	},
	["org.muse.w04.043"] = {
		"If one more hawker shouts in my ear, I'll buy whatever he's selling just to make him stop. Which is probably the plan.",
		"A goblin has been following me down the street with a price that drops every ten paces. I'm tempted to walk to the gate and see where it ends.",
		"Every stall in this city has someone bellowing in front of it. The quiet ones, I've learned, are the ones with the good prices.",
	},
	["org.muse.w04.044"] = {
		"Every doorway in this city was built for orcs. The tauren duck through them all day, horns first, without a word of complaint.",
		"A tauren stoops under a low lintel, slowly, the way you'd step around a sleeping child.",
		"The tauren move through this crowded city as carefully as if it were made of clay. Big, gentle, and never in a hurry.",
	},
	["org.muse.w04.045"] = {
		"A Forsaken walks through the market and the crowd opens a little wider than it needs to. The Horde is still getting used to its newest members.",
		"A Forsaken apothecary haggles with an orc smith over a pair of tongs. Neither of them is enjoying the other's smell.",
	},
	["org.muse.w04.046"] = {
		"Troll laughter carries further than any drum. Someone in the crowd has just told a very good joke, or a very bad one.",
		"Trolls laugh with the whole body, tusks and all. It's hard to stay sour within earshot of one.",
		"Two trolls are teasing a grunt in a language he half follows. He's pretending to be offended, badly.",
	},
	["org.muse.w04.047"] = {
		"A goblin is selling something out of a cart, talking faster than the coins can change hands. Neutral, they call themselves. Neutral like a scale with a thumb on it.",
		"The goblins in this city are polite to everyone and loyal to coin. At least you always know where you stand.",
		"A goblin shook my hand on a deal and then counted my fingers for me, very politely. All there.",
	},
	["org.muse.w04.048"] = {
		"steps aside for a peon staggering under a load of planks, who mutters something and plods on.",
		"watches a line of peons carry timber up the ramp, slow and steady as a column of ants.",
		"makes way for a peon with a basket of ore on each shoulder and the patience of the very tired.",
	},
	["org.muse.w04.049"] = {
		"A pack of young orcs races through the crowd, dodging the grunts' legs. Born free, every one of them. Not all their elders can say as much.",
		"The children here have never seen a camp or a cage. Their games are about axes and wolves, not about running. That is what the walls are for.",
	},
	["org.muse.w04.050"] = {
		"Five peoples on one street, and every one of them in my way.",
		"Excuse me. Pardon. Mind the horns. Mind the tusks. Excuse me.",
		"Orc, troll, tauren, Forsaken, goblin. All in a hurry, all going the other way.",
	},
	["org.muse.w04.051"] = {
		"watches a goblin and an orc shake hands on a deal, each with the look of having robbed the other.",
		"stops to watch a haggle between a troll and a tauren, carried out almost entirely in shrugs.",
	},
	["org.muse.w04.052"] = {
		"A grunt just helped an old troll up the ramp without being asked, then glared at me in case I thought it was soft.",
		"A tauren hands a crying orc child back to its mother, very carefully, as if it might break. The mother thanks him with a growl.",
	},
	["org.muse.w04.053"] = {
		"Here and there an old orc carries pale scars around the wrists. Shackles, I'd guess. Nobody here asks, and nobody hides them.",
		"The old orcs in the crowd move slower than the young, and look at the walls longer. They remember what it was like before there were walls of their own.",
	},
	["org.muse.w04.054"] = {
		"stops to let a kodo rider through; the beast fills the whole road and apologizes to nobody.",
		"presses back against a wall as a kodo lumbers by, its rider nodding thanks from high above.",
		"waits while a kodo stops dead in the middle of the road to scratch, and its rider sighs with the patience of habit.",
	},
	["org.muse.w04.055"] = {
		"A wolf pup is chewing a grunt's bootlace, and the grunt is pretending very hard not to notice.",
		"A wolf cub tumbles out of a doorway after a scrap of leather, and three grown warriors step aside for it.",
		"A wolf pup has fallen asleep on a stack of hides for sale, and the tanner hasn't the heart to move it.",
	},
	["org.muse.w04.056"] = {
		"stands aside as a column of grunts in full armor marches out toward the gate, and the crowd hushes until they have passed.",
		"watches a troop of grunts tramp by in step, the street trembling faintly under their boots.",
	},
	["org.muse.w04.057"] = {
		"catches a coin someone dropped in the crowd and hands it back; the owner looks at it as if counting it twice.",
		"picks up a coin rolling across the road and returns it to a startled peon, who bites it to be sure.",
	},
	["org.muse.w04.058"] = {
		"A mage stands in the middle of the crowd, staring at nothing and moving fingers. Any moment now, gone. Probably somewhere cooler.",
		"Mages here vanish in a flash of light and leave nothing behind but a whiff of something burnt and a gap in the queue.",
		"A mage just appeared out of thin air in front of the bank and was nearly trampled by a wolf. Nobody even looked up.",
	},
	["org.muse.w04.059"] = {
		"Orgrimmar isn't beautiful the way a forest or a lake is. It's beautiful the way a well-made axe is.",
		"No one would call this city pretty. Honest, though: every wall says what it's for, like a good blade.",
		"Not a garden in sight, not a fountain. Just stone, iron and purpose. I've come to like it.",
	},
	["org.muse.w04.060"] = {
		"A city raised by people who were behind fences not so long ago. When the drums start, that's what I hear in them.",
		"Not long ago the orcs were kept in camps and chains. Now they keep a city. The drums sound like that, if you listen.",
	},
	["org.muse.w04.061"] = {
		"Durotar is named for Thrall's father, Orgrimmar for the old Warchief who chose him. A whole land named after the dead, and so full of the living.",
		"Two names on this land, Durotan and Orgrim, and neither of them lived to walk it. The living took their names and built.",
	},
	["org.muse.w04.062"] = {
		"I set out to buy one thing. I'll leave with six, and none of them will be the first.",
		"My list said whetstone. My bags say rope, two hides, a lantern and a meat pie I've already eaten.",
		"Every time I pass a stall I remember one more thing I need. This city was laid out by merchants.",
	},
	["org.muse.w04.063"] = {
		"Anything cold in this city? Water, ale, a patch of shade, I'm not fussy.",
		"Who here sells something cold? I'll pay the goblin price, just this once.",
		"Somebody point me at a cool cellar and I'll pay rent.",
	},
	["org.muse.w04.064"] = {
		"This city wears a body out without a single fight: ramps, crowds, stairs cut in rock, and dust in every breath.",
		"A day in Orgrimmar tires the legs more than a day on the road. Every errand is uphill from the last one.",
	},
	["org.muse.w04.065"] = {
		"Half this city looks ready for a brawl, and the other half looks ready to bet on it.",
		"Three shoving matches in the last hour, and nobody drew a weapon. In Orgrimmar that's practically a peace festival.",
		"Somebody just bumped my shoulder and growled. I growled back. We parted friends. That's how it works here.",
	},
	["org.muse.w04.066"] = {
		"The Horde needs more than axes. It needs leather, nails, bread, ink. Walking through the city, I see the other army.",
		"For every grunt on the wall there are ten peons, smiths and cooks behind him. Wars are won in kitchens too.",
	},
	["org.muse.w04.067"] = {
		"Lok'tar. May the canyon stand and the forges burn.",
		"Lok'tar ogar. The city hears it, even if nobody answers.",
		"Lok'tar, Orgrimmar. Stay loud.",
	},
	["org.muse.w04.068"] = {
		"Everyone here is headed somewhere: the bank, a trainer, the gate. I stand still and the crowd parts around me like water round a stone.",
		"I stop in the middle of the street for no reason, and the city flows past on both sides without a glance.",
	},
	["org.muse.w04.069"] = {
		"leans against a wall in a corner clear of the crowd and watches the city's traffic go by for a while.",
		"sits on a low wall to fix a loose buckle, while the noise of the city rolls on unbothered.",
		"finds a step out of the way, sits, and lets the crowd go past for a while like weather.",
	},
	["org.muse.w04.070"] = {
		"Roast scorpid on a stick, a copper apiece. Crunchy. I'm told it's an acquired taste. I'm acquiring it.",
		"A troll at a brazier sells skewers of something with too many legs. I bought two. The second one was better.",
		"Something is sizzling on every second brazier. My purse and my stomach are having words about it.",
	},
	["org.muse.w04.071"] = {
		"Orgrimmar has a bank, an auction house, an inn and a trainer for every trade there is, and still nobody sells shade.",
		"You can buy anything in this city except a moment of shade and a straight answer from a goblin.",
	},
	["org.muse.w04.072"] = {
		"The city is built in a fist of rock with only a few ways in. Whoever planned it had seen a siege or two.",
		"Walls of red rock on every side, gates you can count on one hand. Orgrimmar was built by people who expected unwelcome guests.",
	},
	["org.muse.w04.073"] = {
		"Every grunt at the gate, every smith at the anvil, every shaman at the fire: the whole Horde at work at once. I'd better find my part in it.",
		"Nobody in this city stands idle for long. Even the wolves look busy. Time I was too.",
	},
	["org.muse.w04.074"] = {
		"Thousands of people, and not one who knows my name. There's a kind of rest in that.",
		"A city this full is the easiest place to be alone. Nobody looks twice, nobody asks where I'm going.",
		"Nobody here knows what I've done or where I've been. In the crowd I'm just one more pair of boots.",
	},
	["org.muse.w04.075"] = {
		"Bones and tusks are worked into half the walls here. After a while I stopped wondering whose.",
		"Tusks over the doorways, skulls on the posts. Orgrimmar decorates with what the hunt leaves behind.",
	},
	["org.muse.w04.076"] = {
		"Stone, fire, and a people who would not die. That's the whole recipe of Orgrimmar; the rest is noise.",
		"Take away the stalls and the shouting and what's left is rock, forge-fire and stubbornness. Enough to build on.",
	},
	["org.muse.w04.077"] = {
		"Why is every ramp in this city uphill? Both ways?",
		"Whoever built Orgrimmar never had to carry anything up it.",
		"My legs have opinions about this city's ramps. Loud ones.",
	},
	["org.muse.w04.078"] = {
		"Huts on ledges, ledges over huts, a ramp to everything. The canyon left no room to build outward, so they built up.",
		"Every level of this city looks down on another. From the top of a ramp you can see three trades, two arguments and a goblin counting coin.",
	},
	["org.muse.w04.079"] = {
		"Not so long ago the orcs drank demon blood and burned whole lands. Now they hammer nails and sell bread. That's a change I trust: slow, and loud.",
		"Whatever was in the orcs' blood once, this city is the long work of getting it out. Every peaceful day here is a day taken back.",
	},
	["org.muse.w04.080"] = {
		"The Alliance would love to see these walls burn. Let them come and take a good look at the walls first.",
		"Every spike on these walls is an answer to a question nobody's been fool enough to ask yet.",
	},
	["org.muse.w04.081"] = {
		"Braziers, forges, cookfires, torches. A city of small fires, each with someone beside it warming hands or supper.",
		"There's a fire on every corner of Orgrimmar. You could walk the whole city and never be cold, if it ever got cold here.",
	},
	["org.muse.w04.082"] = {
		"One day they'll tell stories about me at the inn here. Mostly true ones, I hope.",
		"Orgrimmar's full of heroes. Room for one more?",
		"Somebody here should carve my name somewhere. Small. By the door, maybe.",
	},
	["org.muse.w04.083"] = {
		"All this noise and trade sits on a narrow peace. Somewhere out past the walls, someone is paying for it every day.",
		"The stalls are full and the forges are hot because someone guards the roads. I try not to forget who.",
	},
	["org.muse.w04.084"] = {
		"Orgrimmar is not a place you love at first sight. It grows on you, like a callus.",
		"This city is too loud, too hot, too crowded, and I wouldn't have it any other way. Don't tell it.",
	},
	["org.muse.w04.085"] = {
		"sidesteps a puddle of something that is definitely not water, with great care.",
		"jumps back as a bucket of wash water is emptied from a ledge above, and dodges it by a hair.",
	},
	["org.muse.w04.086"] = {
		"Who's selling, who's buying, who's lying? Ah, Orgrimmar.",
		"Smell that? Somebody's roasting boar. I'm following my nose.",
		"Right, city. Show me what you've got for sale today, and try not to shout it.",
	},
	["org.muse.w04.087"] = {
		"Sand on the wind, and the whole city turns its back to it at once, like a herd on the plains.",
		"The sand blows through Orgrimmar as if it had business at the bank. I keep my mouth shut, and not only from manners.",
	},
	["org.muse.w04.088"] = {
		"tucks chin into collar and leans into the sand-laden wind, following the dim shape of the grunt ahead.",
		"walks on through the hissing sand with eyes half shut, steering by the sound of the anvils.",
	},
	["org.muse.w04.089"] = {
		"Rain in Orgrimmar. The red dust turns to paint and runs down every wall, and the trolls stand in it laughing.",
		"Rain, here of all places. The forge smoke hisses, the streets go dark red, and the whole canyon smells of wet clay.",
	},
	["org.muse.w04.090"] = {
		"turns a face up to the rare rain, as half the street is doing, and lets it wash off some of the dust.",
		"holds out an open palm to catch the rain, the way people do in a dry land, and watches it fill.",
	},
	["org.muse.w04.091"] = {
		"From the bottom of a canyon the stars come in a narrow river between the walls, and the spikes on the rim stand against them like teeth.",
		"Above the torches, a handful of stars. The city is too bright to see more of them, and too loud to miss them.",
	},
	["org.muse.w04.092"] = {
		"hears a wolf howl somewhere in the dark of the canyon, and a dozen more answer from across the city.",
		"stops at a long howl rising out of the dark; it runs round the walls before it fades.",
	},
	["org.muse.w04.093"] = {
		"steps out into the cool of the early hour, before the dust is up and the shouting has begun.",
		"watches the handlers feed the wolves at first light, cursing each animal fondly by name.",
	},
	["org.muse.w04.094"] = {
		"The early hour belongs to the peons. They're up before anyone, sweeping the dust from one side of the road to the other.",
		"Before the merchants wake, the city is all peons and yawning grunts. The most honest hour in Orgrimmar.",
	},
	["org.muse.w04.095"] = {
		"Every torch in the city goes up at dusk, and every cook burns something at the same moment.",
		"Dusk. The torches are lit, the stalls are closing, and the prices are finally coming down.",
	},
	["org.muse.w04.096"] = {
		"The wind riders come in to the tower one after another as the light goes, like crows to a dead tree.",
		"As the light fades, the last wind riders drop out of the sky to the tower, tired and slow.",
	},
	["org.muse.w04.097"] = {
		"At this hour people stand in the narrow shade of the walls in a line, as if queuing for the cool.",
		"The shade crosses the valley as the sun moves, and the crowd moves with it, like a flock behind its shepherd.",
	},
	["org.muse.w04.098"] = {
		"Under a roof at last. The drums still come through the walls, muffled, like someone knocking politely for once.",
		"Indoors, the racket of the city shrinks to a hum. I'd forgotten my own thoughts made any noise.",
	},
	["org.muse.w04.099"] = {
		"Inside, the air is thick with smoke and talk. Outside it was dust and shouting. I'm not sure I've gained much.",
		"Four walls and a roof, and still the smoke finds me. Orgrimmar doesn't do indoors the way other cities do.",
	},
	["org.muse.w04.100"] = {
		"The banners on the walls snap and settle, snap and settle. I find myself breathing in time with them.",
		"Above the road a banner swells and falls like a slow breath. It's the calmest thing in the city.",
	},
	["org.muse.w04.101"] = {
		"watches the smoke of a hundred hearths and forges rise and gather under the canyon rim like a second roof.",
		"follows a column of forge smoke up the red wall with both eyes until the wind on the rim tears it apart.",
	},
	["org.npc_meet.w04.001"] = {
		"passes a grunt at the post, whose eyes follow along without the head turning an inch.",
		"gets a long look from a grunt leaning on an axe, the kind of look that measures and files away.",
		"nods to the grunt by the wall, and the grunt shifts the weight of the axe in what might be a reply.",
	},
	["org.npc_meet.w04.002"] = {
		"Long watch? Don't answer. I can see it in the tusks.",
		"Keeping the peace? Good. I'll try not to test it.",
		"Don't mind me. Just walking. Nothing to see but someone who keeps the rules.",
	},
	["org.npc_meet.w04.003"] = {
		"Forearms like a smith's and a voice that could quiet a brawl from across the room. The ideal innkeeper for Orgrimmar.",
		"The innkeeper glances at my boots before my face. Fair: the boots tell more, and say it without a voice.",
		"Whoever runs an inn in this city has seen every kind of trouble walk in. I try to be the boring kind.",
	},
	["org.npc_meet.w04.004"] = {
		"Something hot to eat and something cold to drink, and I'm not fussy about the order.",
		"A bench out of the way of the door, if you have one. I've had my fill of company for a while.",
	},
	["org.npc_meet.w04.005"] = {
		"The flight master has the smell of the beasts on every sleeve, and the same habit of looking at people as if weighing them for a saddle.",
		"Wind riders shift on the perches behind the master, and every beast of them watches me the way a cook watches meat.",
	},
	["org.npc_meet.w04.006"] = {
		"Somewhere far, please, and smoothly. I've just eaten.",
		"Which of these beasts likes me least? I'll take a different one.",
		"I'd like a wind rider with good manners. Do you keep any of those?",
	},
	["org.npc_meet.w04.007"] = {
		"is hailed by a merchant from three stalls off, which in this city counts as a quiet word.",
		"stops at a stall where the merchant is already holding something out, before a word has been said.",
		"lets a merchant lay out the goods on the counter, one piece at a time, with the care of someone laying out a battle plan.",
	},
	["org.npc_meet.w04.008"] = {
		"Every merchant here has two prices: one for friends and one for everyone else. Let's see which I get.",
		"The goods are good. The smile is better. The price will be best of all, for the merchant.",
	},
	["org.npc_meet.w04.009"] = {
		"Is everything still in there? Actually, don't tell me if it isn't.",
		"Here to visit my belongings. They've been lonely.",
		"Same as always: put things in, take fewer things out.",
	},
	["org.npc_meet.w04.010"] = {
		"Every coin at this counter is counted as if it were a grunt reporting for duty. Not one slips past unseen.",
		"Behind the counter, rows of locked boxes, and a banker who looks like the strongest lock of them all, coin by coin.",
	},
	["org.npc_meet.w04.011"] = {
		"waits while the trainer finishes with another student, then steps forward to be looked over the same way.",
		"stands before the trainer and is studied from boots to brow without a word, like an open book.",
	},
	["org.npc_meet.w04.012"] = {
		"You've got the look of someone with a list. Read me the first line.",
		"Work? I'm listening. Pay? I'm listening harder.",
		"All right, I'll hear it. Short version first.",
	},
	["org.npcd_flightmaster_bye.w04.001"] = {
		"Hold the straps, not the beast's ears. Off you go.",
		"Fly safe. If you pass a zeppelin on the way, wave; the goblins love that.",
	},
	["org.npcd_flightmaster_open.w04.001"] = {
		"The wind riders are fed and rested. The question is whether you are.",
		"Step up to the perch, slowly. The beasts don't like sudden movements, or grunts, or me, some days.",
		"From this tower you can reach half of Kalimdor, if you have the coin and the stomach for a beast's back.",
	},
	["org.npcd_guard_bye.w04.001"] = {
		"Go on, then. Inside the walls, your weapon stays where it belongs.",
		"Move along, and keep to the right of the wolves.",
		"Out past the gate it's your watch. In here, it's ours.",
	},
	["org.npcd_guard_thanks.w04.001"] = {
		"Don't thank me. Thank the Warchief; I only stand where he puts me.",
		"Hm. Thanks are rare at this post. I'll remember the face.",
	},
	["org.npcd_innkeeper_bye.w04.001"] = {
		"Off with you, then. Your bench will be warm under somebody else in a heartbeat.",
		"Take care. And if you meet a caravan on the road, tell them we've beds.",
		"Mind the step, and mind the wolves outside the door.",
	},
	["org.npcd_innkeeper_more.w04.001"] = {
		"That's all I've got. Ask the goblins at the zeppelin towers; they hear everything and charge for half.",
		"No more. What I hear at this counter, I hear in pieces, between orders.",
	},
	["org.npcd_innkeeper_open.w04.001"] = {
		"Get in before the street swallows you whole. There's a free bench by the wall, and the stew isn't burned yet today.",
		"Come in, come in. Orgrimmar's loud enough outside; in here, you only have to listen to me.",
		"Sit anywhere that isn't spiked. Which narrows it down.",
	},
	["org.npcd_innkeeper_open.w04.002"] = {
		"Bed or bowl? Say it loud; the drums don't stop for anyone.",
		"This is the busiest inn in the Horde, and the drums never stop. Find a corner and guard it.",
	},
	["org.npcd_innkeeper_rest.w04.001"] = {
		"The beds are in the back. Thick walls: you won't hear the drums, much.",
		"Sleep as long as you like. The drums will still be going when you wake.",
	},
	["org.npcd_innkeeper_sit.w04.001"] = {
		"That's it. Feet up, if you can find a stool nobody's guarding.",
		"Stay as long as you like. Just keep your elbows off the next table; it belongs to a grunt with a temper.",
	},
	["org.npcd_innkeeper_thanks.w04.001"] = {
		"Thanks are kind. Coin is kinder. Both are welcome here.",
		"No trouble. In this city a polite guest is a rare thing, rarer than a spare coin; I'll tell the cook.",
	},
	["org.npcd_merchant_bye.w04.001"] = {
		"When those soles wear thin in the dust, you know which stall to find.",
		"Off you go. And if anyone asks where the good stalls are, you know the answer.",
		"Safe travels, and if your purse feels heavy out there, you know where I am.",
	},
	["org.npcd_merchant_haggle.w04.001"] = {
		"Haggle? In Orgrimmar that's half the trade. Go on, then: I've heard worse offers from goblins.",
		"Lower? The kodo that carried it here didn't walk for less.",
	},
	["org.npcd_merchant_open.w04.001"] = {
		"Step up, step up. Everything here has crossed Durotar on a kodo's back, and it only shows a little.",
		"You've the look of someone leaving the city soon. Buy before you go; out there, nobody sells.",
		"Browse all you like. Touch what you'll pay for.",
	},
	["org.npcd_merchant_open.w04.002"] = {
		"Coin talks louder than drums in this street. Let's hear yours.",
		"Mind the stock, it bites back. The leather, I mean. Mostly. Coin first, then you can stroke it.",
	},
	["org.npcd_merchant_thanks.w04.001"] = {
		"Thank me by coming back. And by bringing friends with heavy purses.",
		"My pleasure. Spread the word around the valley; I'm easy to find.",
	},
	["org.npcd_trainer_bye.w04.001"] = {
		"Go. Practice. Come back when it's in your hands, not your head.",
		"Off with you. Mind what I said, especially the part you didn't like, and keep your hands busy.",
	},
	["org.npcd_trainer_open.w04.001"] = {
		"Here to learn, or here to be told it's too soon? Either way, stand there.",
		"Show me what the road has taught you. Then I'll show you what it hasn't.",
		"This city is full of recruits who think they know it all. Prove you're not one of them before you take the road again.",
	},
	["org.pray.w04.001"] = {
		"Whatever listens beneath all this noise: keep the walls standing, and keep my hands honest.",
		"Spirits of this red canyon, you have heard a great deal of shouting. Hear one quiet word from me, and steady my hand.",
	},
	["org.quest_complete.w04.001"] = {
		"weighs the purse once in the palm, approves of the sound it makes, and ties it off.",
		"counts the coins twice in the lee of a wall, more out of habit than out of doubt.",
		"tucks the reward away under the cloak before the next shout from the stalls can find it.",
	},
	["org.quest_complete.w04.002"] = {
		"The thanks lasted one breath. Then the eyes went past my shoulder to whoever's next. Orgrimmar has a queue for everything.",
		"Paid, thanked and dismissed in the time it takes a wolf to yawn. Efficient city.",
		"I'd hoped for a speech. I got a grunt and a finger pointed at the way out. Close enough.",
	},
	["org.quest_complete.w04.003"] = {
		"That's settled. Now, which stall in the Drag gets this coin first?",
		"Paid in full. The Drag will have it off me before the day is out.",
		"Good. This purse won't stay heavy for long, not with the Drag so close.",
	},
	["org.quest_complete.w04.004"] = {
		"It's out of my hands now, and my hands feel it. Lighter, and a little empty.",
		"Reported and closed. Whatever comes of it is somebody else's worry from here on.",
		"One weight off the shoulders. The city keeps all of its own weights, as usual.",
	},
	["org.quest_complete.w04.005"] = {
		"hears the task declared done in a voice that carries, and a few heads in the street turn to look.",
		"is given a thanks of a few rough words, and an orc passing by grunts approval as if the matter were his business too.",
		"accepts the reward with a short bow of the head, and the noise of the city closes in again like water.",
	},
	["org.quest_complete.w04.006"] = {
		"Anything else needs carrying, killing or counting, I'll be at the inn.",
		"Right. Next time, ask me something hard.",
		"There. Write it down somewhere, before I forget I did it.",
	},
	["org.quest_complete.w04.007"] = {
		"Another stone laid. One day this city may know my name without asking twice.",
		"Small deeds, set one upon another. That is how walls go up here, and names too.",
		"Nobody remembers the first task. They remember the one after the hundredth. I keep counting.",
	},
	["org.quest_complete.w04.008"] = {
		"steps aside for a peon hauling timber, the task finished and the reward already in a belt pouch.",
		"closes the business while a peon trudges past under a load of timber, looking like someone nobody ever thanks.",
		"leaves the reckoning settled, past a peon who has stopped to watch and is shooed back to work by somebody louder.",
	},
	["org.quest_complete.w04.009"] = {
		"Done as asked, and done right. Tell whoever needs telling.",
		"Consider it settled. My word was on it.",
		"It's finished. I don't leave things half done in the Warchief's city.",
	},
	["org.quest_complete.w04.010"] = {
		"The coin is still warm from the pocket it came out of. Strange, what a piece of work turns into.",
		"Paid, and already the city has forgotten the task. Only I will remember it, and only for a while.",
		"Somebody else's worry became my work, and now it belongs to nobody. That is a kind of magic, too.",
	},
	["org.quest_complete.w04.011"] = {
		"takes the reward as the banners overhead stir in a hot gust, and for a moment the whole street seems to approve.",
		"settles the account beneath the spiked eaves, while far off a horn sounds the change of a watch.",
	},
	["org.quest_complete.w04.012"] = {
		"Somewhere in this city somebody is scratching my name into a ledger. Probably spelled wrong.",
		"A mark on someone's list. Under all the shouting, the Horde runs on lists.",
	},
	["org.quest_complete.w04.013"] = {
		"That's it. My feet would like a word with whoever planned all this walking.",
		"Sorted. Now, where does a body sit down in this city?",
		"Over and done. My boots have earned a rest, even if I haven't.",
	},
	["org.quest_complete.w04.014"] = {
		"This is the best moment: nothing owed, nobody waiting on me, and all the noise of the city belonging to someone else.",
		"Free hands, a light pack, a little coin. For once I could walk the Drag just to look.",
		"Nothing more to fetch, nothing more to find. For an hour, Orgrimmar is only a place to stand in, with empty hands.",
	},
	["org.quest_complete.w04.015"] = {
		"listens to the thanks run on longer than expected, nodding, while somebody behind clears a throat.",
		"is told twice that the work was well done, by a voice not used to saying it even once.",
		"hears a longer thanks than this city usually spends, and nods through all of it.",
	},
	["org.quest_complete.w04.016"] = {
		"Your gratitude is noted. Mine too. Look at us, being polite in Orgrimmar.",
		"No need for a fuss. A small fuss, maybe. In private.",
	},
	["org.quest_complete.w04.017"] = {
		"This city was raised a task at a time: a load carried, a word delivered, someone walking back in through the gate. I am part of that, a little.",
		"None of it will be carved anywhere. Still, the city stands on a thousand errands like this one.",
	},
	["org.quest_complete.w04.018"] = {
		"pockets the reward, glances toward the smell of roasting meat drifting down the street, and swallows.",
		"turns the reward over once, and a goblin across the way is already smiling at it.",
		"tucks the reward away, and three hawkers within earshot raise their voices at once.",
	},
	["org.quest_complete.w04.019"] = {
		"Tell them it's done. And tell them by whom.",
		"Done. If there are songs about it, I'd like a verse. A short one will do.",
		"Done, and done well. Somebody tell the Hall of Legends to wait for me.",
	},
	["org.quest_complete.w04.020"] = {
		"Work given, work done, payment taken. The simplest bargains are the ones I trust.",
		"No speeches, no oaths, just a task and its end. That suits me.",
	},
	["org.quest_complete.w04.021"] = {
		"lets out a breath that seems to have been held since the task began; in the crowd, nobody notices.",
		"rolls both shoulders once the business is closed, as if setting down a pack that was never really there.",
		"allows a small, private smile, gone before anyone in the street could catch it.",
	},
	["org.quest_complete.w04.022"] = {
		"A pleasure. Well, mostly a pleasure. Some of it was dreadful.",
		"If you need me again, I'm easy to find: follow the complaints.",
	},
	["org.quest_complete.w04.023"] = {
		"Late, and the torches are burning low, but the task is closed. I'll sleep better tonight owing nothing.",
		"The night watch is out on the walls, and here I am, finishing the day's business by torchlight.",
	},
	["org.quest_complete.w04.024"] = {
		"steps back into the glare off the red walls, the reward in one hand and the other raised against the sun.",
		"pauses in a strip of shade by the wall to stow the reward, while the sun beats down on the stone.",
		"wipes the sweat off the brow with a forearm, the sun high over the canyon and the reward safe in a pouch.",
	},
	["org.quest_complete.w04.025"] = {
		"I never ask what becomes of the work once it's handed in. Today I nearly did.",
		"Whatever this was for, it's in the city's hands now. Big hands. I hope they're careful.",
	},
	["org.quest_complete.w04.026"] = {
		"Your trust was well placed. Next time, give me something heavier.",
		"It's done. You asked the right one.",
	},
	["org.quest_complete.w04.027"] = {
		"watches the forge smoke climb past the canyon rim while the business is concluded, and lets the moment sit.",
		"takes a moment after the reckoning, eyes on the strip of sky between the canyon walls.",
	},
	["org.quest_complete.w04.028"] = {
		"Every errand teaches me the city a little better: who shouts, who pays, who does both.",
		"One more face in Orgrimmar that knows mine. Slowly, the city is filling up with people I've helped.",
	},
	["org.quest_complete.w04.029"] = {
		"Don't thank me, pay me. Ah, you did. Then thanks are welcome too.",
		"Keep the speech. I'll keep the reward. Fair trade.",
	},
	["org.quest_complete.w04.030"] = {
		"concludes the business with a cloth pulled up over the mouth, the thanks half lost in the hiss of sand along the street.",
		"shields the reward from the blowing sand with one hand and ducks back out into the swirling red.",
	},
	["org.quest_complete.w04.031"] = {
		"The work is done and the city never paused for it. As it should be: a city that stops for every errand stays stopped.",
		"Nobody in the street knows what I've just finished. The forges keep ringing, the wolves keep pacing. Fine by me.",
		"Done, and the drums didn't miss a beat. I'd be worried if they had.",
	},
	["org.quest_complete.w04.032"] = {
		"Who's hungry? I'm buying. Something small, mind.",
		"That calls for a drink. A cheap one. I've seen the prices here.",
	},
	["org.quest_complete.w04.033"] = {
		"The shamans in the Valley of Wisdom say the spirits keep their own tally of deeds. I hope this one made it in.",
		"Somewhere the ancestors are watching, the old ones say. Today, at least, they saw nothing to be ashamed of.",
	},
	["org.quest_complete.w04.034"] = {
		"steps away with the matter settled, past a tauren ducking carefully under a doorway built for orcs.",
		"turns from the finished business and nearly walks into a troll carrying a basket of something that wriggles.",
		"moves off with the task behind, giving way to a goblin who is counting something under his breath and will not be interrupted at the door.",
	},
	["org.quest_complete.w04.035"] = {
		"Odd. The city is as loud as ever, and inside me it has gone quiet, the way it does when a task lets go.",
		"The end of a job always leaves a small hollow. I'll fill it with the next one, I suppose.",
		"Finished, and for a heartbeat I don't know what my hands are for.",
	},
	["org.quest_complete.w04.036"] = {
		"Good. The next one, put it somewhere with shade.",
		"If there's another, I'd like it on this side of the city. My legs are taking a vote.",
		"Settled. And if the next job is down in the Cleft, the price goes up.",
	},
	["org.quest_complete.w04.037"] = {
		"receives the reward from a heavy, calloused hand, and the grip that comes with it lasts a moment longer than needed.",
		"gets a firm clap on the shoulder that nearly knocks the reward out of one hand.",
	},
	["org.quest_complete.w04.038"] = {
		"Nobody haggled over my reward. In this city that's either respect or a mistake. I'm not going back to ask which.",
		"Paid without an argument. I almost miss the argument.",
	},
	["org.reputation_change.w04.001"] = {
		"Somebody, somewhere, thinks a little better of me now. In a city this loud a quiet compliment is easy to miss; I didn't.",
		"A name counts for a little more than it did. Mine, for once.",
		"Standing rises the way walls do here: one hauled stone at a time. Another one is in place.",
	},
	["org.rest_enter.w04.001"] = {
		"loosens a strap or two and lets the din of the city become something to listen to instead of something to push through.",
		"sets the pack down against a wall that has held up a great many tired backs, by the look of it.",
		"eases down onto a step out of the traffic, watching the wolves and kodos go by without having to dodge them.",
	},
	["org.rest_enter.w04.002"] = {
		"Inside these walls, the watch belongs to the grunts. My eyes can finally close without asking permission.",
		"No hand on the hilt here. The grunts carry that weight for all of us.",
		"For once the walls are someone else's problem. I only have to sit inside them.",
	},
	["org.rest_enter.w04.003"] = {
		"A low ceiling, a smoky fire, and a room full of people too tired to start a fight. The best kind of crowd.",
		"Under a roof at last. The fire spits, the stew bubbles, and the noise of the street comes through the walls as a hum.",
		"Somebody is already snoring in a corner by the hearth. I take it as a recommendation.",
	},
	["org.rest_enter.w04.004"] = {
		"ducks in under the low lintel, out of the noise, and lets the smell of smoke and stew settle the rest of the day.",
		"finds a seat with a wall at the back and a fire in front, the old arrangement of the weary.",
		"settles into the warmth indoors, where the walls are thick enough to turn the city outside into a rumor and the fire into the only news.",
	},
	["org.rest_enter.w04.005"] = {
		"Wake me for food or for war. Nothing smaller.",
		"If I start snoring, just roll me under a bench.",
		"My legs and I have agreed: we're not going anywhere for a while.",
	},
	["org.rest_enter.w04.006"] = {
		"Every road that brought me here is still humming in my legs. Let it hum. I'm not going anywhere.",
		"Walls, drums, a roof somewhere near. I don't need the whole city, only one corner of it that keeps still, off the road.",
	},
	["org.rest_enter.w04.007"] = {
		"Night settles over the walls. Somewhere a guard calls out and another answers, and then there is only the crackle of the torch fires.",
		"Night inside the walls. The forge fires glow, the drums slow, and my own heart seems to slow with them.",
	},
	["org.rest_enter.w04.008"] = {
		"lets both shoulders drop at last, and a passing grunt eyes the sudden slouch with professional suspicion.",
		"sits down so heavily that a wolf nearby opens one eye to check, then closes it again in sympathy.",
	},
	["org.thanks.w04.001"] = {
		"Thank you. Nobody in this city gives anything away, so I know what that cost.",
		"Much obliged. I'll remember it next time we're both in the queue at the bank.",
		"Thanks. If you ever need a hand in the Drag, find me.",
	},
	["org.thanks.w04.002"] = {
		"You have my thanks, and the Horde's, for what my word is worth to it.",
		"Thank you. Kindness sits well inside walls like these.",
	},
	["org.travel.w04.001"] = {
		"Halfway through a shout from the Drag, the city folds shut around the stone like a book.",
		"I hold the stone and listen to Orgrimmar for one more breath: hammers, drums, a goblin swearing. Then nothing.",
	},
	["org.weather_change.w04.001"] = {
		"watches the wolves in the street lie down flat and tuck their noses under their tails as the sand comes up on the wind.",
		"steps into the lee of a spiked wall as red sand pours over the canyon rim like water over a weir.",
		"turns up a collar while the sand drifts in through the gate in long, hissing tongues.",
	},
	["org.weather_change.w04.002"] = {
		"Sand in the teeth, sand in the boots, sand in the bank ledgers, probably. Orgrimmar goes on shouting through all of it.",
		"The sky over the canyon turns the color of rust, and the sand starts to fly. Somewhere a goblin is already selling scarves.",
		"The city pulls its head in like a tortoise; everyone keeps working, just with their eyes narrowed against the sand.",
	},
	["org.weather_change.w04.003"] = {
		"Cover your mouths. Durotar's sand is coming in through the gate.",
		"Here it comes. Somebody close the canyon before the sand fills it.",
	},
	["org.weather_change.w04.004"] = {
		"looks up as the air clears, and the strip of sky between the canyon walls turns a hard, clean blue.",
		"watches the haze lift off the city, until every spike on the far wall stands out sharp against the sky.",
		"sees the stall-keepers come out from under their covers as the sky turns fair, shaking out cloths and grumbling.",
	},
	["org.weather_change.w04.005"] = {
		"The air clears. A peon is already sweeping the grit off the bank steps; he'll be back at it the next time the wind turns.",
		"The air goes still and clean, and suddenly I can hear the forges three valleys away.",
	},
	["org.weather_change.w04.006"] = {
		"Rain in Orgrimmar. Every grunt on the walls looks up at once, as if someone had insulted them.",
		"The rain hits the hot roofs, and the whole city smells of wet hide and steam.",
		"Rain! The peons have stopped working to stare at it. So have I.",
	},
	["org.weather_change.w04.007"] = {
		"holds out a palm to the rain, and watches the drops darken the red dust of the street in spreading coins.",
		"steps under a hide awning as the rain comes down, and somewhere in the city the drums falter, then pick up again.",
	},
	["org.weather_change.w04.008"] = {
		"Thunder in the canyon! Sounds like the walls are arguing with the storm.",
		"Lightning on the rim. If I were a wind rider, I'd stay off the towers in this storm.",
	},
	["org.weather_change.w04.009"] = {
		"watches the storm light flicker along the canyon rim, each flash throwing the spiked outline of the walls across the street.",
		"pulls back from the open street as the storm breaks, the wind tearing at awnings and slamming loose shutters.",
	},
	["org.weather_change.w04.010"] = {
		"The sky has cleared, and the narrow strip of it above the canyon is crowded with stars.",
		"A clear night. The torches on the walls look small against all that sky.",
		"The air turns sharp and clear, and the stars come out over the rim one by one, like grunts taking their posts.",
	},
	["org.muse.w17.canyon.001"] = {
		"The canyon wall is striped like a cut loaf: red, darker red, a pale thin line, red again. Each stripe some age of the world, laid down long before anyone had a name for it.",
		"Look closely at the cliffs and they're layered, band over band, like hides stacked in a tannery. The rock had a long history before the orcs gave it a short one.",
	},
	["org.muse.w17.canyon.002"] = {
		"High on the cliff a single scrubby bush grows out of a crack, where nobody could ever water it. It looks as stubborn as everyone down here.",
		"A twist of thornbush clings to the canyon wall, far above any reach. It has chosen its ground the way the orcs chose Durotar.",
	},
	["org.muse.w17.canyon.003"] = {
		"glances up as a trickle of pebbles skitters down the canyon wall and bounces off a roof; nobody else even turns a head.",
		"flinches at a small rattle of stones falling from somewhere high on the cliff, and notices that nobody nearby so much as blinks.",
		"notes a little cascade of grit pouring off a ledge above the street, and moves a pace aside, as everyone around has done without thinking.",
	},
	["org.muse.w17.canyon.004"] = {
		"There's a dark seam on the rock where water weeps out drop by drop, and somebody has set a bucket under it. In Durotar, nobody wastes any.",
		"A wet stain on the canyon wall, green with moss at the edges, and a clay pot underneath catching what falls. Someone checks it often, by the look of the path.",
	},
	["org.muse.w17.canyon.005"] = {
		"Some of the city's rooms are dug straight into the rock. Step into one and the heat stays outside like a dog told to wait.",
		"The canyon keeps its cool on the inside. The rooms carved into the cliff feel like cellars, and the heat waits at the door, sulking.",
	},
	["org.muse.w17.canyon.006"] = {
		"Inside the canyon the rest of Durotar stops being real. No horizon, no open ground: just rock, and whatever the city has put against it.",
		"Down here everything stops at the cliffs. After the open red country outside, there's a strange relief in seeing where the edges are.",
		"Durotar outside is all horizon. In here the horizon is a wall, and I find I don't mind it.",
	},
	["org.muse.w17.canyon.007"] = {
		"A troll in the crowd swears the canyon is where some old loa dragged its tail. The orcs prefer to say they found it empty and kept it.",
		"Ask a Darkspear how this canyon was made and you'll hear about a loa in a hurry. Ask an orc and he'll shrug: it was here, so they used it.",
	},
	["org.muse.w17.canyon.008"] = {
		"spots a lizard lying flat on a warm ledge above the crowd, perfectly still, the only creature in Orgrimmar with nowhere to be.",
		"catches something small and scaly watching the street from a crack in the rock before it decides the city is too loud and vanishes.",
		"peers at a beetle trundling up the canyon wall with great purpose, unbothered by the whole Horde passing beneath it.",
	},
	["org.muse.w17.canyon.009"] = {
		"The steps cut into the rock are already worn into shallow bowls. A young city, and its feet have been busy.",
		"Every stair hewn in the canyon dips in the middle, polished by boots, hooves and claws. Stone keeps a record of traffic better than any clerk.",
	},
	["org.muse.w17.canyon.010"] = {
		"At night the canyon gives back the heat it hoarded. The walls stay warm long after the air has cooled, like a hearthstone after the fire.",
		"The air cools fast at night down here, but the rock doesn't. Lean on a wall and it's like leaning on an oven someone forgot.",
	},
	["org.muse.w17.canyon.011"] = {
		"squints up at a ledge high on the canyon wall, where a big untidy nest hangs over the city like a grudge.",
		"follows a bird of prey as it drops from its ledge on the canyon wall and sweeps over the roofs, unbothered by the noise.",
	},
	["org.muse.w17.canyon.012"] = {
		"This whole city's on a slope. Drop a coin and it rolls off downhill to someone luckier.",
		"Nothing in Orgrimmar sits level. Even the carts need a peon at the back, pulling against them and swearing.",
	},
	["org.muse.w17.canyon.013"] = {
		"Look at that cliff. It was standing there before anyone thought to put a spike on it.",
		"This canyon's older than every quarrel in the city put together. Strange comfort.",
	},
	["org.muse.w17.canyon.014"] = {
		"Sand sifts down from the rim like flour off a baker's table. The canyon takes the worst of it; out in open Durotar it would be flaying skin.",
		"The sand comes over the canyon edge in thin pale veils and settles on everything. The walls catch the rest, which is what walls are for.",
	},
	["org.muse.w17.canyon.015"] = {
		"follows a drop of rain as it gathers at the tip of a wall spike, hangs there, and falls; along the whole wall, the spikes are dripping in turn.",
		"notices that the rain has found every spike on the wall and hung a bead of water from each, a row of small lamps.",
	},
	["org.muse.w17.canyon.016"] = {
		"A storm over the canyon, and all I can think about is how many iron spikes this city has pointed at the sky.",
		"Lightning over the rim. The city bristles with iron points, and for once I'd rather they weren't there.",
	},
	["org.muse.w17.canyon.017"] = {
		"squints against the glare thrown up by the red rock, as if the canyon itself were staring back.",
		"pulls a hood forward against the light bouncing off every wall, until the whole street seems lit from below.",
	},
	["org.muse.w17.canyon.018"] = {
		"Red rock under my boots, and nobody's fence around it. Not the old world, not the camps. Ours, every hard stone of it.",
		"My people have lived on borrowed ground and behind other people's bars. This canyon is the first stone that answers to us.",
	},
	["org.muse.w17.cleft.001"] = {
		"Light reaches the Cleft of Shadow late and leaves it early, like a guest who knows what the hosts do for a living.",
		"The light in the Cleft of Shadow never stays long. It looks in, sees who's there, and finds somewhere better to be.",
		"Even the torches in the Cleft of Shadow burn low, as if they'd been asked to keep their voices down.",
	},
	["org.muse.w17.cleft.002"] = {
		"Somebody in the Cleft of Shadow sells poison by the vial and the antidote by the bottle. I have never seen both prices on the same board.",
		"Poisons at one stall, cures at the next, and the same pair of hands, I'd swear, behind both. The Cleft has a head for business.",
		"In the Cleft you pay for the poison up front and for the antidote whenever you can. They know you'll find the coin.",
	},
	["org.muse.w17.cleft.003"] = {
		"Rogues train in the Cleft of Shadow, and you would never know it to look. That, I suppose, is the lesson.",
		"The rogue trainers of the Cleft are somewhere close, I'm sure of it. I just haven't seen one, which is rather the point of them.",
	},
	["org.muse.w17.cleft.004"] = {
		"The orcs drank demon blood once and swore never again. Down in the Cleft, warlocks keep demons on a leash and swear they're the ones holding it.",
		"A people that nearly burned for the demons' bargains, and still the warlocks of the Cleft call them up. Carefully, they say. They always said carefully.",
		"Warlocks walk the Cleft with demons at heel, and every orc old enough to remember the blood gives them the same long look.",
	},
	["org.muse.w17.cleft.005"] = {
		"The Burning Blade crawled into the chasm under the Cleft to keep the old fire burning. The city goes on with its business one floor up, and keeps an eye on the stairs.",
		"Cultists of the Burning Blade under the city, still in love with the fire that nearly ate the orcs whole. Some debts are still being collected, a little below street level.",
		"Below the Cleft the Burning Blade still chant to their old masters. The rest of Orgrimmar sleeps soundly, mostly.",
	},
	["org.muse.w17.cleft.006"] = {
		"A grunt says troggs dig somewhere under the Cleft. If anything scratches under my boots, I'm leaving first and asking later.",
		"Troggs under the city, they tell me. Wonderful. Now every rattling pebble sounds like a claw.",
	},
	["org.muse.w17.cleft.007"] = {
		"lowers {g:his|her} voice without deciding to, as the walls of the Cleft of Shadow close in on either side.",
		"finds {g:himself|herself} speaking more softly on the way into the Cleft, as if the stone were taking notes.",
	},
	["org.muse.w17.cleft.008"] = {
		"stops to let a robed figure pass in the narrow way of the Cleft; the robe smells of sulfur and old paper.",
		"flattens against the rock as a hooded warlock sweeps by, trailing a smell of brimstone and candle wax.",
	},
	["org.muse.w17.cleft.009"] = {
		"A voidwalker drifts after its warlock through the Cleft, carrying nothing, saying nothing, and leaving a patch of cold where it passed.",
		"The voidwalkers of the Cleft have no faces to read. They follow their masters like shadows come loose, and the air turns chill behind them.",
		"A voidwalker waits outside a door in the Cleft like a patient dog made of smoke and bruises.",
	},
	["org.muse.w17.cleft.010"] = {
		"If anything down in the Cleft offers me a bargain, the answer is no. I'll say it before it finishes the sentence.",
		"Note to self: in the Cleft of Shadow, nod at nothing, sign nothing, and buy nothing that whispers.",
	},
	["org.muse.w17.cleft.011"] = {
		"Whoever lit the Cleft of Shadow put in exactly the torches they couldn't avoid. Not one more.",
		"Somebody's being thrifty with the torches down in the Cleft. For the atmosphere, I'm sure.",
		"Brought my own torch into the Cleft. The locals looked at me as if I'd brought a drum to a funeral.",
	},
	["org.muse.w17.cleft.012"] = {
		"The orcs who first turned to warlock magic lost a whole world to it. In the Cleft, a few of their grandchildren study it again, very carefully, with the door half open.",
		"A world was lost to warlock magic once, the elders say. The Cleft keeps the craft alive anyway, the way you'd keep a wolf: fed, chained, watched.",
	},
	["org.muse.w17.cleft.013"] = {
		"Sound goes into the Cleft and doesn't come out. Whatever is said down there, the rock keeps, like a pawnbroker who never sells.",
		"The Cleft swallows noise. A dropped coin, a curse, a footstep: the stone takes each one and gives nothing back.",
		"Down in the Cleft even my footsteps sound as though they're keeping a secret.",
	},
	["org.muse.w17.cleft.014"] = {
		"A goblin and a hooded orc are talking very quietly at the back of the Cleft. In Orgrimmar, quiet is the most suspicious sound there is.",
		"Two figures in the Cleft are speaking in whispers. Anywhere else that would be manners. In this city it's practically a confession.",
		"In the Cleft, the quieter the voices, the bigger the deal. Somebody back there is buying something enormous.",
	},
	["org.muse.w17.cleft.015"] = {
		"Warm air rises from the way down to Ragefire Chasm, smelling of sulfur and hot stone. The rock itself seems to be running a fever.",
		"Near the mouth of Ragefire Chasm the stone is warm to the touch, as if something large were sleeping with its back against the other side.",
		"The way down to Ragefire Chasm smells like a forge nobody tends. The heat comes up the stone in slow, uneven waves.",
	},
	["org.muse.w17.cleft.016"] = {
		"Here in the Cleft of Shadow nobody asks your name, and it would be rude to offer one.",
		"Names are not traded in the Cleft of Shadow. Faces barely are.",
		"Nobody in the Cleft of Shadow looks straight at anyone. It's considered good manners, and good sense.",
	},
	["org.muse.w17.cleft.017"] = {
		"The walls here are close enough to touch on both sides, and I have the feeling both sides are listening.",
		"Rock to the left, rock to the right, and every few steps a doorway with somebody in it pretending not to see me.",
	},
	["org.muse.w17.cleft.018"] = {
		"I asked the way three times in the Cleft and got three answers. All very polite. All different.",
		"Ask for directions in the Cleft and you'll get them, warmly given and slightly wrong. It's a test, I think.",
	},
	["org.muse.w17.cleft.019"] = {
		"Of all Orgrimmar, the Cleft of Shadow frightens me least. Down there everyone is a stranger with something to hide, and I fit right in.",
		"Strange comfort: in the Cleft nobody looks twice at a face they don't know. Everyone down there is wearing one.",
		"If a grunt has to stop me anywhere in Orgrimmar, let it be in the Cleft. Down there they ask fewer questions and expect worse answers.",
	},
	["org.muse.w17.cleft.020"] = {
		"looks down the dark slope toward Ragefire Chasm, where a dull red glow swells and fades like something turning over in its sleep.",
		"lingers at the head of the way down to Ragefire Chasm, watching a red light come and go on the rock below.",
		"feels the heat rising from the way down to Ragefire Chasm on {g:his|her} face, and steps back from the edge.",
	},
	["org.muse.w17.cleft.021"] = {
		"Whoever owns the felhunter sniffing my boots: lovely beast. Call it off.",
		"That felhunter's followed me all the way from the bottom of the Cleft. Does it want something, or just me?",
	},
	["org.muse.w17.crowd.001"] = {
		"In Orgrimmar you walk shoulder first and apologize never. It took me a while to learn it. Now I do it without thinking, and nobody minds.",
		"The trick to these streets is to lead with a shoulder and keep your eyes ahead. Say sorry and the crowd takes you for weak, or lost.",
	},
	["org.muse.w17.crowd.002"] = {
		"A crowd in this city comes in three heights: tauren horns up top, orc shoulders in the middle, and goblins somewhere about belt level, swearing.",
		"Looking across the press I see horns, then shoulders, then a gap where something short and loud is pushing through at knee height. That'll be a goblin.",
		"From where I stand the crowd is a landscape: horns for peaks, shoulders for hills, and somewhere down in the valleys a goblin elbowing shins.",
	},
	["org.muse.w17.crowd.003"] = {
		"is carried a dozen steps the wrong way by the crowd before managing to turn round, and starts over with a sigh.",
		"gets swept up by a press of bodies, gives up fighting it for a moment, and lets the current decide.",
	},
	["org.muse.w17.crowd.004"] = {
		"I've picked up a dozen words of the troll tongue just by standing in this crowd. Half of them I'd better never use in front of a troll.",
		"The crowd teaches languages for free. I can say 'move' in Orcish, in Taur-ahe and in the troll tongue now, and three ruder things besides.",
		"Every argument in this press is a lesson in a language I didn't ask to learn. My Orcish curses are coming along nicely.",
	},
	["org.muse.w17.crowd.005"] = {
		"Elbows out, then. That seems to be the local custom.",
		"Lead with the elbows, I'm told. When in Orgrimmar.",
	},
	["org.muse.w17.crowd.006"] = {
		"In a crowd this thick I keep one hand on my purse. Nobody here is a thief, of course. My purse just doesn't know that.",
		"Hand on the purse, eyes ahead. I trust the people of Orgrimmar; it's my purse that's the nervous type.",
		"Every time the crush tightens, my hand finds my purse on its own. Not that I suspect anyone. My hand has simply met crowds before.",
	},
	["org.muse.w17.crowd.007"] = {
		"A Forsaken stands perfectly still at the edge of the crowd, watching. Of everyone in Orgrimmar, the dead seem the only ones in no hurry at all.",
		"The crowd swirls around a Forsaken who has simply stopped to look at something. Nobody bumps him. People walk around the stillness as if it were a pillar.",
	},
	["org.muse.w17.crowd.008"] = {
		"Walking through the crowd I catch one word of each life: a debt, a new cub, a quarrel with a brother, a wolf gone lame. A hundred stories, and none of them mine.",
		"Scraps of other people's days drift past in the press: a wedding next week, a sick uncle, a smith who cheated somebody. I carry them a few steps and let them go.",
		"The crowd leaves its stories on me like dust: half a complaint, half a joke, a name called out and never answered. I keep none of them.",
	},
	["org.muse.w17.crowd.009"] = {
		"When I lose my bearings in the crowd I steer by the nearest tauren. They stand above it like a hill, and they move about as fast.",
		"A tauren in a crowd is better than a signpost. Fix your eyes on the horns and follow; you'll get somewhere eventually, slowly.",
	},
	["org.muse.w17.crowd.010"] = {
		"Everybody in this crowd walks like they're late for something important. I wish one of them would tell me what.",
		"So many people in such a hurry. There must be a very important appointment somewhere in this city, and nobody sent me the invitation.",
		"Where is everyone going in such a rush? If it's free food, I want in.",
	},
	["org.muse.w17.crowd.011"] = {
		"Orcs stride, trolls lope, tauren take one step for every three of a goblin's, and the Forsaken move as if they'd already counted every stone. The crowd keeps a dozen rhythms at once.",
		"Watch the feet in this crowd and you can tell the peoples apart without looking up: the long troll lope, the heavy orc stride, the slow tread of hooves.",
	},
	["org.muse.w17.crowd.012"] = {
		"Every people of the Horde in one press of bodies, shoving and cursing in five tongues, and nobody reaches for a weapon. Not so long ago that would have been called a battle.",
		"Shoulder to shoulder with every people of the Horde, and my elbow in a tauren's ribs. Nobody minds. That's what being one side looks like, up close.",
	},
	["org.muse.w17.crowd.013"] = {
		"My best cloak here is the crowd. As long as everyone is busy shoving, nobody stops to wonder what I am.",
		"I keep to the thickest part of the press. In a crush like this nobody looks at faces, only at elbows.",
	},
	["org.muse.w17.crowd.014"] = {
		"One more heel trodden on and I start charging by the step.",
		"Somebody's been standing on my foot for a while now. Feel free to move. Any time.",
		"Whose hoof is that on my toes? No hurry. I wasn't using them.",
	},
	["org.muse.w17.crowd.015"] = {
		"crouches to help a goblin gather a spill of bolts and washers from under the passing feet, and is thanked with a long, suspicious look.",
		"stoops to scoop up a handful of spilled nails for a goblin trader, who snatches them back, checks the crowd for accomplices, and only then mutters thanks.",
	},
	["org.muse.w17.crowd.016"] = {
		"ducks with everyone else as a peon carrying a long plank turns to answer someone, the whole ring of the crowd bobbing down at once as if they'd rehearsed it.",
		"drops {g:his|her} head in time with a dozen others as a beam swings round over the crowd, its bearer quite unaware of the danger.",
	},
	["org.muse.w17.crowd.017"] = {
		"Heard from a little way off, the crowd sounds like surf on the Durotar coast: no voice of its own, just the long roar of everyone at once.",
		"Step back from the press and the voices blur into one sound, rising and falling like the sea against the rocks of Durotar.",
	},
	["org.muse.w17.crowd.018"] = {
		"is overtaken by a troll balancing a basket of fish on her head, who threads the whole crowd without once raising a hand to it.",
		"turns to watch a troll woman glide through the press with a heavy basket on her head, steady as a lantern on a hook.",
	},
	["org.muse.w17.crowd.019"] = {
		"Empty the streets and Orgrimmar would be a fortress in a canyon. It's the crowd, pushing and bargaining and quarreling, that turns it into a city.",
		"Walls make a stronghold. It takes this jostling, shouting throng to make a city of one.",
		"Without the press of people, this would be stone and iron and nothing more. The crowd is the mortar no mason laid.",
	},
	["org.muse.w17.crowd.020"] = {
		"If everyone in this crowd stopped talking at once, I think the walls would fall over from the shock.",
		"Imagine this lot all going quiet together. The canyon would think it had gone deaf.",
	},
	["org.muse.w17.crowd.021"] = {
		"watches the crowd scatter for the nearest awning at the first fat drops, then stand there crammed together, laughing at the strangeness of rain.",
		"ducks under a sagging awning with half a dozen strangers as the rain comes down, and listens to them all agree it never rains here.",
	},
	["org.muse.w17.crowd.022"] = {
		"sets the pack down for a moment under a roof, out of the crush, and listens to the city's trade carry on beyond the door.",
		"takes a moment out of the press, indoors, and lets the noise of the crowd become something that happens to other people.",
	},
	["org.muse.w17.crowd.023"] = {
		"is jostled from three sides at once and simply stops, letting the crowd sort itself out all around.",
		"takes three elbows in quick succession, sighs, and decides to wait for a gap that never comes.",
	},
	["org.muse.w17.crowd.024"] = {
		"gives way to a tauren mother leading three calves through the press in a solemn little line.",
		"smiles without meaning to as a row of tauren young follows its mother through the crowd, each holding the tail of the one in front.",
	},
	["org.muse.w17.drag.001"] = {
		"Here in the Drag you can pick out the dyers from across the street: blue to the elbow, and not the least bit sorry about it.",
		"The dyers of the Drag wear their trade on their arms, stained to the elbow. One of them waves at me with a hand the color of deep water.",
	},
	["org.muse.w17.drag.002"] = {
		"pauses by a leatherworker scraping a stretched hide in long, even strokes, the sound as steady as a broom on stone.",
		"stops for a moment to watch a hide being scraped clean on its frame, stroke after patient stroke.",
		"lingers beside a tanner's frame, where a hide is being worked smooth with a blunt blade and no hurry at all.",
	},
	["org.muse.w17.drag.003"] = {
		"Half the shops along the Drag hang a picture instead of a word: an anvil, a needle, a flask. A sign anyone can read, whatever tongue they grew up speaking.",
		"No lettering over most doors in the Drag: a painted hammer, a spool, a bottle. Orc, troll and tauren all read it the same way.",
		"The signs of the Drag are drawings, not writing. A boot means boots, a pot means stew, and nobody has to argue about the spelling.",
	},
	["org.muse.w17.drag.004"] = {
		"First rule of the Drag: pick it up and you've already started haggling.",
		"Don't touch anything here unless you mean to argue about it. In the Drag, a hand on the goods is an opening offer.",
	},
	["org.muse.w17.drag.005"] = {
		"An alchemist's apprentice hurries up the street holding a cracked flask at arm's length, and the whole Drag steps aside without being asked.",
		"A youngster from one of the potion shops runs past with something fizzing in a flask held as far from the face as an arm allows. Nobody needs telling to make way.",
		"Something in a cracked flask is smoking in an apprentice's outstretched hand. I've never seen this street clear so fast.",
	},
	["org.muse.w17.drag.006"] = {
		"A cook in the Drag swears her stewpot hasn't been empty since the walls went up. She just keeps adding. I don't ask what's at the bottom.",
		"There's a stew in the Drag that the cook claims has been simmering since the city was founded, topped up daily and never emptied. It tastes of history, and a little of boot.",
	},
	["org.muse.w17.drag.007"] = {
		"runs a hand along a rack of finished belts and straps hung outside a shop, setting the buckles chiming like small bells.",
		"brushes past a row of harness hung at a shop door, and a dozen buckles knock together with a sound like loose coin.",
	},
	["org.muse.w17.drag.008"] = {
		"I could walk the Drag with my eyes shut and still know where I was: the rasp of a file, a mallet thudding on leather, iron hissing in the quench, a needle seller droning the same three words.",
		"Every shop on the Drag has its own sound. A file's rasp, a mallet on wet leather, the hiss of hot iron dunked in a barrel. Blindfolded, I'd still find my way by ear.",
	},
	["org.muse.w17.drag.009"] = {
		"A smith's boy sweeps the iron filings into a pail and sells them back to the smith by weight. That one will own half the Drag someday.",
		"I watched an apprentice gather the filings off a forge floor and charge his own master for them. The smith paid, too, and looked proud.",
	},
	["org.muse.w17.drag.010"] = {
		"In one doorway of the Drag an old orc works with a hammer whose handle has worn to the shape of his grip. He'd sooner sell the shop than that hammer.",
		"There's an old smith off the Drag whose hammer handle is polished dark and dented where his fingers go. Tools outlast their masters, he says, if the masters are careful.",
		"One old craftsman in the Drag has used the same hammer so long that the wood has taken the print of his hand. He calls it the only partner who never cheated him.",
	},
	["org.muse.w17.drag.011"] = {
		"Bundles of peacebloom and earthroot hang drying in a doorway along the Drag, and for a few steps the air smells green, like somewhere else entirely.",
		"An herb seller in the Drag has strung silverleaf across the doorway to dry. Walking past it is like a glimpse of a meadow in the middle of all this iron.",
	},
	["org.muse.w17.drag.012"] = {
		"Hear that? Somebody in the Drag is hammering a dent out of something, and the dent is winning.",
		"That clanging down the Drag has been going on for a while now. Whatever the smith is fighting, it's ahead on points.",
	},
	["org.muse.w17.drag.013"] = {
		"Some of the tanners in the Drag still cure hides the old way, with smoke and patience, the way the clans did before the camps. The young ones roll their eyes, and miss nothing.",
		"An old tanner off the Drag works hides the way his clan did in the days before the camps. He says the young have quick hands and short memories. He teaches them anyway.",
		"Smoke-cured hides, done the slow way the clans knew before the internment camps. A few old tanners kept the craft alive in their heads all those years behind the fences.",
	},
	["org.muse.w17.drag.014"] = {
		"A tailor here is measuring a tauren for a cloak, standing on a crate and muttering numbers. The tauren holds very still, patient as a cliff.",
		"In a shop off the Drag a tailor climbs onto a stool to get a cord around a tauren's shoulders, then climbs down and asks for a longer cord.",
	},
	["org.muse.w17.drag.015"] = {
		"watches sparks spray from a grindstone where a grunt is having the edge put back on an axe, the wheel whining under the steel.",
		"stops beside a grinding wheel as it bites into an axe, and leans back from the fan of orange sparks.",
		"waits out a shower of sparks from a grindstone, where an axe is being given back its bite one turn at a time.",
	},
	["org.muse.w17.drag.016"] = {
		"The shops of the Drag hang their good wares out front and keep their best ones in the back, for whoever thinks to ask. Most never think to ask.",
		"What hangs outside a shop in the Drag is bait. The real work is under the counter, wrapped in cloth, waiting for someone who knows the right question.",
	},
	["org.muse.w17.drag.017"] = {
		"Who sells thread in this city that doesn't snap? Asking on behalf of my trousers.",
		"I need a tailor, quickly, and one who doesn't laugh. In that order.",
		"Point me at the nearest needle and thread. And nobody look down.",
	},
	["org.muse.w17.drag.018"] = {
		"The crafters here eat at their benches, a heel of bread in one hand and the work in the other. A meal in the Drag is something you do between stitches.",
		"Nobody in the Drag stops to eat. They chew over the work, crumbs falling into the leather, and wipe their fingers on their aprons.",
	},
	["org.muse.w17.drag.019"] = {
		"Half the shops along the Drag keep an old wolf dozing across the threshold. Cheaper than a lock, and it can't be bribed with anything but meat.",
		"The shopkeepers of the Drag don't trust locks much. They trust the gray-muzzled wolf lying in the doorway, one eye half open.",
		"Every other doorway in the Drag has a wolf asleep across it. Step over it politely. The wolf is the shop's real owner, and it knows it.",
	},
	["org.muse.w17.drag.020"] = {
		"Ask three people why it's called the Drag and you get three answers. The way it winds, says a grunt. The way it drags the coin out of you, says a goblin. The tanner just points at a hide being hauled along.",
		"Nobody agrees on the name. A peon swears the Drag is named for the timber they hauled through it when the city was young; a trader swears it's named for what it does to a purse.",
	},
	["org.muse.w17.drag.021"] = {
		"Thunder rolls down the canyon and every trader in the city hauls the goods in at once. For a moment the only things left out in the open are the forges and me.",
		"The storm cracks over the walls, and stall after stall folds up like a hand closing. The smiths don't even look up.",
	},
	["org.muse.w17.drag.022"] = {
		"stops at an open workshop where a leatherworker is punching holes in a belt, one sharp tap at a time, and catches {g:himself|herself} counting them.",
		"watches an awl go through thick leather with a crisp little knock, over and over, until the belt has holes enough for any waist in the city.",
	},
	["org.muse.w17.drag.023"] = {
		"holds {g:his|her} nose passing the tanners' vats, as nearly everyone does, while the tanners themselves look on, unbothered.",
		"hurries past a tannery doorway with a sleeve over the face, and hears an old tanner chuckle behind.",
	},
	["org.muse.w17.folk.001"] = {
		"watches two grunts change places at a post: a nod, a word too low to hear, and the one going off duty rolls his neck until it cracks.",
		"notices a grunt hand over his watch to another with nothing but a grunt and a jerk of the chin. Clearly that covers everything.",
		"follows a fresh grunt taking over a post while the tired one lingers to point at something down the way, then shrugs and goes.",
	},
	["org.muse.w17.folk.002"] = {
		"keeps an eye on a grunt eating on duty, bowl in one fist and axe in the other, eyes never leaving the crowd, chewing as if that too were part of the watch.",
		"follows with some admiration as a grunt finishes an entire bowl of stew without once looking down at it.",
	},
	["org.muse.w17.folk.003"] = {
		"A small orc stands in a doorway with a stick for an axe and asks everyone for the password. The grunts give it, very gravely, and are let through.",
		"Some child has made herself guard of a hut door and demands a password from every passerby. A real grunt just murmured one. She approved.",
		"A child with a stick is holding a doorway against the whole city. Nobody gets past without a password, and the grunts play along without a smile.",
	},
	["org.muse.w17.folk.004"] = {
		"watches a wolf handler walk a string of wolves through the crowd, talking to them low and steady, both forearms laced with old bite scars.",
		"steps around a wolf handler who has stopped to scratch one of her animals behind the ears; the scars on her arms suggest it was not always so friendly.",
	},
	["org.muse.w17.folk.005"] = {
		"A tauren fresh from Mulgore stands looking up at the walls the way you'd look at a cliff someone built on purpose.",
		"You can spot the tauren who came in from the plains: they keep looking up, as if the city might fall on them, politely.",
		"The plains folk always stop at least once to stare at all this stone. Mulgore has hills, but nobody there ever nailed iron to one.",
	},
	["org.muse.w17.folk.006"] = {
		"Messengers run the city, mostly young ones, weaving between legs with a folded scrap of hide in a fist. Half the business of Orgrimmar travels at their speed.",
		"A runner nearly knocks me over, shouts something that might be sorry, and is gone toward the far valleys. Somebody's message is in a hurry.",
		"The city's news goes by foot: quick young runners from valley to valley, never walking when they can sprint.",
	},
	["org.muse.w17.folk.007"] = {
		"Strength to the watch. Don't get up.",
		"Keep the gate, grunt. I'll keep out of trouble. Mostly.",
		"Good watch to you. Anything I should know before I go and do something foolish?",
	},
	["org.muse.w17.folk.008"] = {
		"An old orc with one hand sits against a wall, telling a battle to anyone who slows down. By the third listener the enemy has doubled.",
		"By the road a one-handed veteran tells his war to passing children. They correct him on the details. He lets them.",
	},
	["org.muse.w17.folk.009"] = {
		"makes way for an orc woman hauling a steaming pot toward the gate, where the grunts on watch straighten up the moment they smell it.",
		"watches a cook carry a pot of stew to the grunts on watch, who stop being terrifying for exactly as long as it takes to eat.",
	},
	["org.muse.w17.folk.010"] = {
		"Give anyone an hour in Orgrimmar and you can see it take: the voice gets louder, the elbows wider, the walk a bit more like a grunt's.",
		"Travelers come in through the gate speaking softly and leave shouting. The city teaches that one for free.",
		"An hour in this city and even a mumbler starts to bellow. I can hear it happening to me.",
	},
	["org.muse.w17.folk.011"] = {
		"passes three peons sharing a bench and a single waterskin, grumbling about their overseer in perfect agreement.",
		"edges past a row of resting peons, shoulders against one wall and feet against the other, their complaints passed down the line like a pipe.",
	},
	["org.muse.w17.folk.012"] = {
		"Off duty, the grunts are other people: armor unbuckled, laughing, arm-wrestling on an upturned barrel. Back on duty, and the face shuts like a gate.",
		"A grunt with a face like a cliff is laughing at a table so hard the table needs holding. Off duty, apparently, it's allowed.",
	},
	["org.muse.w17.folk.013"] = {
		"Easy there, small one. That wolf has had a long day too.",
		"Watch where you run, little warrior. Grunts don't move aside; you'll bounce.",
	},
	["org.muse.w17.folk.014"] = {
		"steps aside for an orc mother crossing with a baby on one hip and a sack of iron on the other, who slows for nobody.",
		"slows to watch a woman with a child tied on her back split firewood by her door, one clean stroke after another, while the child sleeps through all of it.",
	},
	["org.muse.w17.folk.015"] = {
		"sees a grunt scoop up a tumbled child, set it back on its feet and walk on, without breaking stride or changing face.",
		"notices a child trip in front of a patrol; the nearest grunt lifts it upright by the collar and the patrol never misses a step.",
	},
	["org.muse.w17.folk.016"] = {
		"The Forsaken who come down to Orgrimmar keep their hoods up and their business short. They seem to find the noise as strange as everyone finds them.",
		"A Forsaken sits on a step in the middle of all this heat and life, quite still, watching it the way you'd watch a fire you don't intend to touch.",
	},
	["org.muse.w17.folk.017"] = {
		"Water is worth hauling here. The carriers go by bent under yokes of sloshing buckets, and nobody jostles them, not even the grunts.",
		"Of all the people in the city, the water carriers get the most room. Spill a bucket in Durotar and you've spilled something real.",
	},
	["org.muse.w17.folk.018"] = {
		"Every grunt in this city wears the same face. I think they pass it along at the change of watch.",
		"I've counted a dozen grunts and one expression between them. Very thrifty.",
	},
	["org.muse.w17.folk.019"] = {
		"A tauren calf and two small orcs are playing in the dust, a game whose rules all three seem to be inventing as they go. Nobody has told them the Horde is complicated.",
		"Children of three peoples chasing one another round a post, shrieking in a mix of tongues. Whatever pacts the grown-ups made, these ones mean it.",
	},
	["org.muse.w17.haggle.001"] = {
		"In Orgrimmar even the bargains growl at you.",
		"Even the good deals in this city bare their teeth first.",
	},
	["org.muse.w17.haggle.002"] = {
		"I spent the better part of an hour haggling two copper off a price, then bought a drink worth three to celebrate. Trade is a strange art.",
		"Two copper saved after a long, hard argument. I marked the victory with a mug that cost me three. My purse and I are still discussing it.",
	},
	["org.muse.w17.haggle.003"] = {
		"A goblin sold me a map of the city. Half the streets on it run where the goblin wishes they did, and every shop marked belongs to his family.",
		"My new map of Orgrimmar, goblin-drawn, shows a shortcut through solid rock and six shops owned by the same family. Worth every copper, as a joke.",
	},
	["org.muse.w17.haggle.004"] = {
		"Done! Wait. Was I buying or selling?",
		"Deal. Hang on. Which of us was paying?",
	},
	["org.muse.w17.haggle.005"] = {
		"Every merchant in Orgrimmar has a cousin who could do it cheaper. The cousin is always out.",
		"Ask any trader here for a better price and you'll hear about the cousin who sells for less. Nobody has ever met the cousin.",
		"Behind every stall in this city stands a cousin, cheaper and better and never in. I'm starting to think it's the same cousin.",
	},
	["org.muse.w17.haggle.006"] = {
		"The traders here buy my old boots for a copper and sell me water for ten. Somewhere a goblin worked that out on a slate and laughed until he fell over.",
		"Sell a pair of boots: one copper. Buy a skin of water: ten. I don't know who sets the prices in this city, but they've never been thirsty.",
	},
	["org.muse.w17.haggle.007"] = {
		"I came in for a bag. I'm leaving with a bag and everything there is to know about the tanner's knees.",
		"All I wanted was a bag. I got the bag, and half an hour on the leatherworker's bad back, free of charge.",
	},
	["org.muse.w17.haggle.008"] = {
		"turns out both empty pockets with great ceremony as a hawker's eye falls this way, and walks on in peace.",
		"meets a stallkeeper's hopeful look with a sad shake of an empty purse, and is let off with a grunt of sympathy.",
	},
	["org.muse.w17.haggle.009"] = {
		"Is there anything in this city that isn't for sale? No, don't answer. You'll quote me a price.",
		"I asked what wasn't for sale in Orgrimmar. The goblin asked how much I was offering.",
	},
	["org.muse.w17.haggle.010"] = {
		"Haggling with a tauren is very restful. He names a price, I name mine, and then we both wait to see who grows old first.",
		"A tauren trader doesn't argue. He just looks at you, kindly, until your offer climbs up to meet his on its own.",
		"I tried to beat down a tauren leatherworker. He listened to every word, nodded, and named the same price, as calm as grass.",
	},
	["org.muse.w17.haggle.011"] = {
		"Somebody has listed a plain linen shirt at the auction house for the price of a good riding wolf. A joke, or a very hopeful tailor.",
		"At the auction house a single linen shirt is up for a small fortune. I've checked twice now to see whether anyone bites.",
	},
	["org.muse.w17.haggle.012"] = {
		"My purse walked into this city fat and cheerful. Look at the poor thing now.",
		"This purse was heavy at the gate. Orgrimmar has been very attentive to it.",
		"I had coin when I got here. I remember it fondly.",
	},
	["org.muse.w17.haggle.013"] = {
		"By the merchants' own account, every hide in this city is the toughest in Kalimdor and every axe the sharpest. Kalimdor must be very small.",
		"I've now been shown the finest belt in all Kalimdor four times, at four different stalls. Each was finer than the last, apparently.",
	},
	["org.muse.w17.haggle.014"] = {
		"accepts a sniff of the goods from an eager trader's jar, and hands it straight back with watering eyes.",
		"leans in to smell a pot of salve held out by a trader, and recoils sharply, while the trader nods with pride.",
	},
	["org.muse.w17.haggle.015"] = {
		"The inn charges good silver for a bowl of stew and throws in the brawl for nothing. Fair, I suppose.",
		"A bowl of stew at the inn costs more than it should. The fistfight at the next table is included in the price.",
	},
	["org.muse.w17.haggle.016"] = {
		"Just now a goblin tried to sell me a cloak exactly like mine. Turns out it was mine. I'd left it on a hook.",
		"That goblin was halfway through selling me my own cloak before either of us noticed. He still wanted a fee for finding it.",
	},
	["org.muse.w17.haggle.017"] = {
		"Everything in this market is fresh, to hear the hawkers: freshly tanned, freshly forged, freshly caught. My freshly baked loaf could have held a door shut.",
		"Fresh bread, the seller swore. I've since used it to drive a tent peg. It did very well.",
	},
	["org.muse.w17.haggle.018"] = {
		"Somebody in this crowd owes me money. I don't know who. It's just the odds.",
		"With this many people about, at least one of them must owe me silver. I'll start asking at random.",
	},
	["org.muse.w17.haggle.019"] = {
		"listens politely to a merchant's long tale about a famous hunt, and realizes only at the end that it was a sales pitch for a belt.",
		"nods through a trader's story about an old warrior and his lucky charm, and finds the charm being pressed into {g:his|her} palm at the end of it.",
	},
	["org.muse.w17.haggle.020"] = {
		"The flight master's prices are the only thing in this city that climbs faster than the wind riders.",
		"Ask the flight master for a price and you'll understand why the wind riders always look so pleased with themselves.",
	},
	["org.muse.w17.haggle.021"] = {
		"is offered a lucky charm by one trader and a charm against bad luck by the next, and on principle buys neither.",
		"politely declines a charm, then a cheaper charm, then a charm said to make other charms work, and escapes at last.",
	},
	["org.muse.w17.history.001"] = {
		"Ask the grunts at the gate and they'll tell how the Horde crossed the sea in ships taken from the humans, packed so tight half of them never saw the water.",
		"The orcs came to Kalimdor by sea, the veterans say, in stolen hulls, sick as dogs and singing anyway. Not one of them had ever been a sailor.",
		"A veteran at the inn swears he spent the whole crossing below decks with a goat and a troll. He won't say which was worse company.",
	},
	["org.muse.w17.history.002"] = {
		"In the camps my people forgot how to want anything. That's the part nobody puts in the songs. This city is what wanting looks like, once it wakes.",
		"Fences, gray days, guards who were bored of them. The camps didn't kill orcs; they emptied them. Every loud street here is that emptiness filled up.",
	},
	["org.muse.w17.history.003"] = {
		"Thrall could have put his own name over the gate. He gave the city to Orgrim instead, the old Warchief who taught him and died before it was built.",
		"A Warchief who names his capital after his teacher instead of himself. Not many rulers would pass up a chance like that.",
		"The name on this city belongs to a dead orc, by the choice of a living one. That small modesty says more about Thrall than his armor does.",
	},
	["org.muse.w17.history.004"] = {
		"Before there were walls, the ones who were here at the start say, there was a ditch, a row of sharpened stakes and a lot of orcs taking turns not sleeping.",
		"An orc who was here at the beginning will tell you about tents in the dust, a stake fence and a well that went dry twice. The walls came much later.",
	},
	["org.muse.w17.history.005"] = {
		"Kul Tiras sent a fleet to burn Durotar while these walls were barely raised, the grunts still say. Tiragarde Keep still squats on the coast to remind them.",
		"Hardly had the city found its feet when ships from Kul Tiras came for it, the veterans say. They talk about it the way you'd talk about a fever that broke.",
	},
	["org.muse.w17.history.006"] = {
		"Not long ago orcs, humans and elves held one mountain together against the demons. In Orgrimmar that story gets told quietly, and quickly, and never to a crowd.",
		"Hyjal is a name nobody here quite knows what to do with. The Horde fought beside the Alliance there, and the city prefers to remember the fighting, not the company.",
	},
	["org.muse.w17.history.007"] = {
		"The Darkspear tell it plainly: the orcs found them on their islands in a bad way, stayed to fight, and took them along. The trolls have been repaying the favor loudly ever since.",
		"Ask a troll why the Darkspear follow an orc Warchief and you get a long story with sea witches in it, and a short ending: he stayed when he didn't have to.",
	},
	["org.muse.w17.history.008"] = {
		"The tauren say the orcs fought the centaur at their side when the herds were hunted across the plains, and Cairne does not forget a debt. Thunder Bluff is the proof.",
		"Cairne's people walk these streets like old friends of the family, and in a way they are. The orcs stood by them when the centaur were at their heels.",
	},
	["org.muse.w17.history.009"] = {
		"Pick ground nobody wants, the elders say, and nobody comes to take it from you. That's Durotar: chosen for its thorns.",
		"Red rock, thin soil, scorpids under every stone. Thrall chose this country with open eyes, the grunts say, because nobody else would ever covet it.",
		"Nobody fights a war for Durotar, the elders like to say. That was rather the point.",
	},
	["org.muse.w17.history.010"] = {
		"This city's younger than most of the grunts guarding it. Bear that in mind when it gets pompous.",
		"Orgrimmar has fewer years than the average grunt at the gate. It just carries itself older.",
		"Most of the folk on these streets remember when this canyon was empty. The city acts as if it's been here forever.",
	},
	["org.muse.w17.history.011"] = {
		"slows beside an old orc telling a ring of children about the camps; for once, none of them is fidgeting.",
		"lingers at the edge of a small crowd listening to a veteran describe the crossing of the sea, his hands showing the size of the waves.",
	},
	["org.muse.w17.history.012"] = {
		"Orgrim never saw this city. I hope someone tells him anyway.",
		"Doomhammer's city. He'd have hated the crowds and loved the walls, I'd wager.",
		"To Orgrim, who'd have grumbled about the name and been secretly pleased.",
	},
	["org.muse.w17.history.013"] = {
		"Pens and fences, not so long ago. Now forges and a bank and a gate we hold ourselves. When the noise tires me, I think of what the quiet in the camps must have sounded like.",
		"The humans thought we'd forget how to build. A few years out of the camps, and here stands Orgrimmar. I hope word of it reaches Stormwind.",
	},
	["org.muse.w17.history.014"] = {
		"The old clans still matter to the elders: a Warsong will tell you so, and a Frostwolf will tell you quieter. Their children just say Orgrimmar.",
		"Ask an old orc his clan and you'll get a name and a story. Ask a young one and you'll get the name of a valley.",
	},
	["org.muse.w17.history.015"] = {
		"The first thing they built in this canyon was a forge, a grunt told me, before any wall. You can't make a wall without nails.",
		"According to a peon who swears he was there, the first fire lit in Orgrimmar was for iron and the second for supper. He's still bitter about the order.",
	},
	["org.muse.w17.history.016"] = {
		"Not bad, for people who were behind fences a few years back.",
		"Look what they made out of a canyon and a grudge.",
		"All this from a handful of freed orcs and a bad piece of land. Remarkable.",
	},
	["org.muse.w17.history.017"] = {
		"stands a moment looking along the walls, as if trying to picture the canyon bare, before anyone had laid a single stone.",
		"looks about at the stone and timber of the city as though trying to see it as the first orcs did: an empty crack in a hard country.",
	},
	["org.muse.w17.history.018"] = {
		"The elders mention the old world beyond the Dark Portal the way you'd mention a dead friend: seldom, and never loudly. Orgrimmar is what they built instead of grieving.",
		"There was a world before this one, the old orcs say, and it's gone. They don't describe it much. They point at the walls instead.",
	},
	["org.muse.w17.history.019"] = {
		"Thrall found a crack in the ground and made it a capital. Kings have done less with more.",
		"A canyon, a few freed clans and one stubborn Warchief. That's the whole founding of Orgrimmar, and it was enough.",
	},
	["org.muse.w17.hold.001"] = {
		"Inside Grommash Hold every footstep is heard twice: once on the floor, and once by the Kor'kron.",
		"Walk into Grommash Hold and your steps announce you long before anyone else does. The Kor'kron have already made up their minds.",
		"Every boot that crosses the floor of Grommash Hold is weighed by a dozen pairs of eyes. Mine feel heavier than usual.",
	},
	["org.muse.w17.hold.002"] = {
		"No curtain, no antechamber, no clerk with a ledger. The Warchief sits where anyone who walks in can see him, at the end of a long walk under every guard's eye.",
		"The throne of Grommash Hold stands in plain view. To reach the Warchief you cross the whole floor under the eyes of his guard, and that walk is the only gate.",
	},
	["org.muse.w17.hold.003"] = {
		"passes the petitioners waiting outside Grommash Hold: a peon with a grievance, a goblin with a contract, a tauren with all the time in the world.",
		"walks along the line waiting for the Warchief's ear, a chieftain, a widow, a trader with a sore tooth, and finds no two of them from the same people.",
	},
	["org.muse.w17.hold.004"] = {
		"Thrall still goes by the name his captors gave him. He has made it mean something else entirely, and nobody can take that from him.",
		"Thrall: a slave's name, given by the humans who held him. He carries it at the head of the Horde, and by now it sounds like a warning to anyone who would try chains again.",
		"His captors meant the name as a leash. He kept it, and now chieftains bow to it.",
	},
	["org.muse.w17.hold.005"] = {
		"Grom Hellscream died in the forests of Ashenvale with a demon lord fallen at his feet, far from any hall. Thrall gave him one anyway, and my people walk into it every day.",
		"The hall bears the name of an orc who never saw it. Grom fell in Ashenvale freeing us, and the Hold keeps the name ready until we deserve it.",
	},
	["org.muse.w17.hold.006"] = {
		"Keep your voice down near the Hold. The Kor'kron have heard every joke already, and laughed at none of them.",
		"Not so loud. We're in earshot of the Warchief's hall, and I'd rather be remembered for something else.",
	},
	["org.muse.w17.hold.007"] = {
		"pauses where the path climbs toward Grommash Hold to let a pair of Kor'kron pass, their armor making no more noise than it has to.",
		"steps aside for a Kor'kron patrol on the slope below the Warchief's hall, and receives a look that weighs and dismisses in a single glance.",
	},
	["org.muse.w17.hold.008"] = {
		"stands at a respectful distance from the throne, hands kept in plain sight, as the Kor'kron seem to prefer.",
		"keeps to the edge of the great hall, out of the petitioners' way, and looks up at the beams lost in the smoke under the roof.",
	},
	["org.muse.w17.hold.009"] = {
		"The Warchief hears out peons and chieftains in the same hall, from the same seat. I've heard he gives the peons longer; they have less practice at being brief.",
		"Chieftains and peons wait in the same line outside the Hold. Nobody in Orgrimmar finds this strange anymore, which is the strangest thing about it.",
	},
	["org.muse.w17.hold.010"] = {
		"Whatever is decided in Grommash Hold reaches the edge of Durotar before the messenger's wolf has cooled down.",
		"A word spoken in the Hold travels faster than any rider. By the time it reaches the Barrens, it has grown teeth.",
		"Thrall decides in the Hold, and by the next caravan the whole of Durotar has an opinion.",
	},
	["org.muse.w17.hold.011"] = {
		"The Kor'kron never look at the Warchief. They look at everyone else, all at once, and somehow at me in particular.",
		"A Kor'kron's eyes are never on the Warchief. They're on your hands, your belt, your face, and then your hands once more.",
	},
	["org.muse.w17.hold.012"] = {
		"May the hall of Grommash never fall silent for lack of voices.",
		"Long may the Hold stand open, and the one inside it keep an ear to the ground.",
		"Strength and patience to whoever sits beneath that roof. He'll need more of the second.",
	},
	["org.muse.w17.hold.013"] = {
		"Quietest place in Orgrimmar, they say. A few dozen voices and a fire. I'd hate to hear the loud one.",
		"The calm heart of the city, that hall. Calm by Orgrimmar's measure: nobody's hitting anything.",
	},
	["org.muse.w17.hold.014"] = {
		"The Warchief carries a whole people's choices on one pair of shoulders. From here, he looks like he's listening to all of them at once.",
		"Up on the throne Thrall sits very still, and it isn't calm. It's the stillness of someone holding a great weight level.",
		"From the floor of the hall, the throne looks less like a seat of power than a place where someone has to keep listening.",
	},
	["org.muse.w17.hold.015"] = {
		"Orc, troll, tauren, Forsaken: they all come to the same hall to be heard. The Warchief's seat is the one place in Orgrimmar every people has to walk toward.",
		"Every road in Orgrimmar bends toward Grommash Hold sooner or later. Even the ones that look like they're going to the bank.",
		"Forsaken envoys, troll elders, tauren braves: the Hold's door sees them all. Thrall's table is a crowded one.",
	},
	["org.muse.w17.hold.016"] = {
		"turns at the low note of a horn from the direction of the Warchief's hall, waits, and turns back when nothing follows it.",
		"lifts {g:his|her} head at a horn call from up the Valley of Wisdom, then lets it go when the crowd does.",
	},
	["org.muse.w17.hold.017"] = {
		"Our Warchief keeps no gold on his throne and no crown on his head. A seat, a hammer, and a hall full of whoever needs him.",
		"No crown in Grommash Hold. The Horde never wanted a king; it wanted someone who would stand in front when it mattered.",
		"Other peoples cover their kings in gold. We gave our Warchief a hall of timber and hide, and he seems to prefer it.",
	},
	["org.muse.w17.hold.018"] = {
		"Grommash Hold. Can't look at it without standing up straighter. My back has filed a complaint.",
		"One look at the Warchief's hall and I'm checking my boots for dust. As if anyone in Orgrimmar had clean boots.",
	},
	["org.muse.w17.hold.019"] = {
		"watches a petitioner kneel before the throne, say a few halting words, and rise again, lighter by the look of it.",
		"sees the Kor'kron by the throne shift their weight in perfect unison, as if the floor had tilted under all of them at once.",
	},
	["org.muse.w17.hold.020"] = {
		"The walls of Orgrimmar were raised to keep enemies out. Grommash Hold was raised for the opposite: to let every people of the city in and sit them at one fire.",
		"A city needs walls to stand and a hall to hold together. Thrall built the walls for his enemies and the Hold for his friends, and I suspect the second was harder.",
		"Walls for the enemies, a hall for the friends. Of the two, Orgrimmar spends more on the walls and needs the hall more.",
	},
	["org.muse.w17.honor.001"] = {
		"A hunter in the Valley of Honor is trying to teach a scorpid to sit. The scorpid is considering it, very slowly, with its tail.",
		"Over in the hunters' corner of the Valley of Honor, a scorpid is being taught manners. Neither party looks hopeful.",
	},
	["org.muse.w17.honor.002"] = {
		"The warrior trainers in the Valley of Honor are all missing something: a finger, an ear, half a tooth. Every lesson comes with its own proof.",
		"You can tell the trainers in the Valley of Honor from their pupils by what's missing. A notched ear, two fingers short. They teach from experience.",
		"The older the trainer in the Valley of Honor, the fewer the fingers. I listen hardest to the ones with three.",
	},
	["org.muse.w17.honor.003"] = {
		"Look at those two. They've argued about stance longer than the fight would have lasted.",
		"They've stopped sparring to argue technique. With gestures. The trainer's letting them wear themselves out.",
		"Two grunts, one stance, a dozen opinions. Nobody's thrown a punch in a while.",
	},
	["org.muse.w17.honor.004"] = {
		"The Hall of Legends does not open for curiosity. Rank, earned on the battlefields, is the only key its door will take.",
		"No coin buys a way into the Hall of Legends, and no friend at the door helps. Only rank, won in the field, and the field takes no bribes.",
		"Gold opens most doors in Orgrimmar. The Hall of Legends is the stubborn exception.",
	},
	["org.muse.w17.honor.005"] = {
		"Quiet, inside the Hall of Legends. Those who have earned a place in it don't need to shout about it.",
		"Voices drop in the Hall of Legends without anyone asking. The banners on the walls do the boasting for everyone.",
	},
	["org.muse.w17.honor.006"] = {
		"If anyone in the Valley of Honor asks, I'm only watching. These bruises came from somewhere else.",
		"I'm just watching the training. Really. The limp is unrelated.",
	},
	["org.muse.w17.honor.007"] = {
		"stops at the edge of the training ground to watch two grunts trade blows, and winces each time the heavier one lands.",
		"leans on a post at the edge of the Valley of Honor's yard, following a sparring match with the narrowed eyes of someone keeping score.",
		"keeps silent count of a sparring match in the yard, lips moving, and loses track when the smaller grunt suddenly wins.",
	},
	["org.muse.w17.honor.008"] = {
		"slows beside a hunter brushing the dust out of a great cat's coat, while the cat endures it with its eyes closed and its tail twitching.",
		"pauses beside a hunter combing burrs from a wolf's neck; the wolf leans into the comb with the shameless joy of a pup.",
		"stops to see a hunter check a boar's hooves one by one, talking to it the whole time in a low, reasonable voice.",
	},
	["org.muse.w17.honor.009"] = {
		"Every warrior who leaves the Valley of Honor carries off some of its dust in the creases of the armor. Half the battlefields of Kalimdor must hold a pinch of the valley.",
		"The red dust of the training yard travels. It turns up a hundred leagues from Orgrimmar, the trainers like to say, in the boots of the ones they taught.",
		"Some of the Valley of Honor always leaves with its warriors: red dust in the buckles, the trainers' voices in the ears.",
	},
	["org.muse.w17.honor.010"] = {
		"My people once fought with the demon's fire in their blood. In the Valley of Honor the young learn to fight without it, and they are better for it.",
		"Our elders learned war with a curse burning in them. The trainers of the Valley of Honor teach it clean. I watch the young ones and think: this is what we were meant to be.",
	},
	["org.muse.w17.honor.011"] = {
		"Nobody in the Valley of Honor stops for the heat. Heat, the trainers say, is just an enemy you can't hit, so you might as well ignore it.",
		"The trainers of the Valley of Honor treat the heat like a heckler in the crowd: not worth an answer.",
		"The trainers of the yard grant no rest for heat, dust or thirst. The grunts complain about all three and keep drilling.",
	},
	["org.muse.w17.honor.012"] = {
		"The pet trainer in the Valley of Honor speaks to beasts the way a good smith speaks to iron: patiently, and expecting to be understood.",
		"There's a trainer of beasts in the Valley of Honor who never raises a voice. The animals lean in to hear, which may be the whole trick.",
	},
	["org.muse.w17.honor.013"] = {
		"Look at them go. The Valley of Honor could field an army from the onlookers alone.",
		"Half this valley is training and the other half is shouting advice. I know which half I'm in.",
		"More people watching than sparring. Typical. Nobody ever volunteers to be the dummy.",
	},
	["org.muse.w17.honor.014"] = {
		"Everyone here is counting aloud: strokes, laps, paces, scores. The whole Valley of Honor keeps time like one enormous drillmaster.",
		"Somebody in the Valley of Honor is always counting out loud. Ten more. From the top. Five more. The numbers never seem to go down.",
	},
	["org.muse.w17.honor.015"] = {
		"ducks as a training staff goes spinning out of someone's hands and clatters past a pace away, to a roar of laughter from the yard.",
		"steps quickly aside as a sparring pair stumbles out of the yard and onto the path, still grappling, both apologizing through gritted teeth.",
		"sidesteps a pair of grunts wrestling in the dust of the yard, and earns an approving grunt from a trainer for the footwork.",
	},
	["org.muse.w17.honor.016"] = {
		"Some who walk out of the Hall of Legends wear their rank the way others wear a limp: earned, and not open for discussion.",
		"The officers who come and go from the Hall of Legends rarely say how they got there. Their silence is the loudest boast in the Valley of Honor.",
		"The Hall of Legends lets few in, and the few who come out never brag. Bragging is for the yard.",
	},
	["org.muse.w17.honor.017"] = {
		"Hit the post, not the trainer. Unless the trainer started it.",
		"Keep that elbow up! Sorry. Not my yard, not my business.",
	},
	["org.muse.w17.honor.018"] = {
		"Raptors, cats, boars and one very offended turtle. The hunters' end of this valley is a farmyard where everything bites.",
		"Between the beasts, the hunters and the stable smell, this is the nearest thing Orgrimmar has to a farmyard. A farmyard with teeth.",
		"Somebody's raptor just stole a boar's dinner, and the hunters are already betting on the rematch.",
	},
	["org.muse.w17.honor.019"] = {
		"Every grunt in the training yard is fighting someone who isn't there: the foe of the next campaign, the next war. They hit the post as if it had a face.",
		"Sparring partners in the Valley of Honor look past each other. Each one is seeing a different enemy, somewhere far beyond the walls.",
		"The fiercest bouts in the yard are fought against nobody at all: a grunt alone, hammering at the air and at whoever waits for him past the walls.",
	},
	["org.muse.w17.honor.020"] = {
		"squints through the blowing sand at the Valley of Honor's yard, where the sparring goes on as if the grit were part of the lesson.",
		"watches the trainers keep their pupils at it through the hissing sand, every shout half swallowed by the wind.",
		"shields {g:his|her} eyes from the sand and watches a trainer keep shouting the count, as if the wind had merely asked a question.",
	},
	["org.muse.w17.order.001"] = {
		"watches a shoving match between two orcs end before it starts: a grunt appears between them, says one word, and both remember urgent business elsewhere.",
		"sees a scuffle flare by a doorway and a pair of grunts end it almost faster than it began, without drawing steel.",
	},
	["org.muse.w17.order.002"] = {
		"The law in Orgrimmar fits on a thumbnail: no steel drawn on a citizen, no hand in another's purse. The grunts handle the footnotes.",
		"As far as I can tell the city has two laws, and both are enforced by orcs the size of doors.",
		"Nobody reads the laws aloud here. They don't need to; the grunts are standing right there.",
	},
	["org.muse.w17.order.003"] = {
		"pauses to watch a grunt hear out an orc and a troll quarrelling over a debt, then name a sum that leaves both of them equally sour.",
		"lingers while a grunt settles an argument between a goblin and a tauren, mostly by letting the goblin run out of words first.",
	},
	["org.muse.w17.order.004"] = {
		"Trolls in one valley, tauren in another, orcs everywhere in between. Part of the Warchief's peace is simply giving everyone room to sulk.",
		"The city keeps its peoples apart just enough and together just enough. Somebody thought about that for a long while.",
		"Give every people a valley and a grievance of its own, and they'll be too busy to quarrel with each other. Whoever planned Orgrimmar understood that.",
	},
	["org.muse.w17.order.005"] = {
		"A notice nailed to a post: the Warchief's word on something, in Orcish, and under it a drawing of the same thing for those who don't read. The drawing has an axe in it.",
		"Someone has posted the Warchief's orders on a timber beam, with a picture beneath for the unlettered. The picture is clearer.",
	},
	["org.muse.w17.order.006"] = {
		"Everyone in this crowd carries steel, and nobody touches it. That's Orgrimmar's law, written in how people walk.",
		"Axes on every back, knives on every belt, and not one of them out. The city's peace is a thousand people choosing the same thing at once.",
		"A crowd armed to the teeth, and the worst that happens is a stubbed toe. That's discipline nobody had to shout for.",
	},
	["org.muse.w17.order.007"] = {
		"Thieves are rare in Orgrimmar, the grunt says. Mostly because the punishment is him.",
		"Nobody steals here, a grunt told me. I asked why. He just cracked his knuckles.",
	},
	["org.muse.w17.order.008"] = {
		"watches two orcs close a bargain by gripping forearms, and nothing else: no paper, no witness but the street.",
		"witnesses a deal struck with one hard clasp of forearms, and the two parties part as if a contract had been sealed in iron.",
	},
	["org.muse.w17.order.009"] = {
		"Peace in the streets, steel at the gate. That's the arrangement, and it works.",
		"Keep your temper and your purse and the grunts will never learn your name.",
		"Best way to stay friends with the guards here? Give them nothing to write down.",
	},
	["org.muse.w17.order.010"] = {
		"We are not one people. We are a promise several peoples made to each other, and the Warchief is the one who keeps us to it.",
		"The Horde isn't a race, it's a handshake. Orgrimmar is where you can watch it being held, all day long, in a crowd.",
	},
	["org.muse.w17.order.011"] = {
		"observes a pair of grunts stop a cart, poke through the sacks with the haft of an axe, and wave it on without a word.",
		"catches a grunt lifting the cloth off a goblin's cart, looking, sniffing and dropping it again, while the goblin smiles the whole time.",
	},
	["org.muse.w17.order.012"] = {
		"The Warchief rarely leaves his hall, they say, and yet his word is in every street: in how the grunts stand, in who gets out of whose way.",
		"You don't see Thrall in the streets much. You see his rules everywhere, which is perhaps the better way round.",
		"Thrall's peace walks the streets without him, carried on the shoulders of every grunt in sight.",
	},
	["org.muse.w17.order.013"] = {
		"The grunts keep the peace in this city for everyone in it, I'm told. I'd rather not be the one who tests whether everyone includes me.",
		"Order here is strict and fair, as far as I can see. Fair to whom is the question I keep in my pocket.",
	},
	["org.muse.w17.order.014"] = {
		"The grunts remember faces. Stay in the city long enough and one of them gives you the smallest of nods: known, harmless, for now.",
		"Being recognized by a grunt is a strange honor. You get no smile, just a slight easing of the stare, like a door left unbarred.",
	},
	["org.muse.w17.order.015"] = {
		"Quiet streets, grunt? Then you're doing your job, and I'll stay out of it.",
		"Fine work, the lot of you. Nobody's been stabbed in at least an hour.",
	},
	["org.muse.w17.order.016"] = {
		"The Darkspear settle some quarrels their own way, in their own valley, and the grunts find somewhere else to look. Knowing when not to see is part of the law too.",
		"Not every dispute in Orgrimmar reaches a grunt. The tauren have their elders and the trolls their own customs, and the city is wise enough to let them.",
	},
	["org.muse.w17.order.017"] = {
		"straightens up a little as a patrol passes, the way people in Orgrimmar do, without being told.",
		"brings both hands into plain sight as a pair of grunts walks by, almost without noticing, then lets them drop again.",
	},
	["org.muse.w17.order.018"] = {
		"The gate is open to anyone who comes in peace, and the grunts decide on sight who that is. They're rarely wrong, I'm told.",
		"Nobody asks your business at the gate. The grunts just look, and somehow that's the question and the answer both.",
	},
	["org.muse.w17.spirits.001"] = {
		"The masks on the hut posts in the Valley of Spirits are carved with their mouths open, as if caught halfway through a word. I'd give a lot to hear the end of it.",
		"Painted masks watch the path through the Valley of Spirits, every mouth open. Whatever they started to say, they have been saying it a long time.",
		"Every mask in the troll valley seems to have been carved mid-sentence. I keep expecting one of them to finish.",
	},
	["org.muse.w17.spirits.002"] = {
		"Down in the Valley of Spirits there's a pool of still water, the only water in Orgrimmar that nobody is trying to sell me.",
		"A pool lies in the troll valley, flat and quiet, in a city where every other drop is carried in a bucket and paid for.",
		"Still water, in a canyon of red dust. The Darkspear keep their pool the way other folk keep a hearth: something to gather round.",
	},
	["org.muse.w17.spirits.003"] = {
		"An old Darkspear in the Valley of Spirits turns his face toward the coast whenever he talks. Toward the isles they lost, I'd guess. I doubt he knows he does it.",
		"Some of the older trolls keep glancing south-east, past the walls, toward the Echo Isles. A habit, like the tongue going to a missing tooth.",
		"The trolls of the Valley of Spirits rarely speak of the Echo Isles. They don't have to. Half their charms hang facing the sea.",
	},
	["org.muse.w17.spirits.004"] = {
		"stops to watch a troll child beat a rhythm on an upturned pot, while an old one corrects the beat without looking up from his work.",
		"lingers by a hut in the Valley of Spirits, where a child drums badly on a cooking pot and an elder taps the right beat on his knee until she finds it.",
		"smiles in spite of {g:himself|herself} at a small troll pounding on a pot, and at the grown hand that reaches over, now and then, to slow it down.",
	},
	["org.muse.w17.spirits.005"] = {
		"A priest and a shaman are arguing by the water in the Valley of Spirits about where healing really comes from. Neither will win, and both will be patching up the same grunts by the end of the week.",
		"By the troll pool a priest and a shaman disagree, politely and at length, over who mends a wound: the Light or the spirits. The wound does not seem to care who gets the credit.",
		"Light or spirits? The two healers by the troll pool have been at it a good while. Whichever wins, the grunts in the queue behind them still limp.",
	},
	["org.muse.w17.spirits.006"] = {
		"watches a witch doctor rattle a gourd at a passing wolf, and the wolf, very sensibly, take the long way round.",
		"notes that even the wolves give the witch doctors of the Valley of Spirits plenty of room, and follows their example.",
		"steps wide of a witch doctor shaking a gourd at nothing in particular, the way the local wolves do.",
	},
	["org.muse.w17.spirits.007"] = {
		"Careful with the pots, friend. In the Valley of Spirits, half of them have somebody living in them.",
		"Don't kick that jar. Down in the troll valley you never know who's at home inside.",
		"Mind the jars. The trolls say some of them are occupied.",
	},
	["org.muse.w17.spirits.008"] = {
		"watches the reflections of the huts tremble on the pool in the Valley of Spirits each time a drum starts up nearby.",
		"stands by the troll pool long enough to see a drumbeat cross the water as a ring of tiny ripples.",
		"leans over the troll pool and sees the painted masks of the huts behind {g:him|her} hanging upside down in the water, wide-eyed.",
	},
	["org.muse.w17.spirits.009"] = {
		"ducks under a cord of roots hung to dry between two huts in the Valley of Spirits, and comes up sneezing at the peppery smell.",
		"slows beside a line of drying roots, bark and something with legs, and decides not to ask which is medicine and which is supper.",
		"wrinkles {g:his|her} nose at a cord of drying roots in the Valley of Spirits, then, curious, sniffs a second time.",
	},
	["org.muse.w17.spirits.010"] = {
		"The trolls leave out small bowls of food that nobody eats. By the time the flies are done, the witch doctors say, the spirits have had their share too.",
		"Little bowls of meal and fruit sit at the hut doors in the Valley of Spirits. For the spirits, a Darkspear told me, the way you'd keep a plate for a late guest.",
		"A troll child just took a fig from one of the spirit bowls. Her grandmother cuffed her ear and put a bigger one in its place.",
	},
	["org.muse.w17.spirits.011"] = {
		"Orc drums march. The drums of the Valley of Spirits wander instead: they circle, stop, pick up somewhere new, like an old voice telling a story it knows by heart.",
		"The troll drums never keep step. They roam and hesitate and start up elsewhere, and after a while the orc marches sound a little stiff beside them.",
		"Listen long enough to the drums of the troll valley and the city's war rhythms start to sound like someone counting on their fingers.",
	},
	["org.muse.w17.spirits.012"] = {
		"A charm against snakes, a charm against bad luck, a charm against goblins. Guess which one that troll sells out of first.",
		"That troll's got a charm for everything. I asked for one against prices. She laughed for quite a while.",
		"Bought a charm off a troll for luck. She threw in a second one for free, against whatever the first one attracts.",
	},
	["org.muse.w17.spirits.013"] = {
		"Here in the Valley of Spirits the street turns to packed earth, and the orcs' iron gives way to bone, feather and painted wood.",
		"The Valley of Spirits builds with what the orcs throw away: bone, feather, gourd, a great deal of paint. It feels older than the rest of the city, though it can't be.",
		"Fewer spikes here, more feathers. The Valley of Spirits keeps a taste all its own.",
	},
	["org.muse.w17.spirits.014"] = {
		"steps around a ring of painted stones laid out on the ground, and does not ask what it is for.",
		"walks wide of a circle of small stones set in the dust between the huts, the way one walks around someone else's sleeping dog.",
	},
	["org.muse.w17.spirits.015"] = {
		"lingers to see a shaman sit by the troll pool with eyes shut, still as a post, while three small trolls try everything they can think of to make her laugh.",
		"pauses by the water in the Valley of Spirits, where a shaman sits deep in thought and a pack of troll children is doing its best to break her. So far the shaman is winning.",
	},
	["org.muse.w17.spirits.016"] = {
		"Rain on the troll pool, and every Darkspear in sight is out in it with face turned up. Water falling on water: they seem to take it as a good sign.",
		"Rain in the Valley of Spirits. The painted masks run with color, and the old trolls stand by the pool watching it fill as if they were counting the drops.",
	},
	["org.muse.w17.spirits.017"] = {
		"Something's bubbling in that hut. Medicine, curse or soup? In the Valley of Spirits I'm not asking.",
		"That smell's either a cure or a curse. I'll let somebody braver have the first taste.",
	},
	["org.muse.w17.spirits.018"] = {
		"The Darkspear crossed to Kalimdor on Thrall's ships with little more than their spears and their spirits. The valley they were given is small, and they have filled it to the brim.",
		"Thrall took the Darkspear off their isles when nothing was left to hold them there. They paid him in the only coin they had, their word, and the Valley of Spirits is where they keep it.",
		"The Darkspear owe Thrall their lives, and everyone knows it. In the Valley of Spirits nobody needs to say it twice.",
	},
	["org.muse.w17.spirits.019"] = {
		"pauses as a few robed trolls walk past toward the water, unhurried, their hems brushing the dust like brooms.",
		"makes way for a pair of troll priests heading down to the pool, who nod their thanks with the same slow tilt of the head.",
	},
	["org.muse.w17.spirits.020"] = {
		"A few of the troll charms in the Valley of Spirits hang facing outward, toward the rest of the city. Just in case, a Darkspear told me, grinning.",
		"The trolls trust their orc neighbors, a witch doctor explained to me. The charms nailed up facing the Drag are there purely out of good manners.",
		"Half the troll charms point at the rest of the city. Polite, a witch doctor called it. Prudent, I'd call it.",
	},
	["org.muse.w17.spirits.021"] = {
		"Peaceful, this valley. Only three drums going at once. For Orgrimmar that's a lullaby.",
		"Now this is a quiet corner: one drum, a pool, and nobody selling anything. I could nap.",
		"I like this valley. The drums don't shout at you; they just mutter to themselves.",
	},
	["org.muse.w17.strength.001"] = {
		"Everyone who walks in through the main gate stops here a moment to decide what Orgrimmar is going to be for them. You can see the deciding on their faces.",
		"This valley is where travelers finally stand still after days of walking. The road is still on them; the city hasn't begun yet.",
		"Just inside the gate, folk pause and take stock: bank, inn, the Drag beyond. You can watch the road slide off their shoulders.",
	},
	["org.muse.w17.strength.002"] = {
		"steps aside for a cart rolling in through the main gate, its wheels pale with road dust and its driver already arguing with a guard about where to stop.",
		"watches a pack train come in at the gate, crates swaying, while the guards wave it on with the boredom of long practice.",
		"lets a line of laden porters file in past the gate, each one craning to see whether the bank is as far as they feared.",
	},
	["org.muse.w17.strength.003"] = {
		"Somewhere in the bank a clerk keeps my name in a ledger, next to a number. That page knows more about how I live than most people I've traveled with.",
		"One line of ink in the bank's books is only me: a name and a sum. It may be the most honest portrait anyone has made of me.",
		"My name sits in a ledger in the Valley of Strength, beside a figure that rarely grows. The clerk who wrote it wouldn't know my face.",
	},
	["org.muse.w17.strength.004"] = {
		"The auction house lets me buy from people I'll never meet. Somebody out in the Barrens set the price on this pelt and walked off whistling.",
		"Every lot at the auction house was put up by a stranger I'll never see. I'm haggling with a ghost who has already left town.",
	},
	["org.muse.w17.strength.005"] = {
		"The auctioneers never raise their voices. In a city where everyone bellows, that's how you know who really holds the power.",
		"Nobody shouts at the auction house. The auctioneers murmur the bids like a shaman reading bones, and half the city's coin changes hands anyway.",
		"Of all the voices in Orgrimmar, the softest belong to the auctioneers. The loud ones sell hides; the quiet ones move fortunes.",
	},
	["org.muse.w17.strength.006"] = {
		"watches a handler climb the wind rider tower with a bucket of raw meat, and hears the beasts above start to squabble long before he reaches the top.",
		"looks up at the wind rider tower as a handler hauls up a sloshing pail of scraps; somewhere on the platform a beast lets out a hungry, rattling cry.",
	},
	["org.muse.w17.strength.007"] = {
		"The regulars at the inn swear the notches on the doorpost count brawls. The innkeeper says they count unpaid tabs. Nobody has asked which list is longer.",
		"There's a doorpost at the inn cut with a hundred notches. Brawls, say the regulars. Debts, says the innkeeper, and she doesn't smile when she says it.",
		"Ask about the notches on the inn's doorpost and you get two stories: fights, from the drinkers, and unpaid bowls of stew, from the innkeeper.",
	},
	["org.muse.w17.strength.008"] = {
		"Gate, bank, inn. Orgrimmar puts its three best arguments right up front.",
		"First thing past the gate: somewhere to keep your coin and somewhere to spend it. This city knows its visitors.",
	},
	["org.muse.w17.strength.009"] = {
		"The main gate has seen more farewells than welcomes. Whoever marches out through it is bound for some war at the far end of a road.",
		"From the gate the roads run off toward every trouble in Kalimdor. Half the people passing under it are saying goodbye to someone, and pretending not to.",
	},
	["org.muse.w17.strength.010"] = {
		"Meet me by the bank, they all say. Look at this: half of Orgrimmar standing by the bank, waiting for the other half.",
		"Everyone here is waiting for somebody outside the bank. I could sell seats.",
		"The bank steps are the city's meeting place. Nobody's meeting anyone yet, but they're all very patient about it.",
	},
	["org.muse.w17.strength.011"] = {
		"A traveler has just come in past the gate with a pack twice his size and the face of someone who walked every step from Razor Hill to prove a point.",
		"Through the gate trudges a peddler bent under a bundle as big as a tent. He drops it by the bank and sits on it, and for a while he is the happiest soul in the valley.",
	},
	["org.muse.w17.strength.012"] = {
		"Every time I pass the gate into the valley, something in my shoulders lets go. Not safety, exactly. Something closer to belonging.",
		"Through the main gate, and the noise of the valley closes around me like a door shutting the road out. Ours, all of it, the din included.",
	},
	["org.muse.w17.strength.013"] = {
		"At the bank the richest warrior in the city and the poorest peon wait at the same counter. The clerk treats them both with the same polite contempt.",
		"The bank is the one place in Orgrimmar where a famous name gets no bow. A copper is a copper, says the clerk's face, whoever sets it down.",
		"Heroes, peons, goblin traders: the bank clerks look at all of them the same way, as a column of figures that happens to be talking.",
	},
	["org.muse.w17.strength.014"] = {
		"Each time something heavy rolls past outside, a fine red dust sifts down from the ceiling. Even under a roof, the city keeps reminding me it's there.",
		"Under this roof the street is only a rumble, but every passing cart shakes a little red grit loose overhead.",
	},
	["org.muse.w17.strength.015"] = {
		"Bid, outbid, sigh. The auction house is just a slower kind of duel.",
		"Somebody outbid me by a single copper. I'd like to meet them. Briefly.",
		"Beaten at the auction house by one copper. Whoever you are, I hope it rusts.",
	},
	["org.muse.w17.strength.016"] = {
		"The road from the gate to the bank is worn smooth and pale, polished by every boot that ever came into the city on business. A city's habits show first in its stone.",
		"Between the gate and the bank the rock is worn into a shallow groove. Nobody laid that path; ten thousand errands did.",
	},
	["org.muse.w17.strength.017"] = {
		"News moves faster here than the people who carry it. Somebody at the gate mentions a skirmish in the Barrens, and by the time he reaches the bank the skirmish has doubled.",
		"In this valley a rumor walks in with the caravans and grows a size with every stall it passes. By the inn door it hardly fits through.",
		"Every caravan through the gate brings a rumor, and the valley fattens it up. What left Ratchet as a broken axle arrives at the inn as a sunken fleet.",
	},
	["org.muse.w17.strength.018"] = {
		"The orcs walked out of the internment camps owning nothing but the rags they stood in. Now there's a bank by their gate, heavy with coin. Some victories make no noise.",
		"Not long ago the orcs had nothing anyone needed to lock away. Now this city has a bank. That is a quieter victory than any battle, and maybe a larger one.",
	},
	["org.muse.w17.strength.019"] = {
		"Wolves, carts, travelers and a peon with a roll of canvas, all heading for the same doorway. Nobody stands still in this valley for long.",
		"Stand still here for one moment and somebody will set a crate down on you.",
		"Keep moving in this valley. The last fellow who stopped to think got a wolf sitting on his feet.",
	},
	["org.muse.w17.strength.020"] = {
		"Somewhere in the inn a game of knucklebones has gone on so long that nobody remembers who is winning, only who owes whom a drink.",
		"In one corner of the inn the same four old grunts throw bones and argue, and I've never seen them start or finish. They may be part of the building.",
	},
	["org.muse.w17.strength.021"] = {
		"A roof and four walls between me and the hawkers. My purse and I can both rest for a moment.",
		"Out of the market at last. In here nobody is trying to sell me anything, and I keep waiting for the catch.",
	},
	["org.muse.w17.strength.022"] = {
		"drifts with the slow tide of travelers between the bank and the inn, nodding to nobody in particular.",
		"crosses the valley from the bank toward the inn, sidestepping a wolf, two peons and an argument without breaking stride.",
	},
	["org.muse.w17.strength.023"] = {
		"watches a goblin courier dart out of the bank with a satchel clutched to the chest and vanish into the crowd before anyone can ask a thing.",
		"notices a runner leave the auction house at a trot, a rolled bill of sale held high like a banner.",
	},
	["org.muse.w17.trade.001"] = {
		"A tailor in the Drag would pay real coin for the linen scraps I've been using to wipe my boots. I should look in my bags more often.",
		"Everything I've been throwing away has a price here. The torn linen, the odd fang, the half-cured hide: somebody in Orgrimmar wants all of it.",
	},
	["org.muse.w17.trade.002"] = {
		"Pay an orc trader the first price he names and he looks at you as if you'd refused his hand. Haggling here isn't greed; it's good manners.",
		"In Orgrimmar a bargain struck without a fight is a small insult to the seller. You argue because you respect the goods.",
		"I paid the asking price once, without a word. The trader looked hurt. I had robbed him of the best part of his day.",
	},
	["org.muse.w17.trade.003"] = {
		"Goblin traders sell to everyone and fight for no one. In a city built for war, they're the only ones who look at peace and see a market.",
		"A goblin trader told me the Steamwheedle Cartel has no enemies, only customers who haven't paid yet. He meant it kindly, I think.",
	},
	["org.muse.w17.trade.004"] = {
		"Fifteen copper? At that price it ought to walk home by itself.",
		"That much? For that? It had better come with a song and a bow.",
		"You want how much? I've bought whole wolves for less. Small ones, granted.",
	},
	["org.muse.w17.trade.005"] = {
		"turns a trinket over in both hands, names a price, and watches the merchant laugh as if at a fine joke before naming another.",
		"makes an offer for a belt buckle and is answered with a scandalized look, a long sigh and, at last, a counteroffer.",
		"sets something down on a trader's cloth with great reluctance, and is called back before the third step.",
	},
	["org.muse.w17.trade.006"] = {
		"The traders here will buy anything with a bit of use left in it: a chipped fang, a torn hide, a single boot. Somewhere a one-legged warrior must be grateful for that boot.",
		"I've sold a merchant one boot, just the one, and he paid without blinking. Somewhere in Kalimdor there's a buyer for everything.",
		"A trader took my odd boot without a question and gave me two copper for it. I've stopped wondering who buys these things. I just sell them.",
	},
	["org.muse.w17.trade.007"] = {
		"Copper from the hills of Durotar comes into the city by the basket and leaves as buckles, rivets and nails. Somewhere between the two it grows ten times dearer.",
		"The ore in those baskets was dug from the red hills a few days ago. By the time it's a buckle on a grunt's belt, it costs ten times as much and has learned to shine.",
	},
	["org.muse.w17.trade.008"] = {
		"No two scales in this city agree on anything. Every trader swears his is the honest one, and the others are all off by a thumb.",
		"I've weighed the same handful of silver at three stalls and got three answers. Each trader looked deeply sorry for the other two.",
	},
	["org.muse.w17.trade.009"] = {
		"I'll give you half. No? Then half, and a compliment on your stall.",
		"Half the price, and I'll tell the whole inn how fairly you deal. No? Worth a try.",
	},
	["org.muse.w17.trade.010"] = {
		"On one trader's cloth: tauren leather, troll beads, a Forsaken apothecary's stoppered powders, orc iron. Whatever else we argue about, we all agree on a fair price.",
		"Hides from Mulgore, charms from the Echo Isles, Durotar iron and something corked from Tirisfal, all on one table. Our peoples shared a market before they shared much else.",
	},
	["org.muse.w17.trade.011"] = {
		"An old orc minds a stall of plain clay cups. In the camps he had nothing to sell, not even the work of his own hands. He sets each cup out as if it were proof of something.",
		"There's a potter's stall where an old orc lines up his cups very straight. Someone told me he spent half his life in an internment camp. Now everything on that cloth is his.",
		"Plain cups, plain bowls, and an old orc who touches each one before he sells it. Behind the fences, I'm told, nothing he made was ever his to keep.",
	},
	["org.muse.w17.trade.012"] = {
		"I sold a ring to a trader for a handful of silver. Now it's on his cloth for twice that, and it looks better there than it ever did on me.",
		"The bracer I sold an hour ago is already on the trader's table, priced at double. I'm tempted to buy it, just to see the look on his face.",
	},
	["org.muse.w17.trade.013"] = {
		"A goblin offered me credit. Easy terms, he said, and unrolled a contract longer than my arm. I've faced ogres that frightened me less.",
		"Easy credit, the goblin said, tapping a page of very small writing. I read three lines and felt my knees go. Coin up front, thank you.",
		"Never borrow from a goblin, the grunts say. I asked one for terms just to see. The contract had a clause about my grandchildren.",
	},
	["org.muse.w17.trade.014"] = {
		"Not everything here goes for coin. A troll just paid for a mended strap with two fish and a story, and the tanner seemed happiest with the story.",
		"I watched a strap change hands for a pair of fish and a long tale about a shark the size of a boat. The tanner said the tale was worth more than the fish.",
	},
	["org.muse.w17.trade.015"] = {
		"Buying is easy. Selling is the art. I'm bad at both, but cheerful about it.",
		"Anyone can buy. Selling well is a craft, and I'm still an apprentice at it.",
	},
	["org.muse.w17.trade.016"] = {
		"bites a coin given in change, the way the peons do, and tries to look as if it proved something.",
		"tests a silver piece between the teeth, as everyone in the market seems to, without the least idea what it ought to taste like.",
	},
	["org.muse.w17.trade.017"] = {
		"does a quick sum on {g:his|her} fingers, frowns at the answer, and works it out a second time in the hope it has changed.",
		"counts up what is owed and what is left, lips moving silently, and arrives at a number nobody would want.",
		"runs through the day's purchases on one hand, runs out of fingers, and decides not to start on the other.",
	},
	["org.muse.w17.trade.018"] = {
		"Half of what's sold in this city leaves it again in crates: nails for Splintertree Post, salt for the Crossroads, leather for anyone with a war on. Orgrimmar's coin travels further than most grunts.",
		"The traders here don't sell only to the city. Their crates go out on kodo-back to the Crossroads and beyond, wherever there's a post to keep and a wall to mend.",
	},
	["org.muse.w17.trade.019"] = {
		"Coin is coin, even here. The goblin at the stall served me without a flicker, which is more than the grunts behind me would have done.",
		"A trader took my silver without looking twice at my face. In this city the merchants are the only ones who don't care which side I'm from.",
	},
	["org.muse.w17.trade.020"] = {
		"Once the orcs had nothing to trade but the next war. Now my kin argue over the price of nails like any people of the world, and I could listen to it all day.",
		"My people bartered in blood for a generation. Listening to an orc smith haggle over a pair of hinges, I think that was the harder habit to break, and we broke it.",
	},
	["org.muse.w17.trade.021"] = {
		"With sand in the air the hawkers stop shouting and start pointing. The market goes almost quiet, which is the eeriest thing I've heard in this city.",
		"Grit on the air, and every trader pulls a cloth over the goods and a scarf over the mouth. Haggling by eyebrow is slower, but it works.",
	},
	["org.muse.w17.trade.022"] = {
		"Under a roof the hawkers' cries come through the door in pieces: fresh, half price, for you, friend. Even muffled, they're selling.",
		"In here the market reaches me only in scraps shouted through the doorway. Even a wall can't keep a good bargain quiet in this city.",
	},
	["org.muse.w17.trade.023"] = {
		"weighs two nearly identical belts, one in each hand, while their seller waits with the patience of a hunting cat.",
		"holds up a pair of gloves to the light, then another pair, then the first again, as the trader's smile grows thinner.",
	},
	["org.muse.w17.walls.001"] = {
		"The big beams in the city's walls came out of Ashenvale, the grunts say. The elves up north have not forgiven a single plank.",
		"Ashenvale timber holds up half the main gate, a grunt told me with some pride. Somewhere in that forest the kaldorei are still counting stumps.",
		"Every beam in the main gate grew in a forest that wants it back, they say at the gate, and the grunts find that very funny.",
	},
	["org.muse.w17.walls.002"] = {
		"stops to watch a peon on a ladder file the tip of a wall spike back to a point, slow strokes, very serious about it.",
		"tilts {g:his|her} head at a peon high on the wall who hammers a crooked spike straight, then tests the point with a thumb and winces.",
		"looks up at a peon perched on the wall with a whetstone, sharpening a spike as carefully as anyone ever sharpened an axe.",
	},
	["org.muse.w17.walls.003"] = {
		"I've never seen the main gate shut. I'm not sure anyone remembers how.",
		"The great gate stands open as if closing it would insult the grunts in front of it. Maybe it would.",
		"A gate that size, and nobody bothers to close it. The grunts are the lock.",
	},
	["org.muse.w17.walls.004"] = {
		"Rust runs down from every iron band on the walls in long streaks, until it's hard to say where the rock ends and the iron starts.",
		"The iron on the walls is weeping rust into the red stone. Give it a few more years and the whole city will be one color.",
	},
	["org.muse.w17.walls.005"] = {
		"On a post of the main gate someone has scratched a long row of tallies, one for every watch, I'd guess. Nobody has ever crossed any out.",
		"A gatepost at the main gate is scored with hundreds of little marks. Watches kept, a grunt told me. He didn't say how many were his.",
		"Somebody keeps count of the watches on the timber of the gate, one notch at a time, and the notches have nearly run out of post.",
	},
	["org.muse.w17.walls.006"] = {
		"From the road, the walls say keep out. From inside, they say the other half of it: nobody got in.",
		"Seen from Durotar, the walls are a threat. Seen from the street, a promise. Same stone.",
		"Outsiders read the walls as a warning. The people who live behind them read the same stone as a roof.",
	},
	["org.muse.w17.walls.007"] = {
		"Whoever built the main gate built it for giants, then hired orcs to stand in it.",
		"You could get a kodo through the main gate with a hat on. Who were they expecting?",
	},
	["org.muse.w17.walls.008"] = {
		"High on the towers of the wall, small as fence posts, the lookouts face Durotar so the rest of the city doesn't have to.",
		"There are watchers up on the wall towers, dark against the sky. I only notice them when one shifts weight, which is rarely.",
		"Somebody stands on those towers at every hour, looking out at a whole lot of nothing. The city sleeps sounder for it.",
	},
	["org.muse.w17.walls.009"] = {
		"Everyone ducks a little going under the main gate, even goblins who would clear it ten times over. I did it too, and I couldn't say why.",
		"Funny thing about the main gate: people lower their heads going through, though a tauren could pass on another tauren's shoulders.",
	},
	["org.muse.w17.walls.010"] = {
		"A fresh patch of clay on an old wall, paler than the rest. Somebody is still finishing Orgrimmar.",
		"Here and there the walls show new mortar, light against the red. The city isn't done being built, and doesn't pretend to be.",
		"Peons with buckets of wet clay go from crack to crack along the walls. Orgrimmar gets mended the way a warrior does: often, and without fuss.",
	},
	["org.muse.w17.walls.011"] = {
		"A carrion bird has claimed the tallest spike on the wall and sits there as if the whole city were a meal worth waiting for.",
		"There's a big ragged bird on top of a wall spike, looking down at all of us with professional interest.",
		"Every spike on that wall was made to keep enemies off, and one scruffy bird has turned the tallest into a perch.",
	},
	["org.muse.w17.walls.012"] = {
		"Good walls. I'd hate to be the one climbing them.",
		"Look at those walls. Anyone who comes at Orgrimmar comes uphill, into iron.",
		"Fine stonework. Every inch of it says no.",
	},
	["org.muse.w17.walls.013"] = {
		"The builders didn't fight the canyon. Where the rock stood high they left it alone, and where it dipped they filled the gap with timber and iron.",
		"Half the city's wall is just the canyon, untouched. The orcs only mended the places where the rock forgot to be a wall.",
	},
	["org.muse.w17.walls.014"] = {
		"Out in the Barrens I'm one more traveler. Behind these walls I'm Horde, and the stone itself seems to know it.",
		"There's a particular ease in walking under walls that are on your side. I didn't know I'd missed it until I felt it.",
	},
	["org.muse.w17.walls.015"] = {
		"tips {g:his|her} head back to follow the wall up to its spikes, and keeps tipping it a while longer than expected.",
		"measures the height of the city wall by eye, gives up halfway, and settles for a low whistle.",
	},
	["org.muse.w17.walls.016"] = {
		"Even the huts are built like little forts: hide over heavy timber, spikes along the ridge, a door you could hold shut with one shoulder.",
		"The houses here are walls in small. Thick posts, stretched hide, iron at the corners. Nobody in Orgrimmar builds anything that couldn't take a hit.",
		"Look at any hut long enough and you'll see the city wall in it: the same timber, the same spikes, the same plain stubborn shape.",
	},
	["org.muse.w17.walls.017"] = {
		"Oi, up on the wall! Anything coming? No? Good. Stay bored.",
		"Long way up for a lookout. I hope they send the stew up on a rope.",
	},
	["org.muse.w17.walls.018"] = {
		"runs a hand along a thick corner post, worn smooth at shoulder height by every load that ever scraped past it.",
		"pauses by an iron-wrapped post where the way turns, its timber rubbed pale by a thousand passing shoulders.",
	},
	["org.muse.w17.walls.019"] = {
		"Nobody here has raised a hand to me. Still, every grunt I pass looks at me a little longer than at the troll beside me, and I can't blame them.",
		"The walls are handsome, in a brutal way. I'd admire them more if I weren't on the wrong side of the war that built them.",
	},
	["org.muse.w17.wisdom.001"] = {
		"An old tauren sits beside the path through the Valley of Wisdom doing nothing at all, and doing it better than anyone else in Orgrimmar.",
		"An elder tauren in the Valley of Wisdom has sat on the same stone for as long as anyone can say. He isn't waiting. He is simply there, the way the canyon is.",
		"By the path to the Warchief's hall, an elder tauren has not moved since I noticed him. A wolf has curled up against him as if he were a rock.",
	},
	["org.muse.w17.wisdom.002"] = {
		"The Kor'kron are Thrall's own guard, picked one by one. A grunt told me they're chosen less for their strength than for what they won't do when nobody is watching.",
		"Not every grunt can stand among the Kor'kron. The ones I've asked say the Warchief looks for a cool head before a strong arm. The ones who were turned away tell it differently.",
		"A grunt says the word Kor'kron the way other folk say a mountain's name: a little lower, a little slower.",
	},
	["org.muse.w17.wisdom.003"] = {
		"From the floor of the Valley of Wisdom, Grommash Hold looks less like a palace than a war camp that decided to put down roots.",
		"The Hold isn't built to be admired. It sits at the head of its valley like a chieftain on a log, and dares you to call it plain.",
	},
	["org.muse.w17.wisdom.004"] = {
		"They named a valley after wisdom and put the Warchief's hall in it. Wise of them.",
		"Valley of Wisdom. Lovely name. Shame they don't hand out samples.",
	},
	["org.muse.w17.wisdom.005"] = {
		"Thrall's orcs crossed the sea with nothing; Cairne's tauren had been harried across the plains by the centaur for longer than anyone could count. Each knew what it is to need a place to stand.",
		"The orcs helped the tauren break the centaur's grip, and the tauren have a long memory for help. You see it in the Valley of Wisdom, in the way an old bull nods to a grunt half his size.",
		"Grunt and tauren pass each other on the path to the Hold with a nod that holds a whole war's worth of debts, paid.",
	},
	["org.muse.w17.wisdom.006"] = {
		"pauses as a tauren sets a small totem upright beside the path and straightens it twice, the way one straightens a friend's collar.",
		"slows to watch a tauren kneel by the path, press a carved totem into the dust, and sit back on her heels to judge it.",
		"steps carefully around a little totem planted by the path, the way the tauren of the valley seem to expect.",
	},
	["org.muse.w17.wisdom.007"] = {
		"waits while a kodo lying in the dust of the Valley of Wisdom considers whether to move, and decides against it.",
		"goes round a kodo that has lain down in the middle of the Valley of Wisdom, as the rest of the traffic does, the way a stream goes round a boulder.",
		"exchanges a long look with a kodo chewing in the dust near the Warchief's hall; the kodo wins.",
	},
	["org.muse.w17.wisdom.008"] = {
		"The tauren talk of the Earth Mother as if she were listening just under the paving. In a city carved from red rock, it isn't hard to imagine she has ears.",
		"A tauren elder touches the ground before she speaks, every time. For the Earth Mother, I'm told. Even on stone the orcs have shaped, it seems to count.",
		"Even the orcs of the Valley of Wisdom step a little lighter near the tauren's totems. Nobody wants to be the one who woke the Earth Mother.",
	},
	["org.muse.w17.wisdom.009"] = {
		"Slow down, a tauren told me. In Orgrimmar. I laughed, then I tried it, and nobody walked into me. Strange.",
		"The tauren keep telling me to take my time. In this city? Where would I even put it?",
		"Take it slow, says the tauren. Easy for him; everyone gets out of his way.",
	},
	["org.muse.w17.wisdom.010"] = {
		"A shaman first and a Warchief second: so the elders of the Valley of Wisdom describe Thrall. Maybe that's why the ground around his hall feels less hurried than the rest.",
		"Thrall listens to the spirits of the land, the shamans say, the way a good chieftain listens to his scouts. The valley around his hall seems to have caught the habit.",
		"Thrall speaks with the elements before he speaks with his chieftains, the shamans claim. I'd like to know which of them argues more.",
	},
	["org.muse.w17.wisdom.011"] = {
		"Here in the Valley of Wisdom the crowd thins and the voices drop. Even the wolves seem to pad more softly, as if somebody had asked them nicely.",
		"The noise of the city reaches the Valley of Wisdom tired and half its size, and I catch myself slowing down so as not to be the loudest thing in it.",
		"The Valley of Wisdom has its own pace, and it isn't Orgrimmar's. Even my boots seem to have noticed.",
	},
	["org.muse.w17.wisdom.012"] = {
		"The ground here is swept. Everywhere else in Orgrimmar the dust does as it likes; in the Valley of Wisdom somebody tells it where to lie.",
		"Someone sweeps this valley; I can see the broom marks. In a city of red dust, that is the nearest thing to a declaration of respect.",
		"Not a heap of dung, not a pile of scrap: the Valley of Wisdom is the tidiest corner of Orgrimmar, and the tauren look quietly pleased with that.",
	},
	["org.muse.w17.wisdom.013"] = {
		"slows without meaning to on the rise toward the Warchief's hall, as most people seem to, and straightens a strap that was not crooked.",
		"finds {g:his|her} stride shortening on the way up the Valley of Wisdom, and lets it.",
	},
	["org.muse.w17.wisdom.014"] = {
		"An old tauren told me the earth is patient because it has seen every hurry end. I think he meant it kindly. I'm still turning it over.",
		"The elders in the Valley of Wisdom say a thing well rooted never needs to shout. In Orgrimmar that sounds almost like a dare.",
		"Seeing me hurry past, a tauren elder said only: the stone will still be there. I slowed down. I'm not sure why.",
	},
	["org.muse.w17.wisdom.015"] = {
		"Strength to you, Kor'kron. No? Not even a grunt? Fair enough.",
		"Hail, Kor'kron. I'll take that silence as a warm welcome.",
	},
	["org.muse.w17.wisdom.016"] = {
		"Somebody swore to me the Kor'kron blink in shifts, so the Warchief's door is never unwatched. I've been watching them. I believe it.",
		"I tried to catch a Kor'kron blinking. I lost. They take turns, apparently.",
	},
	["org.muse.w17.wisdom.017"] = {
		"Sand blows down the Valley of Wisdom and the tauren simply shut their eyes and wait it out, like boulders. I have half their patience and twice the grit in my teeth.",
		"The sand comes hissing through the valley, and the tauren turn their broad backs to it without a word. I crouch behind the nearest one and call it wisdom.",
	},
	["org.muse.w17.wisdom.018"] = {
		"Thunder Bluff is far off across the Barrens, but the tauren of the Valley of Wisdom carry a little of it with them: a bone chime, a pouch of plains grass, a slower way of standing.",
		"The tauren in the Warchief's valley walk as if the plains of Mulgore went on under the stone. Maybe, for them, they do.",
		"A tauren of the Valley of Wisdom has planted a tuft of plains grass in a cracked pot by her door. In this dust, it's the greenest thing for a mile.",
	},
	["org.muse.w17.wisdom.019"] = {
		"watches an old orc and an old tauren share a bench in the Valley of Wisdom, saying nothing for so long that it turns into a conversation.",
		"passes two elders sitting together near the Warchief's hall, an orc and a tauren, both silent, both nodding now and then at the same moment.",
	},
	["org.muse.w17.wisdom.020"] = {
		"From the Valley of Wisdom I can see our Warchief's hall over the heads of the crowd. Wherever the road takes me, I like knowing exactly where it stands.",
		"Our Warchief's hall stands at the head of its valley, plain and solid. Whatever happens out in the world, there is one roof the whole Horde can point to.",
		"However far I wander, the Horde keeps a hall with a fire in it and a Warchief who listens. From the Valley of Wisdom I can see the roof.",
	},
	["org.muse.w17.wry.001"] = {
		"I asked a grunt the way. He pointed with his axe, and I followed the axe, briskly.",
		"Directions in Orgrimmar come with a weapon attached. You ask, a grunt points with his axe, and you stop asking.",
	},
	["org.muse.w17.wry.002"] = {
		"There's said to be a quiet corner somewhere in Orgrimmar. Every grunt I ask looks at me as if I'd asked where they keep the sea.",
		"I've been hunting for a quiet spot in this city. A peon told me there is one, but it's being used.",
	},
	["org.muse.w17.wry.003"] = {
		"There's wolf hair on everything I own now. I haven't touched a single wolf. The city just sheds on you.",
		"Brush my cloak all I like, it stays half wolf. In Orgrimmar that's practically a uniform.",
	},
	["org.muse.w17.wry.004"] = {
		"I still can't tell the call to arms from the call to supper. Judging by how fast the crowd moves, neither can anyone else.",
		"A drum has just started up, somewhere. Battle or stew? In this city the crowd runs the same way for both.",
		"Every drumroll in this city could mean war, a feast or a drummer with too much free time. I've stopped guessing.",
	},
	["org.muse.w17.wry.005"] = {
		"An orc just thanked me by punching my shoulder. I think we're friends now. My shoulder isn't sure.",
		"That was a friendly thump, was it? Then I'd hate to meet the other kind.",
	},
	["org.muse.w17.wry.006"] = {
		"freezes along with half the street when a grunt sneezes; three hands go to three belts, and then everyone laughs a little too loudly.",
		"jumps when somebody drops a pot nearby, and sees half the crowd reach for a weapon before the pot has even stopped rolling.",
	},
	["org.muse.w17.wry.007"] = {
		"I tried whistling as I walked. A wolf answered, then a grunt, and neither of them liked the tune.",
		"Whistling in Orgrimmar is a mistake. Every wolf within earshot takes it personally.",
		"Note to self: no whistling near the wolf pens. Or near the grunts. Or anywhere, really.",
	},
	["org.muse.w17.wry.008"] = {
		"Can't find something in Orgrimmar? Stand still. Somebody will walk into you soon enough, and then you can ask the way.",
		"Best way to find anything in this city: stop in the road and wait to be shoved toward it.",
	},
	["org.muse.w17.wry.009"] = {
		"I'm fairly sure they pick the gate grunts for width. Not one of them can be walked around in under three steps.",
		"Gate duty seems to go to grunts built like the gate. I suspect that's the whole test.",
	},
	["org.muse.w17.wry.010"] = {
		"answers a grunt's nod with a nod of exactly the same depth, as if the exchange had rules and both of them knew them.",
		"trades a curt nod with a passing grunt, measured to a finger's width, then looks faintly pleased with the result.",
	},
	["org.muse.w17.wry.011"] = {
		"In Orgrimmar a polite request is anything said without showing tusks. By that measure, I've been very courteous.",
		"I've learned the local manners: say please with your voice, not your teeth, and stand a pace further back than seems needed.",
	},
	["org.muse.w17.wry.012"] = {
		"What? No, I said... never mind. I'll write it down later.",
		"Say that again, louder. No, louder. Fine, I'll just nod.",
	},
	["org.muse.w17.wry.013"] = {
		"Every peon in this city has a plan for winning the next war. Nobody's asked them, and everybody's heard it.",
		"Listen to the peons long enough and you'll learn how to run the Horde properly. Mostly it involves fewer logs.",
	},
	["org.muse.w17.wry.014"] = {
		"falls into step beside a grunt grumbling about his boots and nods along as if they were old comrades; the grunt never once looks over.",
		"ends up walking beside a muttering grunt for half a street, agreeing politely with complaints about the wolves, the dust and the price of nails.",
	},
	["org.muse.w17.wry.015"] = {
		"The fiercest grunt I've seen in this city just lost a staring match to a child of about four. He took it well. He blinked first and left.",
		"A small orc child has been staring at a grunt for a good while. The grunt is staring back. Neither will give in, and the street is starting to take sides.",
	},
	["org.muse.w17.wry.016"] = {
		"Even the walls here look like they want a word with me.",
		"I swear that wall just scowled. Everything in Orgrimmar scowls, down to the masonry.",
	},
	["org.muse.w17.wry.017"] = {
		"Nobody has ever drawn a map of Orgrimmar. You learn the city by being shoved through it until the shoves start making sense.",
		"Ask for a map of the city and a grunt taps his own forehead. Apparently that's where they keep it.",
	},
	["org.journey.w18.land.001"] = {
		"comes down in a slow spiral over the canyon, each turn bringing the city closer: first the walls, then the roofs, then faces.",
		"spirals down into the canyon, and with every turn the city sharpens: walls, then roofs, then the color of the awnings, then the people.",
	},
	["org.journey.w18.land.002"] = {
		"drops the last few feet as the wings flare wide, and a ring of dust jumps off the platform and rolls away over the edge.",
		"settles with a jolt as the beast brakes with both wings, blowing loose straw off the boards and down onto the street below.",
	},
	["org.journey.w18.land.003"] = {
		"Landed. My knees took most of it and they'd like that noted.",
		"The beast lands like a dropped sack and my teeth meet with a click. Elegant, as always.",
		"Down, with a thump that went straight up my spine and is still looking for the way out.",
	},
	["org.journey.w18.land.004"] = {
		"sinks below the canyon rim, and the walls rise on either side until the open sky is only the lid of the city.",
		"drops under the line of the rim, and the noise of the city closes over the flight like water over a stone.",
	},
	["org.journey.w18.land.005"] = {
		"Last turn over the Valley of Strength, and I've already measured the line at the bank. Short. A good omen, as omens in this city go.",
		"Before the claws even touch the tower I've picked my route: the bank, then the inn, then whatever comes.",
	},
	["org.journey.w18.land.006"] = {
		"waits on the platform while the handler checks the beast's legs and wings, one by one, before sparing the passenger so much as a glance.",
		"is ignored entirely while the handler runs both hands over the beast's wings looking for damage. Passengers, it seems, can look after themselves.",
	},
	["org.journey.w18.land.007"] = {
		"The first thing Orgrimmar gives you on landing is the smell of the beast pens. The second is the inn's cooking, and it more than makes up for the first.",
		"Down into the smell of the city: wolf, hot iron, cook fires and, right under my nose, whatever the fliers ate last.",
	},
	["org.journey.w18.land.008"] = {
		"works at the saddle straps with stiff fingers, and the last buckle refuses until the handler reaches over and flicks it open.",
		"fumbles with a buckle the high air seems to have frozen shut, while the beast shifts its weight, impatient for its meal.",
	},
	["org.journey.w18.land.009"] = {
		"Where's the nearest thing that doesn't move? I'd like to lean on it.",
		"Is there a wall nearby that stays put? Asking for my knees.",
		"Hold me up, someone. Not you, beast.",
	},
	["org.journey.w18.land.010"] = {
		"After all that open air, the canyon walls close around me like a heavy coat put back on. Too warm, maybe, but it fits.",
		"Sky behind me, red walls on every side. It should feel cramped. Instead it feels like pulling a door shut.",
	},
	["org.journey.w18.land.011"] = {
		"lands on a platform slick with rain, the beast's claws skidding on the wet boards before they find a grip.",
		"drops through the rain into a city gone dark and shiny, every red wall streaming.",
	},
	["org.journey.w18.land.012"] = {
		"lands under a growl of thunder, and the handler hauls the beast in by the reins before the next flash can spook it.",
		"drops out of the storm onto the tower at speed, the beast's wings shuddering at each crack of thunder over the canyon.",
	},
	["org.journey.w18.land.013"] = {
		"Coming in at dusk, I watch the city light itself one lamp after the next below my boots, as if it had waited for me to see.",
		"The lamps of Orgrimmar come on beneath the wings as we drop through the dusk. Somebody down there is very quick with a taper.",
	},
	["org.journey.w18.land.014"] = {
		"steps off onto boards baked hot by the day, and feels the warmth come up through both soles at once.",
		"lands in the full heat of the day, where the only shade on the platform belongs, by right, to the beasts.",
	},
	["org.journey.w18.land.015"] = {
		"drops from the first light above the rim down into the canyon, where the streets are still deep in shade and the lamps still lit.",
		"leaves the dawn up on the rim and lands in the blue half-dark below, where the city is only beginning to stir.",
	},
	["org.journey.w18.land.016"] = {
		"descends through the night by the city's torches, the beast picking out the tower among the lit roofs as if it had a map of every lamp.",
		"lands in the night with a thump that wakes the beasts on the perch, and for a moment the whole tower complains.",
	},
	["org.journey.w18.land.017"] = {
		"After the silence up there, the city comes back in the wrong order: a laugh, a hammer, a wolf, someone swearing at a goblin. By the foot of the tower it has sorted itself out.",
		"The noise doesn't come all at once. One voice first, then a dozen, then the whole Valley of Strength, as if someone kept adding wood to a fire.",
	},
	["org.journey.w18.land.018"] = {
		"passes a peon hurrying up with a bucket of scraps, who has eyes only for the beast and does not seem to notice the rider at all.",
		"steps aside for a peon bringing the beast its meal; the beast, for its part, forgets its passenger the instant it smells the bucket.",
	},
	["org.journey.w18.land.019"] = {
		"Every flight ends the same way: an animal that could eat me sets me down gently, and then a goblin tries to sell me something.",
		"The beast could have swallowed me in one bite and didn't. The first goblin at the foot of the tower is already making up for it.",
	},
	["org.journey.w18.land.020"] = {
		"waits while the beast picks its spot on the crowded platform, edging between two others that hiss and then, grudgingly, make room.",
		"is carried the last few yards at a crawl while the flier noses in among the beasts already perched, every one of them complaining about the latecomer.",
	},
	["org.journey.w18.land.021"] = {
		"On the way down the sea shows for a moment beyond the eastern ridges. The veterans at the inn remember Kul Tiran sails out there in the city's first years. There's nothing on it now.",
		"A glimpse of open water past the ridges as the beast turns in. Old orcs say enemy ships once sat out on that sea, watching the walls go up.",
	},
	["org.journey.w18.land.022"] = {
		"I'd like to report that the sky is still up there. You're welcome.",
		"Down. The sky sends its regards.",
		"Down from the sky, and it didn't even give me a souvenir.",
	},
	["org.journey.w18.land.023"] = {
		"stops at the foot of the tower to empty a boot, and a small heap of somewhere else pours out onto the stone.",
		"pauses by the tower to shake out a boot, and a sky's worth of grit adds itself quietly to the city's own.",
	},
	["org.journey.w18.land.024"] = {
		"Up there I had forgotten how many people fit in this canyon. The crowd at the foot of the tower reminds me with a single shove.",
		"A hundred shoulders between me and the inn. After the sky, Orgrimmar feels like a full pot with the lid on.",
	},
	["org.journey.w18.land.025"] = {
		"lands to a horn blowing somewhere toward the gate, and the beast tips back its head and answers it.",
		"settles onto the tower as a horn sounds from the walls, and the beast, taking it perhaps for a welcome, screams back.",
	},
	["org.journey.w18.land.026"] = {
		"On the way down I look for the inn's chimney smoke first. It means somebody's cooking, and for once that somebody isn't me.",
		"The first thing I pick out from the air is the smoke over the inn. Not the Hold, not the walls. A bowl of stew outranks a Warchief, briefly.",
	},
	["org.journey.w18.land.027"] = {
		"comes in low over the Valley of Spirits on the approach, and the smoke of some herb burning outside a hut climbs to meet the wings.",
		"skims the huts of the Valley of Spirits on the last turn, close enough to see a troll look up from a cookpot and wave a ladle through the smoke.",
	},
	["org.journey.w18.land.028"] = {
		"Off I get. Gracefully. Mostly.",
		"My legs have arrived. The rest of me will be along shortly.",
		"Feet, meet the tower. Tower, be kind to the feet.",
	},
	["org.journey.w18.land.029"] = {
		"leaves the wind rider to its handler and its meal, and the beast is tearing at a haunch before its rider reaches the way down.",
		"hands over the wind rider's reins, and the beast shoulders off toward the meat trough with the manners of a grunt at the end of a watch.",
	},
	["org.journey.w18.land.030"] = {
		"Orgrimmar under the wings, and every banner on its walls one I'd stand under. Good to come down among my own.",
		"The banners of the Horde on the walls, then on the towers, then right beside the landing. After a long way, it's good to settle among them.",
	},
	["org.journey.w18.land.031"] = {
		"Mind out below! Beast coming in.",
		"Clear the platform! We're not stopping gently.",
		"Heads up down there! Wings coming through.",
	},
	["org.journey.w18.land.032"] = {
		"That's the softest anyone's set me down in this city.",
		"Gentle landing. Kinder than the welcome I usually get down there.",
	},
	["org.journey.w18.land.033"] = {
		"Every bone in place? Every bone in place.",
		"Arms, two. Legs, two. Good flight.",
	},
	["org.journey.w18.perch.001"] = {
		"steps onto boards worn smooth and pale by more boots than anyone could count, and the platform barely creaks under the weight.",
		"sets foot on the tower's landing, where the planks have been polished to a dull shine by every traveler the city ever sent anywhere.",
	},
	["org.journey.w18.perch.002"] = {
		"Every beast on the perch turns its head when we land, like a row of old orcs at the inn eyeing whoever just walked in.",
		"A dozen great heads swing round to inspect me as I climb off. Judged, found uninteresting, forgotten. Fair.",
	},
	["org.journey.w18.perch.003"] = {
		"goes down from the tower into the noise, which grows with every step, like walking down into a pot coming to the boil.",
		"takes the long way down from the landing, and each turn of it lets in another layer of the city: voices, then hammers, then the smell of the inn.",
	},
	["org.journey.w18.perch.004"] = {
		"Purse, pack, both boots, every finger. The sky took nothing this time. I'll count again at the bottom.",
		"A quick tally before the way down: everything I had in the air is still on me. One for the beast.",
	},
	["org.journey.w18.perch.005"] = {
		"Feed that one well. It earned it.",
		"Good beast, that. Whatever you're feeding it, keep on.",
		"Tell the beast it flew well. It won't care, but tell it.",
	},
	["org.journey.w18.perch.006"] = {
		"straightens a twisted cloak and smooths down whatever the high air did to the rest, with the look of someone whose flight was entirely dignified.",
		"tugs clothes back into place at the top of the way down, then gives up on the rest; the high air always wins.",
	},
	["org.journey.w18.perch.007"] = {
		"The first thing Orgrimmar says to me after the sky is to get out of the way. Fair enough. I was in it.",
		"Two steps off the platform and someone is already telling me to shift. That's the city's welcome, and that's all of it.",
		"Ten steps from the platform and I've been elbowed twice and offered a fish. Orgrimmar has noticed me after all.",
	},
	["org.journey.w18.perch.008"] = {
		"watches the handler count the beasts on the perch with a moving finger, the way a merchant counts coins after a crowd has passed.",
		"sees the handler tally the fliers with a stub of charcoal on a post, one stroke per beast, and add one more.",
	},
	["org.journey.w18.perch.009"] = {
		"Landing in Orgrimmar is walking into the middle of an argument that started before the walls went up and will go on long after I've left.",
		"Coming down into this city is like opening a door on a quarrel. Nobody stops. Nobody explains. You just find a seat.",
	},
	["org.journey.w18.perch.010"] = {
		"finds the way from the tower blocked by a resting kodo, whose owner shrugs as if the beast were simply the weather.",
		"has to edge around a kodo lying across the path below the tower, chewing slowly, unimpressed by anyone who arrives by air.",
	},
	["org.journey.w18.perch.011"] = {
		"The air down here is thick enough to chew: smoke, dust, onions, somebody's wolf. After the high air it's like being handed a full bowl.",
		"Up there the air had no taste. Down here it has a dozen, and most of them are cooking.",
	},
	["org.journey.w18.perch.012"] = {
		"lingers at the edge of the landing until the boards underfoot stop rising and falling with wings that are no longer there.",
		"takes a moment longer on the platform than needed, the body still riding a beat the beast has already stopped.",
	},
	["org.journey.w18.perch.013"] = {
		"Down. Someone tell the city I've arrived; it won't have noticed.",
		"Out of the sky and into the shoving. Must be Orgrimmar.",
		"There's the racket. Now I know we're down.",
	},
	["org.journey.w18.perch.014"] = {
		"stops at a water barrel at the foot of the tower and drinks a whole dipperful, as if the sky had been a desert.",
		"rinses the grit of the flight out at a trough near the tower, then spits it into the street, where it is very much at home.",
	},
	["org.journey.w18.perch.015"] = {
		"For the first few steps every voice in the street sounds as if it's meant for me. Then the city sorts itself out, and I'm one more pair of boots.",
		"Among people once more, and for a moment each shout feels personal. It passes. Nobody here is shouting at me. Probably.",
	},
	["org.journey.w18.perch.016"] = {
		"A wolf by the foot of the tower takes one sniff at me and growls. I smell of flier, apparently. I'll take it as a compliment.",
		"The wolves in the street keep their distance from me for a while after a flight. Something about the smell of the beast. Useful, in a crowd.",
	},
	["org.journey.w18.perch.017"] = {
		"Don't mind me. Just fell out of the sky on purpose.",
		"Pardon me. Coming through. Recently airborne.",
	},
	["org.journey.w18.perch.018"] = {
		"A queue waits on the platform for the beast I've just left: a tauren with a heavy pack, a goblin with a heavier one. I wish the beast luck.",
		"Someone is already waiting for my flier, a tauren built like a gatehouse. I step aside and send the beast a silent apology.",
	},
	["org.journey.w18.perch.019"] = {
		"looks up from the landing at the canyon walls that were under the beast's belly a moment ago, and finds them very tall again.",
		"tips {g:his|her} head back on the platform: the canyon rim, so easily crossed a moment ago, has taken back all of its height.",
	},
	["org.journey.w18.perch.020"] = {
		"Horde banners, Horde noise, Horde cooking. Good to be down.",
		"Horde ground underfoot. Now, where's the inn?",
	},
	["org.journey.w18.perch.021"] = {
		"leaves the wind rider at its post on the perch, where it folds its wings and gives the city below a long, proprietary look.",
		"gives the wind rider a last glance before the way down; it has already turned its back, wings folded, to keep watch over its city.",
	},
	["org.journey.w18.perch.022"] = {
		"A floor that doesn't flap. Lovely.",
		"Boards that hold still! I could kiss every one of them.",
	},
	["org.journey.w18.perch.023"] = {
		"Something's frying down there, and it's calling me by name. Excuse me.",
		"That smell is the inn, and it's the best greeting this city has.",
	},
	["org.journey.w18.rise.001"] = {
		"follows the Drag from above as the beast climbs, and at last sees where the crooked street was trying to go all along.",
		"looks down on the Drag as the flight gains height: from up here its bends make a long, patient loop that only a bird could love.",
	},
	["org.journey.w18.rise.002"] = {
		"Every spike on every roof in Orgrimmar points straight up at me now. I'm choosing not to take it personally.",
		"From below the spikes looked like decoration. From above they look like a plan.",
		"Orgrimmar bristles at the sky like a startled hedgehog. Nobody told it I'm only passing over.",
	},
	["org.journey.w18.rise.003"] = {
		"Nobody in Orgrimmar looks up. They're all too busy looking at each other. For a few wingbeats the whole city is mine to watch.",
		"Thousands down there, and not one face turned upward. A city that busy never checks the sky, so it never sees anyone leave.",
	},
	["org.journey.w18.rise.004"] = {
		"passes level with the lip of the canyon, close enough to see pick marks in the stone where somebody once made room for a street.",
		"rises along the canyon wall and sees, a wing's length away, the old scars of picks and chisels in the red stone.",
	},
	["org.journey.w18.rise.005"] = {
		"keeps an eye on the sparring yard in the Valley of Honor as it shrinks below, the clash of each blow reaching the saddle a moment after the blow itself.",
		"sees two tiny figures trade blows in the Valley of Honor's yard, and hears the clatter arrive late, as if the sound had to climb on foot.",
	},
	["org.journey.w18.rise.006"] = {
		"From up here the Kor'kron in front of the Hold look like pegs someone drove into the ground and forgot about. Very fierce pegs.",
		"Grommash Hold from above: one great round roof, and at its door two dots who would stop me even if I landed on their heads.",
		"Even at this height the Hold manages to look like it's frowning at me.",
	},
	["org.journey.w18.rise.007"] = {
		"looks down on the bank as the beast clears the tower; the line at its doors shuffles forward by one head, and from this height it looks like a caterpillar.",
		"picks out the line outside the bank from above, a long dark worm of travelers that does not seem to have moved since the takeoff.",
	},
	["org.journey.w18.rise.008"] = {
		"Somebody down there just won a bid at the auction house. From this height it sounds exactly like a war cry. In Orgrimmar it might be one.",
		"A roar goes up from the auction house as the beast climbs. Either someone got a bargain or someone got hit. Both, likely.",
	},
	["org.journey.w18.rise.009"] = {
		"glances down at the Valley of Spirits as the flight banks: the pool lies dark and still among the huts, the only flat thing in all that rock.",
		"catches sight of the pool in the Valley of Spirits on the turn, a round dark eye among the huts, unblinking while the city hurries round it.",
	},
	["org.journey.w18.rise.010"] = {
		"The cook fires of a whole city, each one a thin gray thread, and every thread bending the same way up here. From the street you'd never guess they agree on anything.",
		"A hundred cooking smokes rise out of the valleys and lean together at the top, like a crowd that has finally agreed on something.",
	},
	["org.journey.w18.rise.011"] = {
		"draws level with a lookout on the wall for one wingbeat; the orc meets {g:his|her} eye without turning his head, and then the wall drops away.",
		"passes a sentry on the high wall at eye height, and gets the same flat look the sentry gives everything that comes up the road from Durotar.",
	},
	["org.journey.w18.rise.012"] = {
		"The veterans talk about the camps, walls built to keep orcs in. From up here the walls of Orgrimmar face the other way, out, and that is the whole difference.",
		"Old grunts at the inn say the orcs once knew only walls that held them. These were raised by the same hands, facing outward. From the air you see it at once.",
	},
	["org.journey.w18.rise.013"] = {
		"rises over a rooftop where two peons are patching timbers; one waves his hammer at the beast, and the other ducks for no reason at all.",
		"clears a roof where a peon sits mending a beam, who looks up, judges the beast to be somebody else's problem, and goes back to work.",
	},
	["org.journey.w18.rise.014"] = {
		"clears the rim, and beyond the walls the land lies open: dry riverbeds branching like the veins on the back of a hand, thorn scrub in rusty knots.",
		"climbs until the earth outside the walls can be read like a hide stretched on a frame, every dry wash and ridge a crease.",
		"tops the canyon, and all of Durotar unrolls below, red earth gone brown at the edges and scored with the beds of rivers that are no longer there.",
	},
	["org.journey.w18.rise.015"] = {
		"Mind the spikes on the way up. For both our sakes.",
		"Over the wall, not into it. Thank you.",
		"Up and over. Gently. I've eaten.",
	},
	["org.journey.w18.rise.016"] = {
		"Nobody to wave me off, and nobody at the tower who'll remember my face by the next meal. I like a city that lets you go this easily.",
		"Leaving Orgrimmar is easy: no one asks where, no one asks why. The handler only asked whether I'd paid.",
		"No farewells at the tower. The handler checked the straps, grunted, and that was the whole ceremony.",
	},
	["org.journey.w18.rise.017"] = {
		"rises past a pair of carrion birds circling above the canyon, and for once looks down on them.",
		"climbs higher than the buzzards that wheel over the canyon, and sees their backs for a change, ragged and dusty, as they wait on the city's leftovers.",
	},
	["org.journey.w18.rise.018"] = {
		"From the air the city has four colors: red stone, black iron, the brown of hides on the roofs, and here and there the green of an herb bed somebody is very proud of.",
		"Red stone, dark iron, tanned hide, and in one corner a patch of green. Seen from above, Orgrimmar is a warrior's palette with a single gardener in it.",
	},
	["org.journey.w18.rise.019"] = {
		"passes over the Cleft of Shadow, a dark slot in the city's floor so deep that not even the flight can see where it ends.",
		"looks straight down into the Cleft of Shadow as the beast crosses it, and sees only a deeper dark beneath the dark.",
	},
	["org.journey.w18.rise.020"] = {
		"Look at them all down there, running about. And I thought I was busy.",
		"So that's the city when it isn't shouting in my ear. Not bad.",
		"Every one of them in a hurry. From here they look like ants with axes.",
	},
	["org.journey.w18.rise.021"] = {
		"They named this city for Doomhammer, and the veterans say he was hard, plain and impossible to move. From the air the place lives up to the name.",
		"A city named for a fallen warchief. From up here it looks the way the old orcs describe him: all edges, and planted where it stands.",
	},
	["org.journey.w18.rise.022"] = {
		"watches the beast's shadow race over the roofs of the Drag, and sees a goblin below duck without knowing why.",
		"sees the flier's shadow slide across the Valley of Strength and up the canyon wall, faster than anything walking down there.",
	},
	["org.journey.w18.rise.023"] = {
		"lifts off as the canyon fills with shade from the bottom up, the streets already dim while the rim still burns red.",
		"climbs out of the dusk pooling in the canyon and into the last light above the rim, as if leaving one hour for the next.",
	},
	["org.journey.w18.rise.024"] = {
		"Rain over Orgrimmar, of all things. From above every street has gone dark red, and the whole city must smell like a wet wolf.",
		"The city looks freshly painted from up here: the rain has turned the red stone the color of old wine, and the dust, for once, stays put.",
	},
	["org.journey.w18.rise.025"] = {
		"climbs into a clear sky over the canyon, and from the top of the climb every roof of the city stands out sharp, down to the last spike.",
		"rises through air so clear that the far edge of Durotar looks near enough to reach before the next meal, under an empty sky.",
	},
	["org.journey.w18.rise.026"] = {
		"takes off under a sky the color of a bruise, the beast's wings flinching at every flash along the canyon rim.",
		"rises into the storm as fast as the beast will go, the handler's shout lost behind a crack of thunder over the walls.",
	},
	["org.journey.w18.rise.027"] = {
		"From the air I can tell the Valley of Wisdom by its pace alone. Everywhere else the dots hurry; there, they amble.",
		"The slowest corner of the city, seen from the air, is the Valley of Wisdom. Even the dust there seems to settle more politely.",
	},
	["org.journey.w18.rise.028"] = {
		"spots a lone wolf rider leaving by the road below, a dot dragging a long tail of dust, and soon outpaces it without effort.",
		"looks down on someone leaving the city along the road, all that dust and all that effort, and the beast passes over in a few wingbeats.",
	},
	["org.journey.w18.rise.029"] = {
		"The voices go first as we climb, then the wolves, then the bellowing at the stalls. The last thing to let go of me is a single hammer, ringing somewhere along the Drag.",
		"Climbing out of Orgrimmar, the sounds leave in order of size: the crowd, the forges, one stubborn anvil. Then just the wings.",
	},
	["org.journey.w18.rise.030"] = {
		"Up on the roofs there's a second Orgrimmar nobody walks: hides stretched to dry, a forgotten boot, a sleeping goblin, three broken pots.",
		"The roofs keep the city's secrets: hides pegged out to cure, a lost boot, a goblin asleep among the crates where nobody will ask him to pay for anything.",
	},
	["org.journey.w18.rise.031"] = {
		"raises a fist toward Grommash Hold as the wind rider sweeps past it, though no one inside will ever know.",
		"lifts a hand from the wind rider's neck as the flight crosses Grommash Hold, a small salute to the Warchief's hall that nobody below will see.",
	},
	["org.journey.w18.rise.032"] = {
		"Thrall's city from the air. Every one of us should see it like this once: all of it ours, and not one wall of it a cage.",
		"From up here Orgrimmar is the size of a promise kept. Free orcs built it, and now the whole Horde walks its streets.",
	},
	["org.journey.w18.rise.033"] = {
		"One turn over the city before we go. I want to see all of it at once.",
		"Give me one circle over the valleys. The city's prettier when it can't hear me say so.",
	},
	["org.journey.w18.rise.034"] = {
		"Yes, I see you down there. No, I'm not coming back for it.",
		"Whatever you're shouting, I can't hear it. Farewell!",
		"Wave all you like down there. The beast doesn't do refunds.",
	},
	["org.journey.w18.wing.001"] = {
		"lurches forward as the beast steps out into nothing, and for one long moment they simply fall, until the wings bite into the air.",
		"goes over the lip of the platform with the beast, a sick, weightless instant before the wings open and the fall turns into flight.",
	},
	["org.journey.w18.wing.002"] = {
		"Someone I don't know buckled this saddle. I'm trusting my whole weight to a stranger's knot, and I never even got a name.",
		"The straps were tied by a pair of hands I'll never see again. A strange thing to bet everything on, a stranger's knot.",
		"Whoever checked these buckles had better know the trade. We'll find out together, the beast and I.",
	},
	["org.journey.w18.wing.003"] = {
		"listens to the wings crack open over the tower like a hide tent snapping taut in a gale.",
		"feels each downstroke through the saddle, the great wings booming like wet canvas shaken out in the wind.",
	},
	["org.journey.w18.wing.004"] = {
		"Let's be honest about who's flying. The beast knows the route; I'm the baggage that talks.",
		"I hold the reins for appearances. The beast and I both know who's choosing the way.",
		"I'm not a rider up here, I'm cargo with opinions.",
	},
	["org.journey.w18.wing.005"] = {
		"meets the beast's eye as it turns its head mid-climb to look back at its rider, with a look that is hard to read and easy to worry about.",
		"catches the flier's head swinging round in the climb to study its passenger, then turn forward again, its judgment kept to itself.",
	},
	["org.journey.w18.wing.006"] = {
		"You've done this before, yes? Good. That makes one of us who's calm.",
		"Easy on the turns. The saddle holds me, and you hold the saddle.",
		"No tricks over the city, beast. Too many people down there to land on.",
	},
	["org.journey.w18.wing.007"] = {
		"Three wingbeats past the rim and the air turns thin and cool, like stepping out of a smithy into a cellar.",
		"The air up here has nothing in it: no smoke, no dust, no voices. It's almost rude, after the city.",
	},
	["org.journey.w18.wing.008"] = {
		"tightens both knees as the beast tips sideways into the air rising off the rim and lets it carry them up in a lazy spiral.",
		"leans into the turn as the flier catches the lift off the canyon wall and climbs without beating its wings at all.",
	},
	["org.journey.w18.wing.009"] = {
		"For a little while I belong to no street and no queue. Just the saddle, the wings, and whatever is at the far end.",
		"Between the tower and the next landing, I'm nobody's errand. The only voice that wants anything is the beast's stomach.",
	},
	["org.journey.w18.wing.010"] = {
		"hears the handler's whistle from the tower as the beast lifts, one long note it seems to obey even from the air.",
		"is still within earshot of the handler's last whistle when the beast levels off, and its ears flick back as if to say it heard.",
	},
	["org.journey.w18.wing.011"] = {
		"Up close the beast smells of raw meat and old leather. A few more wingbeats and the high air will scrub that away.",
		"Nobody warns you about the smell of the flier: raw meat, musk, and a damp saddle blanket. The height helps, eventually.",
		"Close up, the beast smells of musk and its last meal. The open sky is going to be a mercy.",
	},
	["org.journey.w18.wing.012"] = {
		"Higher than the walls, lower than the clouds. That's all I ask.",
		"Wings out, beast. The city won't miss either of us.",
		"Take us up, beast. Slowly is also a speed.",
	},
	["org.journey.w18.wing.013"] = {
		"squints into the rush of air as the flight levels out, until the city below goes soft at the edges.",
		"narrows both eyes against the cold air of the climb, and the valleys below blur into a single red smear.",
	},
	["org.journey.w18.wing.014"] = {
		"The flight master took my coin with the face of someone who has never lost a passenger. I hope that's experience and not luck.",
		"Paid in full, straps tight, halfway over the wall already. Too late to ask whether they refund the coin of those who fall off.",
	},
	["org.journey.w18.wing.015"] = {
		"eyes the beast's barbed tail swinging behind like a rudder as it tilts out over the valley, and keeps both legs well clear of it.",
		"keeps a careful eye on the flier's stinging tail as it steers them out over the city, swaying a little too close to the saddle for comfort.",
	},
	["org.journey.w18.wing.016"] = {
		"A wind rider climbs like it holds a grudge against the ground. I've known orcs like that. I've liked most of them.",
		"The wind rider tears into the air as if the sky owed it money. I've always admired that in a beast.",
	},
	["org.journey.w18.wing.017"] = {
		"scratches the wind rider behind one ear as it levels out, and gets a low rumble that might be thanks or might be a warning.",
		"settles into the wind rider's saddle once the climb is done, one hand resting on the warm hide of its neck.",
	},
	["org.journey.w18.wing.018"] = {
		"Fly true, wind rider. The Horde has work for me out there.",
		"Strong wings, wind rider. Show the city how it's done.",
	},
	["org.journey.w18.wing.019"] = {
		"Walking out of Orgrimmar means the gate, the guards, the road and the dust. Flying out means one lurch, and then nothing between me and anywhere.",
		"On foot this city lets you go slowly, past every guard and stall. The air takes you all in one go.",
	},
	["org.journey.w18.wing.020"] = {
		"arranges {g:his|her} face into calm for the benefit of anyone watching from the tower, and keeps it there until the walls are out of sight.",
		"sits very straight in the saddle as the beast clears the walls, as if flying were an everyday thing and not much worth thinking about.",
	},
	["org.journey.w18.wing.021"] = {
		"The beast doesn't care what I leave behind in the city, or what waits at the other end. It only cares about the next wingbeat. I could learn from that.",
		"Wings, air, the next stroke and the one after. The beast keeps no accounts. For a while, neither do I.",
	},
	["org.journey.w18.wing.022"] = {
		"Those spikes on the wall are closer than I'd like. Up, beast, up.",
		"Wall. Wall! Good. Thank you.",
		"That was the wall. I saw the cracks in it. Higher, please.",
	},
	["org.journey.w18.wing.023"] = {
		"Hold steady while I find my stomach. It stayed on the platform.",
		"My stomach is still on the tower. Fly slower, it's trying to catch up.",
	},
	["org.muse.w18.anvil.001"] = {
		"The smiths here don't name the heat of iron with numbers. They name it after things: the color of rust, of a wolf's tongue, of a ripe cactus fruit. An apprentice learns the whole list before touching a hammer.",
		"Ask an orc smith whether the iron is ready and she'll squint and tell you it's only at wolf's tongue. She's waiting for straw.",
		"Rust, wolf's tongue, straw, bone: the smiths of this city read hot iron the way herders read a sky before a change.",
	},
	["org.muse.w18.anvil.002"] = {
		"watches a smith's apprentice work the bellows until both arms tremble, while the smith, eyes on the coals, never once says stop.",
		"stops beside a forge where a youngster pumps the bellows in a steady rhythm, jaw set, waiting for a word from the master that does not come.",
	},
	["org.muse.w18.anvil.003"] = {
		"Miners bring their ore into the city with a chalk mark on every sack, each miner's own sign. The smiths know which marks mean honest copper and which mean half of it is rock.",
		"Every sack of ore that comes down from the hills carries a scrawl of chalk. A smith told me he reads them like names: this one never cheats, that one sells you gravel with a copper coat.",
		"A chalk sign on a sack of ore is a miner's whole reputation. Smudge it and the smiths will weigh the sack twice.",
	},
	["org.muse.w18.anvil.004"] = {
		"Every smith here is crying out for tin, and every miner swears Durotar's hills are copper and nothing else.",
		"No tin, no bronze. Somebody go and tell the hills.",
		"Copper everywhere, tin nowhere. A smith just offered me a hot meal for a single bar.",
	},
	["org.muse.w18.anvil.005"] = {
		"A miner's hands never come clean. The grit lives in the cracks of the knuckles, and he can weigh a lump of ore in his palm and tell copper from tin before he has looked at it.",
		"I shook hands with a miner by the smithies. It was like gripping a rock that someone had taught to be polite.",
		"Miners spend their days in the hills and their coin at the smithies. You know them by the knuckles, scraped raw and healed thick, over and over.",
	},
	["org.muse.w18.anvil.006"] = {
		"In the camps the humans held every key and every nail. Now an orc smith hammers out a hinge for her own door, hangs the door, and shuts it when she likes. My people still find that a small wonder.",
		"Behind the fences my people owned no iron, not even a spoon. Every hinge and latch in this city was made by orc hands for orc doors, and I never pass a smithy without thinking of it.",
	},
	["org.muse.w18.anvil.007"] = {
		"listens as two anvils along the Drag fall into the same beat for a dozen strokes, then drift apart, each smith back to a rhythm of their own.",
		"slows at the sound of two hammers on two anvils striking in turn, like a pair of old friends walking in step, until one of them pauses to turn the work.",
	},
	["org.muse.w18.anvil.008"] = {
		"Three smiths, three opinions on the quench. One swears by brine, one by oil, and the third keeps a barrel he won't let anyone look into.",
		"The smiths of Orgrimmar will share a drink, a bench and an enemy. What's in the quenching barrel, never.",
		"Ask a smith what's in his quenching barrel and you'll get a long answer about the weather, the price of tin and his bad knee.",
	},
	["org.muse.w18.anvil.009"] = {
		"After a campaign the grunts queue at the smithies with notched axes, and the smith runs a thumb along each edge as if reading a letter. This one met armor. This one met bone. This one met something he doesn't name.",
		"A good smith can tell where an axe has been by its notches. I watched one go quiet over a grunt's edge, file it smooth without a word, and charge him half.",
		"The repair bench tells the war better than the veterans do. Every notch filed out of an axe is a sentence nobody will say aloud.",
	},
	["org.muse.w18.anvil.010"] = {
		"Don't touch the dark iron on the anvil. Dark doesn't mean cold.",
		"Black iron, hot iron. Ask anyone at the smithies with a scar across the palm.",
		"Iron goes dark long before it goes cold. The smiths let you learn that once.",
	},
	["org.muse.w18.anvil.011"] = {
		"At night the smithies bank their coals under ash rather than let them die, and the glow leaks out through the cracks of shut doors all along the street, like eyes half closed.",
		"The forges are shut for the night but not cold. Through every gap in every workshop door shows a thin red line of banked coal, keeping watch for the hammers of the next day.",
	},
	["org.muse.w18.anvil.012"] = {
		"Nothing made of iron is ever thrown away in Orgrimmar. A cracked helm comes back as nails, the nails as a hinge, and the hinge, one day, as somebody's belt buckle. Iron here has more lives than a cat.",
		"The scrap heaps behind the smithies are the most honest market in the city: a broken pot, a snapped chain, half a stirrup, all waiting patiently to become something else.",
		"A smith picked a bent nail out of the dust, straightened it with two taps and dropped it in her apron. In this city iron is never finished.",
	},
	["org.muse.w18.anvil.013"] = {
		"flinches as a smith plunges something glowing into a barrel and a hissing cloud of steam rolls out across the way, then waits for it to clear.",
		"steps back from a quenching barrel a moment too late, and walks on through a puff of steam that smells of hot iron and old water.",
		"is wrapped for a moment in the steam of a smith's quench, and comes out of it blinking, to the smith's open amusement.",
	},
	["org.muse.w18.anvil.014"] = {
		"Every axe on the wall went across an anvil in this city before it went across a battlefield. When the Horde marches, it marches on a smith's sore shoulders.",
		"Our grunts get the songs. The smiths get the burns, the bad backs and the first sight of every dent the war sends home.",
		"For every grunt who comes home with a tale, there's a smith who knows the real one. It's written in the dents.",
	},
	["org.muse.w18.anvil.015"] = {
		"One smith swears her anvil crossed the sea in the hold of a stolen ship, wrapped in hides like a sleeping child, and was the first thing carried ashore. She tells it every time somebody leans on it.",
		"An old smith tells anyone who'll listen that his anvil came over the sea with the first ships, lashed to the deck. He won't say how many orcs it took to lift, because the number keeps growing.",
	},
	["org.muse.w18.anvil.016"] = {
		"The mining trainer's first lesson is about listening. Tap the rock with the pick and hear whether it rings or thuds; ore sings a little higher than stone.",
		"Miners learn to hear a vein before they see it, the trainer says. Good rock rings under the pick. Bad rock just sulks.",
		"A miner taught me to knock on a cliff like a door and wait for the answer. Copper, she says, answers brighter.",
	},
	["org.muse.w18.anvil.017"] = {
		"That smith's been beating the same strip for ages. Either it's a masterpiece or it insulted her.",
		"Either that iron owes the smith money, or it's going to be beautiful.",
	},
	["org.muse.w18.beast.001"] = {
		"A saddled wolf trots by with no rider, turning corners without a moment's doubt. It knows the way to the pens better than I know the way to the bank.",
		"No rider, saddle still on, and the wolf takes every turn of the city with confidence. Sent home on its own, I suppose, like a well-trained letter.",
		"There goes a riderless wolf, saddle flapping, picking its way through the crowd like a regular. Somebody stayed at the inn; the wolf had better things to do.",
	},
	["org.muse.w18.beast.002"] = {
		"passes a raptor tied by a shop doorway, tapping one long claw on the stone with the patience of a creditor.",
		"edges past a raptor tethered outside a shop; the long head turns to follow every step, slow and interested, the whole length of the street.",
	},
	["org.muse.w18.beast.003"] = {
		"sees a rider swing down from a wolf, and the wolf drop onto the stone in the very same instant, like a cloak let fall.",
		"notices a wolf go flat on the ground the moment its rider steps off, with a groan that says the whole day was a personal favor.",
		"smiles at a wolf that sags to the ground as soon as its rider's boots touch stone, and stays there, refusing all further duties.",
	},
	["org.muse.w18.beast.004"] = {
		"A kodo brushed the wall as it passed and left a long clean stripe in the dust. The wall looks almost embarrassed.",
		"Kodos keep the walls of the narrow streets polished. Every corner they squeeze round has a smooth band at flank height, dull as old leather.",
	},
	["org.muse.w18.beast.005"] = {
		"Two wolves met nose to nose in the middle of the road, and their riders had to sit there while the wolves finished their greetings. Nobody hurries a wolf's manners.",
		"Two riders stuck in the street, glaring at each other, while their wolves sniff each other slowly and thoroughly. In Orgrimmar the beasts handle the introductions.",
		"Traffic stopped for a good while just now: two wolves had met and had a great deal to say to each other's noses. The riders could only wait.",
	},
	["org.muse.w18.beast.006"] = {
		"Good wolf. Fine wolf. Please stop yawning at me.",
		"Lovely teeth. Really. You can put them away now.",
	},
	["org.muse.w18.beast.007"] = {
		"notices every wolf in the street lift its head in the same moment as a butcher's door bangs open, a dozen noses swinging round together.",
		"follows the eyes of the wolves as a butcher tips a bucket of scraps behind his shop, and sees them arrive from three directions as if called by name.",
	},
	["org.muse.w18.beast.008"] = {
		"Kodos in the street, swaying the way they sway on the plains. A little of Mulgore walking on stone, and it doesn't seem to mind the change.",
		"When a kodo goes by I hear its slow step before I see it, and for a moment the stone under me feels like grass.",
	},
	["org.muse.w18.beast.009"] = {
		"The old ones say there were no wolves in the camps. Now they trot loose through our own streets, and some of the elders still stop to watch them, as if making sure they're real.",
		"Wolves running free in an orc city. My elders went years without that sight, behind the humans' fences. Some of them still reach out to touch every wolf that passes.",
	},
	["org.muse.w18.beast.010"] = {
		"makes way for a kodo carrying what looks like a whole household on its back, pots clanking, with a small tauren asleep on top of the pile.",
		"stops to let a heavily laden kodo through, rugs and poles and pots lashed high, and a tauren calf dozing at the summit.",
	},
	["org.muse.w18.beast.011"] = {
		"A raptor follows me with one yellow eye, head cocked. I've had that look from goblin traders: it's working out what I'd fetch.",
		"Raptors look at you sideways, one eye at a time, weighing. I'd swear one just priced me by the pound.",
	},
	["org.muse.w18.beast.012"] = {
		"steps aside for a peon with a shovel and a bucket, who follows the wolf riders around the city with the resignation of a long career.",
		"lets a peon pass who is trailing a pack of wolves down the street with a shovel, cleaning up behind them without once looking up.",
	},
	["org.muse.w18.beast.013"] = {
		"Nearly every wolf in this city has a torn ear or an old scar on the muzzle. A handler told me a wolf with neither hasn't finished its schooling.",
		"Notched ears, scarred noses: the wolves of Orgrimmar wear their quarrels on their faces. The handlers say that's how a pack settles who eats first.",
		"Look closely at the wolves here and every one carries a mark of some old squabble. The handlers don't mind; a wolf, they say, learns its place with its teeth.",
	},
	["org.muse.w18.beast.014"] = {
		"sees a Forsaken ride in on a skeletal horse, and every wolf along the street lift a lip, very slightly, then think better of it.",
		"catches the wolves along the road going stiff as a bony horse clicks past under its Forsaken rider; not one of them growls, and not one looks away.",
	},
	["org.muse.w18.beast.015"] = {
		"Every post near the wolf pens is chewed to the height of a wolf's jaw. The peons replace them; the wolves treat each new one as a gift.",
		"Posts by the wolf pens wear a ring of tooth marks at jaw height. Fresh timber goes in every so often, and the wolves greet it like a new toy.",
	},
	["org.muse.w18.beast.016"] = {
		"Kodo coming through. You'll smell it before you see it. Hay, mud and old rug.",
		"Wonderful beast, the kodo. Smells like a wet tent that's been through a war.",
		"Make way for the kodo. And for its smell, which arrived first.",
	},
	["org.muse.w18.beast.017"] = {
		"Whose wolf is this? It's decided I'm its new pillow.",
		"No, I don't have any meat. Stop checking my pockets.",
	},
	["org.muse.w18.camps.001"] = {
		"The listlessness of the camps comes up in the old orcs' talk like an illness with no name: warriors who once broke battle lines, sitting all day by the fence, too tired to want what lay beyond it.",
		"What the camps did wasn't the beatings, an elder told me. It was the slow gray quiet that settled on everyone, until even the strongest stopped looking at the gate.",
	},
	["org.muse.w18.camps.002"] = {
		"follows the slow meal of an old orc who eats with one arm curled around the bowl, a habit nobody at the table remarks on.",
		"sees an elder by a cookfire shielding his bowl with a forearm as he eats, though nobody near him is reaching for it.",
	},
	["org.muse.w18.camps.003"] = {
		"A gray grunt at the inn counts the room every time he sits down. A camp habit, he says: a missing face at roll call meant trouble for everyone left.",
		"There's an elder who can't sit anywhere without first counting heads. In the camps, he explains without being asked, you always knew how many of you there were.",
	},
	["org.muse.w18.camps.004"] = {
		"The camp guards were mostly farmers in borrowed mail, bored and a little afraid, as one old orc remembers them. That was worse, somehow, than cruelty would have been.",
		"Nobody hated us much in the camps, an elder said once. They just forgot we were people. He says it flatly, and then changes the subject.",
		"One guard used to slip the prisoners extra bread and never once looked them in the face, an elder recalls. He still can't decide what to make of that man.",
	},
	["org.muse.w18.camps.005"] = {
		"Hardly a fence in this city. Spikes, yes. Fences that keep folk in, never. I don't think that's an accident.",
		"Walls in Orgrimmar keep things out. I've yet to see one built to keep anybody in.",
		"Plenty of walls in this city. Not one of them faces inward.",
	},
	["org.muse.w18.camps.006"] = {
		"Every door in this city bolts from the inside. An old orc pointed it out to me as if it were the finest carving in Kalimdor.",
		"The latches here are all on the inner side of the doors. An elder once made me try one, sliding it back and forth, until I understood why he was smiling.",
	},
	["org.muse.w18.camps.007"] = {
		"A veteran I met fought in a human lord's arena for other people's wagers. He'll spar with anyone in the Valley of Honor now, gladly, but if a coin changes hands on the bout, he walks away.",
		"Some orcs in the city were fighting-pit slaves before they were anything else. One of them told me he still can't stand to hear a crowd cheer a wound.",
	},
	["org.muse.w18.camps.008"] = {
		"An old peon salts everything, even his bread. Years of camp gruel, he says, taught his tongue to beg, and he has never stopped feeding it.",
		"At the cookfires there's an elder who empties half a pouch of pepper into every bowl. After the gruel of the camps, he says, he made himself a promise about flavor.",
	},
	["org.muse.w18.camps.009"] = {
		"notices an old orc rap his knuckles on an open doorframe as he passes through, light as a greeting, the way some of the elders always seem to.",
		"watches an elder pause at a doorway, rest a palm flat on the open door for a moment, and walk through without a word.",
	},
	["org.muse.w18.camps.010"] = {
		"The tellers don't hide it: when the camp gates were broken open, some orcs did not walk out. They had to be argued with, or carried.",
		"Freedom didn't come all at once, the elders say. The gates went down in an hour; getting some of the prisoners to stand up took a season.",
		"The hardest gate to open, an old shaman says, was the one inside each prisoner. Thrall broke the wooden ones; the rest took longer, and a few are shut still.",
	},
	["org.muse.w18.camps.011"] = {
		"When an elder of my people speaks of the camps, I keep quiet. The least I owe them is to listen without explaining their own story back to them.",
		"Our elders tell the camps in pieces, a little here and there, never in order. I've learned not to ask for the rest. It comes when it comes.",
	},
	["org.muse.w18.camps.012"] = {
		"The camps stood in Lordaeron. Now Lordaeron is a dead kingdom, the Forsaken walk where the wardens walked, and the prisoners have a capital. Nobody here laughs about it. They don't need to.",
		"The hills he remembers from behind the fence are Forsaken country now, an old orc told me. He said it without triumph, the way you'd note that a river has changed its bed.",
		"Lordaeron built the camps to last. It didn't, and they didn't, and the orcs did. An elder counts it off on three fingers, and that is the whole lesson.",
	},
	["org.muse.w18.camps.013"] = {
		"lingers near an old orc and a Forsaken who have found they both knew the same Lordaeron hills, one from behind a camp fence and one from before the grave, and neither seems sure what to make of the other.",
		"overhears an elder orc and a Forsaken apothecary discover they once lived a day's walk apart in Lordaeron, on opposite sides of a fence; the talk stops there and then, carefully, goes on.",
	},
	["org.muse.w18.camps.014"] = {
		"In a doorway off the Drag, a dented human helmet holds a little pot of herbs. Its owner took it from a camp warden on the day the gates fell, and swears it has never been so useful.",
		"Somebody keeps his spoons in a warden's helmet with the plume torn off. He took it from a camp guard, the old orc says, and it has carried better things since.",
	},
	["org.muse.w18.camps.015"] = {
		"May every gate in this city stay open, and every lock stay on the inside.",
		"Open gates and inside latches. That's all a city needs to be a city.",
	},
	["org.muse.w18.camps.016"] = {
		"Somewhere in Lordaeron's old archives there must have been ledgers of these orcs: numbered, fed, counted. Walking past them in their own city, I'm glad I never read those pages.",
		"My side kept these people in pens and called it mercy, because the other choice was the axe. Their grandchildren sell me bread now. I pay without haggling.",
	},
	["org.muse.w18.camps.017"] = {
		"Rain on Orgrimmar, and an old orc stands out in it scowling. It rained all the time in the camps of Lordaeron, he tells anyone near him, and he crossed a sea to be rid of it.",
		"An elder curses the rain as it comes down the canyon. In the camps it never stopped, he mutters, and he'd thought Durotar had more sense.",
	},
	["org.muse.w18.camps.018"] = {
		"The elders of my people carry the camps in small ways: a flinch at a whistle, a crust saved in a pocket. Whatever I carry of it, they carried more.",
		"Every old orc I know saves the heel of the bread. Nobody says why. Among us, nobody has to.",
	},
	["org.muse.w18.camps.019"] = {
		"notices an old orc stop short at the jangle of a ring of keys on a passing goblin's belt, then shake his head at himself and walk on.",
		"sees an elder turn sharply at a rattle of keys in the crowd, hold very still for a moment, and then let it go with a grunt.",
	},
	["org.muse.w18.camps.020"] = {
		"The elders don't talk about the camps much. When they do, I put my mug down.",
		"When an old one starts on the camps, the whole table goes quiet. Even the goblin.",
	},
	["org.muse.w18.caravan.001"] = {
		"stands aside as a kodo caravan from the Barrens sways in through the gate, a tauren drover walking at the lead beast's head and murmuring to it like an old friend.",
		"waits for a long kodo train to plod past, crates roped high on every back and a tauren drover at the front who never once raises a voice.",
		"lets a caravan of kodos rumble by, the beasts so heavily loaded that each step sounds like a decision.",
	},
	["org.muse.w18.caravan.002"] = {
		"The caravans bring the Barrens in with them: yellow grass caught in the harness, burrs in the folds of the kodos' hides, a thorn somebody is still trying to dig out of a boot.",
		"After a caravan has passed, the road is littered with dry yellow stalks shaken off the kodos. For a few steps the canyon smells of open savanna.",
		"Every kodo that comes in from the west trails a little of the Barrens behind it, grass seed and pale dust, and the peons sweep it up without knowing what they're sweeping.",
	},
	["org.muse.w18.caravan.003"] = {
		"This caravan came in with a splintered crate, a kodo limping on a bound leg and, if the empty saddle means anything, one guard fewer than it set out with. Nobody unloading says a word about the Barrens.",
		"There are fresh gouges down the side of one of the caravan's wagons, and the drivers unload in silence. Centaur, somebody mutters at the gate, and nobody asks any more than that.",
	},
	["org.muse.w18.caravan.004"] = {
		"A caravan just came in. Give it an hour and every price in the Drag drops a copper. I can wait.",
		"Never buy hides the day a caravan arrives. Buy them the day after, when the traders are sick of looking at the pile.",
		"Kodos at the gate, crates on the ground. Hold on to your coin, friends; it's about to be worth more.",
	},
	["org.muse.w18.caravan.005"] = {
		"watches a caravan master tally crates against a list, frown, start over and get a different number, while the kodos look on without any sympathy whatever.",
		"lingers beside a caravan master counting the unloaded crates for the third time, the total stubbornly one away from what the list insists on.",
	},
	["org.muse.w18.caravan.006"] = {
		"Some of the crates coming up from the Barrens started their trip in Ratchet, off goblin ships. You can smell it when the lids come off: salt, tar, and somewhere much farther away.",
		"Goods from Ratchet reach Orgrimmar on kodo-back, salt still in the straw. A bolt of foreign cloth, a jar of something pickled, a whiff of harbor at the bottom of a canyon.",
		"The Ratchet crates are easy to spot: stenciled in goblin script, packed in seaweed, and opened by every trader in reach with the eagerness of a child at a feast.",
	},
	["org.muse.w18.caravan.007"] = {
		"Every caravan I've seen here comes with the same argument built in: the goblin who owns the goods, the orc who guarded them and the tauren who actually walked the kodos, each sure the trip was his doing.",
		"The goblin counts the money, the orcs count the dangers and the tauren drover counts the kodos. Then they all argue over whose count matters.",
		"Behind every caravan there's a goblin with the ledger, an orc with the scars and a tauren with the patience, and each one tells the trip as a story about himself.",
	},
	["org.muse.w18.caravan.008"] = {
		"pauses beside a tauren drover rubbing down a kodo's huge forelegs with a rag, slowly, as the beast lets out a long, rumbling groan of relief.",
		"slows to watch a drover kneel to check the feet of every kodo in the string, one by one, before anyone is allowed to unload a single crate.",
		"stops by a kodo that has folded its legs right in the road, while its drover sits against its flank and shares a waterskin with it, a mouthful each.",
	},
	["org.muse.w18.caravan.009"] = {
		"When a caravan unloads here in the Valley of Strength, the whole valley turns into a game of stepping over crates. The bank is still in there somewhere, behind a wall of salt sacks.",
		"A caravan has stopped in the middle of the valley to unload, and now the way to the bank goes over crates, under ropes and between two kodos who don't care for each other.",
	},
	["org.muse.w18.caravan.010"] = {
		"Caravan guards, just paid. Watch them: inn first, bath maybe, sleep never.",
		"There go the caravan guards with their wages. The innkeeper's about to have a very good week.",
		"Look at those caravan hands make for the inn. Weeks of dust, and every grain of it wants a mug.",
	},
	["org.muse.w18.caravan.011"] = {
		"The drovers don't count the road to the Crossroads in miles. They count it in water: so many skins, so many holes, so many days of the kodos grumbling.",
		"Ask a caravan drover how far it is to the Crossroads and you get an answer in waterholes, not leagues. Out in the Barrens, that's the only distance that matters.",
		"Three wells and a muddy hole, a drover told me when I asked the way west. It took me a while to understand he'd given me the distance.",
	},
	["org.muse.w18.caravan.012"] = {
		"catches a caravan forming up in the gray first light, kodos lowing as the ropes go tight and a drover walking the line with a lantern, checking every knot.",
		"stops to see a kodo train being loaded in the early cool, crate by crate, the drovers moving quietly so as not to wake the half of the valley still asleep.",
	},
	["org.muse.w18.caravan.013"] = {
		"When a full kodo caravan goes by, the cups on the stalls rattle and the dust on every ledge jumps. Orgrimmar has its own small earthquakes, and they all smell of kodo.",
		"A kodo train rolls past and the whole street hums with it: pots chatter on their shelves, a loose spike in a fence ticks against its post. Nobody even looks up.",
	},
	["org.muse.w18.caravan.014"] = {
		"Every caravan that makes it up from the Barrens is a small battle won: centaur, quilboar and thirst, all beaten without a single drum. Nobody sings about it, and somebody should.",
		"A caravan reaching our gate whole is worth more to the Horde than half the boasting at the inn. Somebody walked those kodos past every raider in the Barrens to get here.",
	},
	["org.muse.w18.caravan.015"] = {
		"That kodo is hauling more than I own, and it looks happier about it than I do.",
		"Look at the load on that kodo. Everything I own would fit in one of its saddlebags, with room left for lunch.",
	},
	["org.muse.w18.courier.001"] = {
		"notices a courier walking, not running, toward the Valley of Wisdom, and sees the people who notice it too fall quiet one after another.",
		"marks a messenger crossing the valley at a slow, even walk; around the satchel the crowd goes silent, because a courier stops hurrying for only one kind of news.",
	},
	["org.muse.w18.courier.002"] = {
		"A courier on a lathered wolf just came through the gate and nearly fell out of the saddle handing over the satchel. Two grunts caught him, and someone led the wolf off before it could lie down in the road.",
		"The courier who rode in a moment ago could barely stand once the satchel left his hands. They gave the message to a runner and the rider to a bench.",
		"Somebody's dispatch just arrived at a gallop, and the rider who brought it is sitting on the ground by the gatepost, staring at nothing, while a grunt holds a cup to his mouth.",
	},
	["org.muse.w18.courier.003"] = {
		"A goblin by the bank will carry a letter anywhere in Kalimdor and charges by the word. It has done wonders for the grunts' prose: 'Alive. Send boots.'",
		"Letters carried, priced by the word, says the goblin courier's board. Half the notes I see handed over are three words long, and one of them is always 'coin'.",
	},
	["org.muse.w18.courier.004"] = {
		"is stopped by a young courier who asks, very quietly, which way the Valley of Honor lies, and then sprints off as if the question had never been asked.",
		"gets asked the way by a courier in a great hurry and greater embarrassment, and watches the satchel vanish into the crowd before the answer is finished.",
	},
	["org.muse.w18.courier.005"] = {
		"No courier has ever come running with my name on a satchel. Watching them dash past, I can't decide whether that's freedom or the other thing.",
		"Every runner in this city is carrying somebody's news. None of it is mine, and some days that's a relief, and some days it isn't.",
		"The satchels go by full of other people's lives. I watch them pass like boats on a river I'll never fish.",
	},
	["org.muse.w18.courier.006"] = {
		"At the inn the couriers drink for nothing. They pay in news, and the innkeeper weighs every rumor like a coin before she pours.",
		"A courier never pays for a mug at the inn. A skirmish in Ashenvale buys one, a scandal at the Crossroads buys two, and the innkeeper keeps the tab in her head.",
		"Couriers are the inn's best customers and its worst payers. Every mug goes on the tab of whatever news they brought.",
	},
	["org.muse.w18.courier.007"] = {
		"keeps clear as a courier swings down at the gate, drains a whole waterskin standing up and vaults onto a fresh wolf without once letting go of the satchel.",
		"times a dispatch rider trading a spent wolf for a fresh one in less time than it takes to tie a boot, the satchel never leaving the shoulder.",
		"makes way at the gate for a courier's change of mounts: one wolf led away limping and steaming, another already turning toward the road before the rider is settled.",
	},
	["org.muse.w18.courier.008"] = {
		"The couriers carry orders they'll never read and news they'll never hear the end of. Half the business of Orgrimmar passes through hands that don't know what they're holding.",
		"A courier doesn't read the satchel. That's the whole craft, one of them told me: run fast, ask nothing, and forget the face you hand it to.",
		"Sealed satchel, closed mouth, quick feet. Ask a courier what's inside and you get the look a grunt gives a pickpocket.",
	},
	["org.muse.w18.courier.009"] = {
		"Make way for the courier! No, not me. Him. The fast one.",
		"Mind the runner! Too late. He'll live, and so will the cart.",
		"Courier coming through, everyone. Flatten yourselves against something.",
	},
	["org.muse.w18.courier.010"] = {
		"You can read the war on the couriers' faces. Ashenvale news comes in grim and fast, Barrens news comes in dusty and bored, and the riders from the coast always ask for the same officer.",
		"Nobody tells a passerby how the fighting goes out there. But watch the couriers come in through the gate, how fast and how worn, and you can guess well enough.",
		"I've learned more about the war from the couriers' boots than from any talk at the inn: mud means Ashenvale, ash means trouble in the south, and blood means nobody is saying anything.",
	},
	["org.muse.w18.courier.011"] = {
		"steps quietly past a courier asleep on a bench by the wall, boots on, satchel under the head and one hand closed tight on the strap.",
		"lowers {g:his|her} voice passing a courier who has fallen asleep sitting up in a corner, the dispatch bag hugged like a child.",
	},
	["org.muse.w18.courier.012"] = {
		"Every courier who runs past makes me wonder what's in the satchel. Orders, letters, or a description of a stranger who doesn't belong here.",
		"I watch the couriers more closely than anyone in this city does. One of those sealed satchels might carry my face someday, written down.",
	},
	["org.muse.w18.courier.013"] = {
		"Run well, courier. May the next bag be lighter.",
		"Go on, runner. Good news, I hope, for whoever's waiting.",
	},
	["org.muse.w18.courier.014"] = {
		"The couriers run a different Orgrimmar from the one I walk: ledges, back stairs, a gap between two huts barely a shoulder wide. They're across the city before I've finished the first ramp.",
		"Follow a courier with your eyes and you learn there are shortcuts all over this city, up walls and through doorways nobody else seems to think are doorways.",
	},
	["org.muse.w18.crossing.001"] = {
		"Over one doorway off the Drag the lintel is curved like the rib of a hull, black with old tar. Ship's timber, the owner says, from the crossing. He knocks on it for luck when he leaves.",
		"A beam in an old hut still has the bend of a keel and a row of rusted nail holes. It came over with the orcs, a grunt says, and refused to become firewood.",
	},
	["org.muse.w18.crossing.002"] = {
		"Orcs don't trust the sea, a grunt told me, and they crossed it anyway, all of them, sick to the last one. That, he says, is the whole story of his people in one sentence.",
		"The veterans hate any water deeper than a trough. And yet they crossed an ocean, one of them said, because the far shore was the only place nobody had a fence ready.",
	},
	["org.muse.w18.crossing.003"] = {
		"watches an old veteran stand at ease with a faint, steady sway, as if the ground were a deck; the grunts beside him swear the crossing never left his knees.",
		"catches an elder who, even standing still, rocks very slightly from heel to toe, the way sailors do, while his companions pretend not to see it.",
	},
	["org.muse.w18.crossing.004"] = {
		"The veterans still argue about the stranger who told Thrall to sail west. A man in a cloak, says one; a great black bird, says another; a madman, says a third. They agree only that he was right.",
		"Somebody warned Thrall to take his people over the sea before the plague came, the old orcs say. Who it was, they can't settle, and they've stopped trying. The warning was enough.",
	},
	["org.muse.w18.crossing.005"] = {
		"The Darkspear tell the crossing with a different hero: not Thrall but the sea, which tossed the orcs onto their island just when the trolls needed someone to throw at their enemies.",
		"In the trolls' telling, the orc ships didn't land on the isles by chance. The loa sent them, a Darkspear explained, and the loa would like that remembered.",
	},
	["org.muse.w18.crossing.006"] = {
		"A whole people of orcs on ships. I'd have paid good silver to watch the first one try a rope ladder.",
		"Orcs at sea. There's a gull out there that still remembers it and shudders.",
		"Picture a ship full of orcs in a heavy swell. Now picture whoever had to clean it.",
	},
	["org.muse.w18.crossing.007"] = {
		"A grunt at the gate remembers his first sight of Kalimdor from the rail: a red coast, no walls, nobody's banner planted on it. He says it looked like a hand held out.",
		"The lookouts shouted land, an old orc recalls, and there it was: a long line of red rock, empty, waiting. Nobody cheered. They all just stared, as if someone might take it back.",
	},
	["org.muse.w18.crossing.008"] = {
		"stops to watch a gang of children play at the crossing: a plank across two crates for a ship, one small orc bellowing orders, and a troll child being seasick with great conviction.",
		"steps around a children's game in the street, where a row of cubs sits on a bench rowing at nothing while the smallest stands on a barrel shouting land.",
	},
	["org.muse.w18.crossing.009"] = {
		"A cooper in the city still seals his barrels with ship's tar, and the elders who pass slow down at the smell. The crossing, one told me, smelled exactly like that, plus fear.",
		"Near a cooper's shed the air smells of hot pitch, and the old orc walking ahead of me stops dead, then laughs at himself. The ships, he says. Every plank of them stank of it.",
	},
	["org.muse.w18.crossing.010"] = {
		"The fleet that carried the orcs to Kalimdor was borrowed from Lordaeron's harbors, the veterans say with a grin. Nobody has ever offered to return it.",
		"Lordaeron lent the orcs a fleet, as one old grunt likes to put it. It didn't know it was lending and never got the ships back, but it was very generous all the same.",
		"Where did the ships come from? A gift, a veteran will tell you. From whom? Lordaeron didn't object, he'll say. Not out loud, anyway.",
	},
	["org.muse.w18.crossing.011"] = {
		"Not every ship of the crossing reached the coast, the elders say, and they don't name the lost in a crowd. Some names were left out at sea, and that is where they keep them.",
		"Ask how many sailed and how many landed and the old orcs give two numbers, then look away. The difference is still out there on the sea.",
	},
	["org.muse.w18.crossing.012"] = {
		"We came over the sea in borrowed hulls, orc and troll packed together, nobody sure of the other shore. Every time I walk these streets I'm walking the far end of that voyage.",
		"The crossing isn't over, an old shaman told me. Every orc who walks Orgrimmar is still stepping off those ships. I think of it at the bank, of all places.",
	},
	["org.muse.w18.crossing.013"] = {
		"When the tauren first met Thrall's orcs on the plains, the elders of the Valley of Wisdom say, they took them for shipwrecked strangers. In a way, a tauren added, they were right.",
		"Lean, loud, salt still in their hair, asking the way to nowhere in particular: that's how an old tauren remembers the orcs arriving inland. The herds liked them, he says, before the elders did.",
	},
	["org.muse.w18.crossing.014"] = {
		"On the cliffs toward the coast, the grunts say, lookouts still watch the sea for sails. Kul Tiras came once with a fleet; they don't mean to be caught unready a second time.",
		"Every grunt who has stood watch above the coast knows the shape of a Kul Tiran topsail. They were taught it, a veteran says, the way children are taught the shape of a scorpid's tail.",
	},
	["org.muse.w18.crossing.015"] = {
		"To whoever kept those stolen ships afloat. Nobody ever tells a story about the ones bailing.",
		"Every tale of the crossing has a captain in it. I'd like to hear one about the orc with the bucket.",
	},
	["org.muse.w18.crossing.016"] = {
		"runs a finger along a row of tiny hulls carved into an old post near the inn, a dozen or so, the last few scored through with deep, deliberate cuts.",
		"notices a little fleet of boats whittled into a beam, worn shiny at one end where passing hands seem to touch them.",
	},
	["org.muse.w18.crossing.017"] = {
		"An ocean, stolen ships and hardly a sailor among them. That's not courage. That's a whole people refusing to drown.",
		"Crossing a sea with nobody who could sail. I'd call that mad if it hadn't worked.",
	},
	["org.muse.w18.depths.001"] = {
		"Near the way down to Ragefire Chasm little bands gather to check straps and count heads, the way people do before walking into a fire on purpose.",
		"There's always a knot of armed folk by the descent into Ragefire Chasm, tightening buckles, arguing about who goes first, pretending not to look down.",
	},
	["org.muse.w18.depths.002"] = {
		"The troggs came up out of the deep rock under the city, the Cleft's old hands say, from somewhere nobody has mapped. A trogg only knows one direction, and it's the one nobody else wants to go.",
		"Nobody knows where the troggs under Orgrimmar came from. Down, says everyone who's asked, as if that were an answer. Perhaps for a trogg it is.",
	},
	["org.muse.w18.depths.003"] = {
		"The worst thing about the Burning Blade isn't the fire. It's that the faces under those hoods are orc faces, and some of them have cousins selling bread one floor up.",
		"Under the Cleft the cultists wear the same tusks as the grunts on the wall. Whatever the Burning Blade worships, it recruits from the same streets as everyone else.",
	},
	["org.muse.w18.depths.004"] = {
		"makes way for a sooty, singed band climbing back up out of Ragefire Chasm into the Cleft, blinking at the dim torches as if they were dazzling.",
		"steps aside for a party coming up from Ragefire Chasm, smelling of smoke and burnt hair, every one of them grinning or limping or both.",
	},
	["org.muse.w18.depths.005"] = {
		"Ragefire Chasm. The name's a warning, and the smell's a second one.",
		"Whoever named that chasm didn't waste a word on politeness. Good. Neither will I: no.",
	},
	["org.muse.w18.depths.006"] = {
		"The chasm was burning long before anyone laid a stone in this canyon. Orgrimmar sits on top of it the way a pot sits on a coal: comfortably, until somebody forgets to stir.",
		"Before the walls, before the gate, the fire was already down there. The city was built over it like a lid, and lids rattle.",
	},
	["org.muse.w18.depths.007"] = {
		"Every great city keeps something in the cellar. Most settle for rats. Orgrimmar has troggs, cultists and a river of fire, and still complains about the rats.",
		"Rats in the cellar, the other capitals say, as if that were trouble. Orgrimmar's cellar has cultists and molten rock, and the grunts call it the basement.",
		"Other capitals worry about damp in the cellar. Orgrimmar's has the opposite problem, and a cult living in it.",
	},
	["org.muse.w18.depths.008"] = {
		"At night the Cleft is the warmest corner of Orgrimmar, thanks to whatever burns below it. Nobody lingers to enjoy it.",
		"The canyon cools fast after dark, except down by the Cleft, where the rock stays warm all night from the fire underneath. Not one soul sleeps there by choice.",
	},
	["org.muse.w18.depths.009"] = {
		"The Burning Blade was a clan once, the elders say, with a banner and a hearth like any other. Now it's the one clan name in Orgrimmar nobody says above a mutter.",
		"Ask an old orc about the Burning Blade and he'll tell you it was a clan before it was a cult. Then he'll change the subject, quickly, the way you'd step off a hot stone.",
	},
	["org.muse.w18.depths.010"] = {
		"The Warchief could march his grunts down into the chasm. Instead, the grunts say, he lets anyone with a weapon and a reason try their luck. Cheaper, and the walls stay manned.",
		"Clearing out Ragefire Chasm seems to be left to volunteers. The grunts call it a test of mettle. The volunteers, coming back up, call it other things.",
	},
	["org.muse.w18.depths.011"] = {
		"Going down there? Take water. Take twice what you think.",
		"Ragefire? Bring water, bring a spare cloak, and bring somebody who can run.",
		"Down into the chasm? Leave the heavy cloak behind. Take a friend who doesn't mind carrying you.",
	},
	["org.muse.w18.depths.012"] = {
		"Thin smoke seeps from a crack in the floor of the Cleft, smelling of sulfur. Somebody has stuffed it with rags. The rags are smoking too.",
		"A wisp of yellowish smoke rises from a split in the rock of the Cleft. A rag has been jammed into it, a stone set on the rag, a second rag tucked round the stone, and still it seeps.",
	},
	["org.muse.w18.depths.013"] = {
		"feels a long low rumble rise through the rock from somewhere deep below the Cleft, and sees the people around carry on talking as if the city had only cleared its throat.",
		"stops at a deep grumble coming up through the stones underfoot; the others in the Cleft wait it out with the patience of long habit.",
	},
	["org.muse.w18.depths.014"] = {
		"Down in the chasm, orcs still kneel to the fire we spat out. Every one of them is a reminder that the blood-curse wasn't only done to us. Some of us held out the cup.",
		"Below our own streets the Burning Blade keep the old bargain alive. I'd like to think they're strangers. They aren't. They're us, the way we were.",
	},
	["org.muse.w18.depths.015"] = {
		"nudges a loose stone over the lip of the way down to Ragefire Chasm and listens to it rattle away for a long, long time.",
		"drops a pebble down the slope toward Ragefire Chasm and waits for the last click of it, which takes longer than seems reasonable.",
	},
	["org.muse.w18.depths.016"] = {
		"Rain finds its way into the Cleft and hisses where it meets the warm rock near the way down. Steam rises from the stone in little ghosts, and the hooded folk stand in it as if it were a bath.",
		"In the rain the Cleft steams. The rock near Ragefire Chasm is too warm to stay wet, and every drop goes up again in a thin white thread.",
	},
	["org.muse.w18.depths.017"] = {
		"studies the soot that climbs the rock above the way down to Ragefire Chasm in long black tongues, as if the fire below had tried more than once to climb out.",
		"notices the stone over the descent to Ragefire Chasm blackened in streaks, like the marks of fingers that reached up and failed.",
	},
	["org.muse.w18.drill.001"] = {
		"The practice axes in the Valley of Honor are wood, bound with iron so they weigh like the real thing. They don't cut. They only teach, the trainers say, in the language of bruises.",
		"Wooden axes, banded with iron for weight: the Valley of Honor's way of letting a pupil feel every mistake without losing a hand to it.",
		"Nothing on the practice racks of the Valley of Honor has an edge. A bruise is a cheap teacher, the trainers say, and a cut an expensive one.",
	},
	["org.muse.w18.drill.002"] = {
		"The trainers in the Valley of Honor will have a pupil hold a crouch until the legs shake, with no blow struck and no word said. When the pupil finally drops, that's the lesson: staying up is most of fighting.",
		"Before anyone in the yard learns to hit, they learn to stand, a trainer told me, until standing hurts more than any hit.",
		"Half of every lesson in the training yard is spent not moving. The pupils hate it. The old warriors watching from the edge nod along as if it were music.",
	},
	["org.muse.w18.drill.003"] = {
		"At the hunters' end of the Valley of Honor there's a straw target that has been hit so often it's now mostly hole. The hunters keep aiming at the last bit of straw, out of respect.",
		"One target in the hunters' yard is more gap than straw. Nobody replaces it. Hitting what's left of it, a hunter told me, is the real test.",
		"The hunters' oldest target has given up its straw handful by handful, and now stands on reputation alone.",
	},
	["org.muse.w18.drill.004"] = {
		"watches a trainer correct a pupil's grip without a word: two fingers moved a finger's width, a tap on the wrist, and the trainer is already walking away.",
		"sees a trainer reach over and shift a pupil's hand on the haft, barely at all, then step back; the next blow lands twice as hard.",
	},
	["org.muse.w18.drill.005"] = {
		"winces at the flat smack of a wooden axe against a leather jerkin, a sound that carries all the way down the yard, and at the cheer that follows it.",
		"flinches at a crack of wood on hardened leather from the training yard, then again at the pupil's yelp, a moment later.",
	},
	["org.muse.w18.drill.006"] = {
		"A pupil walks off the sparring ground of the Valley of Honor with a bloodied nose and a grin. The trainer gave him one nod. By the look of him, he'd trade a full purse for another.",
		"A single nod from a trainer is the highest pay the training yard has to give. I've seen grunts take a split lip for one and call it a bargain.",
	},
	["org.muse.w18.drill.007"] = {
		"The hunters' trainers drag a scrap of hide through the dust of the yard and make the pupils follow its trail with their eyes alone. Then they scuff it out and make them do it from memory.",
		"Tracking is taught in the Valley of Honor with a dragged hide and a lot of shouting. Follow it, says the trainer. Now without looking. The pupils groan in several languages.",
	},
	["org.muse.w18.drill.008"] = {
		"The oldest trainer in the yard teaches falling before anything else. Pupils go down in the dust a hundred times a day. A warrior who can't fall well, he says, only gets to fall badly once.",
		"Learn to fall, the trainers in the Valley of Honor tell their pupils, and then they throw them, over and over, until hitting the ground is just another way of getting up.",
	},
	["org.muse.w18.drill.009"] = {
		"At dawn, before the pupils arrive, the trainers of the Valley of Honor walk the yard and pick out every loose stone. It's the gentlest thing they'll do all day, and they make sure nobody sees it.",
		"First gray light, and the training yard is empty except for the trainers, stooping to clear away pebbles so nobody turns an ankle. An hour later they're shouting again, and the kindness is never mentioned.",
	},
	["org.muse.w18.drill.010"] = {
		"That grunt's been beating on the same post for ages. Either it owes him money or he means to marry it.",
		"Somebody tell that grunt the post surrendered a while back.",
	},
	["org.muse.w18.drill.011"] = {
		"Rain on the Valley of Honor turns the yard to red paste. The trainers call it a gift and keep everyone in it until the pupils are the same color as the canyon.",
		"Any other trainer would call off the drill in the rain. In Orgrimmar they cheer it: mud, they say, teaches the feet what dust never will.",
	},
	["org.muse.w18.drill.012"] = {
		"The warrior trainers and the hunter trainers of the Valley of Honor have one argument, and they've been having it since the city was built: close or far. Neither side has budged a step, which the warriors count as a win.",
		"Get close, say the warriors' trainers. Stay back, say the hunters'. They share one valley and that one quarrel, and both seem to enjoy it more than they'd admit.",
		"Close in or keep your distance: the oldest quarrel in the Valley of Honor, and nobody expects it to end while there are two kinds of trainer to keep it going.",
	},
	["org.muse.w18.drill.013"] = {
		"keeps an eye on a troll at the edge of the training yard as she binds a pupil's split knuckles, clicking her tongue, and sends him straight back into the dust.",
		"notices a troll healer sitting by the yard with a basket of bandages, mending each grunt who limps over and handing them back to the trainers like borrowed tools.",
	},
	["org.muse.w18.drill.014"] = {
		"Every pupil in that yard will stand somewhere for all of us one day: a post in the Barrens, a wall in Ashenvale. I watch them land in the dust and I'm grateful in advance.",
		"The Valley of Honor drills the ones who'll keep our roads open. Every bruise taken in that yard is one the Horde won't take somewhere worse.",
	},
	["org.muse.w18.drill.015"] = {
		"Feet, then hands, then mouth, the trainers say. Most of the yard does it the other way round.",
		"Footwork first, they bellow in that yard. I'd settle for walking without tripping.",
	},
	["org.muse.w18.drill.016"] = {
		"From a few streets off, that training yard sounds like a kitchen losing a fight with its pans.",
		"Hear the Valley of Honor? Clatter, thud, crash, laughter. Somebody dropped the soup again.",
	},
	["org.muse.w18.drill.017"] = {
		"straightens up by reflex at a trainer's bellow from somewhere across the city, then remembers it was meant for somebody else and lets the shoulders sag, a little sheepish.",
		"jumps at a far-off roar of 'Again!' from some training yard, and finds both feet already set as if for a fight.",
	},
	["org.muse.w18.drill.018"] = {
		"Bruises fade, lessons stay, say the trainers. Usually just before handing out the bruise.",
		"The yard's creed, as far as I can tell: hit, fall, get up, be shouted at, start over.",
	},
	["org.muse.w18.edict.001"] = {
		"stops with the rest of the valley as a herald climbs onto a crate by the bank and calls out the Warchief's word; the moment he steps down, a dozen haggles resume exactly where they left off.",
		"listens as a herald's voice rolls across the valley with word from the Hold, and grins at the trader alongside, who has held the same price in the air, unfinished, the whole time.",
	},
	["org.muse.w18.edict.002"] = {
		"The Warchief gives one order and it reaches the street as three. Each grunt carries it his own way, and somehow all three are right.",
		"Thrall's word comes down from the Hold plain and short. By the time it reaches the gate, every grunt has added a little something of his own, usually a scowl.",
		"One order leaves the Hold. By the bank it's an order and a warning; by the gate it's an order, a warning and a story about the last fool who ignored it.",
	},
	["org.muse.w18.edict.003"] = {
		"An elder at the inn complained that a quarrel used to end with an axe and a burial, and now it ends with a grunt and a fee. The young ones at his table didn't see the problem.",
		"In the elders' day, they say, two orcs with a grudge met in a ring and one walked out. Now they meet a grunt and both walk out, poorer. The elders call it soft. Nobody younger argues.",
	},
	["org.muse.w18.edict.004"] = {
		"The Warchief has spoken. That settles it, whatever it was.",
		"Thrall's word, is it? Then there's nothing left to argue about. Pity.",
		"Orders from the Hold. Well, that's my grumbling sorted for the week.",
	},
	["org.muse.w18.edict.005"] = {
		"The Warchief's orders are always short. A ruler who explains at length is asking to be argued with; Thrall just says it, and the city moves.",
		"No long speeches from the Hold. A sentence or two, carried out to the streets, and everyone knows where they stand. Short words weigh the most.",
		"Thrall doesn't argue with the city. He says a thing once, in few words, and leaves the city to do the arguing among itself.",
	},
	["org.muse.w18.edict.006"] = {
		"The Warchief's word on the Burning Blade has never needed repeating, a grunt told me: find them, root them out. It's the one order nobody grumbles about.",
		"Of all the Warchief's orders, the grunts say, the one about the Burning Blade is the only one nobody has ever asked him to explain. The fire they serve explained it long ago.",
	},
	["org.muse.w18.edict.007"] = {
		"Never step over an axe someone has laid down, a grunt warned me; walk round it. Law or manners? He didn't know either. He just knew.",
		"Nobody remembers who made the rule about weapons left on the ground, the grunts say: you go round, never over. Everybody keeps it.",
	},
	["org.muse.w18.edict.008"] = {
		"pauses beside a scribe reading a new order of the Warchief aloud to a ring of peons; to every question he answers by reading the same line again, louder.",
		"stays to hear a clerk read the Warchief's latest word to a knot of laborers, who go on arguing over its meaning long after he has rolled up the page and left.",
		"lingers at the edge of a knot of listeners round a scribe with a fresh order, where every listener seems to have heard a different one.",
	},
	["org.muse.w18.edict.009"] = {
		"The Warchief asks three things of the Horde, as far as I can tell: keep the peace in his city, pay what we owe, and come when he calls. The last is the only one that keeps me up.",
		"Our law is short enough to carry anywhere: no feuds inside the walls, no debts left behind, and an answer when the Warchief calls. The first two I keep without trying.",
	},
	["org.muse.w18.edict.010"] = {
		"Every clan once had its own law, and they mostly agreed on one thing: the other clans were wrong. Thrall's law is the first all of them have had to share. You can hear the old ones chafing at it, and keeping it.",
		"The elders still mutter about clan custom: how their own clan did it, how the clan across the valley got it wrong. Then a grunt enforces the Warchief's way, and they go quiet and obey. Old habits grumble; they don't rule.",
	},
	["org.muse.w18.edict.011"] = {
		"A goblin explained the city's trade laws to me at length. As far as I could follow, they come down to this: the Warchief takes his share, and the goblin takes everyone else's.",
		"The rules of trade in Orgrimmar, as a goblin tells them: pay the Warchief's due, keep your scales honest wherever a grunt can see them, and everything else is open to discussion.",
		"Goblins here keep the Warchief's law to the letter, a grunt told me sourly, and have studied every letter for the gaps in between.",
	},
	["org.muse.w18.edict.012"] = {
		"waits at the back of the hall while a ruling is given from the throne in a few low words, and watches both parties bow to it, one of them through clenched teeth.",
		"stands among the onlookers as a judgment is spoken from the throne, so quietly that the whole hall leans in to hear it.",
		"sees a ruling settle over two disputing petitioners like dust after a cart, until neither has anything left to say.",
	},
	["org.muse.w18.edict.013"] = {
		"New orders from the Hold? Read them to me slowly. I want to know what I'm about to grumble at.",
		"A fresh word from the Warchief? I'll start obeying as soon as someone tells me what it says.",
		"Orders, is it? Lovely. What aren't we allowed to do now?",
	},
	["org.muse.w18.edict.014"] = {
		"An elder told me the oldest orc law he knew: whoever has eaten at your fire is safe under your roof. The Warchief's peace, he says, is only that law with a much bigger roof.",
		"The old clans had one rule they all kept, a grizzled orc told me: a guest at the fire is not touched. Orgrimmar, to his mind, is that same fire, built big enough for every people at once.",
	},
	["org.muse.w18.edict.015"] = {
		"A thief in Orgrimmar doesn't hang, a grunt told me. He hauls stone for the walls until he's paid it back, and then some. Half the wall, he says, was built by people who regretted something.",
		"Caught thieves end up on the walls, the grunts say, carrying clay and timber until the debt's worked off. Every patch of new mortar might be somebody's apology.",
		"Steal here and you'll end up helping to build the city, the grunts like to say. Some of the sturdiest stretches of wall are said to be confessions.",
	},
	["org.muse.w18.elder.001"] = {
		"A tauren elder crouches by the path and studies the dust the way a scholar studies a page. Two kodos, a goblin in a hurry and a grunt with a limp, he tells the calf beside him. The calf looks as if it believes every word.",
		"One old tauren in the Valley of Wisdom is teaching a calf to read the path: hoofprint, boot, the long scrape of a cart. In a city this crowded the lesson never runs short of ink.",
	},
	["org.muse.w18.elder.002"] = {
		"stops to watch an old tauren whittle a tiny kodo out of a scrap of bone, while an orc child at his knee waits with both hands already held out.",
		"lingers near a tauren elder carving a thumb-sized kodo from bone; the small orc beside him has been told twice to be patient and is failing at it with great dignity.",
		"catches a tauren handing a little bone kodo down to an orc child, who inspects it as gravely as any trader before bolting off with it.",
	},
	["org.muse.w18.elder.003"] = {
		"The tauren in the Valley of Wisdom live under hide, though the orcs would have cut them rooms in the rock. A tent can be folded and carried, one of them told me. Her people have needed that more than once.",
		"Stone all around, and still the tauren pitch tents of painted hide. They have been driven off their grazing before, a tauren explained without any bitterness, and a house that packs onto a kodo is a house nobody can take.",
		"Every tauren tent in the Valley of Wisdom could be struck and loaded before a grunt finished his stew. Nobody expects to need it. Nobody takes the poles out of the ground for good, either.",
	},
	["org.muse.w18.elder.004"] = {
		"An elder in the Valley of Wisdom smokes a pipe as long as my arm. A young brave told me you can read his mood from the smoke: straight up means thinking, rings mean he has already decided and is enjoying himself.",
		"Watch an old tauren's pipe smoke long enough and you learn him, the braves say. A thin straight line: he's weighing something. Rings: he's weighed it, and you lost.",
		"The tauren elders talk with their pipes as much as their mouths. A long pull and a slow plume means no. A short puff means ask again later. I have yet to see the sign for yes.",
	},
	["org.muse.w18.elder.005"] = {
		"I asked a tauren elder the way. Three stories later I know where his grandfather's kodo lies, and not the way.",
		"Never ask a tauren elder for directions in a hurry. You'll get there eventually, much wiser and very late.",
	},
	["org.muse.w18.elder.006"] = {
		"Tell a tauren elder you'll be back soon and he asks, quite seriously, which season you mean. In the Valley of Wisdom, soon is a long word.",
		"An orc promised a tauren the job would be done shortly. The tauren nodded and sat down to wait, as if shortly meant a migration of the herds.",
	},
	["org.muse.w18.elder.007"] = {
		"skirts a ring of tauren sitting on hides and passing a wooden bowl from hand to hand; the talk stops, politely, until {g:he|she} has gone by.",
		"steps around a circle of seated tauren sharing one bowl among them, and notices the conversation wait for {g:him|her} to pass, like a door held open.",
	},
	["org.muse.w18.elder.008"] = {
		"The tauren greet with an open hand on the chest; the orcs with a fist. In the Valley of Wisdom the two have met halfway, and some of the grunts now lay a loose fist over the heart without quite knowing where they picked it up.",
		"Somewhere between the tauren's open palm and the orc's closed fist, the Valley of Wisdom has grown a greeting of its own: a half-open hand laid on the chest. Nobody taught it. Everyone uses it.",
		"I once saw a grunt lay his fist on his chest for a tauren elder, and the elder open the grunt's fingers, gently, one by one. Nobody explained it. Plenty of grunts greet that way now.",
	},
	["org.muse.w18.elder.009"] = {
		"An old orc shaman in the Valley of Wisdom wears a cord of beads, one for each clan she has known. A few of those clans are gone now. She hasn't taken their beads off; she says they still count.",
		"Some of the beads on an old shaman's cord belong to clans nobody fights under anymore. She keeps them on anyway, worn smooth by her thumb, the way you'd keep a name in your mouth so it doesn't go quiet.",
	},
	["org.muse.w18.elder.010"] = {
		"A tauren here leans on a staff notched from top to bottom. One notch for every time the herds had to move, she told me. There isn't much room left at the bottom, and she seems glad of it.",
		"The walking staff of an old tauren in this valley is scored along its whole length: each mark a move of the herds, a camp struck, a road taken. The newest notch is Orgrimmar's, and it sits a long way from the one before.",
		"Every elder here carries a staff, and every staff is a map of roads, cut in notches. The youngest notches are the deepest. The old ones have nearly worn away under the hand.",
	},
	["org.muse.w18.elder.011"] = {
		"At night, once the stalls are shut, the tauren elders of the Valley of Wisdom keep a low fire going and talk. Orcs drift over, then a troll or two, and sit just outside the light as if they hadn't really come to listen.",
		"Night in the Valley of Wisdom: a small fire, three old tauren and a story that seems to have no end. At the edge of the firelight there are always a few grunts, off duty, pretending to warm their hands.",
	},
	["org.muse.w18.elder.012"] = {
		"watches the tauren of the Valley of Wisdom set out every bowl and pot they own the moment the rain starts, then sit down among them to listen to them fill.",
		"stops beside a row of tauren pots and bowls left out in the rain, each ringing with its own note, while their owners sit close by with eyes half shut, listening.",
	},
	["org.muse.w18.elder.013"] = {
		"May I sit, elder? ...I'll take the silence for a yes. I'm told it usually is.",
		"Mind if I share your bench, elder? No answer. In tauren, I believe that's a warm welcome.",
	},
	["org.muse.w18.elder.014"] = {
		"A tauren elder is scolding a young brave in a voice so soft that half the valley has stopped to lean in. In Orgrimmar, where everyone shouts, it's the most frightening telling-off I've ever heard.",
		"Nobody in the Valley of Wisdom raises a voice to scold. An old tauren murmured three words to a careless calf, and the calf looked as if the ground had opened under its hooves.",
		"The quietest voices in Orgrimmar belong to the tauren elders, and they are the ones nobody dares to argue with.",
	},
	["org.muse.w18.elder.015"] = {
		"The hides of the tauren tents are painted with hunts and herds. An old tauren is touching up a faded kodo with a finger dipped in ochre, as carefully as if the kodo might feel it.",
		"One of the tents in the Valley of Wisdom is painted all over with running beasts. The paint fades fast in the canyon dust, so an elder goes round with a pot of ochre, giving each animal back its legs.",
	},
	["org.muse.w18.elder.016"] = {
		"Red rock, shaped by orc hands and stamped flat by orc boots. The Earth Mother is under it all the same. She doesn't mind who paves her.",
		"My hooves know this ground is hers, iron spikes or no. Even in the loudest city of Kalimdor, the Earth Mother is only a hand's depth down.",
	},
	["org.muse.w18.elder.017"] = {
		"dips {g:his|her} head to an old tauren passing by, copying the habit of the grunts, and receives a slow, grave nod in return, as if something had been agreed.",
		"returns the unhurried nod of an elderly tauren, and finds {g:himself|herself} walking a little slower for some way afterward.",
	},
	["org.muse.w18.elder.018"] = {
		"has to bite back a grin as a tauren calf follows a swaggering grunt for a dozen steps, copying the walk exactly, until its mother hooks it back by the ear.",
		"smiles in spite of {g:himself|herself} at a young tauren strutting behind an orc, shoulders rolled, chin out, until an elder's low word turns it back into a calf.",
	},
	["org.muse.w18.elder.019"] = {
		"Lower your voice near the tauren elders. They hear everything and repeat it years later, word for word.",
		"Mind what you say near an old tauren. It'll come back to you as a proverb.",
	},
	["org.muse.w18.errand.001"] = {
		"A letter finally caught up with me at the mailbox, seal cracked, a pinch of grit in the fold. It traveled harder than I did.",
		"The mail found me at last: one folded page, creased twice over, its corners worn soft. Whoever carried it earned the postage.",
	},
	["org.muse.w18.errand.002"] = {
		"The mailbox hands me a note from the auction house: outbid. They went to the trouble of writing just to tell me that.",
		"My only letter is from the auction house, informing me with great courtesy that someone else wanted it more.",
		"A letter! From the auction house. Somebody, somewhere, paid a little more than I did, and they wanted me to know it in writing.",
	},
	["org.muse.w18.errand.003"] = {
		"Something of mine sold at the auction house, and the coin came by mail with the house's cut already taken. Even good news here arrives a little lighter.",
		"The auction house paid me by letter, minus its share. They take their bite before you've even broken the seal.",
		"Coin by post from the auction house: lighter than the price I set, heavier than I feared. The house never forgets its share.",
	},
	["org.muse.w18.errand.004"] = {
		"I have a path through this city now: bank, mailbox, a bowl somewhere, the trainer. My feet walk it without consulting me.",
		"Gate, bank, mail, food. I don't plan it anymore; my boots know the order, and I just go along.",
		"There's a groove my errands have worn in Orgrimmar, and I fall into it the moment I arrive. Some days I'd like to see where the other streets go.",
	},
	["org.muse.w18.errand.005"] = {
		"checks a short list scratched on a scrap of hide, crosses one line out with a thumbnail, and adds two more underneath.",
		"consults a crumpled list, frowns at it, and scratches a new item in at the bottom with a fingernail.",
	},
	["org.muse.w18.errand.006"] = {
		"waits in line at the bank behind a goblin depositing a fortune one coin at a time, each counted aloud, and twice.",
		"shifts from foot to foot at the bank counter while the goblin in front deposits his earnings coin by coin, naming each one.",
	},
	["org.muse.w18.errand.007"] = {
		"I washed my cloak in a bucket behind the inn and hung it out to dry. It came off the line red again. In Orgrimmar, clean is a short season.",
		"Laundry is a hopeless art in this city. Wash a shirt, hang it out, and the dust has dyed it again before it's even dry.",
		"Three buckets of water to get my cloak clean, and the canyon took it back in the time it took to dry. I've decided the dust is part of the weave.",
	},
	["org.muse.w18.errand.008"] = {
		"That's everything. No, wait. Everything except the thing I came for.",
		"Done. All of it. Except the one thing I came into the city for, which I've only just remembered.",
	},
	["org.muse.w18.errand.009"] = {
		"The bank is the coolest room in the city. I've caught myself lingering at the counter far longer than any deposit needs.",
		"Thick walls, dim light, cool stone: the bank keeps the heat out as carefully as it keeps the coin in. My business there always takes longer than it should.",
	},
	["org.muse.w18.errand.010"] = {
		"My pack split a seam in the middle of the Drag and shed half my belongings into the crowd. Three strangers handed things back. A fourth tried to sell me one.",
		"The bag gave out at the worst moment and my things went everywhere. Orgrimmar returned most of them, and offered me a new bag before I'd got up off my knees.",
		"Everything I owned, scattered across the street by one bad seam. The crowd stepped round it, picked it up, handed it over, and a goblin quoted me a price for a stronger pack.",
	},
	["org.muse.w18.errand.011"] = {
		"I've found a shortcut that saves a whole bend of the road. Three peons and a wolf already knew it, and none of them were sharing.",
		"Every city has its back ways. In Orgrimmar I've found exactly one, and judging by the traffic on it, everyone knew before I did.",
	},
	["org.muse.w18.errand.012"] = {
		"If anyone's looking for me, I'm at the bank, arguing with my own savings.",
		"Bank first. My coin's been nervous out here.",
	},
	["org.muse.w18.errand.013"] = {
		"starts a letter by the mailbox, gets as far as the second line, and folds it away unsent, for later.",
		"leans on the mailbox to write a few lines, stops, reads them over, and tucks the page back into a pocket.",
	},
	["org.muse.w18.errand.014"] = {
		"Here in the Valley of Strength everything a traveler needs stands within a stone's throw: bank, mail, inn, auction house. Whoever planned it had once walked very far and sworn never again.",
		"Bank, mailbox, inn and auction house, all within shouting distance of each other here. A valley laid out by someone whose feet hurt.",
		"I can do every errand I have without leaving this valley, and I mean to. My feet voted on it.",
	},
	["org.muse.w18.errand.015"] = {
		"Stocking up before the road is its own small rite: bread wrapped in cloth, a full waterskin, a coil of new cord. The city fits in a pack, if you choose the right pieces.",
		"I fill the bag for the road the same way every time, bread, water, cord, a little salt, and every time it feels like packing a small piece of Orgrimmar to take along.",
	},
	["org.muse.w18.errand.016"] = {
		"Three letters, all from merchants. Even the mail haggles in this city.",
		"Mail! Oh. It's a goblin offering me a better price on something I never bought.",
	},
	["org.muse.w18.errand.017"] = {
		"Still waiting on that letter. Any day now. Any year.",
		"Nothing in the mailbox again? Patient thing, that mailbox. Patient as I am.",
	},
	["org.muse.w18.fallen.001"] = {
		"The grunts tell Doomhammer's end in few words: he fell in the fight to free a camp, and before he died he gave his armor to Thrall. They tell it the same way every time, word for word, as if a change might wake him.",
		"Ask how Orgrim died and the answer comes short and fixed, like a soldier's report: a camp, a lance, the black armor passed on. Nobody ever adds anything.",
	},
	["org.muse.w18.fallen.002"] = {
		"Among the city's old Warsong, nobody argues about Grom's end. They argue about everything that came before it, at length and at volume, and then go quiet together.",
		"Grom's last fight is the one thing his old warriors agree on. Ask about his first, or his temper, or his drinking, and you'd better have nowhere else to be.",
	},
	["org.muse.w18.fallen.003"] = {
		"watches an old grunt passing below Grommash Hold knock once on a post with his knuckles, without slowing or looking up, the way a few of the old Warsong seem to.",
		"glimpses an elder touch two fingers to the timber of a post on the way past the Warchief's hall, then to his own brow, and walk on as if nothing had happened.",
	},
	["org.muse.w18.fallen.004"] = {
		"Durotan was killed for refusing a bargain he thought rotten, the Frostwolves say. So the whole red country outside the walls, an elder told me, is named for a no.",
		"Saying no to the wrong people got Durotan killed, in the old Frostwolves' telling. They like that the land carries his name. It's a stubborn land; it suits him.",
	},
	["org.muse.w18.fallen.005"] = {
		"No one raised a hall for the orcs who died in the camps. They're in the walls instead, an old mason told me: one stone for each, set by hand. He won't say which stones.",
		"Every wall of the city holds a few stones laid for the camp dead, unmarked on purpose, as one elder tells it. You lean on them all the time, he says. That's the idea.",
	},
	["org.muse.w18.fallen.006"] = {
		"The grunts don't gloat over the Kul Tiran admiral who came to burn Durotar. He'd lost a son to the old wars, they say, and came for that, and found a different kind of orc waiting.",
		"Even the veterans who fought off the Kul Tiran landing speak of the admiral without much heat. A grieving father with a fleet, one said. Dangerous, and sad, and dead.",
	},
	["org.muse.w18.fallen.007"] = {
		"watches a grunt tip a few drops from his mug onto the ground before the first swallow, without a word, the way some of the old soldiers do.",
		"sees an old orc pour a thin splash of his drink into the dust at his feet, nod to nobody in particular, and only then drink.",
	},
	["org.muse.w18.fallen.008"] = {
		"The shamans of the city keep the names of the dead longer than any stone could, a troll told me. They say them aloud to the fire, one after another, and the list never gets shorter.",
		"Each season a gray shaman speaks into the flames the names of those lost on the crossing. The fire forgets nothing, she says, and somebody has to be the one who remembers.",
	},
	["org.muse.w18.fallen.009"] = {
		"Not every orc came out of the old wars. The Burning Blade still serve the masters everyone else walked away from, and the city speaks of them the way a family speaks of a son who went bad.",
		"Nobody among the elders says Burning Blade loudly. They say it the way you mention a cousin who took the wrong road: briefly, with a look at the floor.",
		"When someone in the crowd glances toward the Cleft of Shadow and spits, the old orcs know exactly who is meant. In this city the Burning Blade barely needs naming.",
	},
	["org.muse.w18.fallen.010"] = {
		"Far to the east, inside Blackrock Mountain, orcs still march under the banners of the old wars and call someone else Warchief. Say so aloud in Orgrimmar and watch the faces shut.",
		"The grunts have a word for the Blackrock orcs who never gave up the old ways, and it's not one I'll repeat. Every one of them, they say, is a brother the demons kept.",
	},
	["org.muse.w18.fallen.011"] = {
		"Grom was the first chieftain to drink the demon's blood, the elders say, and the last orc to be freed of it. In between he did more harm than most, and at the very end more good than anyone.",
		"First to drink and last to be cured: so the old ones sum up Hellscream. They let the sentence sit there. Nobody needs it explained.",
		"Hellscream's whole life fits between a cup and an axe, a Warsong grunt says: the cup he drank before anyone, and the axe he paid it back with.",
	},
	["org.muse.w18.fallen.012"] = {
		"To the ones who fell before the walls went up. They'd have liked the walls.",
		"Strength to everyone who didn't make it this far. The rest of us will keep the noise up.",
		"For the ones still at sea and the ones still in the camps' ground. Somebody here remembers you.",
	},
	["org.muse.w18.fallen.013"] = {
		"Grom fell deep in Ashenvale, in country the night elves guard with every tree. His old warriors can't sit by the place without an army along, so they come and sit in his hall instead.",
		"The spot where Hellscream fell is too far into elf woods for an old orc's knees, or for the welcome he'd get, his old soldiers say. The hall with his name will have to do. It does.",
	},
	["org.muse.w18.fallen.014"] = {
		"Here in Grommash Hold the name over the door weighs on the whole room. Voices drop without anyone asking, as if Grom might still be listening for a quarrel.",
		"Inside the hall that bears his name, I keep expecting a big, rough voice to fill the room. It never comes. The Warchief's quieter one does instead, and the hall seems to have chosen it.",
	},
	["org.muse.w18.fallen.015"] = {
		"slows beside an old orc mending a strap who mutters a string of names as he works, one per stitch, and stops when the strap is done.",
		"lingers near an elder who is whittling and murmuring names, one for every curl of wood that falls, and never seems to run short of either.",
	},
	["org.muse.w18.fallen.016"] = {
		"notices an old warrior set a clay cup of water in a corner of the yard before the drilling starts; the sparring pairs step around it all the while, and nobody kicks it over.",
		"sees a scarred veteran place a full cup at the edge of the yard and leave it there untouched, while the trainers work their pupils around it as if it were a post.",
	},
	["org.muse.w18.fallen.017"] = {
		"Grom, if you can hear it: they keep your name loud. You'd have wanted it louder.",
		"Hellscream. They still say it with the scream in it. Good.",
	},
	["org.muse.w18.founding.001"] = {
		"When the orcs first came down into this canyon, an old builder says, it was thick with harpy nests, and the city's first job was persuading the harpies to leave. He doesn't say how. He doesn't need to.",
		"Before a single wall stood, the canyon belonged to harpies that shrieked at every hammer blow. A peon tells it with a grin: they lost the argument.",
	},
	["org.muse.w18.founding.002"] = {
		"stops at a stretch of wall where the stones are smaller and set more crookedly than the rest, and runs a thumb along the old, uneven mortar.",
		"lingers by a low run of the oldest wall, rough and patched, laid by builders who were plainly in more of a hurry than the ones who came after.",
	},
	["org.muse.w18.founding.003"] = {
		"Somebody carried every one of these stones down here. I hope they were paid in stew.",
		"All this rock, hauled by hand. There's a peon out there whose back built half a valley.",
		"Each stone in these walls went down that slope on somebody's shoulders. I'd like a word with the planner.",
	},
	["org.muse.w18.founding.004"] = {
		"A goblin trader insists his cartel sold Thrall the first crane in the canyon, at a special price. Every goblin in the city tells this story, and each names a different price.",
		"To hear the goblins tell it, the city would still be a heap of rocks without the pulleys they sold the orcs, for a few coins and out of the goodness of their hearts. Nobody has seen the receipts.",
	},
	["org.muse.w18.founding.005"] = {
		"No one can name the day the city was founded. There wasn't one, an elder told me: only a day when nobody bothered to fold the tents back up.",
		"Ask when Orgrimmar began and the old orcs shrug. No ceremony, they say. The tents simply stayed where they were, and soon after somebody hung a door.",
		"There was no founding feast, says a gray-haired grunt. The city started the way a habit does: by not leaving.",
	},
	["org.muse.w18.founding.006"] = {
		"The walls went up twice as fast once Kul Tiran sails showed off the coast, the grunts say. Nothing teaches masonry like a fleet.",
		"According to the veterans, the city was mostly tents and good intentions until Kul Tiras came calling by sea. After that, everyone learned to lay stone.",
		"A peon who hauled stone in those days calls the Kul Tiran ships the best foremen the city ever had: with the sails in sight, nobody slacked.",
	},
	["org.muse.w18.founding.007"] = {
		"The tauren of the city like to remind the orcs, gently, that kodos dragged a good part of this stone into place. The orcs remember it differently, and loudly.",
		"His herd's kodos hauled timber down into the canyon when the walls were young, an old tauren says, and never got a word of thanks for it. He thanks the beasts himself now and then, he adds.",
	},
	["org.muse.w18.founding.008"] = {
		"spots an old stake, split and silvered with age, still standing in a corner among newer timbers, as though nobody has had the heart to pull it out.",
		"pauses by a weathered post set into the ground at a slant, older than anything around it, with a scrap of rope still knotted at the top.",
	},
	["org.muse.w18.founding.009"] = {
		"The orcs who raised the first walls are old now. They sit with their backs against the stone they set, and the young walk past without knowing whose work they're leaning on.",
		"Some of the elders on the benches by the walls laid those walls. They never say so. You find out only when one of them reaches back and pats the stone like an old wolf.",
	},
	["org.muse.w18.founding.010"] = {
		"Tents to a bank in one lifetime. Some families take three to get a decent roof.",
		"From a ditch and some stakes to an auction house. Somebody was in a hurry.",
		"Not long back this was rocks. Now there's a queue at the bank.",
	},
	["org.muse.w18.founding.011"] = {
		"Ask where the first stone of Orgrimmar went and you get a tour. Three tours, all different, all certain.",
		"Everybody old enough knows where the first stone was laid. Everybody points somewhere else.",
	},
	["org.muse.w18.founding.012"] = {
		"The first picks that bit into this canyon were beaten out of camp chains, an old smith says. He tells it as a matter of iron, not of poetry: there was nothing else to melt.",
		"Shackles, says an elder at his forge, made the first tools of Orgrimmar. He shrugs at the look on my face. Good iron is good iron, whoever forged it first and for what.",
	},
	["org.muse.w18.founding.013"] = {
		"As dusk settles into the canyon, an old builder points out the first walls: the ones that go dark earliest, he says, because they were set lowest, by orcs who didn't yet trust the high ground.",
		"At dusk the shadow climbs the walls in the order they were built, an elder swears, the oldest first. He watches them go with a builder's pride.",
	},
	["org.muse.w18.founding.014"] = {
		"One crooked hut sits at an angle to everything around it. Its owner says it was the first roof in the canyon, raised before anyone had decided where the streets would go, so the streets went round it.",
		"There's a hut that faces the wrong way for its street. It was standing first, its old owner growls, and the street can apologize.",
	},
	["org.muse.w18.founding.015"] = {
		"crouches by one of the oldest walls, where a row of handprints is pressed into the clay, faded nearly flat, and holds {g:his|her} own hand beside one without quite touching it.",
		"stops at a stretch of old clay wall marked low down with dozens of handprints, large and small, worn almost smooth: the only part of the wall nobody has patched.",
	},
	["org.muse.w18.founding.016"] = {
		"Old walls built in a hurry, new walls built to last. You can read this city like a diary.",
		"Old stonework says: quick, before they come back. New stonework says: let them.",
	},
	["org.muse.w18.founding.017"] = {
		"Here in the Valley of Strength, an old grunt says, the first caravans unloaded straight into the dust, before there was a bank to keep the coin or an inn to lose it in.",
		"This valley was nothing but a trampled yard once, the elders say: crates, wolves, shouting and a single tent where a scribe kept count. Not much has changed, they add, except the tent.",
	},
	["org.muse.w18.founding.018"] = {
		"watches two old peons argue over a crooked stretch of wall they apparently built together, each blaming the end the other one laid.",
		"lingers near a pair of elderly peons pointing at the same lopsided course of stones, one calling it the best work in the city and the other calling it his partner's fault.",
	},
	["org.muse.w18.founding.019"] = {
		"Somebody had a plan for this city. You can tell, because nobody followed it.",
		"Laid out by a warchief, built by a dozen clans with opinions. It shows.",
		"Every ramp in this place was somebody's good idea. Several somebodies, arguing.",
	},
	["org.muse.w18.gate.001"] = {
		"The grunts at the gate claim they can tell where a traveler has been by the dust on the boots: red for Durotar, pale yellow for the Barrens, black mud for places they'd rather not ask about.",
		"A gate guard once read my boots for me like a fortune-teller: Barrens grit on the heel, Durotar red on the toe. He wasn't wrong, and he didn't charge.",
		"Boot dust is a map, the gate grunts say. They glance down before they glance up, and they're seldom wrong about the road you took.",
	},
	["org.muse.w18.gate.002"] = {
		"watches a traveler stop just short of the gate to pat every strap and pocket in turn, then step out onto the road without looking back.",
		"notices how the people leaving all pause at the same spot under the gate, check their packs one last time, and only then go.",
		"sees a departing troll halt in the gateway, count the knots on her bundle with one finger, nod to herself and walk off at a lope.",
	},
	["org.muse.w18.gate.003"] = {
		"Watch the gate long enough and you notice it: the ones arriving drag their feet, the ones leaving walk too fast. By the bank, most of them have swapped.",
		"People come in through the gate slow and go out of it quick. Ask either kind why and both would say they're tired of the place they've just been.",
	},
	["org.muse.w18.gate.004"] = {
		"sees a grunt at the gate count a patrol coming in, lips moving, and stop one short; neither he nor the patrol says a word about it.",
		"follows a squad tramping in off the road as the gate guard tallies them by eye, once, then twice, as if the second count might come out kinder.",
		"lingers as a patrol files in under the gate, and catches the moment the grunt on watch notices the empty place in the line.",
	},
	["org.muse.w18.gate.005"] = {
		"Rope, waterskins and hats, double price, right at the gate. Whoever sells there knows exactly how people forget things.",
		"Last chance for rope before the road, the hawker by the gate says. Last chance at that price, I'd hope.",
		"That stall by the gate sells nothing but what people forget to pack. Judging by the prices, people forget a lot.",
	},
	["org.muse.w18.gate.006"] = {
		"The water seller just inside the gate does her best trade with the ones coming in. Nobody haggles over the first cup after the Durotar road.",
		"Right inside the gate someone sells cups of water off a barrel, and nobody arriving argues the price. The road out there has already set it.",
		"A ladle, a barrel and a stool by the gatepost: the simplest shop in Orgrimmar, and nobody coming in off the road ever walks past it.",
	},
	["org.muse.w18.gate.007"] = {
		"The gate grunts keep a heap of things travelers dropped on the way out: one boot, a hat, a pot lid, a straw doll. One of them told me nobody has ever claimed a single piece.",
		"There's a pile by the gatepost of everything the road has shaken loose from travelers: a single glove, a ladle, a hat with a hole in it. Nobody ever claims a thing.",
	},
	["org.muse.w18.gate.008"] = {
		"From the gate the road to Razor Hill runs plain and pale for a while, then a red hill takes it, and after that you have to trust it's still there.",
		"Out past the gate the road shows itself for a few hundred paces and then ducks behind the hills of Durotar, like a shy guide walking on ahead.",
	},
	["org.muse.w18.gate.009"] = {
		"steps around a traveler sitting just inside the gate with both boots off, pouring a small hill of Durotar out of each.",
		"watches someone hop on one foot by the gatepost, upend a boot, and look with real betrayal at how much road comes out of it.",
		"has to wait while a dusty arrival shakes out a cloak right in the gateway, raising a cloud that makes three grunts turn their faces away at once.",
	},
	["org.muse.w18.gate.010"] = {
		"Wolves strain at the reins on the way out of the gate and kodos speed up on the way in. Each beast knows where it would rather be, and neither has asked the rider.",
		"At the gate you can read the beasts' opinions: the wolves pull toward the open road, the kodos toward the stable and the feed. The riders just hang on.",
		"Ride out on a wolf and you get towed through the gate; ride in on a kodo and you get carried straight to the feed trough, whatever your plans were.",
	},
	["org.muse.w18.gate.011"] = {
		"Gate's that way. So is everything else, sooner or later.",
		"Out that gate and turn any way you like. Trouble's in every direction, they tell me.",
		"Pick a road, any road. They all leave from the same gate.",
	},
	["org.muse.w18.gate.012"] = {
		"The sand has everyone coming in through the gate dusted the same pale red. Orc, troll, tauren: for a few steps you can't tell one people from another.",
		"Travelers stumble in at the gate coated in sand from hood to heel, like statues somebody forgot to paint. The grunts wave them through by shape.",
	},
	["org.muse.w18.gate.013"] = {
		"Every road out of that gate runs past someone of ours on watch: a post in the Barrens, a tower in Ashenvale, a camp in the jungle. I pass them all eventually, and nod.",
		"The roads leaving Orgrimmar are only roads because somebody of the Horde stands along each of them. I never walk out of the gate without remembering that.",
	},
	["org.muse.w18.gate.014"] = {
		"sees two friends part at the gate with a hard thump on the shoulder each; the one staying watches the road a good while after there's nothing left on it to watch.",
		"witnesses a farewell at the gate done orc-fashion, one shove and no words, and the one left behind standing there long after the dust has settled.",
	},
	["org.muse.w18.gate.015"] = {
		"There's a spot just past the gate where the city's racket drops off all at once, like stepping out of a tent. Ten more paces and Orgrimmar is only a rumor behind me.",
		"The din of the city doesn't fade gently at the gate. It stops, as if somebody shut a door on it, and the road outside is suddenly quiet enough to hear my own boots.",
		"Inside the gate, a thousand voices. Twenty paces outside, my boots, a beetle and the hills. The change always takes me by surprise.",
	},
	["org.muse.w18.gate.016"] = {
		"Water, rope, bread. Anything I've forgotten, the road will mention.",
		"Packed, paid, fed. Whatever I've left behind, I'll find out a mile past the gate.",
	},
	["org.muse.w18.goblins.001"] = {
		"A goblin trader greets an orc in Orcish, a troll in the troll tongue and a Forsaken in their own dry speech, all without pausing, and quotes the same price in each.",
		"I counted four languages out of one goblin in the time it took me to choose a belt. The price was the only word that never changed.",
	},
	["org.muse.w18.goblins.002"] = {
		"A goblin walks the street between two enormous orcs he pays by the hour. He keeps a little hourglass on his belt and checks it whenever they slow down.",
		"Two hired orcs follow a goblin trader everywhere, a step behind each shoulder. When he stops to chat, he glances at a tiny hourglass, sighs, and keeps the chat short. They cost money standing still.",
	},
	["org.muse.w18.goblins.003"] = {
		"I've never seen a goblin in Orgrimmar sit down. They lean, they perch, they hop up on a crate. Sitting, I suspect, counts as time nobody is paying for.",
		"Goblins don't sit. I watched one eat a whole meal standing on a barrel so he could keep an eye on two stalls at once.",
		"Sitting down, one of them told me, is how a goblin loses money.",
	},
	["org.muse.w18.goblins.004"] = {
		"makes room for a goblin marching up to a tall stall with his own small crate, who sets it down, climbs on, and starts haggling at eye level.",
		"steps aside for a goblin who unfolds a little stool before a high counter with a snap, and conducts his business from a dignified height.",
	},
	["org.muse.w18.goblins.005"] = {
		"Quite sincerely, a goblin asked a grunt what honor costs by the pound. The grunt has been trying to answer for a while now, and the goblin is taking notes.",
		"I overheard a goblin ask an orc to explain honor in plain terms: who pays, who collects, what the interest is. The orc's answer was long, loud and, I think, very moving. The goblin wrote down none of it.",
	},
	["org.muse.w18.goblins.006"] = {
		"There's a goblin by the bank who sells news by the sentence. The first one's free. It always ends just before the interesting part.",
		"News is a trade like any other to the goblins. One just offered me what's happening in Ratchet: two copper for the headline, five for who did it.",
		"News by the sentence, from a goblin: every sentence stops right at the edge of the cliff.",
	},
	["org.muse.w18.goblins.007"] = {
		"dodges a goblin racing the storm along the street, throwing oilcloth over a cart full of ticking contraptions and swearing at each thunderclap as if it owed him money.",
		"chuckles at a goblin trader who drags a tarp over his wares at the first crack of thunder, sits on it, then thinks better of sitting on metal in a storm and climbs off quickly.",
	},
	["org.muse.w18.goblins.008"] = {
		"Favors go in a goblin's little book as well as debts: who held a door for him, who helped lift a crate. He showed me my own line. I'm apparently owed a copper.",
		"Even kindness goes in the book with the goblins. One of them thanked me for picking up his hat, wrote something down, and told me the account was open.",
	},
	["org.muse.w18.goblins.009"] = {
		"One goblin pushes a handcart along the street with a painted sign that says, in four languages, DO NOT JOSTLE. The crowd, which jostles everything, gives it room on both sides without a word.",
		"Nobody in Orgrimmar makes way for anyone, except for one particular goblin cart. It hums faintly, and it has a skull painted on the side.",
	},
	["org.muse.w18.goblins.010"] = {
		"Here in the Drag a goblin tinker will mend anything with a gear in it. Things without gears he mends too, by putting a gear in.",
		"A goblin's stall along this street fixes whatever you bring. My buckle came back working, and ticking, and I never asked for the ticking.",
	},
	["org.muse.w18.goblins.011"] = {
		"watches a goblin hold a coin up to one eye through a little lens, turn it twice, sniff it, and only then drop it into the till.",
		"pauses as a goblin examines a silver piece under a brass eyeglass, with the look of a healer studying a rash.",
	},
	["org.muse.w18.goblins.012"] = {
		"Just now a goblin wished me a profitable day. I think that's the warmest thing a goblin can say.",
		"May your margins be wide, says the goblin. I suppose that's a blessing, where he comes from.",
		"Profit be with you, says the goblin, and bows like a priest.",
	},
	["org.muse.w18.goblins.013"] = {
		"The goblins in our capital are not of the Horde, and they mention it often, cheerfully, usually right before a price. Guests, they call themselves. Very well-paid guests.",
		"Our goblins never let anyone forget they're neutral. The Cartel sells to us and to the Alliance alike, one told me, and he smiled as if that ought to comfort me.",
	},
	["org.muse.w18.goblins.014"] = {
		"Under a little parasol of oiled hide, a goblin crosses the valley out of the sun, and everyone who laughs at it is squinting.",
		"In this glare one goblin has the right idea: a small hide parasol, tilted at the sun like a lid on a pot. The orcs mock it. The orcs are also squinting.",
	},
	["org.muse.w18.goblins.015"] = {
		"I asked a goblin the way. He told me, very kindly, and then handed me a bill.",
		"Directions and a receipt, from the same goblin. Both very neat.",
		"Free directions, said the goblin, and then charged me for the paper he drew them on.",
	},
	["org.muse.w18.hearth.001"] = {
		"Half the food in this city is sold on a stick, so you can eat with one hand and keep the other free. Nobody ever says free for what.",
		"Meat on a skewer, bread wrapped round meat, meat wrapped round more meat: Orgrimmar eats with one hand and keeps the other for business.",
		"I've yet to see a fork in this city. A stick, a fold of bread, a set of fingers: that's the cutlery, and nobody misses the rest.",
	},
	["org.muse.w18.hearth.002"] = {
		"Nothing gets thrown away here. A bone goes from a plate to a wolf, from the wolf to a carver, and comes back to the market as a needle.",
		"A bone has a long life in this city after supper: the wolves have it first, then a carver, and in the end someone in the Drag sews with it.",
		"I left a rib on my plate at the inn. By the time I stood up a wolf had it, and a peon was waiting for whatever the wolf would leave.",
	},
	["org.muse.w18.hearth.003"] = {
		"accepts a flatbread folded round something hot, juggles it from hand to hand for a while, and eats it anyway.",
		"buys a flatbread straight off a griddle stone and shifts it from palm to palm, too hungry to wait for it to cool.",
	},
	["org.muse.w18.hearth.004"] = {
		"The mugs at the inn are clay, thick as a wall and heavy as a whetstone. I suspect they were made to survive being thrown.",
		"Drinking at the inn takes two hands: one for the mug, one to help lift the arm that holds it. These cups were built to outlast their drinkers.",
		"I've seen a mug at the inn bounce off a skull and land without a chip. The skull fared worse. The innkeeper chose her crockery well.",
	},
	["org.muse.w18.hearth.005"] = {
		"The innkeeper never lets the hearth go out. In the slack hours she buries the coals under ash, the way a farmer covers seed, and digs them up again with a poker.",
		"There's a fire at the inn that nobody remembers lighting. They bank it under ash when the room empties and wake it with a stick when it fills.",
		"That hearth at the inn has outlived a good many customers, I'd guess. Ash over the coals when it's quiet, a stir and a log when it isn't, and never once cold.",
	},
	["org.muse.w18.hearth.006"] = {
		"stops at a water barrel near the bank, drinks from the dipper chained to its rim, and hangs it back where the next thirsty soul will find it.",
		"takes a turn at the barrel by the bank, where a dipper hangs on a short chain so that nobody walks off with it, and drinks without hurry.",
	},
	["org.muse.w18.hearth.007"] = {
		"Two bowls of whatever that is. No, don't tell me what it is.",
		"Whatever's in the big pot. I've decided not to ask.",
	},
	["org.muse.w18.hearth.008"] = {
		"I bought a strip of dried kodo by the bank and I'm still chewing it. It may well outlast the road.",
		"Dried kodo: sold by the strip, chewed by the hour. My jaw has stopped speaking to me.",
	},
	["org.muse.w18.hearth.009"] = {
		"At the inn someone is always mending something by the fire: a boot, a strap, a torn pack. Half the room is a workshop with ale.",
		"Nobody at the inn just sits. One stitches a sleeve, one oils a buckle, one whittles a peg for a tent. Rest, in this city, still keeps its hands busy.",
		"Even the inn works. Look around the fire and every pair of hands is fixing something: a heel, a ring of mail, a cracked bowl bound with wire.",
	},
	["org.muse.w18.hearth.010"] = {
		"A troll at a stall peels cactus fruit with a gloved thumb, spines flying, and hands over the red flesh with a grin that dares me to complain.",
		"Cactus fruit, peeled while you wait: the spines go on the ground, the sweet red part goes to you. Mind where you stand.",
	},
	["org.muse.w18.hearth.011"] = {
		"A pallet of hides, a blanket that smells of wolf, and through the wall somebody snoring like a landslide in no hurry. The rooms of the inn promise rest, and mostly keep the promise.",
		"The inn's beds are hides over straw, and the walls are thin. Someone next door snores in long rolling waves. I'll sleep anyway; the city has taught me how.",
	},
	["org.muse.w18.hearth.012"] = {
		"The cook at the inn tastes the stew, frowns, and throws in salt. Then tastes it again, nods, and throws in more salt. It's a habit, not a recipe.",
		"I watched the inn's cook taste, scowl and salt the pot three times over. By the third time I don't think it was about the stew anymore.",
	},
	["org.muse.w18.hearth.013"] = {
		"Bread, salt and a place by the fire: the inn gives the same to every people of the Horde, and charges each of us the same too. That's a fairness I can trust.",
		"Orc, troll, tauren or Forsaken, we all get the same bowl at the inn and the same scowl with it. Equal before the ladle.",
	},
	["org.muse.w18.hearth.014"] = {
		"shakes a waterskin beside one ear, hears nothing, and sets off in search of the nearest barrel with a look of great purpose.",
		"upends a waterskin over an open mouth, gets two drops for the trouble, and goes looking for a refill with grim determination.",
	},
	["org.muse.w18.hearth.015"] = {
		"At the stew stalls you pay for the bowl as well as the stew, and get the coin back when you return it. Nobody steals a bowl in Orgrimmar. Nobody wants that conversation with the cook.",
		"The stew sellers charge a copper for the bowl and hand it back with a nod when the bowl comes home. I've never seen one go missing. I have seen the cooks.",
	},
	["org.muse.w18.hearth.016"] = {
		"Anyone hungry? I bought too much, and the wolves are already looking hopeful.",
		"Who wants half of this? My eyes ordered for two.",
	},
	["org.muse.w18.hearth.017"] = {
		"The old orcs eat slowly and leave nothing, not a crust. In the camps, they say, every meal was counted by somebody else. Here they count their own, and still leave nothing.",
		"Watch an old orc at the inn wipe the bowl clean with the last of the bread. The camps taught that, I'm told, and freedom hasn't been enough to unteach it.",
	},
	["org.muse.w18.hearth.018"] = {
		"Water first, questions after. Where's the barrel?",
		"Has anyone seen a full waterskin? Mine's been empty since the gate.",
	},
	["org.muse.w18.hide.001"] = {
		"A skinner will lend you coin, a meal, even a wolf for a day. Never the skinning knife. Asking is like asking to borrow her teeth.",
		"Skinners keep their knives in oiled wraps and sleep with them close. I asked to borrow one and got a look I'm still thinking about.",
		"Every skinner I've met carries the knife the way others carry a purse: close, with one hand never far from it.",
	},
	["org.muse.w18.hide.002"] = {
		"pauses to watch a leatherworker stitch a seam with two needles at once, passing both through each hole from opposite sides and pulling the pair tight with a little tug.",
		"follows the hands of a leatherworker sewing a heavy seam, two needles crossing in every hole, quick and even as a drummer's sticks.",
	},
	["org.muse.w18.hide.003"] = {
		"A tanner pinches a hide between finger and thumb and names its grade, light, medium or heavy, before I've even seen her look at it.",
		"Hunters bring their hides to the tanners rolled and salted, and the tanners grade them with a pinch, a sniff and a disappointed sigh. Nobody's hide is ever as good as its hunter thinks.",
		"The tanners can grade a hide blind. A pinch for thickness, a rub for grain, a sniff for how long it lay in somebody's pack.",
	},
	["org.muse.w18.hide.004"] = {
		"Nobody buys leather here without sniffing it first. I'm learning to do it without pulling a face.",
		"Sniff, frown, nod, pay. Apparently that's how a belt gets bought in this city.",
		"Good leather smells of bark and patience. Bad leather just smells.",
	},
	["org.muse.w18.hide.005"] = {
		"Scorpid plates sewn onto leather: armor made of the very thing that stings travelers outside the walls. Durotar wastes nothing, not even its grudges.",
		"The leatherworkers buy scorpid shell by the sackful and stitch it on in overlapping rows. You end up wearing the beast's own answer to being hit.",
		"Whoever first sewed scorpid plates onto a jerkin had clearly been stung once too often and decided to take the armor for himself.",
	},
	["org.muse.w18.hide.006"] = {
		"Some of the older leatherworkers still tool their clan's pattern into a belt, on the inside, against the skin, where only the wearer knows it's there.",
		"Turn over a belt from one of the old tanners and you may find a clan mark pressed into the back. That part isn't for sale. It simply comes with the belt.",
		"An old tanner presses a pattern into the hidden side of every belt he makes. Ask what it means and he only says it's between him and the belt.",
	},
	["org.muse.w18.hide.007"] = {
		"steps over a dark trickle running out of a tannery door and down the slope of the Drag, and decides not to wonder what is in it.",
		"lifts a boot just in time to miss a thin brown stream of tanning water winding its way down the Drag toward somebody else's doorstep.",
	},
	["org.muse.w18.hide.008"] = {
		"A tauren leatherworker says a few quiet words over every kodo hide before she cuts. The orc at the next bench used to grumble at the delay. Now he waits until she's finished, knife lowered.",
		"Before the knife goes into a kodo hide, the tauren at the leather bench lays a hand flat on it for a moment. Nobody near her picks up a tool until she lifts it.",
	},
	["org.muse.w18.hide.009"] = {
		"A tip: here in the Drag, never ask a tanner what the stain on the apron is.",
		"Whatever you do in the Drag, don't ask about the tanners' aprons. I did. I'm still sorry.",
	},
	["org.muse.w18.hide.010"] = {
		"Nothing of a hide is wasted. The good part becomes boots, the scraps become laces, the leftover laces become thongs, and the last trimmings go into the glue pot, which smells worse than everything before it put together.",
		"The leatherworkers boil their last scraps down for glue. You can find the glue pot without being told; you could find it from the bank.",
		"Ask a leatherworker what becomes of the trimmings and she points at a bubbling pot in the corner. Then she points at the door, for your sake.",
	},
	["org.muse.w18.hide.011"] = {
		"keeps out of the way as a leatherworker hauls half-cured hides in under the eaves at the first drops, cursing the rain with every armful.",
		"stands aside as a tanner and two apprentices race the rain to get the drying frames under cover, and lose by a handful of hides.",
	},
	["org.muse.w18.hide.012"] = {
		"When the canyon is at its hottest the glue won't set and the leather goes soft as cheese. The leatherworkers simply put down their tools and sit in whatever shade the wall allows them.",
		"Midday, and every leather bench along the street stands empty. The hides go limp on their frames, and their owners lie in the shade beside them, just as limp.",
		"Under this sun no tanner works. They say the hides need a rest, and nobody is fool enough to ask whether the tanners do too.",
	},
	["org.muse.w18.hide.013"] = {
		"A leatherworker rubs the edge of a strap with a smooth slip of bone, round and round, until it shines like wet stone. An hour of work nobody will ever notice but her.",
		"The edges are what tell a good belt from a cheap one, a tanner told me, and showed me the bone she polishes them with, worn smooth as a river pebble.",
		"Burnishing, the tanners call it: an edge rubbed with bone until it gleams. Customers never ask for it. They just keep coming back.",
	},
	["org.muse.w18.hide.014"] = {
		"The leatherworker measured my wrist for a bracer without a word and without a smile. If she knew what I was, she charged me for it. If she didn't, she charges everyone that much.",
		"A tauren took my measurements for a pair of gloves, holding my hand in hers as calmly as a hide on the bench. I've never felt so thoroughly weighed, and nobody here even knows my name.",
	},
	["org.muse.w18.hide.015"] = {
		"Boots from an orc bootmaker are built to outlast whoever wears them. Breaking them in takes roughly as long.",
		"These boots will still be walking when I'm not, the bootmaker promised. At the moment they're winning.",
		"My new boots and I are still negotiating. So far they've won every argument, and I've limped away from each one.",
	},
	["org.muse.w18.hide.016"] = {
		"Want a good belt? Watch the tanner's hands, not the tanner's mouth.",
		"Never mind the sales talk. A tanner's hands tell you what the leather's worth.",
	},
	["org.muse.w18.hollow.001"] = {
		"The rogue pupils in the Cleft practice on each other. By the end of a lesson nobody is sure whose purse is whose, and that, the trainer says, is the lesson.",
		"Rogues in training pick each other's pockets all through the Cleft of Shadow. The purses go round and round, and every so often one comes back lighter than it left.",
	},
	["org.muse.w18.hollow.002"] = {
		"glimpses a hooded pupil drop from a ledge in the Cleft without a sound, then get a cuff from the trainer for landing on a pebble.",
		"notices a figure slip down from an overhang in the Cleft, soft as a cat, and the grumbled complaint that follows: one pebble, rolling, enough to wake a camp.",
	},
	["org.muse.w18.hollow.003"] = {
		"An imp is running errands through the Cleft: a candle to one door, a scroll to the next, cursing at every step and doing every job.",
		"Somebody's imp is the Cleft's busiest courier. It carries wax, ink and messages, insults everyone it delivers to, and is never late.",
	},
	["org.muse.w18.hollow.004"] = {
		"In the Cleft the warlocks' books are chained to their lecterns. Not against thieves, I'm told.",
		"Every tome in the warlocks' rooms hangs on a chain. A thief would only need a file. Whatever those chains are holding in, it isn't thieves.",
		"The chains on the warlocks' books are heavier than the books. Someone did that on purpose.",
	},
	["org.muse.w18.hollow.005"] = {
		"Mind that circle on the floor. No, don't step in it. No, not that one either.",
		"Careful where the feet go down here. Half these chalk marks were drawn for something, and I'd rather not meet it.",
	},
	["org.muse.w18.hollow.006"] = {
		"catches a sweet, wrong smell drifting from a doorway in the Cleft and lifts a sleeve across the face until it passes.",
		"wrinkles the nose at a smell from a doorway in the Cleft, sweet and rotten at once, like flowers left far too long in a jar.",
	},
	["org.muse.w18.hollow.007"] = {
		"The poison makers of the Cleft never hurry, never sneeze and never scratch their noses. I didn't know you could tell a trade by what its people don't do.",
		"Watch the poisoners at work in the Cleft: slow hands, no sudden moves, not a sniffle. Whoever used to sneeze in that trade isn't in it any longer.",
	},
	["org.muse.w18.hollow.008"] = {
		"Every lock in the Cleft is ringed with fine scratches around the keyhole. Practice, I'm told. Nobody says whose doors the practice is for.",
		"The keyholes of the Cleft are all scored around the edges, like the rim of a well-used cup. The rogue trainers call it homework.",
	},
	["org.muse.w18.hollow.009"] = {
		"Hands where I can see them? Down in the Cleft that's practically a greeting.",
		"Show your hands, show your teeth, show nothing else. Cleft manners.",
		"Keep your hands still and your questions short. That's the whole of the Cleft's courtesy.",
	},
	["org.muse.w18.hollow.010"] = {
		"The warlock pupils of the Cleft wear the most serious faces in Orgrimmar. Whatever they're learning down there, nobody is learning it for fun.",
		"I've never heard a warlock pupil laugh. Their teachers, sometimes. That's worse.",
	},
	["org.muse.w18.hollow.011"] = {
		"Water drips somewhere in the Cleft of Shadow, from a crack nobody has found. In Durotar a drip ought to be good news. Down there it only sounds like someone counting.",
		"There's a drip in the Cleft that never stops and never fills anything. The rogues, I'm told, learn to walk between the drops.",
	},
	["org.muse.w18.hollow.012"] = {
		"Outside a shop in the Cleft a voidwalker and an imp wait for their masters like mounts at a rail. The imp has been insulting the voidwalker for some time. The voidwalker hasn't noticed.",
		"Two demons left waiting at a door in the Cleft: an imp, chattering abuse, and a voidwalker, saying nothing back. I've seen old married couples like that.",
	},
	["org.muse.w18.hollow.013"] = {
		"Not one forge in the Cleft of Shadow. In a city that hammers everything hot, whatever is made down there is made cold, by hand, and quietly.",
		"The only corner of Orgrimmar without an anvil is the Cleft. Its trades are done with needles, vials and patience, and none of them rings.",
	},
	["org.muse.w18.hollow.014"] = {
		"Cool and quiet down here. Suspiciously so.",
		"Best shade in Orgrimmar, and nobody's charging for it. I don't trust that.",
	},
	["org.muse.w18.hollow.015"] = {
		"The grunts walk the Cleft like every other street, and the rogues greet each of them by name. Not one grunt has ever given his.",
		"The rogues of the Cleft know every patrolling grunt by name, and say so, cheerfully. The grunts know theirs too, and say nothing at all.",
	},
	["org.muse.w18.hollow.016"] = {
		"Give my eyes a moment here in the Cleft and the shadows fill up with people: one in that doorway, two on the ledge, one so close I could have touched the hood.",
		"The longer I stand in the Cleft of Shadow, the more of it turns out to be occupied. Every dark corner is a person who got there first.",
	},
	["org.muse.w18.hollow.017"] = {
		"pauses to watch a hooded warlock buy candles at a stall in the Cleft, weighing each one in the palm and rejecting two for reasons nobody explains.",
		"lingers by a candle seller in the Cleft as a warlock picks through the stock with long fingers, sniffing every wick.",
	},
	["org.muse.w18.hollow.018"] = {
		"follows a pair of hooded rogues along the narrow way of the Cleft and loses them at the first bend, without ever seeing where they went.",
		"keeps two cloaked figures in sight down the Cleft for exactly a dozen steps; then there is a bend, and then there is no one.",
	},
	["org.muse.w18.hollow.019"] = {
		"Walked into the Cleft with three pockets. Checking all three on the way out.",
		"Lovely folk in the Cleft. Remind me to count my coin once I'm out of it.",
	},
	["org.muse.w18.hours.001"] = {
		"At dawn the canyon is cut in two: one side still in cold blue shadow, the other already warm. The peons carry their loads along the line between, undecided.",
		"First light reaches only half the city. On one side of the street the stone is cold, on the other it has begun to warm, and the wolves have already moved across to lie on it.",
		"The early light comes over one rim and not the other, and for an hour Orgrimmar is two cities: one waking in the warmth, one still hunched in shadow.",
	},
	["org.muse.w18.hours.002"] = {
		"sees the inn's first fire of the day send a fat coil of smoke out of the wrong opening, and hears the innkeeper curse it like an old friend.",
		"stands aside as smoke billows out of the inn door at dawn, the fire refusing to draw, and a voice inside promises it a beating.",
	},
	["org.muse.w18.hours.003"] = {
		"Before the first hammer, the first sound of the day in Orgrimmar is a wolf yawning: a long squeaky whine, and then a dozen more, all down the street.",
		"At dawn the wolves wake before the smiths, and they wake loudly: yawns, stretches, a shake that rattles every collar in the pen.",
	},
	["org.muse.w18.hours.004"] = {
		"Up before the hawkers. I can almost hear myself think. It's unsettling.",
		"Quiet streets at this hour. Somebody wake the city; it's making me uneasy.",
	},
	["org.muse.w18.hours.005"] = {
		"In the full heat of the day the wolves lie flat in whatever shade the walls throw, and their riders sit beside them, just as flat and twice as sullen.",
		"The midday sun has beaten every wolf in the city: they lie in the strips of shade with their tongues out, and nobody dares ask them to work.",
		"At this hour the shade belongs to the wolves. They got there first, they're bigger than I am, and they know it.",
	},
	["org.muse.w18.hours.006"] = {
		"At this hour the iron on the walls is too hot to touch. I watched a peon find that out the honest way, and the whole street learned some new words.",
		"Midday turns every iron band and spike in the city into a griddle. Lean on the wrong post and you'll be branded with the city's own hardware.",
	},
	["org.muse.w18.hours.007"] = {
		"In the hard light of day every crack in the canyon walls shows, every old rockfall, every patch of mortar. By day the city looks its real age; it's the torches that flatter it.",
		"Full sun shows the canyon without mercy: the seams, the scars, the places the peons patched. Orgrimmar looks younger by firelight.",
	},
	["org.muse.w18.hours.008"] = {
		"Too hot to argue. I'll argue later, when it's cooler. Remind me.",
		"Somebody move that wall a little to the left. The shade's in the wrong place.",
	},
	["org.muse.w18.hours.009"] = {
		"At dusk the anvils stop one by one, and you can follow it across the city: a hammer here falls silent, then one further off, like candles pinched out.",
		"Listen as the light goes and you can count the forges giving up, one ringing hammer after another dropping out of the noise.",
		"The last hour of light takes the hammers away one at a time. By the end there's a single stubborn smith somewhere, ringing on alone.",
	},
	["org.muse.w18.hours.010"] = {
		"As the light goes, the canyon walls change color by the minute: red, then rust, then the dull purple of an old bruise, and at last no color at all.",
		"Dusk does strange things to the red stone. It deepens, darkens, takes the shade of dried wine, and then simply goes out.",
	},
	["org.muse.w18.hours.011"] = {
		"joins the slow tide drifting toward the inn as the light fails, and finds half the valley already squeezing through the same door.",
		"drifts toward the inn with everyone else as dusk comes down, and waits a turn at a doorway that seems to have shrunk.",
	},
	["org.muse.w18.hours.012"] = {
		"Lamps lit already? Then the bank queue was longer than I thought. Or I was slower.",
		"Torches going up along the walls. That's my signal to stop pretending I'll get anything else done.",
	},
	["org.muse.w18.hours.013"] = {
		"catches a pair of eyes shining at knee height in a dark doorway, and then the rest of the wolf, asleep with one eye on the street.",
		"notices green sparks in the shadow of an alley as torchlight passes: a wolf watching from the dark, not bothering to get up.",
	},
	["org.muse.w18.hours.014"] = {
		"At night you hear the small sounds the day drowns: a door bar dropping into place, a wolf scratching, a kettle somewhere, two voices laughing low.",
		"When the crowds go in, the city's little noises come out: the knock of a shutter, a wolf's claws on stone, someone humming behind a wall.",
		"The night strips Orgrimmar down to a handful of sounds, each one alone: a cough, a chain, a wolf turning over. I can tell them apart now.",
	},
	["org.muse.w18.hours.015"] = {
		"The moon clears the canyon rim late, and for a while every spike on the walls has two shadows, one from the torches and one from the sky, pointing different ways.",
		"When the moon finally climbs over the rim, the walls get a second set of shadows, pale and long, crossing the red ones the torches throw.",
	},
	["org.muse.w18.hours.016"] = {
		"steps quietly around an off-duty grunt asleep sitting up against a wall, chin on chest, axe across the knees like a blanket.",
		"goes softly past a grunt dozing upright on a bench, still in half his armor, snoring with great dignity.",
	},
	["org.muse.w18.hours.017"] = {
		"At night the city closes around me like a hand around a coal. Our walls, our torches, our grunts on the towers: I sleep easier here than anywhere under the sky.",
		"Night inside our own walls. Out in the wild I keep one eye open; here the Horde keeps it open for me.",
	},
	["org.muse.w18.korkron.001"] = {
		"I watched one of the Kor'kron buy bread. He paid the first price named, counted it out to the copper, and left. The baker looked as if she'd been robbed of something.",
		"The only customer in Orgrimmar who never haggles wears Kor'kron armor. He pays what he's told, and the trader is left holding the argument he'd prepared.",
		"Even a Kor'kron has to eat. I saw one pay for a loaf without a word of bargaining, and the baker stared after him like someone stood up at a wedding.",
	},
	["org.muse.w18.korkron.002"] = {
		"falls into the slow, even pace of a Kor'kron walking ahead, and only notices when the Kor'kron turns off and {g:his|her} feet keep the rhythm a few steps longer.",
		"finds {g:his|her} stride matching the measured tread of a Kor'kron a few paces ahead, and breaks it off with a small, embarrassed shake of the head.",
		"realizes, a dozen paces on, that {g:he|she} has been walking in step with a Kor'kron the whole way up the street, and falls out of it with a cough.",
	},
	["org.muse.w18.korkron.003"] = {
		"Did you see that? A goblin just lost a sale to a Kor'kron who never once looked at him.",
		"A goblin, out-talked by someone who never opened his mouth. I'll remember this.",
		"Full pitch, falling price, free strap, and the Kor'kron didn't even glance down. Poor goblin.",
	},
	["org.muse.w18.korkron.004"] = {
		"Every surface in Orgrimmar wears a coat of red dust except the Kor'kron. Somebody brushes that armor every hour, or the dust simply doesn't dare.",
		"I've never seen a speck on a Kor'kron's armor. In this city that takes either constant work or some private arrangement with the dust.",
		"A Kor'kron's armor is the cleanest thing in Orgrimmar, the bank's coin included. I'd love to meet whoever polishes it, and ask how.",
	},
	["org.muse.w18.korkron.005"] = {
		"pauses at a game of small orcs and trolls playing Kor'kron: two stand rigid by a doorway with sticks, and a third plays the Warchief, badly, by giving orders nobody follows.",
		"watches three children take turns being Kor'kron, which seems to consist mostly of standing very straight beside a door and refusing to laugh. Nobody lasts long.",
		"slows beside a doorway guarded by two very small Kor'kron with broom handles, who scowl magnificently until one of them sneezes.",
	},
	["org.muse.w18.korkron.006"] = {
		"A grunt was bellowing about the price of nails until a Kor'kron walked past. He finished the sentence at half the volume and about a third of the conviction.",
		"Nothing in Orgrimmar lowers a voice like a Kor'kron going by. I've watched a whole argument sink to a mutter and climb back up once he'd turned the corner.",
		"When a Kor'kron passes, the market drops a notch, like a pot taken off the boil, and creeps back up behind him.",
	},
	["org.muse.w18.korkron.007"] = {
		"A Kor'kron takes no orders from a chieftain, however old the clan. Only one voice moves them, and it speaks from the Hold. The clans have had to get used to that.",
		"Chieftains of proud old clans wait in line like everyone else, and the Kor'kron step aside for none of them. That's the Warchief's whole idea of a Horde, standing there in armor.",
		"The oldest chieftain in the city and the greenest peon get the same look from the Kor'kron at the Hold: measured, brief, unimpressed. The clans grumble. Thrall doesn't.",
	},
	["org.muse.w18.korkron.008"] = {
		"I wouldn't want their job. Stand still all day while the whole Horde talks at you.",
		"Kor'kron duty: stand there, say nothing, frighten everyone. Two out of three I could manage.",
		"Hard work, being a Kor'kron. All that not moving.",
	},
	["org.muse.w18.korkron.009"] = {
		"notices a Kor'kron by the throne shift half a step aside so that a short goblin petitioner can see the Warchief, then settle back as if nothing had moved.",
		"sees one of the Kor'kron make room, by the width of a hand, for a stooped old troll who could not see past him; neither of them looks at the other.",
		"catches a Kor'kron leaning, very slightly, so that a tauren calf waiting in line with its mother can glimpse the Warchief past his shoulder.",
	},
	["org.muse.w18.korkron.010"] = {
		"The orcs spent years under the eyes of human guards in the camps. Now the best guards in the city are orcs, and they keep a door that's always open. Someone thought hard about that.",
		"Not long ago every guard an orc knew was a jailer. The Kor'kron stand at an open door with their faces to the city: the same work, turned the right way round.",
		"The camps taught the orcs what a guard is for: keeping people in. The Kor'kron are the Warchief's answer, guards who hold a door open and dare anyone to shut it.",
	},
	["org.muse.w18.korkron.011"] = {
		"Thunder over the rim and the street runs for cover. Up at the Hold, I'd wager, the Kor'kron haven't so much as tilted a helmet. The storm is probably being inspected.",
		"The storm breaks and everyone dives under an awning. Up the Valley of Wisdom, I'd bet my boots, a row of Kor'kron is standing in it and staring at the rain as if it had come without an appointment.",
	},
	["org.muse.w18.korkron.012"] = {
		"Near the Hold I saw an older Kor'kron move a younger one's elbow a finger's width, with two fingers, and go back to his post without a word. That was the whole lesson, apparently, and it took.",
		"A gray-tusked Kor'kron corrected a younger one's grip on the haft with a single tap. Nothing was said. The young one won't need telling twice.",
		"Kor'kron don't teach with words, as far as I can see. A nudge to the elbow, a glance at the feet, and the younger one stands a little more like the older.",
	},
	["org.muse.w18.korkron.013"] = {
		"The Kor'kron stand where the Horde keeps its heart. Every time I pass them I want, a little, to be worth guarding.",
		"Somebody has to stand between our Warchief and every knife in the world. I'm glad it's them, and a little ashamed it isn't me.",
		"They guard one orc, and through him every one of us. I nod as I pass the Kor'kron, never get a nod back, and that seems right.",
	},
	["org.muse.w18.korkron.014"] = {
		"Nice armor, Kor'kron. Don't worry, I'm only looking.",
		"I'll just walk past very ordinarily, then. Nothing to see. Carry on looming.",
		"Fine helmet. No, I won't touch it. I value my fingers.",
	},
	["org.muse.w18.korkron.015"] = {
		"Has anyone ever seen a Kor'kron sit down? The peons say no. I'm starting to believe them.",
		"I'd pay a silver to see a Kor'kron sit down. Just once, on a stool, like a person.",
		"Do Kor'kron sit? Honest question. I've never caught one at it.",
	},
	["org.muse.w18.legend.001"] = {
		"The grunts at the door of the Hall of Legends aren't picked for size, a veteran told me, but for memory. They know every face that has earned the way in, and they never need to ask twice.",
		"Nobody shows papers at the Hall of Legends. The guards simply know who has the rank and who doesn't, and they've never yet been wrong in front of anyone.",
		"A guard at the Hall of Legends once turned away a chieftain and waved in a limping grunt in the same moment, the officers like to tell. That door reads rank, not renown.",
	},
	["org.muse.w18.legend.002"] = {
		"watches an officer of the Hall of Legends walk through the crowd in armor far too fine for errands, and a small orc trot after her at a respectful distance, copying the walk.",
		"stands aside as a decorated warrior goes by, the kind with a place in the Hall of Legends, and notices how the crowd quiets for a step or two and then pretends it didn't.",
	},
	["org.muse.w18.legend.003"] = {
		"Every honor in the Hall of Legends was paid for somewhere far from Orgrimmar, in some valley where the Alliance was waiting. The hall is quiet. The paying wasn't.",
		"No building in the Valley of Honor is quieter than the Hall of Legends, and none carries a heavier bill. Everything in it was bought with battles fought a long way off.",
	},
	["org.muse.w18.legend.004"] = {
		"Saw an officer from the Hall of Legends haggle over a loaf and lose. Made me like the whole place better.",
		"Legend is a big word for someone who still argues about the price of bread.",
	},
	["org.muse.w18.legend.005"] = {
		"An old veteran sits on a step near the Hall of Legends most days and never goes in, though people say he could. Legends, he tells anyone who listens, are just the ones who didn't die at the wrong moment.",
		"There's a scarred old orc who keeps watch on the Hall of Legends from across the path. He has the rank, people say, and no wish to use it. The ones who deserved it more, he says, aren't here to walk in.",
	},
	["org.muse.w18.legend.006"] = {
		"Hall of Legends. Grand name. I'd settle for a Hall of Decent Wages.",
		"If they ever build a hall for almost-legends, save me a bench near the door.",
	},
	["org.muse.w18.legend.007"] = {
		"Even the quartermasters of the Hall of Legends speak low. They'll take coin like any trader in the city, but only after a long look that asks what you did to stand here.",
		"In here the merchants check your rank before your purse. It's the only shop in Orgrimmar where coin comes second.",
	},
	["org.muse.w18.legend.008"] = {
		"Through the walls of the Hall of Legends the clatter of the training yard comes in faint and far off, like something the room is remembering.",
		"In here the din of the Valley of Honor shrinks to a distant rattle. Every officer in the hall started out in that noise, and none of them seems in a hurry to go back to it.",
	},
	["org.muse.w18.legend.009"] = {
		"The young grunts dare each other to touch the door of the Hall of Legends. One always does, the guard always roars, and both run off laughing, the bolder one a little taller than before.",
		"Touching the Hall of Legends' door is a dare among the young of the city. The guards know it, and roar on cue, which I suspect is their favorite part of the watch.",
		"Every child in Orgrimmar has touched the door of the Hall of Legends at least once, a guard told me with a sigh. He seems to have taken each of them personally.",
	},
	["org.muse.w18.legend.010"] = {
		"The Hall of Legends stands in the same valley as the practice yard, and I don't think that's an accident. Every pupil who hits the dust can see its door from where they're lying.",
		"Put the Hall of Legends beside the training yard and you need no speeches. The pupils fall, look up, see that door, and get back on their feet.",
	},
	["org.muse.w18.legend.011"] = {
		"That one's a legend, they told me. He looked like he needed a nap and a hot meal, same as me.",
		"Met a legend at the inn. He snored. Legendarily.",
	},
	["org.muse.w18.legend.012"] = {
		"Maybe one day the Hall of Legends will know my face. Maybe not. The Horde needs legends, but it needs far more of us who simply keep showing up.",
		"Not everyone gets a place in the Hall of Legends. Someone has to hold the gates and carry the water while the legends are being made. Most days I don't mind being that someone.",
	},
	["org.muse.w18.legend.013"] = {
		"There's a hall in this city for the ones who have done my side the most harm. I find myself walking past the Valley of Honor a little faster than anywhere else.",
		"Orgrimmar keeps a whole hall to honor the Horde's best against people like me. Strange, to admire the timber of a monument raised against my own side.",
	},
	["org.muse.w18.legend.014"] = {
		"They keep adding to the honors of the Hall of Legends. Someone said it with pride and someone else with a sigh, and I think both were right.",
		"The Hall of Legends grows a little every season the war goes on. Whether that's a good sign depends on who you ask, and on what they lost.",
	},
	["org.muse.w18.legend.015"] = {
		"catches sight of an officer's rank on a passing warrior and, without quite meaning to, stands a little straighter until the warrior has gone by.",
		"notices the grunts nearby touch their fists to their chests as a decorated officer passes, and finds {g:his|her} own hand halfway to doing the same.",
	},
	["org.muse.w18.legend.016"] = {
		"Strength to the ones in the Hall of Legends. Leave a little glory lying about for the rest of us.",
		"To the legends: well done. Now stop making the rest of us look idle.",
	},
	["org.muse.w18.lore.001"] = {
		"An old shaman told me the Valley of Honor and the Valley of Wisdom were set side by side on purpose. You need both, she said, and in that order, or the other way round, depending on who's paying for the mistake.",
		"Ask a grunt why wisdom and honor are neighbors in this city and he'll say honor first. Ask a tauren and she'll smile and say nothing, which is the answer.",
	},
	["org.muse.w18.lore.002"] = {
		"A Warsong veteran swears Grom's war cry could be heard over a whole battle, drums and all, and that the enemy always heard it first. He tells it as a plain fact, the way you'd say water is wet.",
		"The old Warsong grunts still argue about Grom's voice: whether it carried over the drums, or the drums simply stopped to let it through. Neither side has ever won.",
		"Grom's voice is the one thing about him the Warsong veterans never exaggerate, they insist. It never needed the help.",
	},
	["org.muse.w18.lore.003"] = {
		"Asked three grunts what Kor'kron means. Got three answers and one fight. I'll ask a tauren next time.",
		"What does Kor'kron mean? Apparently it means don't ask the Kor'kron.",
	},
	["org.muse.w18.lore.004"] = {
		"Thrall learned the shaman's ways in the mountains of Alterac, among the Frostwolves, the shamans of the Valley of Wisdom say. That is why the spirits are welcome in his valley: he knew them before he ever led anyone.",
		"Before he was Warchief he was a pupil, the elders of the Valley of Wisdom like to remind the young: a freed slave sitting in the cold with old Frostwolf shamans, learning to listen.",
	},
	["org.muse.w18.lore.005"] = {
		"The grunts say the Warchief's hall sits at the far end of the city from the main gate on purpose: any enemy who wants Thrall has to cross every valley of Orgrimmar first, and every valley has opinions.",
		"Whoever chose the Valley of Wisdom for the Hold thought like a soldier, an old grunt told me. Put your chief at the back and make the whole city the wall in front of him.",
	},
	["org.muse.w18.lore.006"] = {
		"stops for a moment where a grunt is telling a cluster of children about Grom's last fight; when he reaches the war cry, every child bellows it for him.",
		"catches the end of a story about Grommash told to a handful of young orcs, who roar the war cry on cue and then squabble over who roared best.",
	},
	["org.muse.w18.lore.007"] = {
		"A trainer in the Valley of Honor makes every pupil help the beaten one up before saying a word. It's older than the camps, she says, older than the Portal. The young ones roll their eyes and do it anyway.",
		"In the training yard nobody crows over a fallen partner until a hand has pulled him back to his feet. The trainers call it the old way, and nobody dares ask how old.",
	},
	["org.muse.w18.lore.008"] = {
		"In the hunters' corner of the Valley of Honor the orcs swear by wolves and the tauren swear by patience. The trolls swear at both, and their raptors bite whoever loses the argument.",
		"Ask an orc hunter for the best beast and he'll say wolf before you've finished. Ask a tauren and he'll want to know what you're hunting, and how long you can wait.",
	},
	["org.muse.w18.lore.009"] = {
		"Thrall learned to fight in a human ring, for a crowd that paid to see him bleed. The trainers of the Valley of Honor remember that. Nobody in their yard fights to be watched.",
		"The Warchief was a gladiator once, for human coin. In the Valley of Honor they'll tell you that's why the yard has onlookers and no stands: a fight there is a lesson, never a show.",
	},
	["org.muse.w18.lore.010"] = {
		"Grom was the first of us to drink the demon's blood, and in the end the one who spilled the demon's. The hall carries his name because he was both, and so were we.",
		"The orc who led my people into the demon's bargain is the same orc who broke it. Whenever I look toward Grommash Hold I remember we can be either, and have to choose.",
	},
	["org.muse.w18.lore.011"] = {
		"Before there was a Hold, an old grunt says, there was a fire in the open and the chieftains sat around it on their heels. Thrall kept the fire and built a roof over it.",
		"The first councils of this city, the old peons claim, met in the dust around a single fire, with no hall at all. Grommash Hold, they say, is only that fire with walls around it.",
		"Some of the oldest grunts still call an audience in the Hold sitting at the fire, though everyone in there stands under a roof with the Kor'kron watching.",
	},
	["org.muse.w18.lore.012"] = {
		"They put Grom's name on the one hall where everyone keeps their voice down. He'd have found that very funny.",
		"Grommash Hold, where nobody may shout. Somewhere, Hellscream is laughing.",
	},
	["org.muse.w18.lore.013"] = {
		"There's one name the old orcs of the Valley of Wisdom never say: the warlock who sold the clans to the demons. They call him that one, spit in the dust, and change the subject.",
		"Mention the orcs' old warlock chieftain to an elder and you get a look, a spit, and silence. Some names, the elders say, are only kept alive by saying them.",
	},
	["org.muse.w18.lore.014"] = {
		"Honor, the way the Horde means it, isn't the shine on an officer's armor. It's being the one the others can count on when the war comes close. The valley is named for the second thing, and I try to remember it.",
		"Our Valley of Honor drills warriors, trains beasts and hangs no medals in the yard. Honor is what you are on a bad day, the trainers say, not what you wear on a good one.",
	},
	["org.muse.w18.lore.015"] = {
		"Strength, Spirits, Wisdom, Honor: Orgrimmar named its valleys after the things it wanted to be. Nobody thought to name one Patience, though the line outside the Hold could have used it.",
		"Every valley in this city carries a virtue in its name. Wisdom and Honor sit at the far end, past all the trading, as if you had to earn your way to them.",
	},
	["org.muse.w18.lore.016"] = {
		"lingers by two old orcs arguing over which clan had the best drums before the camps, each tapping out the old rhythm on a barrelhead to prove it.",
		"overhears a pair of veterans settle an old clan quarrel by drumming it out on their knees, neither willing to admit the other kept better time.",
	},
	["org.muse.w18.lore.017"] = {
		"listens to an orc and a tauren tell, between them, how their peoples first met; the details change with every interruption, and the ending never does.",
		"follows a friendly argument between a tauren and a grunt over who saved whom from the centaur, which both of them seem to have won several times.",
	},
	["org.muse.w18.mingle.001"] = {
		"witnesses an orc cook glare as a troll customer pours a red pepper sauce over his stew, then, once the troll has gone, steal a cautious taste of it from the jar.",
		"sees a troll tip a little gourd of fiery sauce into an orc's stew; the cook takes it as an insult, the troll as a kindness, and in the end both of them eat it.",
	},
	["org.muse.w18.mingle.002"] = {
		"A goblin has hired a tauren to hold up the corner of his awning while a pole is replaced. The tauren stands there, arm raised, patient as a tent post, and has been paid in advance.",
		"One tauren, one goblin, one sagging awning: the tauren holds it up, the goblin supervises from below, and it's unclear which of them thinks he's in charge.",
	},
	["org.muse.w18.mingle.003"] = {
		"The street has its own tongue by now. The orc peons name the dishes with troll words, count in Orcish and swear in whatever's handy, and everyone follows.",
		"Listen at any corner and the talk is a stew: Orcish bones, troll seasoning, a tauren word here and there for things the orcs never had a name for.",
	},
	["org.muse.w18.mingle.004"] = {
		"stops at a corner where an orc, a troll, a tauren and a goblin are throwing dice, each of them plainly playing by a different set of rules, and all four winning.",
		"lingers long enough to see a dice game between four peoples dissolve into an argument over what a double six means, which turns out to be four different things.",
		"passes a dice game where four players argue the rules in four tongues, and nobody has rolled for some time.",
	},
	["org.muse.w18.mingle.005"] = {
		"A tauren offered a Forsaken a cup of water on a hot step. The Forsaken took it with both hands, thanked him, and held it until he'd gone. Some kindnesses are about the giving.",
		"I watched a tauren share his waterskin with a Forsaken who probably had no use for water. She accepted with a little bow. Neither of them seemed to find it strange.",
	},
	["org.muse.w18.mingle.006"] = {
		"At the trough a wolf, a raptor and a kodo are having a disagreement about turns. Their owners stand well back, each pretending the beast belongs to somebody else.",
		"A raptor nipped a wolf, the wolf snapped at a kodo, the kodo sat down. The troll, the orc and the tauren who own them have found something very interesting to study on the wall.",
	},
	["org.muse.w18.mingle.007"] = {
		"A grunt on watch and a Forsaken waiting by his post had nothing to say to each other until a goblin went past. Now they're agreeing, at length, about zeppelins.",
		"Nothing unites two peoples like a shared complaint. The orc and the Forsaken by the post have discovered they both loathe the zeppelin, and they've been friends ever since.",
	},
	["org.muse.w18.mingle.008"] = {
		"The clerk at the bank greets each customer in a different tongue: Orcish for the orc, a troll word for the troll, a slow Taur-ahe phrase for the tauren. For me, a nod. A very considerate nod.",
		"Somebody at the bank has learned a greeting in every language that comes through the door. You can tell who's next in line by which word the clerk is saying.",
	},
	["org.muse.w18.mingle.009"] = {
		"We learned each other's insults long before each other's names: orc, troll, tauren, Forsaken. I've heard that's how most families start.",
		"Our peoples still mock each other at every corner of this city, horns, tusks, stitches and all. Nobody outside the walls is allowed to, though. That's the part that matters.",
	},
	["org.muse.w18.mingle.010"] = {
		"watches an orc and a tauren carry a long beam between them up a ramp, the beam tilted steeply toward the orc's end, and neither willing to be the one who mentions it.",
		"steps aside for a beam carried by a tauren at one end and a goblin at the other, which travels up the street at a slant that suggests real trust on the goblin's part.",
	},
	["org.muse.w18.mingle.011"] = {
		"I was told the Horde was a mob of brutes held together by fear. Watching a troll and a tauren argue politely over a shared bench, I wonder who told me, and why.",
		"Where I come from, the word is that the peoples of Orgrimmar barely tolerate each other. I've watched an orc fetch water for a Forsaken and a goblin help a troll count. I'll keep that to myself.",
	},
	["org.muse.w18.mingle.012"] = {
		"At the inn every people finds its own way to sit: orcs at the long tables, tauren in the corners where the beams are highest, trolls up on the sills, and one goblin on the counter itself until the innkeeper shoos him off.",
		"The inn has chairs, in theory. In practice the tauren take the corners under the high beams, the trolls take the windowsills, and the goblins take whatever's nearest the bar.",
	},
	["org.muse.w18.mingle.013"] = {
		"watches a gang of children play at Warchief and guards: an orc boy on an upturned crate, two trolls as stern Kor'kron, and a tauren calf, by unanimous vote, as the hall.",
		"stops to see a game of court in the dust, with a goblin child as Warchief, an orc and a troll on guard, and a patient tauren calf standing in for the walls.",
	},
	["org.muse.w18.mingle.014"] = {
		"Arranging to meet anyone in this city is a puzzle. The troll says after the third drum, the orc says after supper, the tauren says when the shade reaches the bank, and the goblin names a time and a fine for lateness.",
		"Four peoples, four ways of saying later, and not one of them means the same hour. I've learned to bring something to eat while I wait.",
	},
	["org.muse.w18.mingle.015"] = {
		"The troll who mocks my accent, the tauren who walks too slow, the orc who shoves me, the Forsaken who unsettles me: if trouble came over the walls, I'd want every one of them on our side of it. They are.",
		"We get on each other's nerves all day in these streets. Let a real enemy show at the gate, and you'd see how fast we stop.",
	},
	["org.muse.w18.mingle.016"] = {
		"lingers near a goblin translating between an orc and a tauren, a word to each side and a copper from each, and notes that the conversation is taking much longer than it needs to.",
		"eavesdrops on an orc and a tauren negotiating through a goblin interpreter, who appears to be adding a few sentences of his own each way.",
	},
	["org.muse.w18.mingle.017"] = {
		"Orc, troll, tauren and Forsaken at one table, and nobody's thrown a cup yet. Someone mark the date.",
		"Look at that table. Four peoples, one jug, no bloodshed. I want to be there when it goes wrong.",
		"Four peoples sharing one jug. Somebody fetch a painter.",
	},
	["org.muse.w18.mingle.018"] = {
		"On a bench near the pool an old troll and an old tauren compared their beliefs for an hour: the loa, the Earth Mother, the spirits of the land. They concluded, to their mutual satisfaction, that everyone involved has probably met.",
		"For a good while a troll elder and a tauren elder have been trading stories of the loa and the Earth Mother, nodding at each other's best parts like two craftsmen.",
	},
	["org.muse.w18.mingle.019"] = {
		"Who taught that tauren calf to swear in Orcish? Somebody's going to get a talking-to from its mother.",
		"That little tauren just used an orc word I'd never say in front of an elder. The orc children are very proud.",
		"Listen to that calf. Pure Orcish gutter talk. The mother's ears have gone flat.",
	},
	["org.muse.w18.names.001"] = {
		"Strength, Spirits, Wisdom, Honor: the valleys got virtues, and only the city and the hall got names. An elder told me the dead were heavy enough on two words.",
		"The orcs named the city for one dead hero and the hall for another, then stopped. The valleys got plain virtues, a grunt says, because nobody wanted to give directions by way of a grave.",
		"No valley here is named for a person. A grunt's theory: a dead name on a city is pride, but a dead name on every street would be a graveyard.",
	},
	["org.muse.w18.names.002"] = {
		"The trolls say Durotar with a lilt, as if it were a song. The orcs say it like a clenched fist. The tauren say it slowly, as if it would be rude to hurry a dead chieftain's name.",
		"Listen long enough and you can tell who's speaking by how they say Durotar: rolled by a troll, barked by an orc, set down gently by a tauren, like a heavy pack.",
	},
	["org.muse.w18.names.003"] = {
		"On the hall it's Grommash, the full name. At the inn it's just Grom. The old Warsong say both are right: one for what he did at the end, one for who he was before it.",
		"Nobody calls him Grommash over a drink. Grom, they say, and lift the mug a little. Grommash is for the hall, and for the moments when they stand up straight.",
	},
	["org.muse.w18.names.004"] = {
		"The Darkspear named their village on the coast for Sen'jin, Vol'jin's father, who never reached Kalimdor. In Orgrimmar the trolls say his name softly, the way the orcs say Durotan's.",
		"Sen'jin Village carries the name of a troll who died on the old isles before the crossing was over, a Darkspear told me. Every people of this city seems to have built on a father's grave.",
	},
	["org.muse.w18.names.005"] = {
		"Shout 'Grom!' in this street and count the heads that turn. I got four. Two were wolves.",
		"Half the cubs born here got named for the dead, the mothers say. Call for Grom and you'll be busy all day.",
	},
	["org.muse.w18.names.006"] = {
		"pauses at a stall of little carved figures, Thrall, Grom and Orgrim among them; the dead heroes sell best, the carver admits, since they can't complain about the noses.",
		"turns over a small wooden Doomhammer, black-painted armor and all, while the carver explains that the living Warchief is harder to sell: everyone knows what he looks like.",
	},
	["org.muse.w18.names.007"] = {
		"The Burning Blade was a clan's name once, the elders say, before it was a cult's. Some names go bad and can't be washed clean, and nobody in the city will answer to that one.",
		"Before it meant cultists in the chasm, an old grunt says, Burning Blade was a clan known for its blademasters. He says it with real anger, like someone speaking of a fine tool ruined by fools.",
	},
	["org.muse.w18.names.008"] = {
		"looks up at a faded clan sign painted over an old doorway, a wolf's head half worn away, and meets the eye of the elder sitting beneath it, who sits up a little straighter.",
		"stops under a doorway where three old clan marks are painted side by side, one of them carefully scratched out, the scratches newer than the paint.",
	},
	["org.muse.w18.names.009"] = {
		"Kul Tiran, a grunt told me, has become a word among the guards for anyone who shows up uninvited with a lot to say. A goblin got called one at the gate and took it as a compliment.",
		"Call somebody a Kul Tiran in this city, the veterans say, and you mean a guest who came to stay without asking. They say it with a smile now. The smile took a while.",
	},
	["org.muse.w18.names.010"] = {
		"Warchief is said two ways by the old orcs. About Thrall, plainly. About the ones before Doomhammer, with a pause in front of it, as if the word had to be wiped first.",
		"Warchief is an old word, older than this city and dirtier, an elder told me. Orgrim scrubbed it, Thrall wears it clean, and the elders still check it for stains.",
	},
	["org.muse.w18.names.011"] = {
		"Doomhammer, Hellscream, Durotan. Every grand name in this city belongs to someone who never saw it.",
		"Durotan's land, Orgrim's city, Grom's hall. The dead are well housed, at least.",
		"Three dead orcs hold the deeds to this place. The rest of us are tenants, and loud ones.",
	},
	["org.muse.w18.names.012"] = {
		"In Alliance taverns they say Orgrimmar like the name of a sickness. Standing in it, I find it's mostly the name of a great many people shopping.",
		"Among my side, Orgrimmar is a word you lower your voice for. Here hawkers shout it a hundred times an hour, and it's hard to keep fearing a word that sells turnips.",
	},
	["org.muse.w18.names.013"] = {
		"When I say Orgrimmar far from here, nobody hears a dead Warchief's name in it any more. They hear a gate, a bank, a hall that listens. Orgrim would probably call that a fair trade.",
		"Out in the world our capital's name has stopped meaning one old orc and started meaning all of us. He wouldn't have minded. He'd have minded the speeches.",
	},
	["org.muse.w18.names.014"] = {
		"Doomhammer is a hammer and a dead Warchief, both at once. A grunt told me he swore once to die for the Doomhammer, and two people asked him which one.",
		"Say Doomhammer in Orgrimmar and you might mean the old Warchief or the hammer at Thrall's side, and the veterans say it hardly matters: both are still at work.",
	},
	["org.muse.w18.names.015"] = {
		"hears a goblin trader mangle the name Grommash and three orcs correct him at once, from three different directions, with identical scowls.",
		"watches a goblin try to say Hellscream with the proper growl, fail, and be coached through it by a grunt who seems to be enjoying himself.",
	},
	["org.muse.w18.names.016"] = {
		"hears a troll woman call a child in from the street by the name Vol'jin, and watches the small troll come at a run, as if the name were an order.",
		"turns at a shout of Thrall from a doorway and finds a tiny orc being summoned to supper, already sulking under the weight of the name.",
	},
	["org.muse.w18.names.017"] = {
		"Orgrimmar. Say it properly: it should sound like a gate slamming shut.",
		"You can't whisper that name. I've tried.",
	},
	["org.muse.w18.noise.001"] = {
		"From the bank door comes a sound like gravel shaken in a pan: coin poured out and counted, on and on, never quite stopping.",
		"Stand near the bank and you hear the city's money at work, a dry rattle of coin on wood that rises and falls but never ends.",
		"There's one sound in the Valley of Strength that outlasts every other: coin on the bank counter, chinking away like a stream that runs on silver.",
	},
	["org.muse.w18.noise.002"] = {
		"A cart axle has been squealing the length of a whole street. Every grunt in earshot is quietly thinking the same violent thought.",
		"That axle needs grease, and the whole street knows it. The peon pushing the cart is the only soul in Orgrimmar who seems not to hear.",
		"Of all the city's racket, the one I can't bear is a dry wheel. It shrieks past, and a dozen faces wince at once.",
	},
	["org.muse.w18.noise.003"] = {
		"hears a patrol before seeing it: the clink of mail, the creak of leather, the dull knock of an axe haft against a shoulder plate.",
		"turns at a sound coming round the corner, mail and leather and heavy boots in step, a moment before the grunts themselves appear.",
	},
	["org.muse.w18.noise.004"] = {
		"Something goblin-made goes off with a bang in a shop down the way, and nobody even turns. Apparently it does that every hour or so.",
		"A bang from a goblin's workshop, then a short silence, then the goblin laughing. The street carries on as if nothing happened, because, as far as it's concerned, nothing did.",
	},
	["org.muse.w18.noise.005"] = {
		"Half the doors in this city are hides hung from a pole, and each one slaps shut behind whoever passes, a soft clap that follows you down every street.",
		"Leather doors everywhere, and every one of them claps closed behind somebody. Walk the city long enough and you hear it like slow applause.",
	},
	["org.muse.w18.noise.006"] = {
		"A goblin's cigar leaves a trail through the crowd you could follow with your eyes shut. I know exactly which way he went, and I wish I didn't.",
		"That smell of cheap cigar cutting across the stew and the tannery: a goblin went this way, and not long ago.",
		"You can track the goblin traders through the crowd by nose alone: a thread of cigar smoke, a whiff of oil, and somewhere at the end of it, a sales pitch.",
	},
	["org.muse.w18.noise.007"] = {
		"What is that smell? No. Don't tell me. I'd rather keep guessing.",
		"Something here smells like a boot that died. Nobody else has noticed. That worries me more.",
	},
	["org.muse.w18.noise.008"] = {
		"The rasp of a saw somewhere off the road, and a smell of fresh timber cutting through the smoke. Somebody's hut is going up, and the neighbors are already complaining about the hammering.",
		"In a few corners Orgrimmar still smells of sawdust. New posts, new beams, a peon humming over a fresh joint. The city never stops adding rooms.",
	},
	["org.muse.w18.noise.009"] = {
		"Under all the shouting there's one sound that never stops: a whetstone on steel, somewhere close, always. This city keeps its edges the way other cities keep gardens.",
		"Listen past the crowd and you'll find it: the patient scrape of a whetstone. On every bench and doorstep in Orgrimmar someone is sharpening something.",
		"Other cities hum with bells or fountains. Orgrimmar's quiet sound is the whetstone, stroke after stroke, from a hundred doorways at once.",
	},
	["org.muse.w18.noise.010"] = {
		"Every sound in this city makes me flinch: a shout, a drum, a door banging. Most of them turn out to be someone selling fish.",
		"I jump at every raised voice here. So far each one has been a hawker, a quarrel or a joke. I keep jumping anyway.",
	},
	["org.muse.w18.noise.011"] = {
		"follows a smell of fresh bread for three turns of the street, loses it outside a tannery, and stands there betrayed.",
		"catches a whiff of something baking, turns to track it, and walks straight into the tannery smell instead, which wins.",
	},
	["org.muse.w18.noise.012"] = {
		"From the inn comes a song nobody knows all the words to, so the room hums the gaps. It sounds better that way.",
		"Somebody at the inn has started a song, and by the second verse half the room is singing a different one. Nobody seems to mind.",
	},
	["org.muse.w18.noise.013"] = {
		"After a while in Orgrimmar the nose simply resigns. I can't smell the tannery anymore, which is either a mercy or a warning.",
		"My nose has given up on this city. Tannery, wolf pens, burnt fat: it reports nothing now. I'm not sure I want to know what I smell like.",
		"Somewhere along the way my nose stopped complaining about this city. I can't decide whether I've grown used to it, or it has grown into me.",
	},
	["org.muse.w18.noise.014"] = {
		"Could everyone lower their voices for just a moment? No? Carry on, then.",
		"A little quiet, that's all I ask. ...That was a joke. Carry on.",
	},
	["org.muse.w18.noise.015"] = {
		"Sometimes, in the din, I hear the canyon itself: a creak of old rock settling, a trickle of grit. The city is loud, but the stone has a voice too, older and slower.",
		"Under all the noise of the people, the rock makes its own small sounds: a tick, a settling, a hiss of grit. It was talking long before the orcs came, and it hasn't stopped.",
	},
	["org.muse.w18.noise.016"] = {
		"Who's beating that pot? It isn't a drum, and whoever it is isn't a drummer.",
		"There's a rhythm in that racket somewhere. I'll find it eventually.",
	},
	["org.muse.w18.orcs.001"] = {
		"watches an old orc woman teach a child to tie a harness knot, and pull it loose with one tug each time it comes out wrong.",
		"lingers by a doorstep where a gray-haired orc guides a small pair of hands through the same strap knot, over and over, with no word of praise until it holds.",
	},
	["org.muse.w18.orcs.002"] = {
		"An orc at the trough is telling his wolf about his whole day, in long patient sentences. When a peon asks him the way, he answers with one word and a thumb.",
		"Some orcs save their gentlest voice for the wolf. That one by the trough has been explaining something to his for a good while; to me he grunted once.",
		"Plenty of orcs in this city keep their long sentences for their wolves. The rest of us get the short version.",
	},
	["org.muse.w18.orcs.003"] = {
		"At the bank an old orc flinched when a clerk turned a key in a lock. Then he laughed at himself, too loudly, and set his coin down.",
		"The sound of a lock closing still makes some of the older orcs look round. Just for a moment. Then their hands find something to do.",
		"Some of the old ones still turn at the click of a lock. Not for long.",
	},
	["org.muse.w18.orcs.004"] = {
		"pauses at the sound of a small orc girl practicing a war cry behind a hut; her voice cracks on the top note, and two passing grunts nod at her very seriously.",
		"turns at a fierce little shout from an alley, where an orc child is rehearsing a war cry at a wall, and the wall, by all signs, is losing.",
	},
	["org.muse.w18.orcs.005"] = {
		"The old soldiers at the inn all want the same bench: back to the wall, eyes on the door. They take turns at it without ever agreeing to.",
		"Watch the veterans come into the inn. Every one of them looks for a wall to sit against first and a drink second.",
		"No veteran at the inn sits with a door behind him. Not one.",
	},
	["org.muse.w18.orcs.006"] = {
		"notices an orc dabbing fresh paint along her jaw, using a scrap of polished iron for a mirror and a fingertip for a brush.",
		"catches a grunt renewing the old marks on his face from a little clay pot, tilting a bright buckle to see the work.",
	},
	["org.muse.w18.orcs.007"] = {
		"Orcs often give a parent's name along with their own, as if a name came in two halves. I gave mine alone once and got a look of real pity.",
		"Introduce yourself to an old orc and he waits a beat for the rest of it: whose child you are. A bare name, a grunt told me, sounds like a coat with no sleeves.",
	},
	["org.muse.w18.orcs.008"] = {
		"An orc just called my work not bad. I'm told that's the highest praise in the city.",
		"Not bad, he says. From an orc that's practically a serenade.",
		"Not bad, from an orc. I'm going to need a moment.",
	},
	["org.muse.w18.orcs.009"] = {
		"An old orc by the water barrel tips the first splash of every cup onto the ground before he drinks. For the spirits of the land, he says, who were thirsty here first.",
		"Some of the older orcs spill a little water in the dust before they drink. A shaman's habit from the old days, one of them told me, and in Durotar it costs something.",
	},
	["org.muse.w18.orcs.010"] = {
		"watches an orc cook taste the stew off a knife tip, frown, add salt, taste once more, and frown in a slightly different way.",
		"stops to see an orc cook judge a pot by smell alone, nose over the steam, eyes shut, like a smith listening to iron.",
	},
	["org.muse.w18.orcs.011"] = {
		"An old orc whose hands shake too much for the hammer now sorts nails by size into little jars, all day long. Sitting idle, he told me, is something he did enough of behind the fences.",
		"There's an orc too old for the forge who sorts the smith's nails instead, slowly, one jar for each size. Idleness, he says, was the camps' work, and he won't do it for free.",
	},
	["org.muse.w18.orcs.012"] = {
		"I just watched an orc apologize to a troll. It took a long run-up, and he said most of it to his own boots, but it counted.",
		"Few sights beat an orc apologizing. This one cleared his throat three times, studied the ground, and got it out in four words. The troll accepted with great ceremony.",
	},
	["org.muse.w18.orcs.013"] = {
		"The young of my people ask the elders what the demon's fire felt like in the blood. The elders change the subject to the price of iron, every time, and I think that is the right answer.",
		"Our young ones have never felt the old fury, and the elders mean to keep it that way. Ask about it at the inn and someone always orders another round instead.",
	},
	["org.muse.w18.orcs.014"] = {
		"Somebody tell that grunt his wolf is eating his lunch. No, wait. Let's see how this ends.",
		"Should we warn him about the wolf and the sausage? No. Some lessons an orc has to learn alone.",
		"Nobody warn the grunt about the wolf. I want to see his face.",
	},
	["org.muse.w18.orcs.015"] = {
		"An orc with a scarred face whittles little wooden wolves on a step and sells them for a copper. The children who can't pay get one anyway, and are told sternly to say nothing.",
		"On a step near the bank a battered old orc carves toy wolves for the city's children. He scowls at every one he hands over, and nobody believes the scowl.",
		"The old orc who carves toy wolves gives away more than he sells, and threatens anyone who says so.",
	},
	["org.muse.w18.orcs.016"] = {
		"sees an orc woman tie a cloth over her child's face against the blowing sand before she covers her own.",
		"walks behind an orc father who pulls his cub inside the shelter of his cloak as the sand comes down the street, and goes on half blind without complaint.",
	},
	["org.muse.w18.orcs.017"] = {
		"That orc gripped my forearm so hard I think my bones signed the deal too.",
		"Good grip. I'll be wanting that arm back at some point.",
		"Next time an orc offers me his forearm, I'm bracing first.",
	},
	["org.muse.w18.orcs.018"] = {
		"Let me take that, elder. No, I insist. Yes, I know you carried worse in your day.",
		"Here, give me the sack. You've earned a walk with empty hands.",
	},
	["org.muse.w18.patrol.001"] = {
		"A cook at a fire off the Drag pulls her flatbread from the stones each time the patrol comes round. She says the grunts keep better time than any drum.",
		"One cook I know sets her bread by the patrol: when the boots come round the corner, the loaves come off. She swears she hasn't burned one yet.",
		"The bread-woman near the Drag needs no hourglass. The patrol passes, she turns the loaves; it passes once more, she takes them off.",
	},
	["org.muse.w18.patrol.002"] = {
		"slips in behind a passing patrol and rides its wake through the thickest part of the crowd, then peels off before anyone thinks to object.",
		"tucks in close behind two grunts on their rounds, letting the crowd part for them and close again only once {g:he|she} is through.",
		"falls in a pace behind a patrol, borrows the path the crowd makes for it, and slips away down a side way with a look of complete innocence.",
	},
	["org.muse.w18.patrol.003"] = {
		"comes upon a patrol bent over a snoring orc sprawled across some steps; one grunt rolls him onto his side with a boot, the other tucks his purse inside his shirt, and they walk on.",
		"sees two grunts on their rounds find a sleeper slumped in a doorway, shift him gently out of the traffic and leave him with his head on his own pack.",
		"spots two grunts on patrol lifting a drunk off the middle of the road and propping him against a wall, which he thanks warmly before going back to sleep.",
	},
	["org.muse.w18.patrol.004"] = {
		"lingers near a water barrel as a patrol stops to take one ladle each in a fixed order, eldest first; the youngest drinks last and is the one who puts the lid back.",
		"sees two grunts on their round share a ladle at a barrel, the elder first without a word, the younger after, then the lid set back exactly as it was.",
	},
	["org.muse.w18.patrol.005"] = {
		"pauses as a grunt on his round stops to push a loose stone back into a wall with the heel of his hand, then walks on as if mending were part of the watch.",
		"catches a passing grunt kicking a toppled post upright and stamping the earth firm round it, without once breaking his round.",
	},
	["org.muse.w18.patrol.006"] = {
		"You hear a patrol before you see it: two pairs of boots in no hurry, and a little pool of quiet that moves with them, where the gossip stops and starts up again behind.",
		"Patrols carry their own hush. Gossip dies a few paces ahead of the grunts and comes back to life a few paces after, like grass springing up behind a cart.",
		"The patrol goes by and the street lowers its voice for exactly six steps. I've counted.",
	},
	["org.muse.w18.patrol.007"] = {
		"The night patrols carry torches up and down the ramps, and from below they look like a few slow sparks climbing the dark, stopping, turning back.",
		"After dark you can follow the watch by its torches: one flame on the high ramp, two near the bank, one going down toward the Cleft of Shadow, none of them in a hurry.",
	},
	["org.muse.w18.patrol.008"] = {
		"squints into the blowing sand at a patrol going by in single file, each grunt with one hand on the shoulder in front, steady as a string of laden kodos.",
		"watches a pair of grunts walk their round through the sand regardless, heads down, the second one's fist hooked in the first one's belt.",
	},
	["org.muse.w18.patrol.009"] = {
		"Any news, grunt? ... Nothing. Best answer I've had all week.",
		"Asked a patrol what's happening. 'Nothing.' Finest news there is.",
		"Nothing to report, he says. From a grunt, that's practically a song.",
	},
	["org.muse.w18.patrol.010"] = {
		"keeps an eye on a grunt testing the shutters of a closed shop with the flat of his hand, one after another down the row, like a goatherd counting by touch.",
		"follows a patrol along a row of shut stalls, where one grunt gives each door a firm push and the other waits for the knock of a bar holding.",
		"trails a patrol past a row of shut workshops, where a grunt rattles each latch in turn and stops, head cocked, at the one that rattles too freely.",
	},
	["org.muse.w18.patrol.011"] = {
		"A wolf had slipped its pen and was making a tour of the stalls. The patrol caught it by the scruff, scolded it like a nephew, and walked it home without breaking stride.",
		"The grunts on their rounds catch more runaway wolves than thieves. I saw one led back to its pen by the scruff, sulking, while its catcher told it exactly what he thought of it.",
		"Half of what a patrol chases, a grunt complained to me, has four legs and a guilty face. The other half has two legs and the same face.",
	},
	["org.muse.w18.patrol.012"] = {
		"Same corner, same grunts, same scowl. You could set a clock by them, if anyone here owned a clock.",
		"There goes the patrol. Right on time, wherever time is kept in this city.",
		"Round they come, regular as rent. I'd swear they wear a groove in the street.",
	},
	["org.muse.w18.patrol.013"] = {
		"Up in the valleys the grunts patrol in pairs. Here in the Cleft of Shadow they come in threes, and the third one walks backward for a good part of the way.",
		"Patrols in the Cleft of Shadow are a grunt larger than anywhere else, and they don't chat. One of them always watches the way they've just come.",
		"In the Cleft of Shadow the patrols walk slower and closer together, and nobody down here takes it as an insult.",
	},
	["org.muse.w18.patrol.014"] = {
		"watches a grunt finish his round with a lost troll child riding on his shoulders, calling for the parents in a voice that clears half the street.",
		"spots a patrol going by with an unexpected passenger: a small, tearful tauren perched on a grunt's shoulders, searching the crowd for its mother.",
		"smiles at a grunt carrying a strayed child along his round like a lantern held up high, so that whoever lost it can find it by looking up.",
	},
	["org.muse.w18.patrol.015"] = {
		"The patrol grunts know everything the street knows: which brewer waters the ale, which goblin keeps two sets of weights. They say nothing until saying something is worth the trouble.",
		"A grunt on patrol knows this city better than its merchants do. He knows the short scale and the watered cask, and he lets them be, until one day he doesn't.",
		"Who sells short and who sells sour, the patrols know. Knowing and saying are two different trades, and most of the time the grunts practice only the first.",
	},
	["org.muse.w18.patrol.016"] = {
		"Nothing on your stretch, grunts? Then you've earned your pay.",
		"How many times round is that? Don't tell me. Your feet already know.",
		"Quiet round, grunt? Good. Long may it bore you.",
	},
	["org.muse.w18.pool.001"] = {
		"Look down into the troll pool and the canyon walls go on below as far as they rise above. A second Orgrimmar, upside down, and the only quiet one.",
		"The pool in the Valley of Spirits holds a whole red canyon in it, hanging the wrong way up. Nothing in that one shouts.",
		"In the still water of the troll valley the whole canyon hangs upside down, spikes and all, and not one hammer reaches it.",
	},
	["org.muse.w18.pool.002"] = {
		"dips two fingers in the pool and draws them back cool, the coolest thing to be found anywhere in Orgrimmar.",
		"trails a hand at the edge of the troll pool and holds it there a moment longer than seems polite.",
	},
	["org.muse.w18.pool.003"] = {
		"Where the troll pool gets its water depends on who you ask. A spring under the rock, says a shaman. A debt some loa still owes, says a witch doctor. Buckets, says a peon with very tired shoulders.",
		"A spring, say the shamans. A gift, say the witch doctors. The peon who swore it was buckets wouldn't say whose buckets, and limped off.",
	},
	["org.muse.w18.pool.004"] = {
		"That pool is begging for a pair of tired feet. Mine, ideally. The trolls disagree.",
		"One toe in that water. Just one. No? The look on that troll says no.",
		"Sore feet, cool water, and a troll guarding it with one look. Life is cruel.",
	},
	["org.muse.w18.pool.005"] = {
		"Nobody drinks from the troll pool, nobody washes in it, nobody fishes it. In Durotar, water that nobody uses is the dearest thing there is.",
		"In a land that counts every bucket, the Darkspear keep a whole pool of water that no one touches. That isn't waste. It's respect, paid in the hardest coin they have.",
		"A pool nobody drinks from, in a country where people fight over wells. The trolls never explain it, and it explains itself.",
	},
	["org.muse.w18.pool.006"] = {
		"watches a troll child set a leaf afloat on the pool, and an elder lift it out with a stick before it can drift to the middle.",
		"follows a little leaf boat across the troll pool until an old troll fishes it out, gently, and hands it back to its sulking captain.",
	},
	["org.muse.w18.pool.007"] = {
		"Over the troll pool sound plays tricks: a murmur from the far bank arrives clear as a bell, and the whole roar of the Drag arrives as nothing at all.",
		"Water carries a whisper and drowns a shout. Across the pool in the Valley of Spirits, two trolls talking softly sound closer than the hammering one street away.",
	},
	["org.muse.w18.pool.008"] = {
		"There's a frog living in the troll pool. How it reached the middle of Durotar nobody can say, and the trolls treat it like a visiting dignitary.",
		"One frog, fat and unbothered, owns the troll pool. The Darkspear step around it. I suspect it's been told it's important.",
		"Somewhere in the troll pool lives a single frog, the only one in Orgrimmar, and it croaks at the drums as if correcting them.",
	},
	["org.muse.w18.pool.009"] = {
		"A Darkspear told me the pool is the sea, made small enough to carry inland. I laughed. She didn't.",
		"The sea, folded up small and brought into the desert: that's what the troll pool is, according to an old fisherwoman of the valley. She said it without a smile.",
	},
	["org.muse.w18.pool.010"] = {
		"crouches by the troll pool to watch small insects skate across its skin, leaving rings that close as fast as they open.",
		"lingers at the water's edge, following one skating insect as it stitches its way from bank to bank.",
	},
	["org.muse.w18.pool.011"] = {
		"Sand has settled on the troll pool in a pale skin, and an old troll is skimming it off with a cloth, slowly, the way you'd wipe a child's face.",
		"The blowing sand dulls the pool to the color of the canyon. Two trolls are already at the edge with a sieve, lifting it out handful by handful.",
	},
	["org.muse.w18.pool.012"] = {
		"At night the troll pool holds every torch in the valley twice, and the second set burns without smoke.",
		"Each torch in the Valley of Spirits gets a twin in the pool after dark. The twins are steadier, and nobody ever has to tend them.",
	},
	["org.muse.w18.pool.013"] = {
		"At the bottom of the troll pool lie a bead, a tooth, a few copper coins. Nobody fishes them out. In this city of all cities, that alone is a small wonder.",
		"Copper glints on the floor of the pool in the Valley of Spirits, and in Orgrimmar, where a dropped coin rarely reaches the ground, nobody reaches for it.",
	},
	["org.muse.w18.pool.014"] = {
		"Copper in the pool and not one goblin wading after it. Somebody check the goblins are well.",
		"There's coin in that water, and nobody's fishing for it. Is everyone in this valley feeling all right?",
	},
	["org.muse.w18.pool.015"] = {
		"Here by the pool the air is a shade cooler, and the stone under my hand is cool for once. I could sit until somebody asks me to move. Nobody does.",
		"The air by the water is a few steps kinder than anywhere else in Orgrimmar. I've found a stone at the edge and I mean to keep it.",
	},
	["org.muse.w18.pool.016"] = {
		"watches an old troll lower a gourd into the pool of the Valley of Spirits, lift it full, and pour it back, slowly, three times over, before walking away with it empty.",
		"sees a Darkspear elder fill a gourd at the troll pool and tip it back into the water in a thin bright stream, then go off empty-handed, apparently satisfied.",
	},
	["org.muse.w18.pot.001"] = {
		"Durotar boar is all gristle and grudge. The cooks here stew it until it gives up, and then a little longer, out of spite.",
		"A cook told me the trick with boar from the hills is patience: it fought its whole life, and it will fight in the pot too, for a while.",
	},
	["org.muse.w18.pot.002"] = {
		"watches a cook taste from the ladle, frown, throw in a pinch of something red, taste again, and nod once at nobody.",
		"stops by a cookpot as its keeper blows on a spoonful, tastes, scowls, adds salt from a cupped palm and tastes once more, satisfied at last.",
	},
	["org.muse.w18.pot.003"] = {
		"Fish come up from the coast in wet baskets slung on poles, already quarrelling with the heat. By the time they reach the stalls they need eating, and they make sure everyone knows it.",
		"The fish sold in Orgrimmar have had a long walk from the sea. The fishmongers shout twice as loud as anyone else, and for good reason.",
	},
	["org.muse.w18.pot.004"] = {
		"ducks as an angler shoulders a long pole through the crowd, the hook swinging at ear height and somehow catching no one.",
		"marvels at a fisherman threading a pole the length of a wolf's leap through the busy street, the line trailing, the whole crowd bending around it like grass.",
	},
	["org.muse.w18.pot.005"] = {
		"Something's burning. In this city that narrows it down to everything.",
		"Smells like somebody burned supper. Or a hut. Hard to tell in Orgrimmar.",
	},
	["org.muse.w18.pot.006"] = {
		"Before full light the cooks are already gutting the fish by lantern, and the wolves of the street have gathered in a polite half-circle to wait for the heads.",
		"Cookfires are coaxed awake before anything else in the city: water hauled, fish split in the half dark, and not a word said that isn't about salt.",
	},
	["org.muse.w18.pot.007"] = {
		"Under a roof the smell of the cookpot settles into every corner, into the beams and into my cloak, where it will wait to make me hungry somewhere far from here.",
		"Indoors the stew smell is thick enough to lean on. I'll carry it out on my clothes, and some stranger on the road will turn to sniff.",
	},
	["org.muse.w18.pot.008"] = {
		"A pinch of goblin pepper costs more than the stew it goes into. The cooks buy it anyway. Without it, one told me, stew is just hot water with ambitions.",
		"The spice seller is a goblin, naturally, and she weighs out pepper on scales the size of a coin. The cooks pay her as if it were gold dust and grumble as if it were gravel.",
	},
	["org.muse.w18.pot.009"] = {
		"stops beside a cook cleaning fish with three quick strokes apiece, flicking the scraps to a waiting wolf without once looking down.",
		"lingers to see a fishmonger split and clean a whole basket in the time it takes to haggle over one fish, the wolf at her feet catching every scrap in the air.",
	},
	["org.muse.w18.pot.010"] = {
		"Any cook here will give you her recipe, kindly and at length, minus the one part that matters.",
		"Recipes in Orgrimmar aren't written down. They pass from cook to cook in a low voice, and somehow the best bit is always missing from the version strangers get.",
	},
	["org.muse.w18.pot.011"] = {
		"Who taught that troll to cook? I want to shake their hand, then eat their supper.",
		"That thing on the brazier: I'll have two. Don't tell me what it was.",
	},
	["org.muse.w18.pot.012"] = {
		"In the camps the food came in one gray bowl, the same every day. My people cook loudly now: too much pepper, too much fat, every pot argued over. All of it ours.",
		"The elders say the camp gruel had no taste at all, and that was the worst of it. Maybe that's why every orc cook in this city salts like the sea.",
	},
	["org.muse.w18.pot.013"] = {
		"The anglers are the quietest folk in Orgrimmar. A lifetime of not frightening the fish has left them unable to frighten anyone.",
		"In this loud city a fisherman is easy to spot: the only one waiting for something without tapping a foot.",
		"Fishers coming up from the coast carry a stillness the city can't knock out of them, at least until the first haggle.",
	},
	["org.muse.w18.pot.014"] = {
		"The cooking trainer makes her apprentices eat their own failures. All of them, to the last spoonful. It's a fast school.",
		"There's a cook who teaches by one rule: what you burn, you eat. Her pupils learn quickly, and some of them look a little gray.",
	},
	["org.muse.w18.pot.015"] = {
		"buys a skewer of something charred from a brazier, bites, chews thoughtfully, and goes back for another before the first is finished.",
		"accepts a taste of stew from a cook's ladle, burns the tongue, nods with watering eyes and pays for a bowl.",
	},
	["org.muse.w18.pot.016"] = {
		"I'd learn to cook if this city would ever stop cooking for me.",
		"Why learn to cook? Orgrimmar has a pot on every corner and somebody happy to stir it.",
		"Every corner of this city has a pot on it. I've stopped carrying food.",
	},
	["org.muse.w18.quarrel.001"] = {
		"Two goblins were at each other's throats over a contract until a grunt told them to read it aloud to him, all of it. He was gone before page two. They're still reading.",
		"A grunt settled a goblin quarrel by ordering both of them to read their contract out loud, slowly, from the top. He walked off at the first clause. I suspect that was the ruling.",
	},
	["org.muse.w18.quarrel.002"] = {
		"hears a shouting match between two traders stop dead as a patrol rounds the corner; both put on the same broad smile and admire each other's goods until the grunts have passed.",
		"sees two quarreling porters notice the grunts at the same instant and switch, mid-shove, to a hearty clap on the back.",
		"catches the exact moment a fistfight in the making becomes a friendly chat, which is the moment a grunt turns to look.",
	},
	["org.muse.w18.quarrel.003"] = {
		"Two orcs both claimed a wolf pup, and the grunt they called over set it down between them and stepped back. It trotted straight past both of them to the butcher's stall. The case is still open.",
		"Ownership of a stray pup was decided by letting the pup choose, a grunt's idea. It chose neither claimant and went to sleep on his boot. He seems to have accepted the verdict.",
		"A stray pup, two orcs claiming it, and a grunt who let the pup decide. It decided on the butcher.",
	},
	["org.muse.w18.quarrel.004"] = {
		"Some quarrels in this city are older than its walls. Two gray orcs glaring at each other across the street over something from the camps: who talked, who didn't. No grunt has a ruling for that.",
		"I watched two aged orcs pass each other without a word, stiff as posts. A grudge from the internment camps, someone muttered. The Warchief's peace keeps their hands still. It can't reach any further than that.",
	},
	["org.muse.w18.quarrel.005"] = {
		"Take it outside the gate, you two. The grunts have enough on their hands.",
		"Settle it with words or settle it with the grunts. I know which is cheaper.",
		"Shout quieter, both of you. There's a patrol two stalls down.",
	},
	["org.muse.w18.quarrel.006"] = {
		"Here in the Drag two stallkeepers settled a quarrel over a hand's width of frontage the orc way: arm-wrestling on a barrel, with a grunt holding their elbows square. The loser moved his awning without a word.",
		"How do you settle whose stall gets the extra hand's width in the Drag? On a barrel top, wrist to wrist, with a grunt refereeing. The loser shifted his poles and bought the winner a drink.",
	},
	["org.muse.w18.quarrel.007"] = {
		"watches a grunt listen to two quarreling neighbors for a long moment, then fold his arms and wait in silence until they have, awkwardly, settled it between themselves.",
		"looks on as a grunt refuses to take a side between two feuding neighbors; he simply plants himself between them and stays, until they find an agreement just to be rid of him.",
	},
	["org.muse.w18.quarrel.008"] = {
		"A troll and a tauren were quarreling with no tongue in common, so a goblin stepped in to translate, at a copper a sentence. By the end both were furious with the goblin, and the quarrel was forgotten.",
		"Nothing ends a quarrel between two peoples faster than a goblin interpreter. He charges both sides by the insult, and soon they're united against him.",
		"A goblin translating for a troll and a tauren made their quarrel worse on purpose, a copper per insult, until both turned on him. Peace, of a sort, at a fair price.",
	},
	["org.muse.w18.quarrel.009"] = {
		"Two white-tusked orcs are arguing over which of their clans held the line in a battle fought before the grunt listening was born. He has no idea who's right, and the wisdom to say so.",
		"An argument about a war older than the city: whose clan broke, whose stood. The young grunt sent to calm it just leans on the wall and listens, like a student in the back row.",
	},
	["org.muse.w18.quarrel.010"] = {
		"Two traders were halfway through a proper quarrel when the rain came down, and they ended up under the same awning, shoulder to shoulder, too astonished by the weather to remember what they'd been shouting about.",
		"Rain in Orgrimmar stops everything, even a feud. The two stallholders who were at each other's throats a moment ago are sharing an awning and gaping at the sky.",
	},
	["org.muse.w18.quarrel.011"] = {
		"At the auction house there's a quarrel without a single word: two bidders raising a copper each time, each pretending not to know who the other is. The grunts can't settle that one. The clerk just smiles.",
		"The quietest quarrel in Orgrimmar happens at the auction house: one copper, then another, between two people who will never meet. No grunt has ever had to break it up.",
		"A bidding war at the auction house is the only feud in the city fought entirely in copper and silence.",
	},
	["org.muse.w18.quarrel.012"] = {
		"I'm not taking sides. I'm taking a step back.",
		"Nobody asked me, but you're both wrong. Good day.",
		"Don't look at me. I saw nothing, and I'm leaving.",
	},
	["org.muse.w18.quarrel.013"] = {
		"Here in the Valley of Spirits a Darkspear elder hears a quarrel sitting down, and makes both sides sit as well. Hard to shout from the dust, she told me. She's right; I tried.",
		"Troll quarrels in this valley get heard on the ground. The old woman who settles them won't listen to anyone standing up, and it's remarkable how much smaller an anger gets at that height.",
	},
	["org.muse.w18.quarrel.014"] = {
		"An hour ago those two were nose to nose. Now they're hauling one log between them, still bickering, and neither has dropped his end. Nobody here says sorry; somebody needs a hand.",
		"Two who were quarreling earlier now carry one beam together, trading insults, never once out of step. Orgrimmar doesn't do apologies. It does the next heavy thing.",
		"They were ready to brawl a while ago. Now one is holding a ladder for the other and criticizing his footing. That counts as making up, in these streets.",
	},
	["org.muse.w18.quarrel.015"] = {
		"steps around a pair of orcs closing a quarrel the way it is evidently done here: a long stare, one shove each, and then both turn away satisfied, as if the matter had been signed and sealed.",
		"watches two orcs end a disagreement in three moves: a stare, a shove apiece, and a nod. Whatever the matter was, it has plainly been closed.",
	},
	["org.muse.w18.quarrel.016"] = {
		"Two orcs are bellowing at each other a few paces away. I move off before the grunts arrive: when they come, they look at everyone nearby, and mine is the face they'd stop on.",
		"A quarrel breaks out near me and I'm gone before the first shove. Any grunt sent to settle it would settle on me first.",
	},
	["org.muse.w18.shaman.001"] = {
		"A shaman crouches in the middle of the street and lays a palm flat on the stone, as if listening to someone speak through a floor. Whatever it says, she nods, stands, and walks on.",
		"I watched a shaman kneel and press a hand to the ground between two stalls, head tilted, for as long as it takes to hear a short answer. Then off she went, satisfied.",
	},
	["org.muse.w18.shaman.002"] = {
		"steps aside for a shaman with four carved totems slung from one strap, knocking together at every step like a peddler's pots.",
		"makes room for a shaman whose totems clack against each other on his back, so that he can be heard coming from the far end of the street.",
	},
	["org.muse.w18.shaman.003"] = {
		"The shamans thank the water before they drink it. The peons thank nobody and drink faster. Both seem to stay alive.",
		"Before every sip, one shaman murmurs a word over her waterskin. The grunt next to her just drains his. The water, as far as I can tell, plays no favorites.",
		"Shamans greet their water like a guest at the door. Grunts treat theirs like a ration. Both skins come back empty.",
	},
	["org.muse.w18.shaman.004"] = {
		"The old orcs say the spirits stopped answering when the warlocks rose, and kept their silence for a generation. Every shaman walking these streets is part of the reply, late and hard won.",
		"Once the elements turned their backs on the orcs, the elders tell it, and the shamans had nothing left to listen to. Seeing them on every corner now, it's easy to forget how long that silence lasted.",
	},
	["org.muse.w18.shaman.005"] = {
		"A shaman told me she keeps a pebble from every place she has walked, so that the stone of Orgrimmar won't feel lonely among strangers. Her pouch weighs about as much as a small anvil.",
		"Pebbles from every road she has taken, one each: that's what fills a certain shaman's pouch, to keep the earth company. She asked if I had one to spare. I gave her a bit of Durotar from my boot.",
	},
	["org.muse.w18.shaman.006"] = {
		"The shamans say the rock of this canyon is still restless, still settling after whatever split it open. I feel nothing underfoot. They look at me kindly when I say so, the way you'd look at someone hard of hearing.",
		"Ask a shaman about the canyon and you'll hear that the stone hasn't finished moving. Slowly, she says, slower than anyone lives. I still check the walls on my way past.",
	},
	["org.muse.w18.shaman.007"] = {
		"If the spirits are taking requests, a little shade, please. No? Worth asking.",
		"Spirits of the air, if you're listening: a cool breeze. Anything. I'm not proud.",
		"Earth, fire, water, air. Could one of you sell me a cold drink?",
	},
	["org.muse.w18.shaman.008"] = {
		"The spirits turned their faces from us once, and we earned it. Now there's a shaman at a corner of our own city, talking quietly to the earth like an old friend who has decided to forgive.",
		"We lost the spirits' ear in the old world, through our own folly. Hearing a shaman murmur to the stones of Orgrimmar, I think: they came back. They didn't have to.",
	},
	["org.muse.w18.shaman.009"] = {
		"notices a shaman stop dead in the street, turn her head toward the empty air above the roofs and wait, then walk on as if someone had called a name only she could hear.",
		"sees a passing shaman pause, head cocked toward nothing in particular, and nod once to nobody before going about her business.",
	},
	["org.muse.w18.shaman.010"] = {
		"An orc, a tauren and a troll shaman share a bench and argue about which element is the most stubborn. Each one names the element he works with, and each one sounds proud of it.",
		"Three shamans of three peoples on one bench, debating which of the elements is hardest to deal with. Fire, says one. Earth, says the next. The troll just points at a waterskin and laughs.",
	},
	["org.muse.w18.shaman.011"] = {
		"The water spirits of Durotar, a shaman told me, are few and short-tempered, like anything that has to live here. She speaks to them very politely, and never asks twice.",
		"In a land this dry, the shamans say, the spirits of water are scarce and easily offended. You can hear it in how they address them: the voice they'd use with a rich and touchy aunt.",
	},
	["org.muse.w18.shaman.012"] = {
		"Whose totem is that? It's been staring at me for a while now.",
		"Somebody's left a totem by this wall, and I swear the carved face has moved.",
		"That totem's carved face hasn't blinked once. I'm starting to take it personally.",
	},
	["org.muse.w18.shaman.013"] = {
		"You don't worship a river, one of the shamans corrected me. You learn where it floods, you thank it when it feeds you, and you never build too close.",
		"Worship, a shaman said, is for things that don't answer back. The elements answer back, sometimes rudely. You treat them the way you'd treat a powerful, moody neighbor.",
	},
	["org.muse.w18.shaman.014"] = {
		"spots a shaman calming a wolf that has spooked in the crowd, one palm on its neck and a single low word, until it stands as quiet as a dog by a hearth.",
		"starts as a wolf shies at some noise, then sees a passing shaman lay a hand on it without breaking stride; the animal settles at once, as if reminded of something.",
	},
	["org.muse.w18.shaman.015"] = {
		"A shaman in the crowd shrugs into the shape of a pale ghostly wolf and lopes off toward the gate. Nobody in the street so much as turns a head.",
		"Somebody just turned into a spirit wolf beside the bank and trotted away, and the queue simply closed the gap. Orgrimmar has seen everything twice.",
		"One moment a shaman, the next a gray wolf made of mist, gone between two carts. The goblin she'd been haggling with finishes the price to empty air.",
	},
	["org.muse.w18.shaman.016"] = {
		"steps around a shaman sitting cross-legged in the middle of a busy street, eyes closed, while the crowd parts round her without a single complaint.",
		"edges past a shaman seated in the thick of the traffic with eyes shut and hands open on her knees, the one still point in a street full of elbows.",
	},
	["org.muse.w18.shaman.017"] = {
		"Ask a shaman a quick question and you'll get an answer from the earth. Eventually.",
		"Simple question, I said. The shaman went off to consult a rock. I'll wait.",
	},
	["org.muse.w18.skies.001"] = {
		"Rain, and in a moment every pot, bucket and upturned helmet in the city is out in the street. In Durotar nobody lets a gift like this run away into the dust.",
		"The first drops fall and the peons come running with every vessel they own. By the time the rain stops, half the barrels in the city are full and the rest are being argued over.",
		"It's raining, and Orgrimmar has set out every container it owns like begging bowls. Not a drop that lands in a pot will be wasted.",
	},
	["org.muse.w18.skies.002"] = {
		"When it rains here, every wolf in the city smells of wet wolf. It's the strongest perfume in Kalimdor.",
		"A little rain and the whole city smells of wet wolf. The wolves look as offended by it as I am.",
		"The wolves shake themselves dry in the street, one after another, and everyone within reach gets a share of the rain a second time.",
	},
	["org.muse.w18.skies.003"] = {
		"watches a peon push up a sagging hide awning with a pole to spill the rain off it, and drench the grunt standing just beyond.",
		"spots an awning bulging with rainwater, a pole jabbed up from beneath, and a grunt on the far side receiving the whole of it without a word.",
	},
	["org.muse.w18.skies.004"] = {
		"Rain! Quick, somebody sell me a bucket before the goblins think of it.",
		"Water falling free out of the sky, and not one merchant charging for it. Enjoy it while it lasts.",
	},
	["org.muse.w18.skies.005"] = {
		"In a sandstorm even the stew crunches. I've stopped asking whether it's grit or the cook's idea of texture.",
		"Sand in the air means sand in the bowl. Every mouthful at the stalls comes with a little Durotar in it, free of charge.",
		"The sand gets into everything, and the food is no exception. I chewed my bread just now and it chewed back.",
	},
	["org.muse.w18.skies.006"] = {
		"Sand drifts against every door on the exposed side of the street, and the peons dig them out with the patience of people who know it'll be back before supper.",
		"The doors facing the gusts are half buried already. A peon shovels one clear, leans on the shovel, and watches the sand begin filling it in again.",
		"Every doorstep that faces the open has its own little dune by now. The peons clear them in turn, unhurried, like a chore they were born to.",
	},
	["org.muse.w18.skies.007"] = {
		"shakes out a boot and pours a small red dune onto the street, then reaches for the other boot with resignation.",
		"empties a fistful of sand out of a collar, then out of a sleeve, then gives up and accepts it as part of the outfit.",
	},
	["org.muse.w18.skies.008"] = {
		"With the sand up, the sun over the canyon shrinks to a dull copper coin, and you can look straight at it. The whole city goes the color of an old kettle.",
		"The sand turns the sky over the canyon into thick brown cloth with a pale coin stitched in the middle. Nobody looks up for long.",
	},
	["org.muse.w18.skies.009"] = {
		"A storm over the canyon, and every roof in Orgrimmar has become a common room. Strangers share benches, someone shares a pot, and each crash outside gets a cheer.",
		"Thunder outside, and indoors everyone has become everyone's neighbor. Nothing makes a crowd so polite as having nowhere else to go.",
	},
	["org.muse.w18.skies.010"] = {
		"hears a peon under an awning counting aloud between each flash and its thunder, and the crowd around him falling silent to follow the count.",
		"shelters with a knot of strangers in a doorway while a peon counts the beats between lightning and thunder; at four, everyone groans.",
	},
	["org.muse.w18.skies.011"] = {
		"The storm has got under the hides on every roof, and the whole city flaps like a flock trying to take off. A few huts look quite close to managing it.",
		"Every loose hide on every roof is beating in the storm. For a moment Orgrimmar looks as if it wants to fly, and I'm not sure I'd stop it.",
		"Roof hides cracking like sails, poles groaning, a whole hut leaning into the gusts. If the city ever lifts off, I'd like a seat on it.",
	},
	["org.muse.w18.skies.012"] = {
		"Clear air for once, and every edge in the city is sharp: the spikes, the beams, the far ledges. Orgrimmar looks as if someone had just finished painting it.",
		"On a day this clear the far wall seems close enough to touch, and the city's shadows lie on the ground as crisp as cut leather.",
	},
	["org.muse.w18.skies.013"] = {
		"spreads a washed shirt across a sunny rock and finds it dry, stiff and warm before a single strap has been mended.",
		"lays a damp cloak over a sun-baked ledge, turns to one small task, and turns back to find it dry as a cracker.",
	},
	["org.muse.w18.skies.014"] = {
		"Not a grain of sand in the air. Somebody mark the date.",
		"Clean air, clear sky. Enjoy it, everyone. Durotar's only resting.",
	},
	["org.muse.w18.stable.001"] = {
		"The stable master keeps a ledger of every beast left in his care, sorted by what it eats and whether it bites. Most pages, a stable hand told me, say meat and yes.",
		"Somewhere in the stable there's a book with one column for food and one for teeth. A hunter showed me his own page: under teeth, someone had written, and underlined, mind them.",
	},
	["org.muse.w18.stable.002"] = {
		"One of the cats in the stable lies with its chin on its paws, facing the way out. It isn't asleep. It's waiting for one particular pair of boots, and it ignores every other pair that goes by.",
		"There's a beast in the city stable that does nothing but watch the entrance. The hands say its hunter went off down some long road. It eats, it sleeps, and at every footstep it looks up.",
		"Stabled beasts all do the same thing between meals: they face the door. Whatever else a hunter's animal forgets, it never forgets which way its hunter went.",
	},
	["org.muse.w18.stable.003"] = {
		"The city stable smells of meat, straw, wet hide and swamp. Somebody's left a crocolisk in there, and it's winning.",
		"Whoever stabled a crocolisk in Orgrimmar: the whole stable would like a word. From a distance.",
	},
	["org.muse.w18.stable.004"] = {
		"watches a hunter collect a beast that has been stabled a long while; it turns its back on her in a pointed sulk, holds out for exactly one strip of dried meat, and then won't leave her side.",
		"sees a hunter crouch by a pen, apologizing at length to a boar that refuses to look at him, until a scrap of meat settles the matter.",
	},
	["org.muse.w18.stable.005"] = {
		"Never offer a hunter's cat bread. The look you get back is a whole lecture.",
		"Boars eat anything. Scorpids eat whatever you were about to eat. Cats eat what they please, when they please.",
	},
	["org.muse.w18.stable.006"] = {
		"The hunters say a beast that's left hungry and unhappy for too long will simply walk away one day and not look back. So in the Valley of Honor you see them feed their animals first and eat their own food cold.",
		"A tamed beast isn't owned, a hunter told me. It stays because it chooses to, and the choosing has to be paid for every day in meat and patience.",
		"Watch a hunter come in off the road: the beast eats first, drinks first, has its burrs combed out first. The hunter sits down last, and doesn't complain.",
	},
	["org.muse.w18.stable.007"] = {
		"Whenever a hunter has the beast trainer teach a wolf a new growl, the wolf spends the next hour practicing it on everyone: grunts, peons, posts, its own tail.",
		"Freshly trained beasts are a menace for a day or so. A hunter's boar learned a new trick in the Valley of Honor and has been showing it off to the whole street.",
	},
	["org.muse.w18.stable.008"] = {
		"stands aside with the rest of the street as a hunter hurries past with an injured cat draped over both arms, and nobody says a word until they've gone.",
		"makes way for a hunter carrying a limp, whimpering boar toward the Valley of Honor, and finds the crowd has already parted without being asked.",
	},
	["org.muse.w18.stable.009"] = {
		"Wolves are the least of it in the stable: there's a wind serpent coiled in a pen, crackling faintly whenever someone walks past, and a spider nobody will feed by hand.",
		"Not every beast in the stable has fur. There's a coiled serpent with wings that hums like a pot about to boil, and a spider the stable hands feed with a very long stick.",
	},
	["org.muse.w18.stable.010"] = {
		"At dusk the hunters bring their beasts their meat, and for a while the stable is nothing but crunching, growling and a raptor trying to steal from both sides at once.",
		"Feeding time at dusk: the Valley of Honor goes quiet except for teeth on bone, and the hunters stand about watching their beasts eat with the look of proud cooks.",
		"Dusk is the stable's loudest hour: every beast fed at once, and every one convinced its neighbor got the bigger share.",
	},
	["org.muse.w18.stable.011"] = {
		"That boar's been eyeing my boots for a while. Somebody tell it they're not on the menu.",
		"Whose boar is this? It's sniffing my pack as if it paid for the contents.",
	},
	["org.muse.w18.stable.012"] = {
		"turns to follow a hunter going by with a crab at heel, sidling along behind its master in a perfectly straight line, which for a crab must take enormous concentration.",
		"steps out of the way of a tamed crab scuttling sideways after its hunter, and marvels that it never once loses him in the crowd.",
	},
	["org.muse.w18.stable.013"] = {
		"watches the stable hands throw hides over the beasts' pens as the sand starts to blow, while something underneath snarls at the dark it has been given.",
		"hears the stabled animals grow restless as sand hisses down the valley, and sees their keepers go from pen to pen with cloths and low, steady words.",
	},
	["org.muse.w18.stable.014"] = {
		"The stable hands say there's a wolf in the stable whose hunter never came back for it. It's been fed every day since. Nobody has the heart to give it away, and nobody else could make it go.",
		"Some beasts in the stable are waiting for someone who won't come back. The keepers know which. They feed those ones first, and talk to them a little longer.",
	},
	["org.muse.w18.stable.015"] = {
		"Walk through the stable and you walk through half of Kalimdor: a raptor from the Barrens, a cat from Ashenvale, a scorpid caught just outside the gate, all fed from the same bucket.",
		"The stable is a map you can smell. Barrens raptor, Ashenvale cat, Durotar scorpid, each in its own pen and all of them complaining in the same direction.",
	},
	["org.muse.w18.stable.016"] = {
		"holds out a hand, palm down, to a hunter's wolf waiting by a doorway, and is sniffed, judged and dismissed with one bored huff.",
		"crouches to let a hunter's cat inspect an outstretched hand; the cat considers it at length and then sits on {g:his|her} boot, which seems to be a yes.",
	},
	["org.muse.w18.stable.017"] = {
		"Stabling a raptor? Warn the stable hands. Then warn them louder.",
		"Somebody's raptor ate a stable hand's glove. Just the glove, the stable hand insists.",
	},
	["org.muse.w18.still.001"] = {
		"The eyebrows tell you how long an alchemist's apprentice has been at the bench. None at all means a year at least, and a promotion coming.",
		"An apprentice alchemist with both eyebrows is either very careful or hasn't been at it long. The masters trust the singed ones more.",
	},
	["org.muse.w18.still.002"] = {
		"watches an herbalist sort a heap of leaves into three piles with eyes shut, lifting each sprig to the nose before tossing it left, right or into the middle.",
		"stops beside an herbalist sorting her harvest by smell alone, eyes closed, as calm as someone counting coin she trusts.",
	},
	["org.muse.w18.still.003"] = {
		"The herbalists come in from the hills with sacks of earthroot still crusted in red soil, and the alchemists insist on knocking a copper off for the dirt. The herbalists insist the dirt is half the medicine.",
		"Earthroot arrives in the city with a good piece of Durotar still clinging to it. Every sale begins with an argument over how much of the weight is root.",
	},
	["org.muse.w18.still.004"] = {
		"If it bubbles, I don't drink it. If it doesn't bubble, I worry.",
		"Bubbling's bad. Not bubbling's worse. That's alchemy, as far as I understand it.",
		"Smells like medicine. Tastes like a dare.",
	},
	["org.muse.w18.still.005"] = {
		"Empty vials are worth coin in this city. Bring a stoppered one back to the alchemist and she knocks a copper off the next, after checking the stopper.",
		"Glass is dear in Durotar, so the potion shops buy back their own empties. I've seen a goblin gathering them off the street like crumbs.",
		"An alchemist counted my empty vials back into her crate one by one, holding each up to the light for cracks, as tenderly as eggs.",
	},
	["org.muse.w18.still.006"] = {
		"A Forsaken apothecary and a troll alchemist are comparing notes in low voices, each pretending not to write down a word the other says.",
		"Two alchemists of two very different peoples share a bench, one long dead and one heavily tusked, and both keep sneaking glances at the other's notes.",
	},
	["org.muse.w18.still.007"] = {
		"A crack of thunder over the rim, and every shelf in every potion shop rattles together. Somewhere an alchemist is propping one up with both arms and cursing the weather.",
		"A thunderclap, and from every doorway of the potion sellers comes the same sound: glass clinking, then a long, careful silence.",
	},
	["org.muse.w18.still.008"] = {
		"steps into the close air of a potion shop, where something sweet and something rotten are fighting over the same nose, and neither is winning.",
		"ducks under the low lintel of an alchemist's shop into a warm reek of steam and strange smells, and stands blinking until the eyes stop watering.",
	},
	["org.muse.w18.still.009"] = {
		"No herbalist ever tells you where she picked it. Ask, and a hill she climbs every week suddenly slips her memory.",
		"The best patch of silverleaf for leagues around is a secret kept by one herbalist in this city, and she'd sooner sell her own boots than share it.",
	},
	["org.muse.w18.still.010"] = {
		"Whoever's brewing on this stretch of the Drag, I'd like a word about the smell.",
		"Something along this part of the Drag smells like a boot boiled in honey. I hope it's medicine. I hope it's not for me.",
	},
	["org.muse.w18.still.011"] = {
		"An old troll stands at an alchemist's stall reading the labels and clicking her tongue. The Darkspear were brewing from these roots long before anyone wrote the recipes down, and she doesn't care who knows it.",
		"The alchemist has written the herb's name on the jar. The troll beside me has another name for it, an older one, and three uses the alchemist never heard of.",
		"A troll elder bought a jar from an alchemist, sniffed it, and handed half of it back with instructions.",
	},
	["org.muse.w18.still.012"] = {
		"One alchemist told me she will sell anything but a draught that glows green. Her grandmother's generation drank something green once, she said, and a whole people paid for it.",
		"Nothing green on an orc alchemist's shelves. It isn't a law; nobody had to make it one. The old ones remember what the last green drink cost.",
	},
	["org.muse.w18.still.013"] = {
		"steps around an apprentice grinding something in a stone mortar so fiercely that the pestle squeaks, until the master, without looking up, growls at the youngster to go gently.",
		"lingers by a workbench where an apprentice pounds dried leaves in a mortar as if they owed money, until a sharp word from the back of the shop slows the pestle.",
	},
	["org.muse.w18.still.014"] = {
		"You can pick an alchemist out of a crowd with your eyes shut. The smell walks a pace ahead of her, like a herald.",
		"Alchemists wear their work the way tanners do, on the air around them. One passed me just now trailing sulfur, anise and something singed.",
	},
	["org.muse.w18.still.015"] = {
		"Every grunt on the wall carries a red bottle from one of these shops. The Horde runs on stew, iron and stoppered glass.",
		"Our grunts march out with healing draughts clinking at their belts, every one of them mixed by somebody in this city who will never see the fight it's for.",
	},
	["org.muse.w18.still.016"] = {
		"The herbalists measure the seasons by what comes in through the gate: a fat one for peacebloom, a lean one for earthroot. They talk about weeds the way farmers elsewhere talk about grain.",
		"Ask an herbalist how the year is going and she'll answer in leaves: plenty of the common stuff, not a sprig of anything worth more.",
	},
	["org.muse.w18.still.017"] = {
		"Is it medicine if it tastes this bad? The alchemist says that's how you know.",
		"Worst thing I've ever tasted. The alchemist looked delighted.",
	},
	["org.muse.w18.stranger.001"] = {
		"The grunts at the gate look at your boots before your face. Red dust means Durotar, yellow means the Barrens, mud means somewhere they'd like to hear about.",
		"From the boots up: that's how one grunt told me he reads travelers. The color of the dust, the wear on the heel, what's caked in the seams. The face, he says, is the last thing to tell the truth.",
	},
	["org.muse.w18.stranger.002"] = {
		"Ask too many questions in this city and you gain a companion: a grunt, a few paces behind, interested in every answer you get.",
		"I watched a traveler ask one question too many at the bank. When he left, a grunt left too, at a polite distance, admiring the same stalls.",
		"Curiosity is free in Orgrimmar, but too much of it comes with an escort.",
	},
	["org.muse.w18.stranger.003"] = {
		"To hear the gate grunts tell it, they once found a gnome in a crate off the zeppelin, packed in straw, with a notebook full of drawings of the walls. Every version ends with the gnome asking for his notebook back.",
		"There's a story every grunt loves: a gnome smuggled in among the cargo, caught sketching the main gate. In some tellings he's sent home in the same crate. In others he's still asking about his drawings.",
	},
	["org.muse.w18.stranger.004"] = {
		"Behind me a grunt has stopped walking. I can hear the silence where his boots were, and I don't turn round.",
		"A pair of boots behind me has gone quiet. A grunt, standing still, watching. I keep my pace exactly as it was, which takes everything I have.",
		"Footsteps behind me stop. I don't look back. Looking back is how they decide.",
	},
	["org.muse.w18.stranger.005"] = {
		"notices one grunt's eyes follow a hooded traveler across the street, and a second grunt pick the traveler up exactly where the first lets go, like a parcel passed hand to hand.",
		"tracks a stranger in a deep hood across the crowd, under a relay of stares, each grunt handing the watching on to the next without a word or a gesture.",
	},
	["org.muse.w18.stranger.006"] = {
		"Every hood in Orgrimmar earns a second look from the grunts, which must be wearing for the Forsaken, who have good reasons to keep theirs up.",
		"Anyone in a hood gets eyed as a possible spy. Half the Forsaken in the city wear one, so half the Forsaken in the city spend their visit being politely suspected.",
	},
	["org.muse.w18.stranger.007"] = {
		"Every grunt in Orgrimmar carries a list in his head that's never been written: the faces that don't belong, the questions nobody should be asking. I wonder which page I'm on.",
		"A capital at war keeps one record nobody can steal, because it's kept behind the grunts' eyes: who came in, who asked what, who lingered too long by the walls.",
		"Nobody in this city writes down who comes and goes. The grunts don't need to; they remember, and compare faces at the change of watch.",
	},
	["org.muse.w18.stranger.008"] = {
		"notices a little band of children trailing a cloaked stranger at a careful distance, then running to tell a grunt every turn the stranger takes; the grunt nods gravely at each report.",
		"watches three small orcs shadow an unfamiliar traveler through the crowd, ducking behind barrels, and report solemnly to the nearest grunt, who thanks them as if they were scouts.",
		"spots two small trolls guarding an unfamiliar traveler from a careful distance, and the grunt nearby gravely receiving their whispered reports.",
	},
	["org.muse.w18.stranger.009"] = {
		"No grunt stops me. They just remember me: I can watch it happen, a face being filed away somewhere behind the eyes, to be taken out later if needed.",
		"Not one grunt has laid a hand on me. Worse: each one looks once, carefully, the way a merchant memorizes a coin he suspects is false.",
	},
	["org.muse.w18.stranger.010"] = {
		"I'm only browsing, grunt. Very innocently. You can look at someone else now.",
		"Whatever it looks like I'm doing, I'm not. Promise.",
		"Just admiring the stalls, grunt. Purely admiring. No need to admire me back.",
	},
	["org.muse.w18.stranger.011"] = {
		"An Alliance spy in the crowd at any hour: the grunts take it for granted. They don't turn the city over looking. Let him count the axes, one told me, and carry the number home.",
		"An Alliance spy in Orgrimmar? Surely, says the grunt at the post, more than one. He seems untroubled. Whatever they report about these walls can only help keep the humans at home.",
	},
	["org.muse.w18.stranger.012"] = {
		"overhears a grunt by the bank ask an unfamiliar traveler a simple question in Orcish, and listen less to the answer than to the accent.",
		"hears a grunt near the bank put an idle question to a stranger, something about the road from Razor Hill, and sees him weigh the accent of the reply far more than its words.",
	},
	["org.muse.w18.stranger.013"] = {
		"Orgrimmar keeps two watches: one on the walls facing Durotar, and one in the streets facing everyone else. The second is quieter and, I suspect, much bigger.",
		"The walls watch the red country outside. The grunts in the streets watch whoever's inside. Of the two, the walls are easier to fool.",
		"The real wall of Orgrimmar walks about in boots and remembers faces.",
	},
	["org.muse.w18.stranger.014"] = {
		"Rule one in Orgrimmar: look like you know where you're going. The grunts only watch the lost.",
		"Want to go unnoticed here? Never ask the way. Walk as if you'd built the road.",
		"Look lost here and you'll have a grunt for company. Look busy and you'll have peace.",
	},
	["org.muse.w18.tauren.001"] = {
		"spends a while watching a tauren braid a string of beads into a friend's mane on a bench, his great fingers slow and exact, while the friend dozes.",
		"lingers by two tauren on a low wall, one plaiting the other's mane with wooden beads, neither of them saying anything for a long while.",
	},
	["org.muse.w18.tauren.002"] = {
		"A tauren sits on a step rubbing salve into a cracked hoof. Mulgore's grass is soft underfoot; this canyon's stone is not, and the plains folk feel every ramp of it.",
		"The stone of Orgrimmar is hard on hooves, a tauren trader told me, and showed me the chips to prove it. He walks the city like someone crossing a river on bad stepping-stones.",
	},
	["org.muse.w18.tauren.003"] = {
		"That joke the tauren made was so quiet and so dry that the orc beside him only got it halfway down the street. I heard the laugh from the bank.",
		"That tauren by the stall said something with a perfectly straight face, and it took the goblin a full minute to start howling.",
		"Tauren jokes are slow to arrive and impossible to forget.",
	},
	["org.muse.w18.tauren.004"] = {
		"Tufts of tauren fur drift along the street like thistledown. In this dry heat they shed, a tauren told me, a little embarrassed, and I said nothing about the patch on my cloak.",
		"The tauren lose their fur in the heat, a bit at a time, and the gutters gather it in soft brown drifts. Surely a goblin is trying to sell it somewhere.",
	},
	["org.muse.w18.tauren.005"] = {
		"notices a tauren's ears turning at every shout from the stalls, left, right, back the other way, until by the end of the street they droop with fatigue.",
		"follows the ears of a passing tauren as they flick toward each new noise of the market, like a pair of guards who cannot agree on the threat.",
		"sees a tauren's ears fold flat as a drum starts up somewhere close by.",
	},
	["org.muse.w18.tauren.006"] = {
		"Orgrimmar's benches were made for orcs. The tauren simply sit on the ground beside them, and still look down on whoever took the bench.",
		"No tauren I've seen trusts an orc bench with the whole of his weight. They settle on the ground instead, and somehow the ground looks honored.",
		"The tauren sit on the ground and somehow still have the best seat.",
	},
	["org.muse.w18.tauren.007"] = {
		"When a tauren greets someone shorter, she lowers her head with great care, minding the horns. At that angle, a polite nod could start a misunderstanding.",
		"There's an art to a tauren's bow in a crowded street: deep enough to be courteous, not so deep that the horns take somebody's hat off.",
	},
	["org.muse.w18.tauren.008"] = {
		"glances up at a tauren calf riding high on its father's shoulders, a horn in each fist like reins, steering him toward every stall that smells of sugar.",
		"steps aside for a tauren with a calf perched on top of him, both small hands clamped on his horns and both small heels drumming.",
	},
	["org.muse.w18.tauren.009"] = {
		"Iron pots by the stack, bound for Mulgore: a tauren is buying them, and tests every one by knocking a knuckle on the rim and listening, ear bent close, as if the pot might confess.",
		"Iron is scarce on the plains, a tauren told me, so when she comes to Orgrimmar she buys for half her village. Every pot gets knocked and listened to before it goes on the kodo.",
	},
	["org.muse.w18.tauren.010"] = {
		"Here in the Valley of Wisdom a tauren is teaching two orc children a game played with pebbles in rows scratched into the dust. She lets them win the first round, and only the first.",
		"Pebbles in scratched rows, an old tauren and three small orcs bent over them: a plains game, carried across the Barrens and set down in this valley. The children are losing loudly.",
	},
	["org.muse.w18.tauren.011"] = {
		"Pardon me. No, after you. After you, I insist. You're the size of the road anyway.",
		"Go ahead, I'll wait. There isn't room for both of us and the kodo you're towing.",
		"After you. I'm not arguing with a wall that has horns.",
	},
	["org.muse.w18.tauren.012"] = {
		"A tauren sits against a wall playing a long, low tune on a wooden flute. It's a plains melody, slow as a herd crossing, and the grunts walking past fall into step with it without noticing.",
		"Somewhere under the clatter a tauren flute is playing, all long notes and no hurry. The tune doesn't belong to this canyon, and the canyon listens to it anyway.",
	},
	["org.muse.w18.tauren.013"] = {
		"keeps an eye on a tauren at a stall as he lifts a mug that would be a bucket in an orc's hands, empties it in three long pulls, and sets it down for another.",
		"notes that the cups sold along the street come in two sizes, ordinary and tauren, and that the second is always selling out.",
	},
	["org.muse.w18.tauren.014"] = {
		"Rain, and the tauren in the street stop where they stand and turn their faces up. For a moment the whole canyon smells of wet fur, and of Mulgore.",
		"The rain sends orcs under the awnings and brings the tauren out from under them. A big bull by the bank is standing in it with his eyes closed, ears dripping, perfectly content.",
	},
	["org.muse.w18.tauren.015"] = {
		"Slowly and very correctly, a tauren trader speaks Orcish, like someone carrying a full bowl across a room. Then a grunt answers in street slang, and the bowl goes everywhere.",
		"The tauren in the market speak Orcish with care, every word set down whole. The orcs answer in grunts and half-words, and the tauren nod, patient, translating in their heads.",
	},
	["org.muse.w18.tauren.016"] = {
		"That tauren just asked if he might pass. Asked! I didn't know those words still worked in this city.",
		"May I pass, says the tauren. Nobody in Orgrimmar has asked me that before.",
		"Somebody just said excuse me and waited for an answer. A tauren, naturally.",
	},
	["org.muse.w18.thread.001"] = {
		"Half the linen in this city came off the backs of bandits and kobolds, by way of some traveler's bags. A tailor told me she never asks where the cloth has been. She just washes it twice.",
		"Ask a tailor where her linen comes from and she'll look at your bags. Every traveler in Orgrimmar is a cloth merchant without knowing it.",
		"The tailors buy their linen off travelers by the armful, no questions asked. The questions would only spoil the shirt.",
	},
	["org.muse.w18.thread.002"] = {
		"watches a tailor finish a seam and bite the thread off rather than reach for the knife a hand's width away.",
		"notices that the tailor never uses shears for the last thread: a quick snap of the teeth, and the shirt is folded and sold.",
	},
	["org.muse.w18.thread.003"] = {
		"The older tailors still keep bone needles they carved themselves. Iron ones are better, they'll admit, and then go on using the bone.",
		"A tailor showed me a needle of yellowed bone, its eye drilled by hand. She has iron ones in a drawer. The bone one is the one her fingers find.",
		"Ask an old tailor about her bone needle and she'll tell you which beast it came from, and what that beast once did to her uncle.",
	},
	["org.muse.w18.thread.004"] = {
		"Red is the cheapest dye in Orgrimmar. Nobody can tell me why, though everyone I ask glances at the walls.",
		"A dyer told me red costs her almost nothing here. Black, blue, a decent green: those she pays for. Red, she says, gets into the vat whether she wants it or not.",
		"Everything dyed in this city drifts toward red in the end. The dyers just call it the canyon's share.",
	},
	["org.muse.w18.thread.005"] = {
		"Patch it, the tailor said. Then she charged me for a new one.",
		"That tailor looked at my cloak and offered her condolences.",
		"Mend it or bury it? The tailor is still deciding.",
	},
	["org.muse.w18.thread.006"] = {
		"On a tailor's back wall hang the patterns, cut from old hide and worn soft at the edges: the broad tauren yoke, the long troll sleeve, the narrow Forsaken coat, and a goblin cut that seems to be mostly pockets.",
		"A tailor in this city needs a pattern for every shape of body that walks in. Hers hang on pegs by size, from the goblin's to the tauren's, and the tauren's takes up a wall of its own.",
	},
	["org.muse.w18.thread.007"] = {
		"lingers beside a doorway of the Drag where a spinner twists wool into yarn, the spindle dropping almost to the dust and climbing back up her thread, round after round.",
		"pauses to watch a spindle twirl down from a spinner's fingers on its lengthening yarn, nearly touching the street of the Drag before she winds it up.",
	},
	["org.muse.w18.thread.008"] = {
		"Some of the cloth on the tailors' tables hums faintly under the fingertips. Mage-spun, the tailor says, and moves my hand away before I can touch it twice.",
		"There's a bolt of mageweave on a tailor's shelf that seems to shimmer whenever nobody looks at it straight. She charges extra for that, I suspect.",
		"A tailor swears the mage-spun cloth on her shelf keeps itself warm and never tears. She said the second part looking hard at my sleeves.",
	},
	["org.muse.w18.thread.009"] = {
		"With sand in the air the tailors cover every bolt and work by touch under their awnings. A grain of grit sewn into a seam will chafe somebody for a month, and they know who'll get the blame.",
		"Sand on the wind, and the tailors fold their cloth away as fast as a merchant hides coin. Grit in linen is the one thing no needle can mend.",
	},
	["org.muse.w18.thread.010"] = {
		"Spider silk comes in from the hunters in grubby gray wads. The tailors pick the dead flies out of it, then price it as if a queen had spun it.",
		"A hunter sold a tailor a tangle of spider silk with half a beetle still in it. She paid him a pittance, cleaned it, and set it on her table for ten times as much.",
		"Spider silk is the only goods in Orgrimmar sold with a reassurance: the spider is no longer attached.",
	},
	["org.muse.w18.thread.011"] = {
		"Linen too ragged for the tailors goes to whoever rolls bandages. In this city no thread is ever finished being useful: shirt, then rag, then the thing that keeps a grunt standing.",
		"The tailors sell their worst scraps to the healers by the sack. A shirt that failed as a shirt can still hold someone together.",
	},
	["org.muse.w18.thread.012"] = {
		"The tailor asked whether I wanted it fashionable or durable. In Orgrimmar, apparently, you can't have both.",
		"Fashionable or durable, the tailor asks. I asked which one stops an axe. She sighed.",
		"Fashion in Orgrimmar means the spikes match.",
	},
	["org.muse.w18.thread.013"] = {
		"has a dangling thread snipped from {g:his|her} cloak by a tailor's apprentice who darts out of a doorway, mutters something about bad advertising, and darts back in.",
		"finds a tailor's apprentice plucking at a loose thread on {g:his|her} sleeve in passing; a quick snip, a disapproving look, and the youngster is gone.",
	},
	["org.muse.w18.thread.014"] = {
		"Every banner on these walls was hemmed by somebody squinting at a needle. Our colors are mostly patience.",
		"The Horde's tabards don't sew themselves. In some workshop of this city a tailor with tired eyes made every one I've seen, and nobody has ever cheered her.",
	},
	["org.muse.w18.thread.015"] = {
		"Of all the trades in this loud city, the tailor's makes the least noise: the hiss of thread drawn through cloth, the tick of a thimble, a curse now and then when the needle finds a finger.",
		"Step into a tailor's doorway and the city drops half a tone. Nothing in there clangs. Thread hisses, shears whisper, and somebody hums over the work.",
	},
	["org.muse.w18.thread.016"] = {
		"In the Drag a shirt costs two copper and a bit of charm. I'm short on the charm.",
		"Here in the Drag even the tailors haggle like smiths. I offered fair coin and got a lecture on linen.",
	},
	["org.muse.w18.throne.001"] = {
		"Messengers come out of Grommash Hold at every pace there is, and the grunts read them like a sky. A walk is trade. A trot is trouble on some road. A dead run, and every grunt in the valley goes quiet.",
		"You can tell the news by the runner. Out of the Hold at a stroll: a matter of salt and nails. Out at a sprint: somebody, somewhere, is about to have a very bad season.",
		"Watch the door of the Warchief's hall long enough and you learn to read the messengers' feet. The faster they leave, the less anyone nearby wants to ask why.",
	},
	["org.muse.w18.throne.002"] = {
		"passes a Forsaken envoy waiting outside Grommash Hold with a sealed letter, perfectly still; of everyone in the line, the Kor'kron watch that one the longest.",
		"notices a hooded Forsaken standing by the steps of the Warchief's hall with a letter held in both gray hands, so motionless that a fly has settled on the seal.",
	},
	["org.muse.w18.throne.003"] = {
		"Saw a goblin go into the Warchief's hall with a contract longer than the queue. Thrall has my sympathy.",
		"That goblin's scroll was still unrolling down the steps of the Hold when he reached the top. Whatever he wants, he wants all of it.",
	},
	["org.muse.w18.throne.004"] = {
		"From the open door of the Hold comes a low rumble of many voices, then one voice alone, then nothing at all. Whoever spoke last, everyone inside is thinking about it.",
		"A murmur rolls out of Grommash Hold, breaks off, and a single deep voice fills the gap. When it stops, the silence that follows is the loudest thing in this valley.",
		"Every so often the noise inside Grommash Hold drops all at once, as if a hand had been raised. Out in the valley people fall quiet too, without knowing why.",
	},
	["org.muse.w18.throne.005"] = {
		"A peon in the Valley of Wisdom swears his whole job is brushing the dust off the Kor'kron's shoulders. They never thank him. They never move, either, which he says makes it easy work.",
		"The Kor'kron stand so still that the dust settles on them like on furniture, a peon told me, and someone has to go round with a brush. He seemed proud to be that someone.",
	},
	["org.muse.w18.throne.006"] = {
		"passes a row of saddled wolves lying outside the Warchief's hall, each with its head turned toward the door, waiting for its own rider to come out.",
		"walks by the wolves left at the foot of Grommash Hold by whoever is inside; not one of them sleeps, and every ear swivels at each footstep on the threshold.",
		"steps carefully between the wolves waiting at the door of the Hold, and is followed by a dozen yellow eyes that soon decide {g:he|she} is nobody's master.",
	},
	["org.muse.w18.throne.007"] = {
		"A grunt by the door told me the Hold was raised so that a voice from the throne carries to the threshold without being lifted. I believe it. Even the coughs back here sound like they were meant for me.",
		"This hall was raised, a guard claims, so the Warchief need never shout. Standing at the back, I can hear a Kor'kron's armor settle beside the throne, and I'm careful what I mutter.",
	},
	["org.muse.w18.throne.008"] = {
		"Every time I pass the Hold there's someone on its steps muttering a petition over and over. By the tenth time it's shorter. By the twentieth it's polite. By the time they're called, it's usually good.",
		"There's always someone on the steps of the Warchief's hall rehearsing a grievance aloud. The first version usually has three insults in it. The one they go in with has none, and is better for it.",
	},
	["org.muse.w18.throne.009"] = {
		"A grunt who has stood guard inside swears the Warchief laughs, now and then, when the last petitioner has gone. Nobody outside would guess it, and the grunt says that's on purpose.",
		"Thrall laughs, I'm told. Not often, and never in front of the line at the door. It's a comfort to know it happens somewhere in that hall.",
		"Somebody heard the Warchief laugh once, the grunts swear, at a goblin's petition. The goblin, they add, tried to charge him for it.",
	},
	["org.muse.w18.throne.010"] = {
		"If the Warchief ever runs short of opinions, I've got plenty. Strangely, nobody's sent for them.",
		"Thrall could use an adviser with no experience and very firm views. I'm free most days.",
		"Somebody tell the Hold I'm available for advice. Cheap. Possibly wrong.",
	},
	["org.muse.w18.throne.011"] = {
		"watches the petitioners turn away from the throne one after another and reads them as they pass: one relieved, one furious, one counting something on his fingers all the way to the door.",
		"steps aside for those coming back from the throne, and finds that every face says how it went before any word does: a lifted chin, a tight jaw, a dazed half smile.",
	},
	["org.muse.w18.throne.012"] = {
		"The Warchief's door is open to any of us. I'd like, one day, to walk through it with something worth his time, and not just a sore back and a question.",
		"Anyone in the Horde can walk up to that hall and be heard. It makes me want to have something worth saying when my turn comes at the door.",
	},
	["org.muse.w18.throne.013"] = {
		"Somewhere at the far end of this city the Warchief of the Horde sits on his throne, and I'm walking his streets buying bread. Nobody I know would believe it.",
		"The Horde's Warchief holds court a few valleys from where I stand. His soldiers would gladly see me gone; his merchants gladly take my coin. The world is stranger than the war lets on.",
	},
	["org.muse.w18.throne.014"] = {
		"At night, long after the Drag has shuttered, a light still burns in Grommash Hold. Someone in there is still being heard, or still listening.",
		"Night over the canyon, most fires banked, and the Warchief's hall still lit at the head of its valley. Somebody's grievance was too long for daylight.",
	},
	["org.muse.w18.throne.015"] = {
		"Shoulders back, chin up, and whatever happens, don't trip on the way to the throne.",
		"Long walk to that throne. Every Kor'kron's watching my feet. Lovely.",
	},
	["org.muse.w18.throne.016"] = {
		"From the door, the throne at the end of Grommash Hold looks small. I wonder how the door looks from the throne: a bright square that never stops letting in trouble.",
		"Seen from the threshold the Warchief's seat is a long way off and not very big. From the seat, I suspect, the door is the largest thing in the world.",
	},
	["org.muse.w18.throne.017"] = {
		"makes way for two tauren carrying a long bundle of painted hide up toward the Hold between them, as carefully as a sleeping calf.",
		"stands aside as a pair of tauren bear a rolled hide up the slope to the Warchief's hall, slow and in step, as if it weighed more than it looks.",
	},
	["org.muse.w18.throne.018"] = {
		"holds quite still as a Kor'kron's gaze travels across the hall, rests a moment, and moves on, and only then realizes how still {g:he|she} had become.",
		"feels the look of the nearest Kor'kron settle and lift again like a hand on the shoulder, and lets {g:his|her} shoulders drop only afterward.",
	},
	["org.muse.w18.throne.019"] = {
		"Taking a petition to the Hold? Make it short. The Kor'kron count every word, and they dislike large numbers.",
		"Going up to see the Warchief? Practice it on me first. I'll frown like a Kor'kron.",
	},
	["org.muse.w18.tools.001"] = {
		"Something went bang in an engineer's workshop. The goblin came out in a cloud of smoke, counted his fingers, got ten, and went straight back in.",
		"A dull boom from somebody's workbench, a puff of black smoke from the door, and then a goblin voice shouting that it was supposed to do that.",
	},
	["org.muse.w18.tools.002"] = {
		"watches an apprentice sweep a workshop floor while the master lectures a customer, the youngster's lips shaping every word a moment ahead.",
		"notices a crafter's apprentice silently mouthing along with the master's sales talk, word for word, broom moving the whole time.",
	},
	["org.muse.w18.tools.003"] = {
		"An apprentice in this city spends the first year carrying, the second fetching, and only in the third is trusted to break something expensive.",
		"Every crafter I've asked describes the same ladder: carry, fetch, sweep, watch, and only then touch. By the time an apprentice holds the hammer, the arms are already a smith's.",
	},
	["org.muse.w18.tools.004"] = {
		"Engineers. If it whistles, it's working. If it stops whistling, run.",
		"Rule for walking past an engineer's bench: whistling's fine. Silence means duck.",
		"If the goblin's still smiling, it's safe. Probably.",
	},
	["org.muse.w18.tools.005"] = {
		"Borrow a tool from a crafter here and you'll be asked for it back before you've worked out which end to hold.",
		"The crafters lend tools the way wolves lend bones: with a long look, and every intention of having it back before you've gone two steps.",
	},
	["org.muse.w18.tools.006"] = {
		"On many a workshop wall hangs a crooked first piece: a lopsided buckle, a boot that never matched its twin. Nobody sells the first one. It stays up to keep the master humble.",
		"A leatherworker showed me the first strap she ever cut, nailed above her bench, uneven as a goat track. She says she looks at it whenever a customer calls her the best.",
		"The crafters of this city all keep their worst work somewhere in sight: the first one, the ugly one. It does more for a swelled head than any trainer.",
	},
	["org.muse.w18.tools.007"] = {
		"squeezes against a wall of the Drag as a handcart of planks, ingots and rolled hides grinds uphill, a peon straining at the shafts and a goblin perched on top giving directions.",
		"makes room for a cart loaded with copper bars and bundled leather crawling up the Drag, pulled by one muttering peon and steered by a goblin who does nothing else.",
	},
	["org.muse.w18.tools.008"] = {
		"Engineers wear their goggles pushed up on the forehead, a second pair of eyes that always look surprised.",
		"You can tell an engineer by the goggles: up on the brow while talking, down over the eyes when something is about to happen, and halfway when nobody's sure.",
	},
	["org.muse.w18.tools.009"] = {
		"Blasting powder is sold by the little pouch, from behind a counter, and never to anyone with a pipe in his mouth.",
		"The engineer selling blasting powder made me put out the torch before he'd even name a price. Then he lit a cigar.",
		"One goblin sells blasting powder under a little painted sign: no fire, no smoking, no refunds.",
	},
	["org.muse.w18.tools.010"] = {
		"Look up at the ledges and there's a second city at work: cloth laid out to bleach, hides pegged flat to stiffen, rows of pots set out to bake hard.",
		"Every ledge in sight is somebody's workbench. Leather stiffening, cloth whitening, clay drying, and a peon walking among it all like a farmer between rows.",
	},
	["org.muse.w18.tools.011"] = {
		"Goblin engineering, a goblin explained to me with real pride, is the art of making a thing go faster than it ought to and then selling the pieces.",
		"The goblins have a saying about their engineering, or so one of them told me: if it didn't explode, you didn't put enough in.",
	},
	["org.muse.w18.tools.012"] = {
		"catches a trainer taking a crooked piece of work from an apprentice, turning it over once and handing it back without a word; the apprentice goes straight back to the bench.",
		"sees a master pick up an apprentice's work, tap it twice against the bench, listen, and set it on the scrap pile, while the youngster only nods.",
	},
	["org.muse.w18.tools.013"] = {
		"Somebody in this city makes the tools that make the tools. I'd like to meet that one and shake a very calloused hand.",
		"Hammers to make tongs, tongs to hold hammers. Who made the first one? Nobody here will say.",
	},
	["org.muse.w18.tools.014"] = {
		"The crafters keep a quiet economy of favors that no coin ever touches. The smith mends the tanner's knives, the tanner makes the smith's apron, and the tailor patches both their sleeves and calls it even.",
		"A tanner told me she hasn't paid a smith in years. She keeps him in aprons; he keeps her knives keen. Neither of them has ever written it down.",
	},
	["org.muse.w18.tools.015"] = {
		"A trainer here will sell you the recipe for a few silver. The knack isn't for sale; that you steal with your eyes, from across the workshop, month after month.",
		"Every crafter says the same thing: the trainer teaches the steps, and the hands learn the rest by stealing from whoever is better.",
	},
	["org.muse.w18.tools.016"] = {
		"pauses at the counter of an engineer's shop where some small device of gears sits ticking, and steps back sharply when the ticking speeds up.",
		"leans in to look at a contraption of springs and copper tubing on a goblin's table, and is waved off with a cheerful warning about fingers.",
	},
	["org.muse.w18.tools.017"] = {
		"Mind the bench. Everything on it is either sharp, hot or somebody's year of work.",
		"Hands off the workbench. Sharp, hot or priceless: you won't guess which until too late.",
	},
	["org.muse.w18.tower.001"] = {
		"looks up at a squabble on the flight tower, two wind riders hissing over the same perch until a handler wedges a pole between them and a third beast takes the spot.",
		"follows a noisy quarrel among the beasts atop the tower, wings half spread and tails raised, settled at last by a handler with a long pole and a short temper.",
	},
	["org.muse.w18.tower.002"] = {
		"There's a patch of ground under the wind rider tower where the locals never linger. The beasts up top have no manners and excellent aim.",
		"Those who know Orgrimmar walk around the foot of the flight tower, never straight under it. The wind riders above aren't fussy about what they let fall.",
		"Anyone who has spent time in this valley takes the same path past the tower: a wide curve, eyes up, no pausing beneath the perches.",
	},
	["org.muse.w18.tower.003"] = {
		"The wind riders up on the tower carry their tails curled high like a scorpion's, and I notice the handlers never once turn their backs on the sting end.",
		"A lion's body, leathery wings and a stinger at the end of the tail: a wind rider looks like three hunts stitched into one beast, and the handlers respect each part separately.",
	},
	["org.muse.w18.tower.004"] = {
		"spots a rider coming down from the flight tower walking like a peon after a double shift, legs bowed, one hand pressed to the small of the back.",
		"steps aside for a traveler just off a wind rider, wobbling down from the tower with the dignity of someone pretending the ground isn't moving.",
		"notes how everyone stepping off the tower does the same little dance: a stretch, a wince, a careful first stride, as if testing whether the valley will hold.",
	},
	["org.muse.w18.tower.005"] = {
		"When the crowd turns me around, I look for the flight tower. It stands over the Valley of Strength like a tent pole, and everything else in the valley hangs off it.",
		"Lost in the press? Find the tower with the beasts on top. From there the bank, the inn and the gate fall back into their places.",
		"The flight tower is the one thing in the valley you can't lose sight of. I steer by it the way sailors steer by a headland.",
	},
	["org.muse.w18.tower.006"] = {
		"A wind rider just came in low over the stalls, and a whole table of dried fish now wears a coat of dust. The fishmonger is shaking a fist at the sky with real feeling.",
		"Every landing at the tower sends a gust down over the nearest stalls. One trader has given up and simply sells everything pre-dusted.",
		"Stallkeepers near the tower cover their goods whenever wings beat close overhead. They've learned the hard way what a landing does to a table of spices.",
	},
	["org.muse.w18.tower.007"] = {
		"tips {g:his|her} head back to watch a handler on the tower coax a reluctant wind rider toward the edge with a haunch of meat and a stream of insults; the beast takes the meat and stays put.",
		"squints up at the flight tower, where a wind rider has planted all four feet and flatly refuses to fly, while its handler pleads and the waiting passenger studies the sky.",
		"watches a stubborn beast on the tower turn its back on a handler, the passenger and the whole open sky, and settle down for a nap instead.",
	},
	["org.muse.w18.tower.008"] = {
		"Close to the flight tower the air smells of musk and old meat. The wind riders are magnificent from a distance, and the distance is half the charm.",
		"The flight tower has a smell all its own: beast, scraps, and something sharp underneath. The handlers stopped noticing it long ago, and the handlers are the only ones.",
	},
	["org.muse.w18.tower.009"] = {
		"Six wind riders on that tower, and every one of them is eyeing me like a snack.",
		"I swear the beasts on the flight tower follow everyone who walks past with their eyes. Hungrily.",
		"Stop staring, you lot up there. I'm all gristle.",
	},
	["org.muse.w18.tower.010"] = {
		"Keep an eye on the canyon rim and sooner or later a wind rider comes over it, low and steady, wings beating slower than when it set out. Somewhere behind it lies the whole width of the Barrens.",
		"The wind riders that come in over the canyon edge fly lower than the ones leaving, wings heavy, making straight for the tower like a tired traveler for the inn.",
	},
	["org.muse.w18.tower.011"] = {
		"In this storm the wind riders on the tower sit hunched, wings clamped tight over their heads, and they go up only when the handlers drag them to the edge.",
		"The beasts on the flight tower hate this storm. They huddle together like wet tents, and every one that takes off does it with a scream of complaint.",
	},
	["org.muse.w18.tower.012"] = {
		"looks up at the flight tower after dark, where torches burn along the perches and the eyes of the resting beasts catch the light, a row of small embers watching the valley.",
		"stops to watch a wind rider drop out of the dark into the torchlight of the tower, all at once, as if the night had let go of it.",
	},
	["org.muse.w18.tower.013"] = {
		"Every beast that lifts off the tower is a message to some post of ours: the Crossroads, Thunder Bluff, Splintertree. Watching them go, I can almost see the whole map of the Horde light up.",
		"Our sky is busy. Wind riders out to the Crossroads, to Thunder Bluff, to the posts in Ashenvale, and in again with news and sore riders. It's a comfort to watch, from the ground.",
	},
	["org.muse.w18.tower.014"] = {
		"pauses beside a cluster of small orcs and trolls counting the wind riders circling the tower, each count louder than the last and no two of them agreeing.",
		"hears a gaggle of children shout out the wind riders overhead one by one, and lose count with a howl when two of them cross.",
	},
	["org.muse.w18.tower.015"] = {
		"Don't give me that look, beast. I'm not your supper and I'm not your passenger.",
		"Easy up there. Just walking past. Nobody's flying you anywhere.",
	},
	["org.muse.w18.tower.016"] = {
		"People who leave by wind rider never get a proper farewell. One moment they're shouting the last thing they forgot to say, the next they're a speck over the canyon wall.",
		"Saying goodbye at the flight tower is a hurried business: a few words, a wave, and then the rest of the sentence is lost somewhere above the walls.",
		"At the foot of the tower somebody is still waving at a dot in the sky, long after the dot has stopped being anyone in particular.",
	},
	["org.muse.w18.trolls.001"] = {
		"A troll can squat on his heels for an hour while he talks, knees up by his ears, as comfortable as a cat. The orc beside him on the bench has shifted six times.",
		"The Darkspear don't need benches. They fold down onto their heels wherever the talk happens to stop, and stay there longer than anyone else stays anywhere.",
		"Down on her heels, a troll can outlast any bench in the city.",
	},
	["org.muse.w18.trolls.002"] = {
		"stops to watch a troll mend a fishing net in a doorway, holding one end taut with her toes and working the knots with both hands.",
		"lingers by a troll fisher who sits on a step with a torn net across his knees, his long fingers closing each hole faster than the eye can follow.",
	},
	["org.muse.w18.trolls.003"] = {
		"Trolls have a way of ending up above everyone else: on a ledge, a stack of crates, a roof beam, long legs dangling. I've stopped being surprised when a voice comes from overhead.",
		"Look up anywhere in this city and there's a troll perched on something nobody built for sitting, watching the street like a show put on for her.",
		"Somewhere above me there's always a troll. I've stopped looking up to check.",
	},
	["org.muse.w18.trolls.004"] = {
		"notices a troll polishing his tusks with a rag and a pinch of ash, slowly and with care, like a smith tending a good edge.",
		"passes a troll who is fitting a new carved ring onto one tusk, turning it by fractions until it sits just right.",
	},
	["org.muse.w18.trolls.005"] = {
		"A troll gashed his hand loading a cart and waved off the healer with a grin. Next time I passed, the cut had nearly closed, and he was showing it to a goblin who wanted to know the price.",
		"Darkspear wounds mend fast, the grunts say, and the trolls do nothing to discourage the rumor. One just looked at a fresh cut on his arm, shrugged, and went back to hauling crates.",
	},
	["org.muse.w18.trolls.006"] = {
		"An old Darkspear spoke to me of the troll empires of long ago, the stone cities and the blood they ran on. He sounded proud of the stones and glad to be rid of the rest.",
		"The elders of the troll valley talk of the old empires the way you'd talk of a rich uncle who did terrible things. Grand, they admit. Better left in the jungle.",
	},
	["org.muse.w18.trolls.007"] = {
		"watches a troll scratch a raptor under the jaw until its eyes half close and one hind claw starts tapping the dust.",
		"stops beside a troll arguing with her raptor over a strip of dried meat, and cannot say for certain which of the two won.",
	},
	["org.muse.w18.trolls.008"] = {
		"Small trolls are practicing their throws at a gourd tied to a post. The gourd has lost every round, and the post isn't doing much better.",
		"A row of troll youngsters takes turns hurling sticks at a painted gourd, while an old one keeps score with notches in the dust. The gourd is in pieces.",
		"That gourd on the post never stood a chance against the troll youngsters.",
	},
	["org.muse.w18.trolls.009"] = {
		"Someone has strung a hammock between two posts of a hut, and in it lies a troll who carried two baskets of fish up from the coast, one foot trailing, rocking gently while the whole city hurries past.",
		"A troll in a hammock between two hut posts, swaying, eyes shut, his empty fish baskets stacked underneath. In a city that never stops, he has found the one motion worth keeping.",
	},
	["org.muse.w18.trolls.010"] = {
		"Here in the Valley of Spirits, strings of shells hang in the hut doorways and clack together whenever someone passes. It's the only sound of the sea in a city of stone.",
		"Shells, carried all the way up from the coast, rattle in the doorways of this valley. The Darkspear brush them as they go in, the way others touch a doorpost.",
	},
	["org.muse.w18.trolls.011"] = {
		"That troll is using my shoulder as an armrest. I'm choosing to take it as a compliment.",
		"Excuse me. That's a shoulder, not a railing. Though you're welcome to it, apparently.",
		"Lean on me, then. I'm only a person.",
	},
	["org.muse.w18.trolls.012"] = {
		"takes in a troll dipping the tips of her hair into a bowl of red dye on a doorstep, while a friend holds the bowl and gives opinions.",
		"pauses by two trolls on a step, one combing bright new color through the other's crest of hair with great concentration and a great deal of advice.",
	},
	["org.muse.w18.trolls.013"] = {
		"A Darkspear telling a story needs both hands and a good part of the street. This one has just shown me a turtle the size of a hut, and three passersby had to walk round it.",
		"When the trolls talk, the hands do half the work. The one by the bank is describing a fight with a crocolisk, and I swear I can see the water splash.",
	},
	["org.muse.w18.trolls.014"] = {
		"Long after the forges bank down for the night, the trolls are still awake in their valley, talking low around the coals. They seem to like the city best when it finally shuts up.",
		"Most of the orcs turn in early. The Darkspear don't: at night their valley murmurs and laughs softly, and a single drum keeps company with the dark.",
	},
	["org.muse.w18.trolls.015"] = {
		"I tried a word of troll on that fisher. She laughed so hard she had to sit down. Apparently I asked for her hand.",
		"One word in the troll tongue, and the whole stall is in fits. I'm told I said something about a frog's mother.",
		"My troll needs work. The fishwife is still wiping her eyes.",
	},
	["org.muse.w18.trolls.016"] = {
		"Slow down! Not all of us have legs that long.",
		"Walking beside a troll is like chasing a cart downhill. I give up.",
		"Two of my steps to one of hers, and she says I'm dawdling.",
	},
	["org.muse.w18.truce.001"] = {
		"When an orc and a troll can't agree, I'm told, they sometimes ask a tauren to judge. Not because tauren are wiser, a grunt says, but because they take so long that both sides cool off waiting.",
		"A tauren is the favorite judge for a quarrel between orc and troll, the grunts say. He listens, nods, considers, considers some more, and by the verdict nobody can remember being angry.",
	},
	["org.muse.w18.truce.002"] = {
		"Every people of ours gave something up to share this city: the trolls their isles, the tauren a wide sky, the orcs the habit of trusting only orcs. I try to keep the list in mind when the crowd gets on my nerves.",
		"Nobody in our Horde came here whole. The Darkspear left their islands, the tauren their open plains, the orcs an entire world. Sharing a street is the smallest thing we ask of each other.",
	},
	["org.muse.w18.truce.003"] = {
		"stops by a troll vendor offering a grunt a taste of something red and glistening; the grunt eats it without blinking, turns a darker green, and buys two more out of pure pride.",
		"sees a troll hold out a skewer of something fiery to an orc, who accepts it as a challenge between peoples, and loses with great dignity.",
		"eyes an orc accepting a troll's offer of something fiery on a stick, chewing, and fighting the whole matter out in silence with streaming eyes.",
	},
	["org.muse.w18.truce.004"] = {
		"Orcs and trolls have been allies long enough to insult each other freely. With the tauren they're still polite. In Orgrimmar, politeness means a friendship that hasn't settled in yet.",
		"An orc will call a troll every rude name he knows and share his supper after. With a tauren he says please. Give it a few more years, I suspect, and the please will go.",
	},
	["org.muse.w18.truce.005"] = {
		"Ask an elder how long the peoples of this city have lived side by side and he counts on his fingers, and doesn't need both hands. A peace that young still has to be fed every day.",
		"The elders handle the peace between the peoples like a new cub: proudly, and never quite at ease, in case it bites or sickens.",
		"The elders speak of the peace between the peoples the way farmers speak of a first harvest: carefully, and not too loudly, in case something hears.",
	},
	["org.muse.w18.truce.006"] = {
		"Truce with Theramore, war in Ashenvale. The grunts hold both at once and see no problem.",
		"Peace on one border, axes on the other. Orgrimmar doesn't find that strange, so why should I?",
		"Peace with Theramore, war in Ashenvale. Busy fellow, the Warchief.",
	},
	["org.muse.w18.truce.007"] = {
		"Three doors in a row on one street: a troll family, an orc smith, a Forsaken who keeps to himself. They share one water barrel and a common dislike of the goblin who rents to all three. That's a treaty, of a kind.",
		"Neighbors here don't need to like each other's customs or cooking. They need to agree on whose turn it is to fill the barrel, and on how much they all resent the landlord.",
	},
	["org.muse.w18.truce.008"] = {
		"Look at that: a troll holding a door for a Forsaken. Somebody write it down.",
		"A tauren just apologized to a goblin. The Warchief ought to hear about this.",
		"An orc and a troll agreeing on a price. Fetch a herald.",
	},
	["org.muse.w18.truce.009"] = {
		"A Darkspear fisherman mends nets every day at the foot of one grunt's post. The troll talks the whole time; the grunt hasn't said a word in an hour. They are plainly the best of friends.",
		"One grunt's post has a troll attached: an aged net-mender who chatters up at him all through the watch. The grunt never answers. He'd miss it badly if it stopped.",
	},
	["org.muse.w18.truce.010"] = {
		"stops to let a small procession by: a tauren elder walking beside an orc chieftain toward the Valley of Wisdom, the two of them in no hurry, the grunts along the way standing a little taller.",
		"makes way for a tauren elder and a Darkspear healer walking together toward the Warchief's hall, deep in talk, while the street parts around them without being asked.",
	},
	["org.muse.w18.truce.011"] = {
		"The goblins swear they belong to no side, and the grunts guard their stalls anyway. Neutral or not, a goblin robbed in Orgrimmar is the Warchief's problem.",
		"Goblins call themselves neutral, and the city takes them at their word only so far: their stalls get the same grunts as anyone's. A neutral purse still needs a wall around it.",
		"A goblin's stall in Orgrimmar gets the same grunt at its corner as an orc's. Neutrality, it turns out, still likes a guard.",
	},
	["org.muse.w18.truce.012"] = {
		"In the Valley of Spirits I once saw an orc shaman, a troll and a tauren sitting at one fire, each calling the spirits by a different name and nodding at the others as if they'd all said the same thing.",
		"Three shamans of three peoples at one fire, each with his own words for the spirits, each hearing out the others with perfect patience. If the Horde has a council that never quarrels, it's that one.",
	},
	["org.muse.w18.truce.013"] = {
		"Four peoples, one Warchief. Hard to believe, harder to break.",
		"Different tusks, different horns, one banner. That's the Horde for you.",
		"Tusks, horns, hoods, one Warchief. Somehow it holds.",
	},
	["org.muse.w18.truce.014"] = {
		"notes a grunt stepping in, quite gently, when a crowd begins to close around a lone Forsaken; a word, a look, and the ring loosens and drifts away.",
		"sees a passing grunt break up the circle of stares tightening round a hooded Forsaken at a stall: he simply stands beside the Forsaken until the onlookers find somewhere else to be.",
	},
	["org.muse.w18.undying.001"] = {
		"notices a Forsaken on a crate stitching a split seam in his own forearm with a fine needle, while a troll child watches every pull of the thread, enthralled.",
		"passes a Forsaken mending a tear in her own wrist with needle and waxed thread, as calmly as anyone darns a sock, before an audience of two fascinated small orcs.",
	},
	["org.muse.w18.undying.002"] = {
		"A Forsaken at the inn orders a mug of ale and never drinks it. He just holds it, turning it now and then, and leaves a coin when it's gone flat. Company costs something everywhere.",
		"There's a Forsaken who comes to the inn, buys an ale and simply keeps it in front of her, like a ticket. Nobody asks her to leave, and nobody asks why she stays.",
	},
	["org.muse.w18.undying.003"] = {
		"Durotar suits her far better than Tirisfal ever did, a Forsaken told a grunt. Dry air, she said. Nothing goes soft here. The grunt laughed, then stopped, then laughed once more, less sure.",
		"The Forsaken in the market say the dry heat is good for them. In the damp of Tirisfal, one explained to me, you spend half your existence fighting mold. About the other half, I didn't ask.",
	},
	["org.muse.w18.undying.004"] = {
		"hears a wolf growl, hackles up, as a Forsaken goes by, and sees the Forsaken stop, bow to the wolf with grave courtesy, and walk on.",
		"notes how a Forsaken pauses before a wolf that has bared its teeth, inclines her head as one might to a minor official, and steps around it.",
	},
	["org.muse.w18.undying.005"] = {
		"At her collar, the Forsaken apothecary at the stall wears a little bag of dried flowers. Out of courtesy, she told me, for the living. It's the kindest thing anyone has said to my nose in a long while.",
		"Some of the Forsaken who trade in Orgrimmar carry sachets of herbs and flowers tucked in their collars. A courtesy to the crowd, one of them said, with a smile that didn't move much.",
	},
	["org.muse.w18.undying.006"] = {
		"waits behind a Forsaken at a stall who counts out coins with stiff fingers, one by one, without hurrying, while the trader learns patience.",
		"follows the slow work of a Forsaken picking coppers out of a pouch with fingers that no longer bend all the way, and laying them in a neat row on the counter.",
	},
	["org.muse.w18.undying.007"] = {
		"Some tauren, the grunts say, believe the Forsaken can be healed one day, and talk to them as if the cure were already on its way. The Forsaken listen politely. It's hard to tell what they make of it.",
		"On the inn step, a tauren healer sat beside a Forsaken and talked a long while, gently. I heard the word cure once. The Forsaken didn't answer, but she didn't get up either.",
	},
	["org.muse.w18.undying.008"] = {
		"Watch the Forsaken envoy walking the street, with flawless manners: a nod to every grunt, a word to every trader, never a step out of place. Courtesy, worn like armor that doesn't creak.",
		"Almost painfully polite, the Forsaken who pass through: every greeting returned, every bargain thanked. It seems to be how they keep the crowd at a comfortable distance.",
	},
	["org.muse.w18.undying.009"] = {
		"notices that while the whole street scatters for cover at the rain, a lone Forsaken walks on through it unhurried, with the air of someone at last in familiar weather.",
		"sees a Forsaken stop under the falling rain, tilt her face up for a moment, and shrug, as if Tirisfal had sent a letter with no news in it.",
	},
	["org.muse.w18.undying.010"] = {
		"A Forsaken has stopped to watch some orc children squabbling over a stick. He stands there longer than the game deserves, and his face gives away nothing at all.",
		"I saw a Forsaken watch a family eat together on a doorstep, a long look, without envy that I could see and without moving on. Whatever she was remembering, she kept it.",
	},
	["org.muse.w18.undying.011"] = {
		"That Forsaken just told me I look tired. Coming from him, I'm not sure how to take it.",
		"Take better care of yourself, a Forsaken told me. I think it was a joke. I think.",
		"Even the Forsaken think I need rest. That's a bad sign.",
	},
	["org.muse.w18.undying.012"] = {
		"Late at night the inn empties down to a few snoring grunts and one Forsaken at a corner table, reading by a single candle. She doesn't sleep, someone told me, so she reads instead.",
		"At night, when the city finally dozes, the Forsaken are still about: a figure on a step, another at the inn's last table, keeping the hours nobody else wants.",
	},
	["org.muse.w18.undying.013"] = {
		"The Forsaken voice is a dry, quiet thing. When one of them speaks at a stall, the orc behind the counter has to lean in, and for once in this city somebody lowers the volume to be heard.",
		"Never once have I heard a Forsaken shout. So the traders who deal with them learn to lean close and listen, which may be the most unusual skill in Orgrimmar.",
	},
	["org.muse.w18.undying.014"] = {
		"A Forsaken bought a heel of bread at a stall, broke it, and told the baker it tasted of nothing. Then she bought another. Habit, she said, from when it tasted of something.",
		"There's a Forsaken who buys a small loaf from the same baker every time he passes. He doesn't seem to enjoy it. The baker keeps one aside for him anyway, still warm from the oven.",
	},
	["org.muse.w18.undying.015"] = {
		"Never a fight for a table at the inn, if you're Forsaken. Some advantages are worth dying for. Almost.",
		"Best seat at the inn, and nobody contests it. Remind me how one gets to be Forsaken? No, don't.",
		"Nobody ever crowds a Forsaken's table. I'm almost jealous.",
	},
	["org.muse.w18.undying.016"] = {
		"The Forsaken at that stall recommended a salve for stiff joints. If anyone knows stiff joints, it's her.",
		"The best advice on aches I've had in a long while came from a Forsaken. It makes sense, when you think about it.",
		"Took advice on my joints from a Forsaken. Who better?",
	},
	["org.muse.w18.veteran.001"] = {
		"Some of the old soldiers in the city marched in the war that burned Lordaeron's fields. They don't tell those stories. They tell the ones after, the camps and the crossing, as if their lives began behind a fence.",
		"The veterans skip a whole war when they talk. You notice the gap after a while: the camps, the crossing, the walls, and before that, nothing they'll say out loud.",
	},
	["org.muse.w18.veteran.002"] = {
		"stops to watch an old orc teach two cubs a sailor's knot, tying it slowly, then tying it again with his eyes shut to prove it can be done.",
		"follows an elder's thick fingers as they turn a length of rope into a knot no landsman would know, while a ring of children tries to copy it and ties themselves together instead.",
	},
	["org.muse.w18.veteran.003"] = {
		"Every old grunt in this city freed a camp single-handed. There must have been a great many camps.",
		"I've now met six orcs who personally broke down the same gate. It must have been a very large gate.",
		"If every veteran at the inn really carried Doomhammer's banner, they each got a very short turn.",
	},
	["org.muse.w18.veteran.004"] = {
		"Two old orcs at the inn have argued for years about who carried whom out of the camp. Each insists he did the carrying. Neither has ever once suggested they walked.",
		"There's a pair of elders who can't agree on who saved whose life on the march out. Most days they settle it by buying each other a drink, which may have been the point all along.",
	},
	["org.muse.w18.veteran.005"] = {
		"From a long way off, an old orc at the inn says, he can still tell a knight's charger by the ring of its shoes. Shod horses rarely come to Orgrimmar. He listens anyway.",
		"An elder flinches at a clatter of iron on stone, then laughs at himself. Horseshoes, he explains. The knights' horses. It's only a peon dropping a pan.",
	},
	["org.muse.w18.veteran.006"] = {
		"A grunt with a burn up one arm got it from a Kul Tiran fire pot on the Durotar coast, he says. The story grows a little longer with every mug, and the pot a little bigger.",
		"One veteran has a pale burn scar he credits to the Kul Tiran landing. By his third drink the fleet that gave it to him has doubled, and so has his part in sending it home.",
	},
	["org.muse.w18.veteran.007"] = {
		"notices that the old soldiers in the room have all taken seats with their backs to the wall and their eyes on the door, without anyone having arranged it.",
		"looks around the room and sees every gray head placed where it can watch the door, as if the seating had been decided long ago, in some other place.",
	},
	["org.muse.w18.veteran.008"] = {
		"An old Frostwolf in the city sleeps under three blankets in a place this warm. Alterac never left his bones, he says, and he has given up arguing with it.",
		"There's a Frostwolf elder who keeps a fur cloak on in Orgrimmar, of all places. The mountains of Alterac taught him the cold, he says, and he's too old to unlearn a lesson that thorough.",
	},
	["org.muse.w18.veteran.009"] = {
		"A Darkspear elder and an old orc share a bench most days and talk over the crossing in two tongues, each nodding at the parts he can't follow. They seem to agree on everything.",
		"On one bench an old troll and an old orc trade memories of the same voyage, neither fully understanding the other. Now and then both laugh at once, and that seems to settle it.",
	},
	["org.muse.w18.veteran.010"] = {
		"Every tale of the founding has a Warchief in it and no peons. An old peon on the steps by the bank sets that right for anyone who stops: somebody had to dig, and his hands still show where.",
		"The songs remember the chieftains. One stooped peon remembers the ditches, and he'll show you the calluses on his palms to prove who did the work.",
	},
	["org.muse.w18.veteran.011"] = {
		"listens to a young grunt describe the Kul Tiran landing to a crowd, and to the old one beside him correcting every third detail under his voice.",
		"follows a war story told by a young orc at full volume and, beneath it, the low running commentary of an elder who was actually there.",
	},
	["org.muse.w18.veteran.012"] = {
		"Every few days the same three old orcs meet near the bank and say almost nothing for an hour. Survivors of the same camp, a grunt told me. They don't need to talk. They just check that everyone came.",
		"A little knot of elders gathers in the same corner, nods, sits, and parts again without much of a word. Same camp, same crossing, I'm told. Still three. Still enough.",
	},
	["org.muse.w18.veteran.013"] = {
		"Late at night the old ones tell it best: the camps, the crossing, the first walls, in a low voice over a fire to whoever is still awake. By day they'd deny half of it.",
		"By the embers, at night, an old grunt's voice drops and the crossing comes out of him whole, the parts he skips by daylight included. I stay to the end.",
	},
	["org.muse.w18.veteran.014"] = {
		"shields {g:his|her} face from the blowing sand beside an old grunt who doesn't even squint; he has stood on a deck through worse, he mutters, and with less to hold on to.",
		"ducks {g:his|her} head against the gritty wind while an elder nearby stands square in it, grumbling that the salt spray of the crossing stung far worse.",
	},
	["org.muse.w18.veteran.015"] = {
		"The first wolves of Orgrimmar came down out of the hills by themselves, an old wolf handler says, drawn by the cookfires, and the orcs who still remembered the old ways went out to meet them empty-handed.",
		"The orcs lost their wolves in the camps, an elder told me, and found them again here. Or the wolves found them: he's never been sure, and he doesn't think it matters.",
	},
	["org.muse.w18.veteran.016"] = {
		"Go on, tell the crossing once more. The version with the sea serpent.",
		"Sit down, the next mug's mine. Just leave the Kul Tiran fleet the size it was last time.",
	},
	["org.muse.w18.veteran.017"] = {
		"steps aside for an old orc walking very straight on a crutch, and sees every grunt along his way give him the same short nod.",
		"makes room for a one-legged elder swinging along on a crutch; the guards he passes straighten a little, and he pretends not to notice.",
	},
	["org.muse.w18.veteran.018"] = {
		"Never argue with an old grunt about the crossing. You'll lose, and then you'll hear it all from the beginning.",
		"I asked one veteran a single question about Kul Tiras. Two mugs later, we were still on the first ship.",
		"Rule of the inn: don't correct an old soldier's war. He'll only fight it over, slower.",
	},
	["org.muse.w18.voodoo.001"] = {
		"A troll healer sets a grunt's broken finger, binds it, and then keeps humming over it for a good while after the knot is tied. The grunt waits it out. Nobody walks away from a Darkspear halfway through a tune.",
		"The Darkspear healers mend a finger in a moment and hum over it far longer. The patient sits through the whole tune; leaving early, the grunts say, undoes the work.",
		"Splint, poultice, knot, and then the song, which is the long part. The grunt on the healer's stool looks as if he'd rather have the finger broken again.",
	},
	["org.muse.w18.voodoo.002"] = {
		"watches a witch doctor grind something dry in a stone bowl, adding pinches without looking, as if she measured by the sound of the pestle.",
		"pauses beside a troll bent over a mortar, who tips in a pinch of this and that by ear, listening to the grinding the way a cook listens to a pot.",
	},
	["org.muse.w18.voodoo.003"] = {
		"Every troll remedy I've been offered tastes worse than whatever it was meant to cure. The healers say that's how you know it's working.",
		"Troll medicine has one rule, as far as I can tell: if it doesn't make you wince, it isn't strong enough.",
		"I asked a Darkspear healer why her cures all taste of swamp. She said the sickness has to want to leave.",
	},
	["org.muse.w18.voodoo.004"] = {
		"No, thank you, I'll keep the headache. I've seen what goes into the cure.",
		"Kind of you. I think I'll stay sick a little longer, if it's all the same.",
		"That cure has a leg in it. I'll mend by myself, thanks.",
	},
	["org.muse.w18.voodoo.005"] = {
		"The smoke over the troll huts isn't one smoke. Something sweet from one doorway, something bitter from the next, and from a third a haze that stings my eyes and sends my thoughts wander off without me.",
		"Every hut in the Valley of Spirits burns its own herbs, and the smokes never quite mix: sweet, then sour, then something that makes the street tilt a little.",
	},
	["org.muse.w18.voodoo.006"] = {
		"A troll healer quizzes her apprentice by holding out a leaf to sniff. Wrong answer, and he has to chew it. He's getting very good, very fast.",
		"Lessons at the healers' huts are short: the teacher holds out a dried leaf, the pupil names it, and a wrong guess gets eaten. The pupils learn quickly.",
	},
	["org.muse.w18.voodoo.007"] = {
		"Half the herbs a Darkspear healer was taught to use grow on islands the trolls no longer hold. They've learned Durotar's thorns and dry roots instead, and grumble about them like a cook in a borrowed kitchen.",
		"The troll healers mend with what Durotar gives them: thorn, cactus, bitter root. What they really want grows on the Echo Isles, and they say so, every time a cure comes out weaker than it should.",
	},
	["org.muse.w18.voodoo.008"] = {
		"A troll at a charm stall asked me, very sweetly, for one hair, for a charm. I said no. She looked pleased, as if I'd passed something.",
		"One hair, the old troll said, just one, for the charm. I kept it. She laughed and said I'd live long in her valley.",
	},
	["org.muse.w18.voodoo.009"] = {
		"Troll healers wear their learning around the neck: teeth, beads, little pouches, something dried. One cure for each, I'm told. The oldest of them can barely lift their heads.",
		"Count the charms on a Darkspear healer's neck and you'll know how many cures she carries. The old ones jingle when they walk, like a shelf of jars.",
		"The youngest troll healers wear one or two trinkets on a cord. The eldest wear a small rattling museum, and every piece in it once kept somebody alive.",
	},
	["org.muse.w18.voodoo.010"] = {
		"If a troll offers you tea, ask what's in it. Then drink it anyway. Refusing is the one thing worse.",
		"Rule of the troll valley: ask what's in the cup, nod at the answer, drink.",
	},
	["org.muse.w18.voodoo.011"] = {
		"keeps an eye on a troll healer who ties a thread around a grunt's wrist and then slaps the wrist smartly, which seems to be the important part.",
		"sees a Darkspear woman knot a cord around a grunt's arm, mutter over it, and finish with a sharp smack; the grunt nods as though that settled it.",
	},
	["org.muse.w18.voodoo.012"] = {
		"Smells like somebody boiled an entire jungle in there. Hope it's medicine.",
		"Whatever's in that pot used to be half a jungle. Good luck to the patient.",
		"That smoke has more leaves in it than Ashenvale. Somebody's getting cured, or seasoned.",
	},
	["org.muse.w18.voodoo.013"] = {
		"Darkspear fires in an orc city. The herbs in them are wrong, Durotar herbs, but the smoke curls the right way, and for a moment I could be on the islands.",
		"Wrong herbs, right smoke. Whoever is burning that in the Valley of Spirits knows the old way, even with Durotar's poor leaves.",
	},
	["org.muse.w18.voodoo.014"] = {
		"At night the huts of the Valley of Spirits glow from inside, and every painted face on the posts seems to have someone standing behind it.",
		"After dark the troll valley is all small fires and moving shapes, and the masks on the posts look far more awake than they do by day.",
	},
	["org.muse.w18.voodoo.015"] = {
		"reaches toward a bundle of drying leaves and gets a wooden spoon rapped across the knuckles by an old troll who never looks up.",
		"leans in to sniff a rack of drying herbs and is shooed off by a troll healer with a flap of the hand and a word that needs no translation.",
	},
	["org.muse.w18.voodoo.016"] = {
		"Nobody short-changes a witch doctor. Even the goblins pay those stalls in full, on time, and with a nervous smile.",
		"The witch doctors are the only traders in Orgrimmar who never haggle. They don't need to. Nobody dares to start.",
	},
	["org.muse.w18.voodoo.017"] = {
		"The Darkspear stare at me more with curiosity than hate. Their oldest quarrels are with other trolls. To them I'm just one more odd thing the orcs let in.",
		"The trolls in the Valley of Spirits watch me the way you'd watch a strange bird: interested, a little amused. It's the grunts behind them I keep an eye on.",
	},
	["org.muse.w18.voodoo.018"] = {
		"looks on as a troll healer sniffs a grunt's bandaged arm, wrinkles her nose, and unwinds the whole thing to start again, deaf to every protest.",
		"sees an old Darkspear peel back a grunt's dressing, smell it, and click her tongue so loudly that the grunt starts apologizing to his own arm.",
	},
	["org.muse.w18.voodoo.019"] = {
		"Went in with a cut. Came out with a cure, a charm and a lecture. The cut stung least.",
		"Troll healers. They close the wound and then tell you, at length, how you'll get the next one.",
	},
	["org.muse.w18.wander.001"] = {
		"Hardly anyone in the Valley of Strength is where they mean to be. They're between: between the road and the bank, the bank and the trainer, the trainer and the next road out.",
		"Most of the folk I pass are halfway to somewhere else. Orgrimmar is the place you stand in while deciding where to go next, and it's always full.",
	},
	["org.muse.w18.wander.002"] = {
		"steps over a traveler fast asleep on a heap of packs beside the bank, snoring through the din as if the road were still rocking him.",
		"glances at a traveler asleep sitting up against a wall, arms folded over a pack, boots still caked from some faraway road.",
		"tiptoes, without quite meaning to, past a wanderer who has fallen asleep on a crate in the middle of all the traffic, mouth open, hat over one eye.",
	},
	["org.muse.w18.wander.003"] = {
		"Packs go out of Orgrimmar stuffed and come in flat. The city fills them, the road empties them, and a whole market lives off the difference.",
		"Everyone walks out of the gate bulging and walks in later with a rolled blanket and a story. Orgrimmar sells the bulge.",
	},
	["org.muse.w18.wander.004"] = {
		"Of all the faces I've passed in the last hour, I'll likely never see a single one twice. The crowd stays the same size and changes every face in it.",
		"In a city where everyone is arriving or leaving, you stop expecting to meet the same stranger twice. It makes every nod a small farewell.",
		"Each stranger who brushes past is on the way to a road I won't take. By the time I reach the bank, the whole crowd will have been replaced.",
	},
	["org.muse.w18.wander.005"] = {
		"Half this valley just arrived and the other half is leaving. I seem to be the only one standing still.",
		"Everyone's coming or going. Somebody ought to stand here and wave. Fine, I'll do it.",
	},
	["org.muse.w18.wander.006"] = {
		"pauses at a peddler's cart heaped with the leavings of a dozen roads: a seashell, a centaur's broken bead, a jar of Ashenvale honey, a single sock.",
		"picks through a wanderer's tray of oddments laid out on a blanket by the road, gathered, the seller says, from every road between the canyon and the sea.",
	},
	["org.muse.w18.wander.007"] = {
		"Here in the Valley of Strength the comings and goings have their own sounds: cart wheels at the gate, wings at the tower, the bank door that never quite stops swinging.",
		"Shut my eyes in this valley and I can still tell who's leaving and who's arriving: wheels and hooves toward the gate, wingbeats overhead, boots on the bank steps.",
		"This valley is the city's front step, and it never stops creaking: carts, kodos, wings, doors, and a hundred voices asking the way.",
	},
	["org.muse.w18.wander.008"] = {
		"A city isn't only the people in it. It's everyone who set out from it, scattered across Kalimdor. Orgrimmar is much bigger than its walls, and most of it is out on the roads.",
		"Count the ones who left from here and are still out there, at posts and camps and crossings, and Orgrimmar is the biggest city in the world. Most of it just happens to be somewhere else.",
	},
	["org.muse.w18.wander.009"] = {
		"edges around a knot of travelers arguing over a map spread on a crate, four fingers pointing four different ways out of the city.",
		"listens for a moment to a small band of adventurers disagreeing loudly about which road to take, and moves on before they settle on the worst one.",
		"catches part of a heated debate between two wanderers over the shortest way to the Crossroads; both are wrong, and both are certain.",
	},
	["org.muse.w18.wander.010"] = {
		"Tauren come all the way from Thunder Bluff on foot, across the whole of the Barrens, and arrive looking calmer than the ones who rode. I'd like to know the trick.",
		"A tauren just walked in from Mulgore, by the dust on him, and he's the least tired-looking traveler in the valley. They simply don't hurry, and the road seems to respect it.",
		"The tauren who walk here from Mulgore arrive the way they set out, slow and unbothered, while everyone who rushed the road limps in behind them.",
	},
	["org.muse.w18.wander.011"] = {
		"Nobody will notice when I leave the city, any more than I notice the hundred others leaving with me. There's an odd comfort in being part of the tide.",
		"When I go, the crowd will close over the spot where I stood as if I'd never been there. I find I like that. It makes leaving easy.",
	},
	["org.muse.w18.wander.012"] = {
		"Leave now and I reach Razor Hill by supper. Leave after supper and I reach the inn. I know which way I'm leaning.",
		"Road now, or stew first? The stew's closer, and it has never ambushed anyone.",
		"The road will keep. The stew won't. Simple arithmetic.",
	},
	["org.muse.w18.wander.013"] = {
		"Even at night someone is always coming in off the road: a torch bobbing up out of the dark of Durotar, a tired call to the gate, and the grunts' answer.",
		"Travelers keep arriving after dark, small lights climbing the road one by one. The city takes them in without fuss, as if it had been expecting each of them.",
	},
	["org.muse.w18.wander.014"] = {
		"sees a road-worn traveler spotted from the bank steps by someone who has plainly been waiting a while; they meet in the middle of the valley in a hug that lifts one of them off the ground.",
		"pauses at a meeting in the crowd: two travelers off two different roads, recognizing each other mid-stride and stopping the whole flow of the valley to slap backs.",
	},
	["org.muse.w18.wander.015"] = {
		"In the camps nobody came or went. Now I watch my people pour in and out of this gate as they please, and every careless traveler among them is a small victory nobody remembers to cheer.",
		"My people spent years behind fences where the only road led to a work yard. Here the gate stands open and orcs wander off down it on a whim. I don't think the young ones know what a gift that is.",
	},
	["org.muse.w18.wander.016"] = {
		"Every road I take starts at this gate and, with luck, ends at it. Hold it for me, grunts.",
		"Out I go. Keep the gate open and the stew warm. I'll want both.",
	},
	["org.muse.w18.whisper.001"] = {
		"Orgrimmar shows the world its gate and keeps its back stairs in the Cleft. A city with only a front door would be a very honest city, and not for long.",
		"Every stronghold has a door for guests and a stair for everything else. Orgrimmar's guests see the gate. The rest goes down into the Cleft and doesn't ask to be seen.",
		"Visitors remember the gate, the bank, the great hall. The city prefers it that way. What it doesn't show them, it keeps one floor down.",
	},
	["org.muse.w18.whisper.002"] = {
		"A goblin in the Cleft sells news by the word. Gossip is cheap, names cost extra, and whatever he's heard about you, he won't sell to you at any price.",
		"Rumors in the Cleft have a going rate: a copper for what everyone knows, silver for what a few know, and for what you most want to hear, a polite shake of the head.",
	},
	["org.muse.w18.whisper.003"] = {
		"There are corners of this city the patrols walk past a little faster. Nobody gave the order. Everybody knows.",
		"Watch the grunts on their rounds long enough and you'll see where their stride lengthens: a doorway here, an alley there. Orgrimmar has places it chooses not to look at.",
		"Every patrol has a route, and every route has a gap. In Orgrimmar the gaps are as old as the routes.",
	},
	["org.muse.w18.whisper.004"] = {
		"catches a folded note passing from hand to hand in a doorway, quick as a coin trick, and finds something else to look at, like everyone nearby.",
		"glimpses a scrap of paper slipped from one sleeve into another as two strangers pass, and takes a sudden interest in the nearest wall.",
	},
	["org.muse.w18.whisper.005"] = {
		"Somebody in Orgrimmar does the work a Warchief can't be seen to order. The grunts don't say who, and they take great care not to.",
		"Every ruler needs a few hands that never shake his in public. The talk in the Cleft is that Orgrimmar has them. The talk stops there.",
	},
	["org.muse.w18.whisper.006"] = {
		"The grunts mutter that the Burning Blade has ears above ground too, in the market and perhaps nearer the Warchief than anyone likes. Nobody says it loudly. That's how you know they believe it.",
		"Enemies inside the walls, the talk goes: friends of the Burning Blade selling bread and polishing armor among honest folk. Since I heard it, every friendly face takes a moment longer to read.",
	},
	["org.muse.w18.whisper.007"] = {
		"I didn't see anything. I'm very good at not seeing things.",
		"Saw what? I was admiring the rock. Lovely rock.",
		"Whatever that was, I wasn't here for it. Nobody was.",
	},
	["org.muse.w18.whisper.008"] = {
		"Some doors in the Cleft open onto rooms so deep the torchlight gives up before the back wall. I've never seen anyone come out of one. I've never seen anyone go in, either.",
		"There are rooms cut into the rock of the Cleft that go back further than any torch reaches. Their doors stand open as if to say: come and look. Nobody does.",
	},
	["org.muse.w18.whisper.009"] = {
		"The Darkspear keep their secrets in plain sight: said aloud, in the middle of the street, in a tongue hardly anyone else follows. The open air is the best hiding place in the city.",
		"Two trolls in the Valley of Spirits discuss something clearly private at the top of their voices, in their own tongue, with a grunt standing right beside them. Nobody ever needed a cellar less.",
	},
	["org.muse.w18.whisper.010"] = {
		"Whatever you're selling, I'd rather not know what it's for.",
		"Pretty little bottle. No, don't tell me. I sleep better not knowing.",
	},
	["org.muse.w18.whisper.011"] = {
		"Nothing in the Cleft has a price on it. You ask, the seller looks you over, and the price depends on what they see.",
		"Every bargain in the Cleft is priced by eye: your boots, your purse, the look on your face. I've learned to look bored.",
	},
	["org.muse.w18.whisper.012"] = {
		"turns at the feeling of being watched and finds only an empty doorway, and a door within it easing shut without a sound.",
		"looks back over a shoulder at nothing in particular, just in time to see a curtain settle in a doorway that was still a moment ago.",
	},
	["org.muse.w18.whisper.013"] = {
		"Even a city this loud keeps a few silences. The Cleft is one. The troll pool is another. Between the two of them, Orgrimmar does its thinking.",
		"Orgrimmar has two quiet places, and they couldn't be less alike: the still water in the Valley of Spirits and the dark of the Cleft. One keeps calm. The other keeps secrets.",
	},
	["org.muse.w18.whisper.014"] = {
		"The Cleft takes in whoever the rest of the city would rather not look at: the poisoner, the demon-caller, the orc with a past nobody mentions. It asks nothing. That's its own kind of mercy.",
		"Up in the streets you're judged by your clan, your scars, your company. Down in the Cleft nobody asks. For some people that's the only welcome Orgrimmar has.",
	},
	["org.muse.w18.whisper.015"] = {
		"A witch doctor let slip that a few of the painted stones in the Valley of Spirits don't mark anything holy. They mark things buried there that ought to stay put. Then she laughed, and wouldn't say if she'd been joking.",
		"Some of the troll markers in the Valley of Spirits, the Darkspear hint, sit over things better left in the ground. They don't say what. They do walk around them.",
	},
	["org.muse.w18.whisper.016"] = {
		"Why is everybody whispering? Oh. That's just how they talk down here.",
		"I said hello at a normal volume and three hoods turned. Lesson learned.",
	},
	["org.muse.w18.whisper.017"] = {
		"The hooded ones in the Cleft don't worry me much. It's the cheerful fellow by the candle stall, the one with nothing to hide, who makes me check my purse.",
		"Everyone in the Cleft looks sinister, except one smiling old orc mending a sack. He's the one the others step around.",
	},
	["org.muse.w18.whisper.018"] = {
		"is offered, very quietly, something wrapped in a cloth by a stranger in the Cleft, and the stranger is gone into a doorway before any answer can be given.",
		"feels a light touch at the elbow in the Cleft, turns, and finds a hooded someone holding out a small bundle, who melts away again at the first frown.",
	},
	["org.muse.w18.whisper.019"] = {
		"If anyone asks, I was never down in the Cleft. Nobody will ask. That's the beauty of it.",
		"Where've I been? Around. Somewhere without many torches. Next question.",
	},
	["org.muse.w18.zeppelin.001"] = {
		"The goblins take anyone aboard their airships for nothing. Of everything about the zeppelins, that's the part that worries me most.",
		"A goblin contraption that costs nothing to ride. I've met goblins. Nothing they make is free unless the price is hidden somewhere I haven't looked yet.",
		"Free passage on a goblin zeppelin. There's a catch tucked somewhere in that sentence, and I'd like to find it before my boots leave the dirt.",
	},
	["org.muse.w18.zeppelin.002"] = {
		"makes room for a traveler who comes in from the airship side of the gate a little green, sits down on the first free step and refuses to discuss it.",
		"eyes a pair of travelers fresh off a zeppelin walking in through the gate with the careful steps of people who don't yet trust anything underfoot.",
		"steps aside for someone just down from an airship, who stops in the middle of the road, plants both feet and waits for the world to hold still.",
	},
	["org.muse.w18.zeppelin.003"] = {
		"The Forsaken who come off the Undercity airship walk into Orgrimmar squinting, hoods pulled forward, as if all this red were a little too loud to look at.",
		"You can tell who rode in from Tirisfal: hoods up, heads low, wincing at so much red. The damp of Lordaeron still clings to their cloaks.",
		"A pair of Forsaken just walked in from the airship side, looked up at the canyon walls, and pulled their hoods lower in perfect unison.",
	},
	["org.muse.w18.zeppelin.004"] = {
		"Missed the airship by a rope's length. So: more time for bread, and for complaining.",
		"The zeppelin went while I was still on the stairs. The goblin waved. I think he enjoyed it.",
		"Gone, and me with one foot on the last step. Next one, then. Somebody sell me a pie.",
	},
	["org.muse.w18.zeppelin.005"] = {
		"A peon at the gate, gray at the temples, swears he'll never set foot on the goblins' airship: a thing that floats on hot air and promises, he says, comes down when it runs out of either.",
		"Ask the orcs at the gate what holds a zeppelin up and you'll hear two answers: goblin cleverness, or goblin bragging. Either way, they agree, it's mostly hot air.",
	},
	["org.muse.w18.zeppelin.006"] = {
		"The grunts posted to Grom'gol come in through the gate thinner, browner and jumpier, with jungle stories that grow at every table of the inn.",
		"Whoever comes off the Grom'gol airship brings Stranglethorn along: a tiger story, a fever story, and mud in the boot seams that isn't red.",
		"You can pick out the ones just in from Grom'gol by how they keep slapping at the back of the neck, though there's nothing in Durotar that bites like the jungle does.",
	},
	["org.muse.w18.zeppelin.007"] = {
		"overhears a goblin who reeks of engine grease haggle over a sack of bolts, then curse the long walk out to the airship tower.",
		"steps around a goblin with oil to the elbows, buying rope by the coil and complaining that this city was plainly built by people who never had to carry anything to a zeppelin.",
		"trails behind a goblin from the airship tower who staggers out of the Drag with a coil of rope over each shoulder, cursing every ramp in the city by name.",
	},
	["org.muse.w18.zeppelin.008"] = {
		"Out past the gate the airships go two ways: north to the damp gray fields of Tirisfal, south to the steaming green of Stranglethorn. From the canyon, both sound like rumors of other worlds.",
		"One zeppelin to the land of the dead, one to the jungle. Whichever you board, the goblins promise, you'll miss the red rock before you land.",
	},
	["org.muse.w18.zeppelin.009"] = {
		"The goblin at the airship told me it hasn't fallen once this season. I didn't ask about last season.",
		"Not one crash in months, the goblin said, very proud. That's the kind of record I'd rather not hear explained.",
	},
	["org.muse.w18.zeppelin.010"] = {
		"A good part of this crowd is only passing through on its way to the airships. By the time my bread goes stale, some of these faces will be walking in Lordaeron.",
		"Every second traveler in the Valley of Strength has a pack tied for the zeppelin. For them Orgrimmar is a stopover: a meal, a visit to the bank, and off across the sea.",
	},
	["org.muse.w18.zeppelin.011"] = {
		"hears a goblin yell through the gate that the jungle airship waits for nobody, and watches three travelers break into a run, pies still in hand.",
		"follows with some amusement a straggler with one boot half laced who sprints for the gate as word goes round that the zeppelin is about to go.",
	},
	["org.muse.w18.zeppelin.012"] = {
		"The lookouts on the wall say they can follow the northbound airship far out over the water, until it's a seed, then a speck, then a guess.",
		"A grunt who stands watch on the walls told me the airships look like fat beetles as they leave, and like nothing at all once they're over the sea.",
	},
	["org.muse.w18.zeppelin.013"] = {
		"Is the jungle airship in yet? No? Then there's time for one more bowl.",
		"Somebody tell me when the zeppelin docks. Until then, I'm eating.",
		"No zeppelin yet? Good. This stew deserves my full attention.",
	},
	["org.muse.w18.zeppelin.014"] = {
		"A goblin off the airships spent a good while explaining to me how the engine works. I understood 'pressure', 'boom' and 'usually', and I didn't like the order.",
		"I asked a zeppelin goblin how the thing stays up. The answer had a lot of numbers in it and ended with 'mostly'. I've stopped asking.",
		"Goblin engineering, explained by a goblin: three parts pride, two parts numbers, and one small part that makes him lower his voice.",
	},
	["org.muse.w18.zeppelin.015"] = {
		"An airship to Undercity, an airship to Grom'gol. The Horde is scattered over two continents and a sea, and goblin engines are what stitch it together.",
		"Our allies in Lordaeron are a sea away, and what keeps us close is a goblin balloon going to and fro. Strange stitching for a Horde, but it holds.",
	},
	["org.quest_complete.w18.after.001"] = {
		"hooks both thumbs into the belt and stands a moment with hands that have nothing left to hold.",
		"lets both hands hang loose at the sides, as if they too had been let off duty.",
		"tucks the empty hands into the belt for a moment, as if they had earned a rest of their own.",
	},
	["org.quest_complete.w18.after.002"] = {
		"The steps right after handing work in always feel borrowed. Nobody needs me anywhere, and my feet don't quite believe it.",
		"For a little while nothing is owed and nothing is asked. My feet keep looking for an errand anyway.",
		"Nobody is waiting on me. It takes the legs longer than the head to understand that.",
	},
	["org.quest_complete.w18.after.003"] = {
		"So. What does anyone do with free hands in this city?",
		"Empty hands. I'd forgotten what those feel like.",
		"Nothing to hold. Somebody give me something, quick, before I start juggling.",
	},
	["org.quest_complete.w18.after.004"] = {
		"shrugs a strap back into place and lets the clamor of the city fill the space the task has left.",
		"settles the pack higher on the back, now that it carries only what belongs in it.",
		"gives the pack a little hitch and a pat, the way one settles a beast that has behaved.",
	},
	["org.quest_complete.w18.after.005"] = {
		"The moment the work is out of my hands, every ache I've been ignoring raises its hand to speak.",
		"Now that it's finished, my knees have decided to file their complaints. In order. Loudly.",
		"Funny how the shoulders wait for the end of a job to start hurting. Very considerate of them.",
	},
	["org.quest_complete.w18.after.006"] = {
		"sits down on the nearest stone step for no reason except that, for once, nobody is waiting.",
		"lowers {g:himself|herself} onto a low ledge of rock and simply watches the city go on without any help.",
		"finds a stone to sit on and sits on it, which in Orgrimmar is nearly an act of rebellion.",
	},
	["org.quest_complete.w18.after.007"] = {
		"Somebody point me at food. Anything that isn't dried and isn't moving.",
		"First, something hot to eat. After that, I'm anyone's.",
		"Is there a cook in this city who'll feed me without a speech? I've earned silence and a bowl.",
	},
	["org.quest_complete.w18.after.008"] = {
		"I always check my pouches after a job, as if the work might have taken something with it on the way out.",
		"Pouch, belt, pack, boots. I count my own things after every finished task, like a merchant closing up shop.",
		"Everything still where I left it? Good. The work never steals, but I check every time.",
	},
	["org.quest_complete.w18.after.009"] = {
		"opens and closes both hands a few times, working out a grip held longer than it needed to be.",
		"shakes out one hand, then the other, as if flicking the last of the task off the fingertips.",
		"rubs the palms together slowly, the way people do when the work has finally let go of them.",
	},
	["org.quest_complete.w18.after.010"] = {
		"Strange how quickly a finished thing goes cold. A moment ago it was the whole of my attention; now it's just something that happened.",
		"While it was mine to do, it was the most important thing in Orgrimmar. Now it's a story nobody asked for.",
		"It burned so bright in my head while it lasted. Already it's ash, and the city is sweeping it up.",
	},
	["org.quest_complete.w18.after.011"] = {
		"That's one thing fewer. I'll take it.",
		"One less knot in the rope. Good.",
		"Off the list. I do like crossing things off.",
	},
	["org.quest_complete.w18.after.012"] = {
		"moves away from the business along a street that was bare rock before anyone named it, and will be bare rock long after.",
		"leaves the business behind on stone that has outlived every bargain struck on it, and will outlive this one too.",
		"walks off over rock that has seen the canyon empty and seen it full, and is not impressed by either.",
	},
	["org.quest_complete.w18.after.013"] = {
		"I like the quiet that comes after a promise kept. The city is as loud as ever, but that quiet is mine.",
		"Word kept. It makes no sound, but it sits well under all this din.",
		"A kept promise weighs nothing at all. I can tell, because I've carried the other kind.",
	},
	["org.quest_complete.w18.after.014"] = {
		"I'd celebrate, but I can't hear myself think. Later, then.",
		"Somebody cheer for me. Quietly. No? Fair enough.",
		"This calls for a celebration. A small one. Inside my own head, where it's quieter.",
	},
	["org.quest_complete.w18.after.015"] = {
		"My appetite kept quiet the whole time I was busy. Now it wants paying, same as I did.",
		"Funny how hunger waits for the work to end before it says a single word.",
		"I didn't notice I was hungry until it was finished. Now I can't notice anything else.",
	},
	["org.quest_complete.w18.after.016"] = {
		"lets a tight buckle out by one notch, as if it had been the job holding it closed.",
		"eases a strap that has been biting into one shoulder, and the shoulder thanks nobody in particular.",
		"loosens the collar a finger's width and rolls the neck until something in it gives a small, satisfied click.",
	},
	["org.quest_complete.w18.after.017"] = {
		"Nothing to do. Nothing at all. Give it a count of ten and I'll be looking for trouble.",
		"This is the idle part. I've never been any good at the idle part.",
		"Free. Completely free. Somebody find me a problem before I invent one.",
	},
	["org.quest_complete.w18.after.018"] = {
		"Finished, and the streets have thinned to torches and patrols. Whatever comes next can wait until the city stirs.",
		"Late enough that the stalls are shuttered. Good: nobody left to sell me anything on the way to a bed.",
	},
	["org.quest_complete.w18.after.019"] = {
		"There. The city can go back to ignoring me.",
		"Finished. Orgrimmar may now resume not noticing me.",
		"All finished. The city didn't so much as blink, and quite right too.",
	},
	["org.quest_complete.w18.after.020"] = {
		"touches two fingers to the brow toward nobody in particular, a small private ending to a small private task.",
		"gives a short nod to no one, the kind a person gives to close a ledger kept only in the head.",
		"stands a moment with the chin lowered, marking the end of the matter the way some mark the end of a meal.",
	},
	["org.quest_complete.w18.after.021"] = {
		"falls in behind a slow kodo for a few paces, at the beast's own unhurried speed.",
		"drifts along behind a plodding kodo for a stretch of the street, matching its heavy pace step for step.",
		"ends up following a kodo's broad backside down the street, since the beast is in no hurry and neither, for once, is anyone behind it.",
	},
	["org.quest_complete.w18.after.022"] = {
		"That went better than anybody had a right to expect.",
		"Small thing, done right. That's a good feeling.",
		"Not bad. Not bad at all. Somebody remember I said that.",
	},
	["org.quest_complete.w18.after.023"] = {
		"My hand keeps straying to the pouch where the work used to be. Habits take longer to hand in.",
		"Finished, and some part of me is still on the job, checking for something that's no longer mine to check.",
		"The task is gone and my hands haven't been told. They keep patting the pouch, like a dog looking for a bone it buried.",
	},
	["org.quest_complete.w18.boast.001"] = {
		"Mention me to the Warchief. Loudly, so it carries all the way up to Grommash Hold.",
		"If the Warchief asks who did it, point at me. Point twice.",
		"Should word of this reach the Warchief, make sure my name is attached. Spelled properly.",
	},
	["org.quest_complete.w18.boast.002"] = {
		"Not bad, was it? Go on, you can say it. Nobody's listening.",
		"You're impressed. It's all right, I won't tell anyone.",
		"Admit it, that was neat work. I'll pretend I didn't hear you.",
	},
	["org.quest_complete.w18.boast.003"] = {
		"Someone will tell this at the inn eventually, with the details wrong and my name worse. I'll take it.",
		"It won't make the Hall of Legends. It might make a table at the inn, if someone's had enough ale.",
	},
	["org.quest_complete.w18.boast.004"] = {
		"Carve that one into something. Something big, near the gate, where people can see.",
		"That deserves a notch on a post somewhere. A deep one.",
		"Somebody chisel that into a stone. I'll wait. No, I won't. But somebody should.",
	},
	["org.quest_complete.w18.boast.005"] = {
		"Nothing broken, nothing lost, nobody shouting at me. I'm getting rather good at this city.",
		"Clean, tidy, quiet. If Orgrimmar gave out titles for errands, I'd be due one.",
	},
	["org.quest_complete.w18.boast.006"] = {
		"That's it? I've had harder arguments with a vendor in the Drag.",
		"Honestly, haggling over a belt in the Drag gave me more trouble.",
		"Is that all? I've met goblin prices that put up more of a fight.",
	},
	["org.quest_complete.w18.boast.007"] = {
		"One of the grunts gave me a nod just now. Not the crowd: me. I'm going to be unbearable about it.",
		"A nod from a grunt, unprompted. I'll be replaying that one for a while.",
	},
	["org.quest_complete.w18.boast.008"] = {
		"Take a good look, Orgrimmar. You'll be seeing this face around.",
		"Remember this face. It gets things done, and it wants more of them.",
		"Get used to me, city. I'm not going anywhere you won't find me.",
	},
	["org.quest_complete.w18.boast.009"] = {
		"I didn't get lost once. Well, once. Briefly. The Drag curves; that's not my fault.",
		"No wrong turns. One wrong turn. A small one, and the Drag started it.",
	},
	["org.quest_complete.w18.boast.010"] = {
		"That's a satisfied customer. I'm starting a collection.",
		"Happy faces all round. Well, happy for Orgrimmar: nobody's growling.",
		"One more person in this city who doesn't scowl at me. The list is growing.",
	},
	["org.quest_complete.w18.boast.011"] = {
		"The Warchief raised this city out of red rock. I just did one small job in it, properly. Different sizes, same idea.",
		"Somebody built Orgrimmar from nothing. Me, I kept one corner of it in order. Not the same, but not nothing either.",
		"Thrall built a city; I saw to one small part of it. Cities are mostly small parts, when you think about it.",
	},
	["org.quest_complete.w18.boast.012"] = {
		"stows the reward with a touch more ceremony than it needs, in case anyone is watching. Nobody is.",
		"makes rather a show of tucking the reward away, chin up, for an audience of one bored wolf.",
		"pats the pocket where the reward went, twice, the way one might pat a good dog, and glances round for witnesses.",
	},
	["org.quest_complete.w18.boast.013"] = {
		"leaves the business with a swagger the job may not entirely have earned, and wears it well regardless.",
		"struts a few paces into the street, then remembers the slope ahead and settles for a dignified plod.",
		"walks off with the rolling gait of a war hero, which lasts exactly as far as the first ramp.",
	},
	["org.quest_complete.w18.boast.014"] = {
		"They'll never hear about this in Grommash Hold. Their loss, honestly.",
		"Word of this won't climb as far as the Hold. A pity for the Hold.",
	},
	["org.quest_complete.w18.boast.015"] = {
		"The Horde is stronger for it. Slightly. It all counts.",
		"Count that toward the Horde's strength. A small amount. Still counts.",
	},
	["org.quest_complete.w18.boast.016"] = {
		"I'm good at this. It's a small thing to be good at, and I intend to enjoy it all the same.",
		"Small talent, that: doing what a city asks and doing it right. Mine, though. I'll keep it.",
		"Not every skill earns a song. This one earns a nod and a purse, and I'm proud of it anyway.",
	},
	["org.quest_complete.w18.boast.017"] = {
		"Anyone else need a thing done right? I'm right here, and I'm cheap. Fairly cheap.",
		"Next! Somebody in this city must have a problem I can't solve.",
	},
	["org.quest_complete.w18.boast.018"] = {
		"A goblin across the way watched me get paid and looked impressed. Or he was pricing my boots. With goblins it's hard to tell.",
		"Somebody admired that, I'm sure of it. A goblin, I think, though he may only have been admiring the purse.",
	},
	["org.quest_complete.w18.boast.019"] = {
		"straightens once the business is done and gives the nearest guard a look as from one professional to another. The guard does not return it.",
		"squares {g:his|her} shoulders at a passing patrol, colleague to colleagues. The patrol keeps walking.",
		"returns a passing grunt's nod with a much grander one, which the grunt does not stay to see.",
	},
	["org.quest_complete.w18.boast.020"] = {
		"No parade? Fine. I'd have waved, though. I had a wave ready.",
		"If anyone's organizing a parade, I'm free for the rest of the hour. I could bring my own drum.",
	},
	["org.quest_complete.w18.boast.021"] = {
		"The trouble with doing it well: nobody will ever hear of it. Done badly, the whole of Orgrimmar would know my name by now.",
		"Do a job right in this city and it vanishes without a sound. Get it wrong and they'll talk about you at the gate for a month.",
	},
	["org.quest_complete.w18.boast.022"] = {
		"swells a little at the praise, then sees a scarred grunt walk past twice as broad, and settles back to a reasonable size.",
		"stands a bit taller at the words of thanks, until a tauren strolls by and ends the contest without noticing it.",
	},
	["org.quest_complete.w18.boast.023"] = {
		"Let the record show I complained only on the inside.",
		"Not a single complaint out loud. I'd like that noted somewhere.",
		"Every grumble kept behind my teeth. Somebody should give a medal for that.",
	},
	["org.quest_complete.w18.burden.001"] = {
		"The city looks exactly as it did before I started. Either the work mattered in some way I can't see, or it didn't. I'll choose the first and not look too hard.",
		"Same streets, same clamor, same faces. If what I just finished changed anything, it changed it somewhere out of sight.",
		"Not one stone of Orgrimmar has moved because of me. I'd like to think something did, just not anything I can point at.",
	},
	["org.quest_complete.w18.burden.002"] = {
		"sits on a low step once the business is closed, forearms on knees, and studies the ground between both boots for a while.",
		"leans back against a post after the turn-in, eyes on nothing in particular, the reward forgotten in one hand.",
	},
	["org.quest_complete.w18.burden.003"] = {
		"Heavier than it looked, that one. And I don't mean the load.",
		"Done. It weighed more than it should have, and not on the back.",
		"Finished. Some jobs sit on the mind instead of the shoulders.",
	},
	["org.quest_complete.w18.burden.004"] = {
		"Every job done for one side of a quarrel is a job done against the other. I try not to think about who's on the other end of this one.",
		"Somebody, somewhere, is worse off for what I just finished. That's true of most work in a war, and most of the time I manage not to dwell on it.",
	},
	["org.quest_complete.w18.burden.005"] = {
		"Every job done well makes the next one harder to refuse. Trust is a load too, and it only gets heavier.",
		"They'll ask again, now that they know I deliver. Being the one people count on is its own kind of pack to carry.",
		"Do good work in Orgrimmar and the city learns your name for all the wrong reasons: you become the answer to its next problem.",
	},
	["org.quest_complete.w18.burden.006"] = {
		"I hope it helps. Somebody paid for it, one way or another.",
		"I'll take the coin. I hope the thing was worth what it cost.",
		"There. I hope whoever pays the real price for this gets something back.",
	},
	["org.quest_complete.w18.burden.007"] = {
		"presses a thumb into an aching spot at the base of the neck and keeps it there, eyes half shut, while the street goes by.",
		"flexes both hands open and shut a few times, as though to remind them that the job has let go.",
	},
	["org.quest_complete.w18.burden.008"] = {
		"Sometimes I wonder if anyone in this city knows my name, or only the shape of someone who gets things done.",
		"Useful here, certainly. Useful is not the same as known. Most of the time that's fine.",
		"They know my work by sight. Whether they'd know my face without it, I couldn't say.",
	},
	["org.quest_complete.w18.burden.009"] = {
		"Finished. If anyone needs me, I'll be sitting somewhere, thinking about nothing.",
		"Over. I'm going to find a quiet corner, if Orgrimmar owns such a thing.",
		"That's that. Somebody point me to a wall I can lean on.",
	},
	["org.quest_complete.w18.burden.010"] = {
		"Not everyone who takes work in Orgrimmar comes back to hand it in. Standing here with the coin, I try to remember that.",
		"Beyond the walls, someone who took a job like this one isn't going to collect the pay. The coin feels heavier for it.",
		"For every turn-in like this one there's a job somewhere that nobody will ever report. I keep that in the same purse.",
	},
	["org.quest_complete.w18.burden.011"] = {
		"counts the coins once, then frowns at them for a long moment, though the sum is plainly right.",
		"looks down at the reward for a long moment, as if it were the answer to a different question.",
	},
	["org.quest_complete.w18.burden.012"] = {
		"I only have their word for what this was for. In a city this busy, I'll have to let that be enough.",
		"Whoever asked for this knows why. I only know what. That gap is where the doubt lives, and it's not leaving.",
		"The why stayed behind the counter. I walked off with the what and a purse, and that will have to do.",
	},
	["org.quest_complete.w18.burden.013"] = {
		"Let's hope that was the right thing to do. It was the thing I was asked to do, anyway.",
		"Right or not, it's done. I'll sleep on the rest.",
		"It's what was asked. Whether it's what was needed, I can't say.",
	},
	["org.quest_complete.w18.burden.014"] = {
		"Every capital rests on tired backs. Mine has done its share for now, and it would like a bench.",
		"Kor'kron, gates, walls: none of it holds for long without people doing the dull parts. I'm tired, and I'm one of those people.",
		"Somebody has to be the tired one so the city doesn't have to be. Right now that's me.",
	},
	["org.quest_complete.w18.burden.015"] = {
		"keeps both eyes narrowed against the sand blowing through the canyon long after the business is closed, in no hurry to find shelter.",
		"lets the blowing grit sting for a while before pulling a hood up, as if it were a debt that needed paying.",
	},
	["org.quest_complete.w18.burden.016"] = {
		"Part of me expected a laugh and an empty hand at the end. Full pay instead. My doubts make poor fortune-tellers.",
		"All that worrying, and it went exactly as promised. I should bill my doubts for the time they wasted.",
		"I'd braced for some trick at the turn-in. None came. Now I have to find somewhere else to put all that suspicion.",
	},
	["org.quest_complete.w18.burden.017"] = {
		"The Horde asks a great deal. Some days I wonder what's left of me after I give it.",
		"Everything for the Horde. I just wish I knew, now and then, what that everything was going to cost.",
	},
	["org.quest_complete.w18.burden.018"] = {
		"remains under the low roof a moment after the thanks, in the warm haze of lamps and smoke, before facing the street again.",
		"stays a little longer in the shade of the room, the reward tucked away, as if the street outside could wait a moment more.",
	},
	["org.quest_complete.w18.burden.019"] = {
		"Some work you're proud of and some you just finish. This was the second kind, and the second kind keeps the lamps lit too.",
		"Not every job deserves pride. This one deserved finishing, and it got that.",
	},
	["org.quest_complete.w18.burden.020"] = {
		"Don't ask me how it went. It went. That's the good news.",
		"It's done. The rest of the story isn't worth the telling.",
		"How was it? Finished. Leave it at finished.",
	},
	["org.quest_complete.w18.burden.021"] = {
		"Loyalty to the Horde and a few quiet doubts: I bring both to every job. I think the Horde is better served by the two together than by either alone.",
		"My loyalty belongs to the Horde. So do my questions, and I'd like to think a Horde with room for both is the one Thrall meant to build.",
	},
	["org.quest_complete.w18.burden.022"] = {
		"glances at a pair of scuffed boots, then at the length of street ahead, and squares up to it without a word.",
		"tightens a strap that has hung loose for longer than anyone could say, now that there is a moment for it.",
		"shifts the weight of the pack from one side to the other, finds no better arrangement, and accepts the old one.",
	},
	["org.quest_complete.w18.burden.023"] = {
		"While the work lasted there was no room to think. Now there's room, and the thoughts are filing in one by one like customers at the bank.",
		"Work is a good place to hide from your own head. The hiding place just closed.",
		"The job kept the questions out. With it handed in, the door's open, and every one of them is coming through.",
	},
	["org.quest_complete.w18.burden.024"] = {
		"Done. I'm not sorry I did it. I'm not glad either, and that's allowed.",
		"Finished. Ask me later whether I'm proud of it.",
	},
	["org.quest_complete.w18.burden.025"] = {
		"The orcs did terrible things with the demon's blood in them, and the world remembers. Every honest job I finish is a very small stone taken off a very large pile.",
		"Somebody has to work off what the old Horde did. It isn't fair that it falls to me, but it falls to all of us, and this was my piece.",
	},
	["org.quest_complete.w18.grin.001"] = {
		"In a war capital even the thanks come out like orders. I half expected to be told to fall in.",
		"They paid me as if they were assigning me to a watch. That's how warmth sounds in Orgrimmar.",
		"The thanks was barked. Not unkindly; that's simply the only volume this city has.",
	},
	["org.quest_complete.w18.grin.002"] = {
		"is still counting the coins when the next task is pressed on {g:him|her}, and loses the count somewhere in the middle.",
		"gets halfway through counting the reward before somebody starts explaining the next job, and the numbers wander off.",
		"has counted to about seven when a new errand begins, and has to start the coins over from one.",
	},
	["org.quest_complete.w18.grin.003"] = {
		"Let me put the coin away before you hand me the next one. I've only got two hands.",
		"One thing in each hand, please. Purse first, then problem.",
	},
	["org.quest_complete.w18.grin.004"] = {
		"In Orgrimmar a day off is a job that happens to be downhill.",
		"Rest, in this city, means the next errand is on the same street.",
		"A holiday in Orgrimmar: carrying something light.",
	},
	["org.quest_complete.w18.grin.005"] = {
		"In Orgrimmar 'well done' and 'now go' are one sentence, delivered without a pause.",
		"The thanks and the dismissal arrived together, tied with the same string. Very Orgrimmar.",
	},
	["org.quest_complete.w18.grin.006"] = {
		"Does any job in Orgrimmar begin without somebody shouting? Just curious.",
		"Every task in this city comes with a shout attached. I'm starting to find it soothing.",
	},
	["org.quest_complete.w18.grin.007"] = {
		"A grunt on watch saw the whole exchange without moving a muscle. Approval, I think. Or indigestion.",
		"The nearest guard watched me get paid and did nothing whatsoever with his face. I'm counting it as praise.",
		"The guard by the wall gave me the same look he gives everything. I've decided that look means 'splendid'.",
	},
	["org.quest_complete.w18.grin.008"] = {
		"gives a short laugh at nothing in particular as the reward changes hands, the laugh of someone who expected worse.",
		"chuckles under the din of the street, reward in hand, at a joke nobody else was told.",
		"grins briefly at the reward, then at the street, as if both had told the same joke.",
	},
	["org.quest_complete.w18.grin.009"] = {
		"Sand blowing sideways down the street, and still they found me to pay me. And to hand me the next job, of course.",
		"Grit in my teeth, grit in the purse. In Orgrimmar even the pay comes seasoned.",
	},
	["org.quest_complete.w18.grin.010"] = {
		"I'll be off before you remember you had a second job for me.",
		"Quick, before you think of something else. Farewell!",
		"And that's my cue to vanish, before anyone says 'one more thing'.",
	},
	["org.quest_complete.w18.grin.011"] = {
		"Everyone who hands out work in Orgrimmar shares one talent: they can give you the next task without looking up.",
		"There's an art to it, the way this city's taskmasters slide a new job across without ever meeting your eye.",
	},
	["org.quest_complete.w18.grin.012"] = {
		"The pay looks better if I don't count it. So I won't. Not in the street, anyway.",
		"Best not to count it out in the open. Counted, it's small. Uncounted, it's a fortune.",
	},
	["org.quest_complete.w18.grin.013"] = {
		"has barely closed a hand on the reward when a passing goblin offers to sell {g:him|her} something for almost exactly that sum.",
		"is paid, and within a dozen paces a hawker has named a price suspiciously close to it.",
		"has not taken three steps with the reward before a goblin vendor calls out an offer that costs, by remarkable coincidence, just about all of it.",
	},
	["org.quest_complete.w18.grin.014"] = {
		"Half the world is at war with the Horde, and I've just triumphed over an errand. Somebody has to win the small ones.",
		"Armies march out of this city and I march across it. Someone has to win the little wars too.",
	},
	["org.quest_complete.w18.grin.015"] = {
		"Indoors at last, out of the din, and the first thing I'm given is a reason to go straight back into it.",
		"Four walls, a roof, a moment's quiet, and already a new errand is pointing me at the door.",
	},
	["org.quest_complete.w18.grin.016"] = {
		"Thank you. You've made a tired soul slightly less poor.",
		"Much obliged. I'm now one small purse less broke.",
	},
	["org.quest_complete.w18.grin.017"] = {
		"My favorite moment is the gap between finishing and being handed the next one. It's very short. I treasure it.",
		"There's a sliver of freedom between one job and the next in this city, about as wide as a coin's edge. I'm standing on it.",
	},
	["org.quest_complete.w18.grin.018"] = {
		"waits out a wolf rider, then a laden kodo, then a cart with one bad wheel, before a gap opens in the street wide enough to step into.",
		"is nearly run down by a hurrying peon on the way out of the business, and gives way to a wolf as well, for good measure.",
	},
	["org.quest_complete.w18.grin.019"] = {
		"Grunts guard the gate, the Kor'kron guard the Hold, and the one running errands between them guards nothing but a purse. Me, that is.",
		"Everybody in Orgrimmar is guarding something. I'm only guarding this small, freshly earned pouch, and I take it seriously.",
	},
	["org.quest_complete.w18.grin.020"] = {
		"Nobody in Orgrimmar pretends an errand was noble. It needed doing, it got done, here's your coin, mind the wolf.",
		"No fine words over it, no little ceremony. Work, coin, a jerk of the chin toward the street. I almost like it.",
	},
	["org.quest_complete.w18.grin.021"] = {
		"Always glad to serve the Horde. Gladder still when the Horde pays.",
		"Service to the Horde: done. Payment from the Horde: also done. A good arrangement.",
	},
	["org.quest_complete.w18.grin.022"] = {
		"Night in the canyon, torches lit all down the street, and the next errand was waiting anyway. This city keeps no hours I can find.",
		"Even after dark there's someone with a task for me. I suspect Orgrimmar hands out work in its sleep.",
		"Dark over the canyon, and someone still found a job for me. Orgrimmar's errands have never heard of bedtime.",
	},
	["org.quest_complete.w18.grin.023"] = {
		"hums a scrap of a tune while stowing the reward, off-key, and a troll passing by takes it up for a few steps, further off-key.",
		"whistles something tuneless as the business closes, and an old orc at a stall frowns at it on principle.",
		"taps out a little rhythm on the reward pouch, and a goblin nearby raises an eyebrow at the sound of coin keeping time.",
	},
	["org.quest_complete.w18.grin.024"] = {
		"nods through the thanks already half turned toward the street, where somebody is calling for anyone with free hands.",
		"hears the thanks out, and somewhere behind, a voice is already asking whether anyone's free. The timing is uncanny.",
		"has barely heard the last word of thanks when a new voice down the street starts asking for help, as if on cue.",
	},
	["org.quest_complete.w18.grin.025"] = {
		"takes the offered handshake, then spends a few paces quietly flexing the fingers back into working order.",
		"survives a handshake in the Orgrimmar style with a polite face, and only shakes the hand out once safely around a corner.",
		"has a hand crushed warmly in thanks and smiles through it, the smile of someone counting fingers.",
	},
	["org.quest_complete.w18.grin.026"] = {
		"That went smoothly. I don't trust it.",
		"No shouting, no surprises, and in Orgrimmar of all places. Something's wrong.",
		"Too easy. Somewhere in this city a catch is waiting for me, I'd bet the purse on it.",
	},
	["org.quest_complete.w18.grin.027"] = {
		"All this noise. Did somebody announce I was done?",
		"Listen to them. You'd think the whole city had heard I'd finished.",
		"Every hammer in the Drag going at once. For me? You shouldn't have.",
	},
	["org.quest_complete.w18.grin.028"] = {
		"Lovely. Is there anyone in Orgrimmar with work that's done sitting down?",
		"Any jobs going that involve a chair? Asking for my knees.",
	},
	["org.quest_complete.w18.ledger.001"] = {
		"My own tally has three columns: what was asked, what I did, what I was paid. They rarely agree, and the third is always the shortest.",
		"Asked, done, paid. I keep the three side by side in my head, and the sums never quite match. Nobody in Orgrimmar has ever corrected them in my favor.",
	},
	["org.quest_complete.w18.ledger.002"] = {
		"Debts in this city outlive whoever made them. Better to be the one who collects, and to collect from many.",
		"In Orgrimmar a debt gets handed down like an axe. I'd rather be the one holding the handle.",
	},
	["org.quest_complete.w18.ledger.003"] = {
		"Put a mark by my name. A clean one; I'd like it readable.",
		"Cross it off. Firmly, please, so nobody asks me to do it twice.",
		"Is my name written right? Check it. Twice.",
	},
	["org.quest_complete.w18.ledger.004"] = {
		"The Horde forgets no debt, in either direction. For once I'm standing on the side that's owed.",
		"Owed by the Horde, if only a little. It's the safest place to keep a favor; the Horde remembers well and has walls to keep its memories in.",
	},
	["org.quest_complete.w18.ledger.005"] = {
		"The merchants of the Drag say every goblin keeps two books, one for the tax collector and one for the truth. I'd give a coin of this pay to know which one I'm written in.",
		"Two ledgers per goblin, the stallholders swear: one honest, one for show. If my name's in either, I hope it's the honest one, though I doubt it reads any kinder.",
	},
	["org.quest_complete.w18.ledger.006"] = {
		"ticks something off on the fingers, frowns, and ticks it off again, as if the reckoning of the task and the reckoning of the pay were two quite different sums.",
		"counts on three fingers, then on four, and finally gives up and lets the sum be whatever the city decided.",
	},
	["org.quest_complete.w18.ledger.007"] = {
		"A good name is a ledger nobody lets you read. Mine has just grown by a line, and I'll never see the page.",
		"There's an account of me kept in a hundred heads across this city. One of them has just added a line; I'd like to think it's a kind one.",
		"My name is worth a little more in this city than it was a moment ago. Nobody will write it down; everybody will know.",
	},
	["org.quest_complete.w18.ledger.008"] = {
		"We're square. Remember that the next time I come asking.",
		"That's us even. Mind you, I'll be back to unbalance it.",
		"Even. Carve it in the wall if you like; I'll hold you to it.",
	},
	["org.quest_complete.w18.ledger.009"] = {
		"Owing nothing to anyone in Orgrimmar. It's a rare, pleasant feeling, like a quiet corner in the Drag. It won't last, so I'm standing in it a moment.",
		"Nobody in this city can call in a favor from me right now. I'll enjoy it while it lasts; it never lasts.",
		"Debts paid, favors returned, nothing outstanding. In a city of ledgers, a clean page is a small holiday.",
	},
	["org.quest_complete.w18.ledger.010"] = {
		"The pay squared the account. The look that came with it opened a new one, and I'm not sure yet which side of it I'm on.",
		"Coin closes one reckoning; a long look like that starts another. Orgrimmar never lets a ledger stay shut for long.",
	},
	["org.quest_complete.w18.ledger.011"] = {
		"An old grunt at the gate says the orcs in the camps counted every day of their captivity, scratched on whatever would take a mark. Their young count favors and coin now. A better thing to count, he says.",
		"In the camps, the veterans say, the counting was of days lost. In this city the counting is of work done and paid. They tell it as if that were the whole difference between then and now.",
	},
	["org.quest_complete.w18.ledger.012"] = {
		"Settled. Strike me off the list of worries and onto the list of useful people.",
		"Off your list, onto your good list. That's how it works, isn't it?",
	},
	["org.quest_complete.w18.ledger.013"] = {
		"No ink, no seal. Here a deed is written in the memory of whoever asked for it, and in a city this hard that holds better than paper.",
		"Nobody signed anything. In Orgrimmar the record of a job lives in someone's memory, not on a page, and memories in this city are notoriously hard to burn.",
	},
	["org.quest_complete.w18.ledger.014"] = {
		"The goblin way would be to charge interest on gratitude. I'm tempted. A copper a week on every 'well done' and I'd be rich by the turn of the season.",
		"If I were a goblin I'd be charging interest on that thanks by now. Maybe it's for the best that I'm not; I'd have no friends left in the city.",
		"Gratitude ought to earn interest. I'd take it up with a goblin, but I already know the rate would favor him.",
	},
	["org.quest_complete.w18.ledger.015"] = {
		"Debt is the oldest rope in this city. Pull it gently and the whole crowd shifts; pull it hard and it snaps in your hands.",
		"Favors owed hold Orgrimmar together tighter than any iron spike. I've just pulled one of its knots a little tighter.",
	},
	["org.quest_complete.w18.ledger.016"] = {
		"That's one more name on the list of folk who owe me. Short list. Growing.",
		"Count of people in this city in my debt: small, but climbing. Don't worry, I never collect.",
		"Add yourself to my list of debtors. It's a friendly list, mostly.",
	},
	["org.quest_complete.w18.ledger.017"] = {
		"watches a mark go down against the finished business, and follows the stroke with a keen, unhurried interest.",
		"notes the scratch of a tally being made somewhere close, and seems content to let it have the last word on the matter.",
	},
	["org.quest_complete.w18.ledger.018"] = {
		"Account closed. Don't open another in my name without asking first.",
		"That's the books balanced. Leave them that way until I've had a sit-down.",
	},
	["org.quest_complete.w18.ledger.019"] = {
		"Nothing gets rubbed out in Orgrimmar. The good deeds sit beside the bad ones in someone's memory, and each new one shifts the balance a hair.",
		"This city doesn't erase. It just keeps adding, and hopes the total comes out right. Mine came out a little better than it was.",
	},
	["org.quest_complete.w18.ledger.020"] = {
		"closes the business as the canyon walls go from red to dark, the day's last account settled with the day.",
		"settles the reckoning while the shadow climbs the canyon walls, and the torches along the street are lit one after another.",
	},
	["org.quest_complete.w18.ledger.021"] = {
		"Every closed job is a line in the city's long book. I'm somewhere in the margins, in small letters, which is fine. The margins are where the work gets done.",
		"The great names have whole pages in Orgrimmar's story. I get a note in the margin. A good deal of this city was built by margin notes.",
	},
	["org.quest_complete.w18.ledger.022"] = {
		"These walls were raised by those who came before. Each job done for the Horde pays a sliver of that debt back. It will never be paid off, and that's as it should be.",
		"Whoever built Orgrimmar is owed more than any of us will ever repay. A job like this is one coin dropped down that very deep well.",
	},
	["org.quest_complete.w18.ledger.023"] = {
		"My side of the bargain, kept. Pleasure doing business.",
		"Bargain kept, both ends. That's rarer than it should be.",
	},
	["org.quest_complete.w18.ledger.024"] = {
		"How many names are on Orgrimmar's tallies of those who got something done? More than the statues, fewer than the graves. Mine is in the honest middle.",
		"Statues for the few, graves for too many, and a scratched tally for everyone in between. I'll settle for the tally.",
	},
	["org.quest_complete.w18.ledger.025"] = {
		"pauses after the business with an inward look, the face of someone balancing an account that exists only in the head.",
		"stands a moment working something out, lips moving faintly, like a trader reckoning a sum no one else can see.",
	},
	["org.quest_complete.w18.ledger.026"] = {
		"Count it as a favor. I certainly will.",
		"Mark that one down as a kindness. I'll be collecting kindnesses later.",
	},
	["org.quest_complete.w18.ledger.027"] = {
		"Make sure it's my name you put down, not whoever came in before me.",
		"If there's a ledger, I'd like my line in ink, not chalk.",
	},
	["org.quest_complete.w18.next.001"] = {
		"Bank first, before the Drag gets a look at me. It's the only rule I've ever kept in this city.",
		"If I walk past the Drag before the bank, I'll reach the bank with nothing to put in it. Bank first.",
		"The bank, then the shops. Do it the other way round and the bank becomes a very short visit.",
	},
	["org.quest_complete.w18.next.002"] = {
		"Who'll show me the shortest way to my trainer? Shortest, mind, not prettiest.",
		"Trainer next. If I'm going to be told I'm doing it all wrong, it might as well be now.",
		"Off to be taught something. I can afford one lesson, possibly two.",
	},
	["org.quest_complete.w18.next.003"] = {
		"weighs the bank against the inn with a look at each, and a third look at the overloaded bags.",
		"looks from the overstuffed bags toward the bank, the arithmetic plain on {g:his|her} face.",
		"pats one bulging bag, then another, and turns a slow look toward the nearest merchant.",
	},
	["org.quest_complete.w18.next.004"] = {
		"I'll drop by the auction house just to see what everyone else thinks my junk is worth. Usually less than I do.",
		"The auction house, then. I'll put up three things, buy one, and come out poorer. It's tradition.",
		"Somewhere in the auction house a stranger is waiting to outbid me by a single copper. I mustn't keep them waiting.",
	},
	["org.quest_complete.w18.next.005"] = {
		"If anyone needs me, I'll be at the inn, pretending I'm not.",
		"Inn. Stool. Silence. Two out of three would do.",
		"The inn's that way, isn't it? Don't answer. My feet already know.",
	},
	["org.quest_complete.w18.next.006"] = {
		"I ought to write somebody a letter. I won't, but I'll stand by the mailbox and think about it for a while.",
		"Mailbox next. Nothing will be in it. I'll check anyway, the way you check a pocket you know is empty.",
		"I'll look in at the mailbox on the way past. Letters are rare, but hoping costs nothing.",
	},
	["org.quest_complete.w18.next.007"] = {
		"sets off toward the smiths, counting the things that need mending on the fingers of one hand, and then the other.",
		"heads for the nearest anvil with a list of small damages, ticking them off finger by finger.",
		"walks off toward the sound of hammering, holding up a frayed strap to the eye and frowning at it on the way.",
	},
	["org.quest_complete.w18.next.008"] = {
		"For once there's no next job written in my head. I'll walk until something in the city calls my name.",
		"No next errand. I'll follow the busiest street and find out what it's so busy about.",
		"Nothing planned. That's rare enough that I mean to waste it properly.",
	},
	["org.quest_complete.w18.next.009"] = {
		"Bags full, pockets light. Somebody in this city buys junk, and I mean to find them.",
		"First a merchant who'll buy anything. Then a merchant who sells something good.",
		"Who's buying? Odds, ends, a bit of everything. Mostly ends.",
	},
	["org.quest_complete.w18.next.010"] = {
		"There's a craft trainer in the Drag who'll show me the next thing the moment I can pay for it. Let's see if I can.",
		"Somewhere off the Drag a master of some trade is waiting for my coin and my clumsy hands. Both are ready.",
		"My trade could use another lesson, and my purse can just about stand one.",
	},
	["org.quest_complete.w18.next.011"] = {
		"sets off for the bank at a purposeful stride, gets three stalls along, and stops to look at a belt.",
		"heads for the bank in a straight line, which in Orgrimmar lasts as far as the first cookfire.",
		"starts toward the bank, veers toward a stall of buckles, corrects course, and veers again toward a stall of knives.",
	},
	["org.quest_complete.w18.next.012"] = {
		"Somewhere past the main gate the roads are waiting. They can wait a little longer; there's a stool at the inn that has learned my shape.",
		"The roads beyond the gate will still be there after a bowl of something hot. Roads are patient like that.",
		"I can feel the gate pulling at me already. Not yet, road. Let me sit down first.",
	},
	["org.quest_complete.w18.next.013"] = {
		"Food. Then the bank. Then food once more, if the bank's been kind.",
		"Hungry first, rich second. That's the order of things.",
		"Supplies, a meal, a bit of sleep. In whichever order the city lets me have them.",
	},
	["org.quest_complete.w18.next.014"] = {
		"Right after a job is when the zeppelin towers outside the gate call loudest. Anywhere but here, they say. I usually go to the bank instead.",
		"A finished task always makes the zeppelins sound tempting. Then I remember the goblin who sells the passage, and the urge goes quiet.",
		"From the gate I could be on a zeppelin before I'd thought better of it. Which is exactly why I'm going to the inn.",
	},
	["org.quest_complete.w18.next.015"] = {
		"stops where the street splits three ways and stands there a moment, like a wolf testing which way the smell of a cookfire comes from.",
		"pauses at a fork in the road, head turning one way and then the other, until the crowd settles the matter by pushing.",
		"halts where two roads meet and lets three people pass on each side before choosing the one with fewer of them.",
	},
	["org.quest_complete.w18.next.016"] = {
		"I should bind my hearthstone at the inn while I'm in the city. I say that every time, and then I wake up somewhere else.",
		"Hearthstone. Inn. Two minutes' work. I'll forget, of course, and curse myself in some far-off field.",
		"Hearthstone first. The last time I forgot, I regretted it for one very long walk.",
	},
	["org.quest_complete.w18.next.017"] = {
		"Time for a lesson. My trainer will find something wrong with me. Trainers always do.",
		"Off to my trainer, to pay good silver for bad news.",
		"A trainer, then. Somebody has to tell me my elbows are wrong.",
	},
	["org.quest_complete.w18.next.018"] = {
		"No rush toward the next thing. The next thing has never once failed to find me.",
		"I won't go looking for work. In Orgrimmar the work comes looking for you, usually shouting.",
		"The next task will turn up the way they all do, at the worst possible moment. Until then, nothing.",
	},
	["org.quest_complete.w18.next.019"] = {
		"takes the long way round toward the inn, the way that happens to pass every cookfire in the street.",
		"follows a thread of cooking smoke down the street, nose first, purse second.",
		"lets the smell of smoke and fat lead the way, with the face of someone being led quite willingly.",
	},
	["org.quest_complete.w18.next.020"] = {
		"Repairs. Every finished job ends in front of a smith, holding out something dented and trying to look innocent.",
		"The smith will want to know how I did this to my gear. I'll say it was like that when I found it.",
		"Somewhere down the Drag a smith is about to sigh at me. Better get it over with.",
	},
	["org.quest_complete.w18.next.021"] = {
		"Anyone heading toward the gate? I'll walk with you as far as the bank.",
		"Going my way? I'm for the bank, then wherever the bank lets me go.",
		"Company on the road to the inn? I won't talk much. I'll mostly complain.",
	},
	["org.quest_complete.w18.next.022"] = {
		"The trainer, the bank, the inn: the same three doors after every job, and I'm glad of them. A habit is a kind of roof.",
		"Bank door, inn door, trainer's door. I could walk the round blindfold. It's a comfort, knowing where the doors are.",
	},
	["org.quest_complete.w18.next.023"] = {
		"heads off toward the inn as the torches go up along the street, along with everyone else who had the same thought.",
		"makes for the inn while someone works down the street lighting torches, one fire catching after the next.",
	},
	["org.quest_complete.w18.next.024"] = {
		"There's always another job in this city. There's also always a bench. Bench first.",
		"Every street in Orgrimmar leads to more work eventually. I'll take the one with somewhere to sit.",
		"Work later. Sitting now. The city will understand, or it won't, and I'll be sitting either way.",
	},
	["org.quest_complete.w18.next.025"] = {
		"The flight master can wait. My legs want to see the city from the ground for a change.",
		"No flying off just yet. I'd like to walk this city a while without being sent anywhere.",
		"The tower's not going anywhere. Neither am I, for a while.",
	},
	["org.quest_complete.w18.nod.001"] = {
		"receives a single nod, slow and deliberate, the kind that takes a person's measure before it lets go.",
		"is given one long nod, unhurried, and holds still under it as under an appraiser's eye.",
	},
	["org.quest_complete.w18.nod.002"] = {
		"That nod. No words, just the chin dipped once, and I know exactly where I stand in this city.",
		"One dip of the chin. It said more than the purse did.",
		"Barely a movement of the head, and still it's the part I'll remember longest.",
	},
	["org.quest_complete.w18.nod.003"] = {
		"Orgrimmar has a whole language of nods. Deep means respect, quick means move along, and the slow one with the eyes half closed means you'll be remembered. I got the slow one.",
		"I'm learning the city's nods like a tongue: the short one dismisses, the deep one honors, the slow one files you away for later. That was a slow one.",
	},
	["org.quest_complete.w18.nod.004"] = {
		"I'll take the nod for a yes and the grunt for applause.",
		"A nod and a grunt. In this city that's a standing ovation.",
		"Nod, grunt, done. I've had warmer welcomes, but never quicker ones.",
	},
	["org.quest_complete.w18.nod.005"] = {
		"returns the nod precisely as deep as it was given, not a finger's width more, and the arithmetic seems to satisfy everyone.",
		"matches the nod to its depth, neither more nor less, the way all business in this city is done.",
		"nods back with exact care, as if a deeper nod might be taken for owing something.",
	},
	["org.quest_complete.w18.nod.006"] = {
		"In Orgrimmar I've learned to read eyes more than mouths. These ones said: done right, and done without fuss.",
		"The mouth said almost nothing. The eyes said the rest, and the rest was good.",
	},
	["org.quest_complete.w18.nod.007"] = {
		"is dismissed with a flick of the hand and goes without fuss, as though the gesture were a kind of thanks too.",
		"gets a short wave toward the street, the Orgrimmar way of saying the matter is closed, and takes it.",
	},
	["org.quest_complete.w18.nod.008"] = {
		"A grunt at the nearest post caught my eye as the business closed and gave half a nod, as if he'd been keeping score too.",
		"Even the guard nearby dipped his head a fraction when it was over. Nobody in this city admits to watching, and everybody does.",
	},
	["org.quest_complete.w18.nod.009"] = {
		"A nod! I'll have it framed and hung over the bed.",
		"Look at that, a nod. I'll be telling people about this one.",
		"Mark the date, somebody. I've been nodded at.",
	},
	["org.quest_complete.w18.nod.010"] = {
		"Nobody bows in Orgrimmar. A nod between equals, a lowered head before the Warchief, and that's the whole of its ceremony. I prefer it.",
		"No bowing and scraping in this city. Heads go down for the Warchief and for the dead; for the rest of us, a nod does the work.",
	},
	["org.quest_complete.w18.nod.011"] = {
		"holds the other's gaze a moment longer than needed, until the nod comes, then turns away into the street.",
		"waits, eyes level, for the small nod that ends the business, and only then steps back into the crowd.",
	},
	["org.quest_complete.w18.nod.012"] = {
		"You nodded before I'd finished. Was it that good, or that dull?",
		"Halfway through my report and already the nod. I'll assume that's praise.",
	},
	["org.quest_complete.w18.nod.013"] = {
		"Got the nod, and with it a strange wish to nod back at the whole city. It wouldn't notice. It never stops long enough to be nodded at.",
		"I'd like to return that nod to Orgrimmar itself, to every wall and wolf and shouting stall. The city wouldn't notice. It isn't the noticing kind.",
	},
	["org.quest_complete.w18.nod.014"] = {
		"And a nod back. There. We understand each other perfectly.",
		"Nod for nod. Nothing more needs saying, does it?",
	},
	["org.quest_complete.w18.nod.015"] = {
		"A thanks without words is the hardest kind to argue with. I can't even pretend I misheard it.",
		"Nothing was said, and somehow that leaves no room for doubt. Spoken praise can be taken back; a nod can't.",
	},
	["org.quest_complete.w18.nod.016"] = {
		"catches a grin full of tusks from somewhere in the street and answers it with a small, closed-lipped one of {g:his|her} own.",
		"trades a crooked grin with a tusked stranger across the way, with no explanation offered on either side.",
	},
	["org.quest_complete.w18.nod.017"] = {
		"Here respect looks like being ignored by the right people. The guards along the street let me pass without a second look. That's the nod that counts.",
		"The best compliment in this city is a grunt on duty who doesn't bother watching you. Trust is being ignored by people paid to notice.",
	},
	["org.quest_complete.w18.nod.018"] = {
		"receives the nod by torchlight, a quick dip of a head half in shadow, and walks off into the dark street with the matter closed.",
		"gets a nod barely visible in the dark between two torches, and takes it on trust.",
	},
	["org.quest_complete.w18.nod.019"] = {
		"The Kor'kron in Grommash Hold nod at no one. I keep hoping. One day, perhaps. Not by the look of them.",
		"Everyone in this city nods eventually, except the Kor'kron. I've decided to take that as a challenge.",
	},
	["org.quest_complete.w18.nod.020"] = {
		"No need for words. I speak fluent nod.",
		"Understood. Save the words; by now I read nods like a native.",
	},
	["org.quest_complete.w18.nod.021"] = {
		"stands still a moment after the business is done, as if waiting for something more, then gives a short nod to nobody in particular.",
		"lingers, then nods once at the street in general, a private full stop.",
	},
	["org.quest_complete.w18.nod.022"] = {
		"A clap on the shoulder is just a nod for people who'd rather use their hands. Orgrimmar is full of those people.",
		"That thump on the arm was a nod, delivered by fist. The ache will be the receipt.",
	},
	["org.quest_complete.w18.nod.023"] = {
		"That's a level look. I'll take level over warm, every time.",
		"Not friendly, exactly. An equal's look. I'll take it.",
	},
	["org.quest_complete.w18.nod.024"] = {
		"Throm-ka. Until the next one.",
		"Same city, more trouble next time. Throm-ka.",
	},
	["org.quest_complete.w18.nod.025"] = {
		"receives the nod through a veil of blowing grit, eyes squinting on both sides, and the business closes without a word anyone could have heard.",
		"gets a nod half lost in the sand hissing down the street, and answers it with eyes narrowed to slits.",
	},
	["org.quest_complete.w18.nod.026"] = {
		"Likewise. Nod received, nod returned.",
		"And the same back to you, with interest.",
	},
	["org.quest_complete.w18.oath.001"] = {
		"I said I'd see it through, and it's seen through. Nobody checks a promise that small, which is exactly why it's worth keeping.",
		"A small promise, kept all the way to the end. Nobody would have known if I'd let it slide. I would have.",
	},
	["org.quest_complete.w18.oath.002"] = {
		"My word was given and my word is kept. That's all the ceremony I need.",
		"Asked, promised, done. Mark it however you mark these things.",
		"I gave my word. You'll find it right where I left it: kept.",
	},
	["org.quest_complete.w18.oath.003"] = {
		"presses a closed fist briefly to the chest as the work is declared done, a plain gesture that asks for no answer.",
		"touches knuckles to the chest once, the way the grunts at the gate do when a watch passes from one pair of hands to the next.",
		"lays a hand flat over the heart for the space of a nod, then lets it fall and turns back toward the street.",
	},
	["org.quest_complete.w18.oath.004"] = {
		"Honor in Orgrimmar is loud: banners, oaths, names shouted across the Valley of Honor. Mine is quieter. It looks like a job finished when nobody was watching.",
		"The Valley of Honor gets the trainers and the shouting. The quiet kind of honor is done in errands like this one, and nobody keeps a tally.",
		"Plenty of banners in this city for the honor that gets noticed. None for this kind, which is fine. It was never done for a banner.",
	},
	["org.quest_complete.w18.oath.005"] = {
		"Save the thanks for something I didn't promise.",
		"No need for thanks. I'd said yes; this is what yes looks like.",
		"Thanks are for favors. This was a promise.",
	},
	["org.quest_complete.w18.oath.006"] = {
		"The grunts at the gate say that in the internment camps a word was the only thing an orc still owned, so it had to be good. The habit outlived the camps. I can see why.",
		"An old grunt in the Valley of Strength tells it plainly: behind the humans' fences, a promise was all anyone had left to trade. Orgrimmar still deals in that coin, and I've just paid in it.",
	},
	["org.quest_complete.w18.oath.007"] = {
		"waits a moment after the thanks, as if to be sure nothing was left half done, then nods and lets the matter go.",
		"lingers long enough to hear that everything is in order, and only then turns away.",
		"asks one short question to be certain the job is complete, hears that it is, and seems to set something down.",
	},
	["org.quest_complete.w18.oath.008"] = {
		"The Horde asked. The Horde got it. That's the whole of it.",
		"Whatever the Horde needs carried, I carry. Put my name down.",
		"Gladly, for the Warchief's city. Who's next?",
	},
	["org.quest_complete.w18.oath.009"] = {
		"I promised a stranger I'd do a thing, and I did it, and I still don't know why it mattered so much. A word kept blind is still a word kept.",
		"I never asked what it was for. I only said I'd do it. Maybe that's the most honest kind of promise there is, or the most foolish.",
	},
	["org.quest_complete.w18.oath.010"] = {
		"settles the matter with a short nod and a look held a moment longer than politeness needs: the look of a debt closed on both sides.",
		"meets the eyes of the one who gave the work, and holds them long enough to make it plain the account is square.",
	},
	["org.quest_complete.w18.oath.011"] = {
		"Honor is cheap in Orgrimmar: everyone has it, everyone talks about it. The rare thing is someone who shows up when they said they would.",
		"Half the voices in this city will tell you about honor. Fewer will tell you they finished the job they took. I'd rather be one of the few.",
		"Talk of honor costs nothing in these streets, and there's plenty of it going. Finished work is the scarcer coin.",
	},
	["org.quest_complete.w18.oath.012"] = {
		"You trusted me with it. That's worth more than the pay, and I won't say it twice.",
		"You took my word without a second look. I don't forget that kind of trust.",
		"Your trust was the heavy part. The rest was just work.",
	},
	["org.quest_complete.w18.oath.013"] = {
		"Serving the Horde, most of the time, looks exactly like this: a task, a report, a nod. The songs leave that part out.",
		"Nobody pledges to the Horde for errands. Then the errands turn out to be most of it, and the word holds anyway.",
		"Oaths to the Horde are sworn loudly and kept quietly. This was one of the quiet parts.",
	},
	["org.quest_complete.w18.oath.014"] = {
		"is answered with a stiff, formal salute, as though the errand had been a matter of state, and returns it just as stiffly.",
		"receives the thanks standing very straight, and a grunt nearby straightens too, without quite knowing why.",
	},
	["org.quest_complete.w18.oath.015"] = {
		"My word is kept. Whether it was a word worth giving, I'll find out later, if ever.",
		"I did exactly what I promised. Whether I should have promised it is a question for a quieter place.",
		"Kept, every bit of it. Keeping a promise is simple. Knowing it was the right one to make never is.",
	},
	["org.quest_complete.w18.oath.016"] = {
		"Promised, delivered. I'd swear an oath on it, but I've already done the hard part.",
		"There. A promise kept, in Orgrimmar, without anyone shouting. Mark the date.",
		"Oath fulfilled. I'd like that engraved, but a nod will do.",
	},
	["org.quest_complete.w18.oath.017"] = {
		"The shamans in the Valley of Spirits say the earth remembers every step taken on it. If it keeps track of promises as well, it has one more kept one.",
		"A troll in the Valley of Spirits swears the loa hear every promise said aloud. They'll have heard this one end well.",
	},
	["org.quest_complete.w18.oath.018"] = {
		"pulls a creased scrap of paper from a pouch, strikes out one line on it, and tucks it away.",
		"crosses one item off a short, much-folded list, and looks at what remains with a certain grimness.",
		"unfolds a worn list, finds the right line, and draws a careful mark through it with a stub of charcoal.",
	},
	["org.quest_complete.w18.oath.019"] = {
		"Small job, same honor. Nobody gets to weigh it but me.",
		"A small thing, done properly. That's where honor lives, mostly.",
		"Honor doesn't check the size of the job first.",
	},
	["org.quest_complete.w18.oath.020"] = {
		"Thrall broke the camps open and asked only that the orcs stand by each other as free people. Small work like this is how I keep my end of that.",
		"There was a time orcs worked because a human with a whip said so. Now I work because I gave my word. It looks the same from outside. It is nothing alike.",
	},
	["org.quest_complete.w18.oath.021"] = {
		"Between us, the account is square. If that changes, you know my name.",
		"Nothing owed either way now. That's how I like to leave a door.",
		"Square, both sides. I like a clean slate.",
	},
	["org.quest_complete.w18.oath.022"] = {
		"Nobody asked how it went, only whether it was done. Honor answers the second question. The first one I keep for myself.",
		"Done is what they wanted to hear. How it was done is mine to carry, and I'd carry it the same way twice.",
		"They wanted the result. The manner of it was never on the table, and that's the part I'd sign.",
	},
	["org.quest_complete.w18.oath.023"] = {
		"closes the matter as the light leaves the canyon walls, and stands a while in the deepening red, the way some stand at the end of a vigil.",
		"finishes the business while the last light slides up the canyon walls, and does not move until it has gone.",
	},
	["org.quest_complete.w18.oath.024"] = {
		"I don't do things by halves. Ask anyone who's given me work.",
		"Half a job is a broken promise with better manners. This one's whole.",
		"Whole, start to finish. Halves I leave to the butchers on the Drag.",
	},
	["org.quest_complete.w18.oath.025"] = {
		"The pay will be spent soon enough. What stays is that I did what I said. That doesn't spend.",
		"Coin runs out. A kept word doesn't; it just sits there, being true.",
		"Give the purse a week and it'll be empty. The promise kept will still be kept long after that.",
	},
	["org.quest_complete.w18.purse.001"] = {
		"Blackened copper, goblin silver, and one coin with a stamp nobody in this city could read. The stalls take all of it the same.",
		"Mixed coin, as ever in Orgrimmar: worn copper, bright silver, and one odd piece from who knows where. Every stall takes every kind.",
		"Copper with a hole punched through, silver clipped at the edge, a coin rubbed blank. Pay in this city arrives with a history of its own.",
	},
	["org.quest_complete.w18.purse.002"] = {
		"tests one coin of the pay between the teeth, out of plain habit, and earns a pained look from a passing goblin who plainly considers that his trade.",
		"bites a coin from the reward to check it, and a goblin nearby winces as if somebody had just bitten him.",
		"sets a coin of the pay between the back teeth and bites down, then inspects the dent with the air of an expert.",
	},
	["org.quest_complete.w18.purse.003"] = {
		"I count the pay by touch, eyes on the street: rough and thin is copper, smooth and heavier is silver. The fingers know before I do.",
		"Counted without a glance. The hand knows copper from silver by the edge alone, and keeps the eyes free for the crowd.",
		"No need to look down. My thumb sorts the coins inside the pouch while I watch who's watching me.",
	},
	["org.quest_complete.w18.purse.004"] = {
		"One, two... hm. No, it's all there. I just can't count with a drum going.",
		"Wait, one short. No. My mistake. Counting in this racket is a skill I don't have.",
		"Hold on, let me count. Somebody stop that hammer for a moment.",
	},
	["org.quest_complete.w18.purse.005"] = {
		"Paid in the open, counted aloud, pressed into the palm. This city hides a great deal, but never the price.",
		"No envelope, no whisper: the coins come out in plain sight and land in my hand with a slap. Orgrimmar pays the way it argues, out loud.",
		"Nobody in this city slips you coin under a cloak. It gets counted where everyone can see, and that suits me.",
	},
	["org.quest_complete.w18.purse.006"] = {
		"lets the coins run from palm to pouch one by one, listening to each land, and only then pulls the string tight.",
		"pours the pay into the pouch slowly, so that the clink of every piece can be heard, and knots it with a tug.",
		"drops the reward into the pouch piece by piece, giving each coin its own small moment, then draws the string closed.",
	},
	["org.quest_complete.w18.purse.007"] = {
		"Spent already, in my head: new soles for the boots, a hot meal, a strap mended. The coins haven't been told.",
		"Before the purse is even shut, the money has gone in my head to a cobbler, a cook and a leatherworker in the Drag. The real coins will catch up.",
		"This pay has three jobs ahead of it: boots, a bowl of something, a buckle. Nobody has warned it.",
	},
	["org.quest_complete.w18.purse.008"] = {
		"Maybe the first coin of this should go to somebody with less. In Orgrimmar that somebody is never more than a few steps away.",
		"There's always a peon with an empty bowl within sight in this city. One coin of the pay could find its way there.",
		"A single coin of this would feed a peon for a good while. I'm wondering which peon.",
	},
	["org.quest_complete.w18.purse.009"] = {
		"moves the pouch from the belt to inside the shirt, where a crowded street will have to work much harder for it.",
		"shifts the reward to an inner pocket with one quick movement, the kind learned in crowds, and keeps a hand over it a moment longer.",
		"slides the pouch round to the front of the belt, where it can be seen and, more to the point, felt.",
	},
	["org.quest_complete.w18.purse.010"] = {
		"Pay weighs more than metal ought to. Part of it is trust, and trust is the heavier coin to carry.",
		"The pouch hangs heavier than the coins inside can explain. Some of that is the city deciding I can be relied on.",
		"Coin is coin. This lot has a little of the city's faith in me folded inside, and that part is harder to spend.",
	},
	["org.quest_complete.w18.purse.011"] = {
		"The auction house will take its cut of anything I sell, the inn its share of anything I drink. Pay is the only coin in Orgrimmar that reaches me with nobody's hand already in it.",
		"Most coin in this city reaches me thinned: a cut here, a fee there. Pay for honest work is the one kind that arrives whole.",
	},
	["org.quest_complete.w18.purse.012"] = {
		"The Horde pays fairly and never twice. Fair is plenty. Twice would make me wonder what else it wanted.",
		"Not generous, not mean: the Horde pays what the work was worth and not a copper over. I respect a side that knows its prices.",
		"No bonus, no haggling, no favors slipped in with the coin. The Horde pays the price it named, and that is the whole of its kindness.",
	},
	["org.quest_complete.w18.purse.013"] = {
		"tips the reward into one palm for a quick look, then tips it back before anyone in the street can put a price on it.",
		"opens the pouch a finger's width, peers in, and shuts it again as a hawker's head turns this way.",
		"glances into the pouch the way a card player glances at a hand, and gives nothing away.",
	},
	["org.quest_complete.w18.purse.014"] = {
		"I've stopped counting the pay in front of whoever hands it over. Here that reads as an insult. Three steps into the street, it reads as good sense.",
		"Count it under the giver's nose and you've called somebody a cheat. Count it out in the street and you're merely careful. Manners in Orgrimmar are a matter of a few steps.",
		"Never count it while the giver watches; always count it before the next corner. Two rules of this city, and I've broken neither.",
	},
	["org.quest_complete.w18.purse.015"] = {
		"shakes the pouch beside one ear, listening the way a goblin listens to an engine, and nods at whatever the rattle has to say.",
		"gives the purse a small jingle next to the ear, head tilted, like a tinker judging a gear by its noise.",
		"bounces the pouch twice on two fingers, like a cook judging a melon, with an expression that says it will do.",
	},
	["org.quest_complete.w18.purse.016"] = {
		"Let's see. Hm. Good. Now watch me look unimpressed; it helps with the haggling later.",
		"I'll pocket this with a straight face. Looking pleased in this city only raises prices.",
		"Not a smile, see? Smile at your pay in Orgrimmar and every stall hears of it before the next corner.",
	},
	["org.quest_complete.w18.purse.017"] = {
		"Hear that? Earned coin. It rings different from found coin, I swear it does.",
		"Listen to it. Coin you worked for has a better ring than coin you picked up off the ground.",
	},
	["org.quest_complete.w18.purse.018"] = {
		"That keeps my good name paid up for a while.",
		"There. My good name's rent is covered for another stretch.",
		"Good. That's my standing in this city topped up.",
	},
	["org.quest_complete.w18.purse.019"] = {
		"However small the pay, I count it. Small coin is still the city saying somebody noticed.",
		"Large or small, pay means the same thing in a capital this busy: somebody stopped long enough to look.",
		"I never sneer at the size of it. In a city of this many hands, being paid at all is being seen.",
	},
	["org.quest_complete.w18.purse.020"] = {
		"counts the pay by the fire of a brazier, the coins turning red one after another in the palm.",
		"turns the coins of the reward over beside a brazier, each one flaring red as it catches the fire, while the dark sits close around.",
	},
	["org.quest_complete.w18.purse.021"] = {
		"In the camps an orc's work was paid in thin gruel and an overseer's stick. Here the coin goes into my own hand. I don't take that lightly, whatever the sum.",
		"Orcs once labored behind human fences for nothing, the old ones say. Now an orc is paid in an orc city. Small coin, large difference.",
		"No chain, no overseer, no fence: just work, and pay for it, put into an orc's hand by the Horde. The elders would call that the whole point.",
	},
	["org.quest_complete.w18.purse.022"] = {
		"The pouch has barely closed and a goblin trader two stalls down has straightened his wares. Somehow they always know.",
		"No sooner is the pay away than some merchant in earshot clears a throat and raises the price of everything. Coin in this city carries a scent.",
		"Every hawker within earshot has just found something that's exactly my size. Funny how pay changes the street.",
	},
	["org.quest_complete.w18.purse.023"] = {
		"Paid to the copper. I like dealing with people who can count.",
		"Not a coin missing. Whoever minds the purse in this city knows the job.",
		"Sums right. Somebody in this city keeps honest books.",
	},
	["org.quest_complete.w18.purse.024"] = {
		"This coin has been through a hundred hands: a smith's, a grunt's, some goblin's. Mine now, for a little while. Nothing in Orgrimmar stays put, not even money.",
		"Worn smooth by other palms, this pay. Every piece has crossed the city more often than I have, and it will leave me sooner than I'd like.",
	},
	["org.quest_complete.w18.purse.025"] = {
		"Keep one coin of that back for the war chest. I'll manage on the rest.",
		"Half the Horde's coin goes to the walls anyway. I'm only borrowing mine for a while.",
	},
	["org.quest_complete.w18.purse.026"] = {
		"Feels right in the hand. Sounds right in the pouch. Good.",
		"Right weight, right sound. No complaints from me.",
	},
	["org.quest_complete.w18.purse.027"] = {
		"ties off the purse with a double knot, the kind that annoys honest owners and defeats quick fingers, and gives it a pat.",
		"knots the pouch twice and tucks the loose end under, a small fortification for a small fortune.",
	},
	["org.quest_complete.w18.quip.001"] = {
		"Before you say it: yes, I know there's more. There's always more.",
		"Let me guess. The next job is standing right behind this one.",
		"Don't tell me. Somebody else needs something, and they need it from me.",
	},
	["org.quest_complete.w18.quip.002"] = {
		"Can I count it first? No? Fine. What's the next one?",
		"You're handing me the next job with the same hand that paid me. Very efficient.",
		"I'd ask for a moment to enjoy this, but I can see the next job forming on your lips.",
	},
	["org.quest_complete.w18.quip.003"] = {
		"Anyone else comes looking for me, I've moved to Razor Hill. For good.",
		"If there's more work, say you couldn't find me. Orgrimmar's big enough that they'll believe it.",
		"Should anybody ask, I left the city in a great hurry. Toward the Barrens, say. Far into the Barrens.",
	},
	["org.quest_complete.w18.quip.004"] = {
		"Was that a smile? Careful. If the grunts see it, they'll start asking questions.",
		"Easy with the gratitude. People in this city talk over much less.",
	},
	["org.quest_complete.w18.quip.005"] = {
		"Whatever comes next, it comes after a chair. Those are my terms.",
		"The next job is welcome, once I've found a bench. Not one moment sooner.",
		"Happy to help again. Seated, first, for a little while.",
	},
	["org.quest_complete.w18.quip.006"] = {
		"Do I look like I need more walking? Don't answer that.",
		"More walking? My boots have filed a complaint.",
	},
	["org.quest_complete.w18.quip.007"] = {
		"The pleasure's mine. Well, the pleasure's in the purse, but it's mine.",
		"Always nice working with you. The paying bit, especially.",
		"Lovely working together. I'm fondest of the end, where the coin is.",
	},
	["org.quest_complete.w18.quip.008"] = {
		"Skip the speech. Point me at the bank before someone hands me another job.",
		"Thanks, yes. Now which way is the bank, before more work finds me?",
	},
	["org.quest_complete.w18.quip.009"] = {
		"I'm choosing to hear that grunt as a thank-you.",
		"That noise you made: I'm filing it under gratitude.",
		"Was that a word or a growl? Either way, you're welcome.",
	},
	["org.quest_complete.w18.quip.010"] = {
		"If that was one of your easy ones, keep the hard ones for somebody else.",
		"That was the simple job? Then I'll pass on the complicated ones, thanks.",
	},
	["org.quest_complete.w18.quip.011"] = {
		"Three words of thanks. In Orgrimmar that's practically an oration.",
		"That's the longest thank-you I've had in this city. Four words, I think.",
	},
	["org.quest_complete.w18.quip.012"] = {
		"If you'll excuse me, I'm off to be useful somewhere else. Apparently that's my trade now.",
		"Excuse me. Somewhere in this city someone needs a thing carried, and I can feel it.",
	},
	["org.quest_complete.w18.quip.013"] = {
		"Remember the face. And remember the price, while you're at it.",
		"Next time you see me, the rate's gone up. Just so you know.",
		"Lovely. My fee rises with every slope I climb, by the way.",
	},
	["org.quest_complete.w18.quip.014"] = {
		"Is there a bonus for every grunt who shouted at me on the way? There should be.",
		"I was told to move more than once just getting this far. Somebody ought to pay for that too.",
	},
	["org.quest_complete.w18.quip.015"] = {
		"Keep your voice down when you pay. Goblins hear coin through stone walls.",
		"Softly with the coins. Somewhere close, a goblin just pricked up his ears.",
		"Quietly, please. Jingle a purse in Orgrimmar and three hawkers turn around.",
	},
	["org.quest_complete.w18.quip.016"] = {
		"Tell me the next one is close by. Lie, if you must.",
		"Is the next job near? Say yes. I don't care whether it's true.",
	},
	["org.quest_complete.w18.quip.017"] = {
		"Go on, point me somewhere. I can see the finger's already up.",
		"Where to now? You've got that look. The pointing look.",
		"I know that face. That's the face of somebody about to say 'and while you're at it'.",
	},
	["org.quest_complete.w18.quip.018"] = {
		"Pleasure. Now forget my name until you've got something that pays better.",
		"Glad to help. Don't remember me too quickly.",
	},
	["org.quest_complete.w18.quip.019"] = {
		"Does this get me a discount at the inn? No? Worth a try.",
		"I don't suppose finishing that earns me a free meal anywhere. No. I'll keep asking.",
		"Any chance the innkeeper hears about this and knocks something off? I'll mention it myself.",
	},
	["org.quest_complete.w18.quip.020"] = {
		"Same time next week, then? That was a joke. Probably.",
		"Shall I just stop by every week? I'm only half joking.",
	},
	["org.quest_complete.w18.quip.021"] = {
		"No fanfare? Good. I'd only have had to stand still for it.",
		"No drums for me? Just as well. My legs want to keep moving before they change their minds.",
	},
	["org.quest_complete.w18.quip.022"] = {
		"Tell whoever's next they'll have to wait until I've had a sit. Then they can wait some more.",
		"There's a queue for me now? Wonderful. It can stand at the back of my queue for a chair.",
	},
	["org.quest_complete.w18.thanks.001"] = {
		"Thanks in Orgrimmar come without a smile, and the handshake tests the grip. I think I passed.",
		"No smile with the thanks, just a hand that squeezed hard enough to check whether mine would squeeze back. It did. That seemed to settle something.",
	},
	["org.quest_complete.w18.thanks.002"] = {
		"Nobody in this city says thank you the way the words sound anywhere else. They say 'good,' or 'that's that,' and leave the rest to the eyes.",
		"'Good.' That was the whole of it, one word, and the eyes said the rest. Orgrimmar teaches you to hear thanks in very short sentences.",
		"I've been thanked here with a grunt, a jerk of the chin, and once with the word 'adequate.' That last one was nearly a song.",
	},
	["org.quest_complete.w18.thanks.003"] = {
		"Was that a thank you? I'm counting it as one.",
		"I'll take that grunt as gratitude. Don't correct me.",
		"Hm. In most places that noise would be a cough. Here I think it was thanks.",
	},
	["org.quest_complete.w18.thanks.004"] = {
		"is thanked in a single word, in a voice better used to giving orders, and seems to find it more than enough.",
		"receives a thanks of one syllable from a voice made for barking orders, and holds on to every bit of it.",
		"is handed thanks the way this city hands out everything: quickly, firmly, and without wrapping.",
	},
	["org.quest_complete.w18.thanks.005"] = {
		"Thanks here are short because nobody has time for long ones. Long thanks would mean someone had an idle moment, and Orgrimmar would never admit to that.",
		"The city keeps its gratitude brief, like everything else. A capital that stopped to thank you properly would stop being busy, and it couldn't bear that.",
		"Gratitude in Orgrimmar is shaped like its streets: narrow, uphill, and over before you know it.",
	},
	["org.quest_complete.w18.thanks.006"] = {
		"The Darkspear in the Valley of Spirits say a thanks counts twice: once when it's spoken, once when the face is remembered. I hope mine gets the second half.",
		"Around the Valley of Spirits they say thanks are paid in two coins, the word and the remembering. The word I've had. The other comes later, if it comes.",
		"A Darkspear saying, as the trolls tell it: the word is the first payment and the memory is the second. I've had the first.",
	},
	["org.quest_complete.w18.thanks.007"] = {
		"Tauren thanks come slowly, with the Earth Mother in them somewhere. Orc thanks come fast, with a clap on the back that leaves a mark. This city can hand you both before you've turned around.",
		"Some thank you with a slow rumble and a long look, some with a thump on the shoulder, some with a dry Forsaken murmur. Orgrimmar has every kind of thanks, and none of them gentle.",
	},
	["org.quest_complete.w18.thanks.008"] = {
		"answers the gruff thanks with an equally gruff nod; by Orgrimmar standards, a long conversation has just taken place.",
		"trades one curt word for another, and the business is closed with all the warmth this city keeps for its friends.",
		"gives back a grunt for a grunt, and the exchange is complete; nothing more is needed in this city, nor wanted.",
	},
	["org.quest_complete.w18.thanks.009"] = {
		"The truest thanks in this city isn't a word. It's the next job, offered without anyone asking whether I'm free.",
		"Words are cheap in Orgrimmar and nobody spends them. Trust is dear, and it arrives as more work. I'll take that as the compliment it is.",
		"Gratitude here doesn't get said, it gets assigned. If they trust you, there's always another task waiting with your shape on it.",
	},
	["org.quest_complete.w18.thanks.010"] = {
		"You're welcome. You could try the words sometime; they don't bite.",
		"My pleasure. Next time a thanks is allowed. Out loud, even.",
		"No need to look so pained. It's only a thank you; it won't kill you.",
	},
	["org.quest_complete.w18.thanks.011"] = {
		"Here gratitude isn't spoken, it's paid. The coin is how Orgrimmar clears its throat before saying nothing at all.",
		"A city of few words thanks you with its purse. I've heard worse speeches.",
		"Here the purse does the talking and the mouth stays shut. I've learned to listen to the purse.",
	},
	["org.quest_complete.w18.thanks.012"] = {
		"A fist knocked once against a chest, and two words: strength, honor. The Horde has no warmer thanks than that, and needs none.",
		"'Strength and honor.' Short, the way the Horde likes things. I'll carry it out into the street like a second purse.",
		"No speech, only the old salute of the Horde, fist to chest. It went in deeper than any speech would have.",
	},
	["org.quest_complete.w18.thanks.013"] = {
		"hears the words 'good work' said exactly once and without decoration, and seems to put them away somewhere careful.",
		"is told the work was good, plainly, once, and stands a moment as if letting the words settle before moving on.",
		"stands quite still while two plain words of praise are said, then dips the head like someone receiving something small and solid.",
	},
	["org.quest_complete.w18.thanks.014"] = {
		"I'd braced myself for a lecture on how it should have been done. None came. In this city a skipped lecture is the gentlest kind of praise.",
		"No correction, no 'next time, do it like this.' From Orgrimmar, that silence is nearly a hug.",
	},
	["org.quest_complete.w18.thanks.015"] = {
		"Once is enough. You said it loud enough for the whole street to hear.",
		"Say it again and the guards will start thinking there's friendship between us.",
	},
	["org.quest_complete.w18.thanks.016"] = {
		"A word of thanks lasts about as long as its echo off the canyon walls. Then the walls go back to their own business.",
		"The thanks rang off the red walls once and were gone into the city's racket. I'll keep them a little longer than the rock did.",
	},
	["org.quest_complete.w18.thanks.017"] = {
		"When one of the grizzled orcs of this city tells you that you did well, keep it. They don't spend words they'd have to take back.",
		"Praise from an old orc of Orgrimmar is rare and never decorative. If one of them says the job was good, it was.",
	},
	["org.quest_complete.w18.thanks.018"] = {
		"accepts the thanks in the dim of a room cut into the rock, where the street arrives only as a low rumble through the walls.",
		"is thanked in the cool shade of a rock-cut room, the clamor of the city shrunk to a hum beyond the doorway.",
	},
	["org.quest_complete.w18.thanks.019"] = {
		"Lok'tar. When the Horde needs hands again, you know where to find mine.",
		"Lok'tar ogar. Send for me next time; I'll come.",
	},
	["org.quest_complete.w18.thanks.020"] = {
		"is thanked, and then thanked again by a bystander who had nothing whatever to do with the business but liked the look of it.",
		"collects the expected thanks and an unexpected one from a passing grunt, who apparently felt the moment needed a witness.",
	},
	["org.quest_complete.w18.thanks.021"] = {
		"Nobody said please when the job was handed over, so I didn't expect thanks at the end. I got some anyway. Orgrimmar keeps surprising me in small ways.",
		"No please at the start, so I wasn't counting on thanks at the finish. This city has a habit of paying in the coin you didn't ask for.",
	},
	["org.quest_complete.w18.thanks.022"] = {
		"Thanks accepted. I'll spend it somewhere before it goes cold.",
		"Gratitude received and pocketed. I hope it keeps better than bread.",
	},
	["org.quest_complete.w18.thanks.023"] = {
		"Thanks said in the rain come quick, and nobody minds. Folk who live in Durotar don't waste a shower on talking.",
		"The thanks were short, and every eye was on the rain while they were said. In a dry land the sky gets the attention first.",
	},
	["org.quest_complete.w18.thanks.024"] = {
		"Thanked without the other's eyes leaving the work at hand. In Orgrimmar that isn't rudeness: whoever gives out jobs here has three more waiting.",
		"Not one glance up from the next task while the thanks were said. Busy hands in this city don't stop for courtesy, and I don't hold it against them.",
	},
	["org.quest_complete.w18.thanks.025"] = {
		"Any time. Well, most times. Ask nicely and any time.",
		"Happy to. Next time, a smile with it, if the city can spare one.",
		"Glad to be of use. Don't let it get around; everyone will want a turn.",
	},
	["org.quest_complete.w18.thanks.026"] = {
		"Don't mention it. Really, don't; people will start expecting it of me.",
		"No thanks needed. A good word in the right ears would do nicely, though.",
	},
	["org.quest_complete.w18.thanks.027"] = {
		"That's the warmest grunt anyone in this city has given me. I'm touched.",
		"Careful, that almost sounded friendly. People will talk.",
	},
	["org.quest_complete.w18.thanks.028"] = {
		"hears the thanks cut in half by a crack of thunder between the canyon walls, and nods at the half that arrived.",
		"accepts the reward as thunder rolls from wall to wall above the city, and the thanks are left to be guessed at.",
	},
	["org.quest_complete.w18.throng.001"] = {
		"A job finished, and not one head turns. A grunt yawns, a goblin counts, a tauren steps over somebody's wolf. Exactly right.",
		"Nobody looks round. The peons haul, the hawkers bawl, a troll somewhere laughs at something else entirely. Good.",
		"The city's verdict on my finished work: a yawn from a grunt and a hiccup from a kodo. I'll take it.",
	},
	["org.quest_complete.w18.throng.002"] = {
		"rejoins the crowd and is carried a few steps by it, one more shoulder among hundreds, nobody the wiser.",
		"melts back into the press of the street, where a finished task looks exactly like an unfinished one.",
		"slips into the moving crowd and is gone inside it, as unremarkable as a pebble dropped in a stream.",
	},
	["org.quest_complete.w18.throng.003"] = {
		"Somewhere a bard would make a song of this. Here, a peon just trod on my foot and didn't apologize.",
		"Somebody ought to clap. Instead, a kodo has just sneezed on me.",
		"In a story there'd be a crowd cheering now. In Orgrimmar there's a crowd, and it's cheering a dogfight two streets over.",
	},
	["org.quest_complete.w18.throng.004"] = {
		"I like being nobody in particular in a crowd this size. The work is done, and the city keeps it the way it keeps everything: without looking.",
		"Hundreds of people, and not one of them knows what I've just finished. It feels like a coin kept in a boot.",
		"Anonymous again, and glad of it. A finished task is a better secret than most.",
	},
	["org.quest_complete.w18.throng.005"] = {
		"is elbowed aside by a goblin in a hurry, who mutters something about time being money and never looks back.",
		"gets a long, unimpressed look from a wolf sprawled across the road, which then goes back to sleep.",
		"is overtaken by a troll with a crate on each shoulder, who hums the whole way past and sees nothing but the road ahead.",
	},
	["org.quest_complete.w18.throng.006"] = {
		"Don't all cheer at once.",
		"Easy, everyone. Try to contain yourselves.",
		"No, no, please. Keep your applause. All of it.",
	},
	["org.quest_complete.w18.throng.007"] = {
		"Everyone in this street is carrying something finished or something unfinished, and from the outside nobody can tell which. I'm in good company.",
		"Half this crowd has just finished something too, I'd wager. Nobody announces it. Maybe that's the custom.",
		"How many of these people just did a small thing for the city and walked off unthanked? Most of them, by the look of their shoulders.",
	},
	["org.quest_complete.w18.throng.008"] = {
		"watches a pair of grunts on patrol walk straight past without a glance, which in this city is close to a compliment.",
		"feels the eyes of a passing patrol settle for one moment, decide there is no trouble here, and move on.",
		"is measured by a grunt at a post from boots to brow, briefly, and then the grunt finds something more interesting to stare at.",
	},
	["org.quest_complete.w18.throng.009"] = {
		"One old orc by the wall caught my eye and nodded, as if he knew exactly what I'd been up to. He didn't. It was kind of him anyway.",
		"Of all the crowd, only a small troll noticed me, and only to ask whether I had anything to eat.",
		"A tauren carrying water gave me a slow look and the smallest of nods. Out of the whole city, that was the one witness.",
	},
	["org.quest_complete.w18.throng.010"] = {
		"Back into the crush, then. Make room, it's only me.",
		"Shove over, Orgrimmar. One more coming through.",
		"Mind your elbows, everybody. Mine are coming.",
	},
	["org.quest_complete.w18.throng.011"] = {
		"The street swallows the moment whole and goes on chewing.",
		"Three steps into the crowd and the thing I finished is already as small as I am.",
		"One turn of the street and the matter is lost among a thousand others, like a single copper tipped into a goblin's till.",
	},
	["org.quest_complete.w18.throng.012"] = {
		"is nearly flattened by a peon pushing a barrow of ore, who has a task of his own and no patience for anyone else's.",
		"steps out into the traffic of the street and becomes, in a moment, an obstacle to a dozen people with errands of their own.",
	},
	["org.quest_complete.w18.throng.013"] = {
		"No fanfare. The Horde doesn't stop for its own small work, and I wouldn't want it to: better one of the many hands than the one everyone stares at.",
		"The Horde walks past what I did without a glance, the way a body ignores a hand doing its job. That's how I know I'm part of it.",
	},
	["org.quest_complete.w18.throng.014"] = {
		"passes a knot of traders bellowing about prices; not one of them so much as looks up.",
		"threads past a ring of onlookers watching two orcs arm-wrestle on a barrel; every eye is on the barrel, none on the passer-by.",
		"skirts a group of tauren deep in slow conversation, who shift aside without a pause in it.",
	},
	["org.quest_complete.w18.throng.015"] = {
		"I could tell you all what I just did. You'd nod and go back to hammering.",
		"Not one of you asked how it went. I've a good mind to tell you anyway.",
		"Ask me how it went. Anybody. No? Fine, I'll tell a wolf.",
	},
	["org.quest_complete.w18.throng.016"] = {
		"Excuse me. Finished my own business, and now I'm in the way of everyone else's.",
		"Sorry. Out of one errand and straight into your elbow.",
		"Pardon. Passing through. Nothing to see, I promise.",
	},
	["org.quest_complete.w18.throng.017"] = {
		"In the crowd somebody is telling the tale of a job of their own, louder and better than I ever would. I let them have it.",
		"Two orcs beside me are boasting about some errand of theirs. It grows a little with every telling. Mine can stay its real size.",
	},
	["org.quest_complete.w18.throng.018"] = {
		"is bumped from behind, then from the side, and takes both bumps as all the ceremony the city has to offer.",
		"takes an elbow in the ribs from a passing tauren, and then a sorry rumbled from somewhere far above.",
	},
	["org.quest_complete.w18.throng.019"] = {
		"The goblins are the only ones who noticed. Not me, mind: my coin.",
		"If anyone in this crowd noticed, it was a goblin, and he noticed the coin, not whoever carries it.",
		"Not a soul looked up, except a goblin, who looked at my belt pouch with real affection.",
	},
	["org.quest_complete.w18.throng.020"] = {
		"Nobody look. It's done, that's all.",
		"Nothing to see. Move along, same as me.",
		"Go about your business. I've finished mine.",
	},
	["org.quest_complete.w18.throng.021"] = {
		"Under a roof, the talk goes on without a pause for me. Every corner has its own business, and none of it is mine.",
		"In here the voices don't even dip. Everyone's busy with their own affairs, and nobody minds me among them.",
	},
	["org.quest_complete.w18.throng.022"] = {
		"steps out among people crowded under the awnings, all watching the rare rain and not one of them watching {g:him|her}.",
		"finds the whole street gathered at the eaves to stare at the rain, and slips along behind their backs unseen.",
	},
	["org.quest_complete.w18.throng.023"] = {
		"If I fell over right now, three of you would step around me and one would try to sell me a bandage.",
		"The only way to get noticed in this city is to stand in a doorway. Tempting.",
	},
	["org.quest_complete.w18.trudge.001"] = {
		"Whoever planned Orgrimmar put the one with a job at one end and the one who wants it done at the other. Every time.",
		"There's a rule in this city, I'm sure of it: whoever hands out the work and whoever waits for it must never live in the same valley.",
		"Every errand in Orgrimmar seems to have been laid out by somebody who hated short walks.",
	},
	["org.quest_complete.w18.trudge.002"] = {
		"My knees have learned every ramp in this city, and they've an opinion about each one.",
		"There's no slope in Orgrimmar my knees haven't complained about. They're thorough.",
		"My knees and I are no longer on speaking terms. Orgrimmar's slopes came between us.",
	},
	["org.quest_complete.w18.trudge.003"] = {
		"leans on the nearest post the moment the business is closed, and looks down the long street with the face of someone counting steps.",
		"props one shoulder against a timber beam once the reckoning is done, and eyes the slope ahead as if it had been rude to {g:him|her}.",
		"finds a wall to lean on before the thanks are even finished, and stays there a little longer than the thanks.",
	},
	["org.quest_complete.w18.trudge.004"] = {
		"The coin isn't even in my pouch and I already know where I'm wanted next. The far end of the city, naturally.",
		"Before I could tie the purse shut, someone mentioned the next errand. On the other side of Orgrimmar, of course.",
	},
	["org.quest_complete.w18.trudge.005"] = {
		"I know Orgrimmar now, though not the way the histories tell it: the shortcuts, the loose steps, the stalls that never get out of the way.",
		"What I know of this city isn't its history. It's which alleys save a hundred paces, and which ones only pretend to.",
		"Ask me about the founding of Orgrimmar and I'll shrug. Ask me which stone wobbles on the way to the bank and I'll draw you a picture.",
	},
	["org.quest_complete.w18.trudge.006"] = {
		"flexes one foot inside its boot, then the other, the small inventory of someone who walks Orgrimmar for a living.",
		"rolls each ankle in turn once the reward is handed over, slowly, as if checking that both still take orders.",
		"works {g:his|her} toes inside the boots once the reward is stowed, a quiet check that everything down there is still reporting for duty.",
	},
	["org.quest_complete.w18.trudge.007"] = {
		"There's one step on the way to the Valley of Honor that I trip over every single time. I think of it as a colleague now.",
		"This city has a loose stone that knows my boot by now. We greet each other the same way every trip.",
	},
	["org.quest_complete.w18.trudge.008"] = {
		"The work I don't mind. It's the walking in between, and Orgrimmar is mostly in between.",
		"Jobs are short. The city is long. I'm paid for the first and I live in the second.",
		"Nobody pays for the distance between one task and the next, and in this city the distance is most of it.",
	},
	["org.quest_complete.w18.trudge.009"] = {
		"drops onto an upturned crate with the reward still in hand, and for a moment looks in no hurry to be anywhere.",
		"takes the weight off on the nearest crate, reward in lap, as the city goes on hurrying past without {g:him|her}.",
		"finds the edge of a stone step to sit on, reward on one knee, and lets the street flow around {g:him|her} for a moment.",
	},
	["org.quest_complete.w18.trudge.010"] = {
		"Nobody in Orgrimmar walks slowly. Try it, and a goblin with a handcart will teach you why.",
		"Strolling isn't done in this city. Everyone moves as if a sergeant were watching, and some of them are right.",
	},
	["org.quest_complete.w18.trudge.011"] = {
		"My shoulders know the job is over. My legs have heard there's more city to cross.",
		"The hands are finished. The feet suspect otherwise.",
		"Half of me has clocked off. Unfortunately it's the half that doesn't do the walking.",
	},
	["org.quest_complete.w18.trudge.012"] = {
		"Has anyone else noticed that every errand in Orgrimmar ends uphill? Every one.",
		"Uphill. It always ends uphill. Why does it always end uphill?",
	},
	["org.quest_complete.w18.trudge.013"] = {
		"From the bank down to the Cleft of Shadow and up again: I could walk it asleep. I suspect I sometimes do.",
		"I know the road between the Valley of Strength and the Valley of Wisdom so well my feet take it without consulting me.",
	},
	["org.quest_complete.w18.trudge.014"] = {
		"pockets the reward and, before anyone can mention another errand, becomes deeply interested in a crack in the wall.",
		"puts the reward away and studies the far end of the street with great care, the way people do when they hope not to be asked anything.",
		"tucks the reward out of sight and develops a sudden fascination with a passing kodo, eyes carefully elsewhere.",
	},
	["org.quest_complete.w18.trudge.015"] = {
		"Half the work in Orgrimmar is carrying words from one valley to another. The city is one long conversation, and I'm its legs.",
		"Somebody in the Valley of Spirits wants a word with somebody in the Valley of Honor, and neither of them will walk. That's where people like me come in.",
	},
	["org.quest_complete.w18.trudge.016"] = {
		"glances up the long slope ahead, then down the one behind, and seems unable to decide which of them is more personal.",
		"looks from one end of the street to the other once the business is done, with the air of someone who knows both ends far too well.",
		"considers the street in both directions and finds neither of them downhill.",
	},
	["org.quest_complete.w18.trudge.017"] = {
		"Light purse, wide city, and somebody somewhere already waiting on me. That's Orgrimmar's arithmetic.",
		"Small pay, long streets, and a queue of people who need a thing carried. The sums in this city never change.",
	},
	["org.quest_complete.w18.trudge.018"] = {
		"The ache in my legs has the shape of this city: long, steep, and full of sudden corners.",
		"I could map Orgrimmar from where my legs hurt. The long stretch is the Drag.",
		"My calves have their own map of the city, drawn in aches, and it's more accurate than the real one.",
	},
	["org.quest_complete.w18.trudge.019"] = {
		"Is there a single spot in Orgrimmar that isn't a long walk from everywhere else?",
		"Every corner of this city is the far corner. How is that even possible?",
	},
	["org.quest_complete.w18.trudge.020"] = {
		"closes the business as the canyon walls go a deep, tired red, and looks at the long way to the inn with resignation.",
		"takes the reward as the last light slides off the canyon rim, and the slope to the inn suddenly seems twice as long.",
	},
	["org.quest_complete.w18.trudge.021"] = {
		"Rain, in Orgrimmar of all places, and the ramps turn to red slick. Naturally the next job is at the top of one.",
		"The city's gone slippery with rain, and I've been finished a moment at most before someone points me up the steepest street.",
	},
	["org.quest_complete.w18.trudge.022"] = {
		"Walking this city leaves no room for thinking. Between one valley and the next there's always a wolf rider to dodge, a hawker to refuse, a grunt with an opinion.",
		"I can't brood in Orgrimmar even when I want to. Something on four legs or two always needs dodging, and the wolves don't wait.",
	},
	["org.quest_complete.w18.trudge.023"] = {
		"is paid and, in almost the same motion, pointed toward some other corner of the city; the reward and the direction arrive together.",
		"receives the reward in one hand while a thick finger is already waving toward the far end of Orgrimmar.",
	},
	["org.quest_complete.w18.trudge.024"] = {
		"I don't ask where the next job is anymore. I assume: the farthest spot, the steepest street, the loudest corner.",
		"Where will the next one be? I can tell you without asking. As far from here as the walls allow.",
		"The next errand, wherever it is, will be on the other side of something. It always is, in Orgrimmar.",
	},
	["org.quest_complete.w18.trudge.025"] = {
		"looks down at boots red to the ankle with the city's dust, and knocks them together once, without much hope.",
		"taps the red dust off one boot against a post, then the other, though twenty paces will undo it all.",
	},
	["org.quest_complete.w18.trudge.026"] = {
		"rubs the small of {g:his|her} back once the matter is closed and mutters something unkind about canyons.",
		"presses a fist into an aching back and says a few low words about whoever decided to build a city on a slope.",
		"stretches until something in {g:his|her} back gives a loud click, and looks briefly satisfied with it.",
	},
	["org.quest_complete.w18.trudge.027"] = {
		"shifts weight from one leg to the other while the thanks run on, with the patient sway of someone who has learned the city's queues.",
		"stands through the reckoning with a slight lean, favoring whichever leg complained less on the way.",
	},
	["org.quest_complete.w18.trudge.028"] = {
		"steps aside for a runner pelting up the street, plainly being sent from one end of the city to the other as well, and the two exchange a look of fellow sufferers.",
		"trades a weary glance with a peon trudging past under a load: two of a kind, in a city that always needs something carried.",
	},
	["org.quest_complete.w18.trudge.029"] = {
		"limps away from the business with great dignity, then forgets to limp somewhere around the next stall.",
		"makes a fine show of a sore leg for the first few paces, and is walking normally by the time the street bends.",
	},
	["org.quest_complete.w18.trudge.030"] = {
		"Nobody ever says how much of this work is just standing in a doorway, waiting for someone to look up.",
		"Half of every errand is walking. The other half is waiting to be noticed. The pay covers neither.",
	},
	["org.quest_complete.w18.turn.001"] = {
		"pivots on one heel and is three steps into the street before the thanks have quite finished.",
		"is already turning away with the last word of thanks still hanging, and nobody seems to mind the haste.",
		"spins round with the business barely closed, as if the street had called a name.",
	},
	["org.quest_complete.w18.turn.002"] = {
		"There's a moment, turning away, when the task is behind me and the city isn't in front of me yet. I like to stretch it out.",
		"Between turning from the work and stepping into the street there's a gap the width of a doorway. I stand in it as long as I can.",
		"On the threshold between the work and the street I stop a moment, belonging to neither.",
	},
	["org.quest_complete.w18.turn.003"] = {
		"That's me, then. Off I go.",
		"I'll leave you to it. Plenty to do on both sides.",
		"Good. I'll get out from under your feet.",
	},
	["org.quest_complete.w18.turn.004"] = {
		"I turn away and the city hands me a dozen small choices at once: left or right, eat or sleep, spend or save. Spend, the city suggests.",
		"The moment I turn round, Orgrimmar starts making offers. Food to the left, a bed ahead, a bargain everywhere.",
		"Turn your back on one job here and three hawkers fight over what's left of your attention.",
	},
	["org.quest_complete.w18.turn.005"] = {
		"turns from the business back toward the city, which has been finishing and beginning things in this canyon since its first walls went up.",
		"looks back to the streets, where nothing has waited and nothing has needed to.",
	},
	["org.quest_complete.w18.turn.006"] = {
		"I turn too fast and walk straight into a tauren. He doesn't move. I do.",
		"Note for later: before turning round in this city, check for horns.",
		"Spun round, met a chest made of solid tauren, bounced. He apologized. I'm still not sure to whom.",
	},
	["org.quest_complete.w18.turn.007"] = {
		"Go well. The Horde will have other work for me, I don't doubt.",
		"Until the next one. The Horde never runs short of work.",
		"Done for the Horde, and gladly. Send for me when it needs more.",
	},
	["org.quest_complete.w18.turn.008"] = {
		"looks back once over the shoulder, as people do, then gives the street {g:his|her} full attention.",
		"pauses mid-turn for a single glance at where the work ended, then lets it go.",
		"glances back exactly once, the way one checks a door already known to be shut.",
	},
	["org.quest_complete.w18.turn.009"] = {
		"Walking away is the part nobody teaches. You finish, you're thanked, and then you simply have to turn and become someone without a task.",
		"The hardest step is the first one away. After that, the city does the walking for you.",
	},
	["org.quest_complete.w18.turn.010"] = {
		"Good. Now, which way did I come in?",
		"Lovely. Which way's out?",
		"Fine. Somebody point me at the street, I've lost track of it.",
	},
	["org.quest_complete.w18.turn.011"] = {
		"Out of habit I turn toward the canyon wall to take my bearings. The rock never moves, which is more than I can say for anything else here.",
		"Whenever I lose my direction in this city, I find the canyon wall and start from that. It has never once steered me wrong.",
	},
	["org.quest_complete.w18.turn.012"] = {
		"swings away and, for a few steps, walks with the loose, easy gait of someone between errands.",
		"wheels round into the street with a looser step than before, shoulders no longer set for work.",
	},
	["org.quest_complete.w18.turn.013"] = {
		"Turning my back on a finished task always takes a little importance off me and gives me a little air. I've never decided which matters more.",
		"Turn away, and I belong to nobody's errand. A small loss and a small freedom, and together they come out to something like peace.",
	},
	["org.quest_complete.w18.turn.014"] = {
		"Handed over. About face. Footloose.",
		"That's the end of that. The rest of the city can have me now.",
	},
	["org.quest_complete.w18.turn.015"] = {
		"half turns away, half turns back as if to ask something, then waves it off with one hand and keeps walking.",
		"starts to leave, stops, lifts a finger, lowers it, and leaves for good this time.",
	},
	["org.quest_complete.w18.turn.016"] = {
		"As soon as I turn my back on a job, the next worry steps up to stand in its place. This time it's my boots.",
		"Turn from one worry, face the next. At the moment it's whether that smell of stew is coming from the left or the right.",
	},
	["org.quest_complete.w18.turn.017"] = {
		"turns from the finished task and squares {g:his|her} shoulders at the city, which squares its iron shoulders back.",
		"faces the street with a straighter back than before, the banners and spikes all around standing as if at attention.",
	},
	["org.quest_complete.w18.turn.018"] = {
		"Some people take a last look back after a job. I take a last look at the exits. Old habit.",
		"Before I turn away, I always count the ways out. Nobody in this city has ever given me reason to. I count them anyway.",
	},
	["org.quest_complete.w18.turn.019"] = {
		"Look after yourself. And this city, while you're at it.",
		"Keep well. I'll be somewhere loud if you need me.",
		"Take care of things here. I'll be close, if not quiet.",
	},
	["org.quest_complete.w18.turn.020"] = {
		"Finished early enough that the cookfires are only just catching. I'll turn round and be first in line for whatever goes on them.",
		"The first hammers are only now waking the canyon. A good hour to turn from a finished job: nothing open yet, and nothing owed.",
	},
	["org.quest_complete.w18.turn.021"] = {
		"turns away from the business straight into a gust of sand, and turns right back round to finish the turning later.",
		"swings toward the street, meets a wall of blowing grit, and backs straight into the shelter of the doorway with eyes screwed shut.",
	},
	["org.quest_complete.w18.turn.022"] = {
		"Back toward the streets, then, thinking of the ones who raised them out of bare rock. A small job done well is the least I can lay at their feet.",
		"Somebody cut these ramps into the canyon with tired hands and no promises. Turning from a finished task, I walk them a little more carefully.",
	},
	["org.quest_complete.w18.turn.023"] = {
		"Don't watch me leave. It's not that kind of farewell.",
		"No need to see me out. I know the way. Roughly.",
		"I'll see myself out. Into the crowd, that is. The crowd sees nobody.",
	},
	["org.quest_complete.w18.war.001"] = {
		"While I stand here being paid, somebody in Ashenvale is standing among the trees with an axe in hand and an eye on the shadows. The quiet in this city has a price, and it's paid out there.",
		"Every coin in Orgrimmar has a little of Ashenvale's sap on it, the grunts say. The timber that holds this place up is bought dear.",
	},
	["org.quest_complete.w18.war.002"] = {
		"Done here. Now point me at whatever's troubling the Horde out past the gate.",
		"That's this one handled. The Horde has bigger fights waiting, and I'd like to be at one.",
		"Errand's finished. If the Horde has a harder job somewhere beyond the walls, I'm listening.",
	},
	["org.quest_complete.w18.war.003"] = {
		"turns from the finished business as a file of grunts tramps past toward the gate, packs on their backs, and watches until the last of them is gone.",
		"falls quiet as a column of armored grunts marches by toward the road out, and stays that way until the sound of boots has faded.",
		"stands aside for a squad heading out in full harness, and follows them with a long look that has nothing to do with the reward.",
	},
	["org.quest_complete.w18.war.004"] = {
		"The talk in the street is of the Barrens: centaur raids, a caravan that never reached the Crossroads. My work feels small next to that. Maybe small is what holds the rest together.",
		"Somebody behind me is passing on news from the Crossroads, in the flat voice people keep for bad news. I pocket my pay and listen, and don't like what I hear.",
	},
	["org.quest_complete.w18.war.005"] = {
		"Good. Somewhere out past the gate, somebody's holding a line. I hope this helps them, even a little.",
		"If any of this finds its way to the ones doing the fighting, it was worth more than the pay.",
		"May this reach the ones who need it most, wherever the fighting is.",
	},
	["org.quest_complete.w18.war.006"] = {
		"Kul Tiran sails still show off the coast of Durotar, the guards say. A city that knows it's being watched does its small work faster and checks its locks twice.",
		"There's a keep full of Kul Tiran soldiers down the Durotar coast, close enough that the grunts at the gate talk of it in lowered voices. Inside the walls the errands go on anyway. That's the answer, I suppose.",
	},
	["org.quest_complete.w18.war.007"] = {
		"gives way to a grunt with an arm bound in a sling and a fresh scar, and the grunt nods back like someone who has just come from somewhere worse.",
		"meets the eyes of a bandaged warrior limping toward the inn, and for a moment the finished business seems a very small thing.",
		"makes room on the street for a stretcher carried at a run, and the reward stays forgotten in one hand until it has passed.",
	},
	["org.quest_complete.w18.war.008"] = {
		"The bards will say the war was won with axes. The quartermasters know it was won with boots, bread, rope and somebody running errands. I'm in the second story.",
		"Axes win battles. Errands win wars, as any quartermaster will tell you at length. Right now I feel like a quartermaster's favorite.",
	},
	["org.quest_complete.w18.war.009"] = {
		"That's my part done. I hope the ones at the front are faring better than the last reports.",
		"Done. Now, what's the word from Ashenvale? Anyone?",
		"Finished here. Any news from the Barrens while I was busy?",
	},
	["org.quest_complete.w18.war.010"] = {
		"Odds are the Horde lost someone in Ashenvale while I was busy with this. That's how it always goes: the work here carries on over the top of the grief out there.",
		"The Horde counts its fallen far from these walls, and none of them were thanked at a counter like this one. I keep that in mind when I take the coin.",
	},
	["org.quest_complete.w18.war.011"] = {
		"steps back from the finished business as a cart stacked with spear shafts and rolled bandages rattles past, bound for the gate.",
		"watches a pair of goblins argue over a crate marked for a garrison in the Barrens while the reward is counted out.",
		"makes way for a line of porters bent under crates of salted meat and lamp oil, all of it headed for the road out.",
	},
	["org.quest_complete.w18.war.012"] = {
		"Everyone in this city has an opinion on the war, loud and certain. My certainty stops at the job I just finished, and I'm not sure that's a bad place for it to stop.",
		"The streets argue about the war the way other places argue about the harvest. I don't know enough to argue. I know this job is done.",
	},
	["org.quest_complete.w18.war.013"] = {
		"Whatever's coming over those hills, the city's a little readier for it now.",
		"Done. Let the war find this place prepared.",
		"One more thing in order. If trouble comes knocking, it'll find fewer loose ends.",
	},
	["org.quest_complete.w18.war.014"] = {
		"My people were made into a weapon once, by a demon's bargain. Now we fight only when we must, and the rest of the time we do this: small work, in our own city.",
		"The orcs know war too well; it was poured into our blood. Every quiet errand in Orgrimmar is a vote for the other thing we can be.",
	},
	["org.quest_complete.w18.war.015"] = {
		"pauses with the reward half stowed while someone nearby reads a dispatch aloud to a knot of grunts, and the street around goes noticeably quieter.",
		"catches a few words of news passed from one grunt to another, names of places in the Barrens and a number, and goes still for a moment.",
	},
	["org.quest_complete.w18.war.016"] = {
		"The war isn't only out past the gate. Under the Cleft of Shadow the Burning Blade hides in Ragefire Chasm, and the city does its chores right on top of them. Every finished job up here is a quiet insult to them.",
		"Cultists in the deeps under the city, enemies on every road beyond it. Orgrimmar goes on working between the two, and so do I.",
	},
	["org.quest_complete.w18.war.017"] = {
		"Done. The war may now continue.",
		"You can tell Ashenvale it's safe to carry on. My part's finished.",
		"There. Somebody tell the generals they can stop waiting on me.",
	},
	["org.quest_complete.w18.war.018"] = {
		"The grunt beside me has the look of someone who buried a friend not long ago. I keep my satisfaction quiet. It's only an errand, and it's only coin.",
		"Not everyone in this street is having an easy time of it. Half the faces carry somebody they lost to the war. A finished job is no reason to be loud.",
	},
	["org.quest_complete.w18.war.019"] = {
		"turns toward the Valley of Wisdom, where the Warchief keeps his hall, and offers a short, solemn salute before moving off.",
		"faces the way of Grommash Hold for a moment once the reward is stowed, and raises a fist to it, as grunts do before marching out.",
	},
	["org.quest_complete.w18.war.020"] = {
		"Across the sea the Scourge fills the old kingdom of Lordaeron, and the reports that reach this city are grim. And here I am, finishing an errand and glad of it. That's allowed.",
		"The dead march in Lordaeron and the fighting in Ashenvale never quite stops, and in Orgrimmar a small job gets done and paid. That isn't foolishness. It's what keeps a city from breaking.",
	},
	["org.quest_complete.w18.war.021"] = {
		"Somebody send word to the front: the rear's holding up fine.",
		"Back here, all's in order. Somebody let the fighters know.",
		"Rear guard reporting: the errands are under control.",
	},
	["org.quest_complete.w18.war.022"] = {
		"Wars are lost in the cities behind them before they're lost in the field: the bread stops, the boots stop, the word stops. Not here. Not while jobs like this keep getting done.",
		"A front line is only as good as the city at its back. Every small job finished in Orgrimmar is a stone in that back.",
	},
	["org.quest_complete.w18.war.023"] = {
		"closes the business as thunder rolls over the canyon, and turns toward the gate for a moment, as if listening for something farther off than the storm.",
		"pockets the reward as lightning stalks along the canyon rim, and watches it with the narrowed eyes of someone measuring the distance to a fight.",
	},
	["org.quest_complete.w18.war.024"] = {
		"Not every front has a wall in front of it. This one was mine, and it held.",
		"Some fight at the front. Some keep the front fed. I don't mind which, so long as it gets done.",
		"This was my piece of the fighting. Smaller than most, but it's done.",
	},
	["org.quest_complete.w18.war.025"] = {
		"If the war turns bad, nobody will remember who finished which errand in Orgrimmar. I'd still rather have finished it.",
		"Errands don't decide wars. But a city where nobody finishes them has already lost one, quietly.",
	},
	["org.quest_complete.w18.war.026"] = {
		"takes the reward amid low talk of the Barrens from a corner of the room, and carries a few words of it out the door.",
		"settles the account while two grunts by the wall murmur over a map, and glances once at the map on the way out.",
	},
	["org.quest_complete.w18.worth.001"] = {
		"People think a capital is its walls and its throne. Mostly it's chores: somebody fixing, carrying, fetching, sorting. Just now, somebody was me.",
		"A city this size doesn't run on the Warchief's speeches. It runs on errands, and errands run on people like me.",
		"Strip away the banners and Orgrimmar is a long list of small needs. I just crossed one off it.",
	},
	["org.quest_complete.w18.worth.002"] = {
		"Small work. Something in this city holds a little better because of it. That'll do.",
		"Not glorious. Necessary. I'll take necessary.",
		"Nobody will notice this got done. That's how you know it was needed.",
	},
	["org.quest_complete.w18.worth.003"] = {
		"looks out over the busy street after the turn-in, at the stalls, the carts, the shouting, with the air of someone checking that a fitted part is still in place.",
		"turns from the finished business to watch the city at work, and gives the whole clattering machine a small approving nod.",
		"takes in the press of carts and porters for a moment, as a smith might look over a chain to see that every link is closed.",
	},
	["org.quest_complete.w18.worth.004"] = {
		"I'm allowed to be proud of that. A little. As far as the next corner, and then it's back to being anyone.",
		"A small, private pride, the size of a coin. I'll keep it in the same pocket.",
		"Pride, a pinch of it, no more. Enough to walk a bit taller to the end of the street.",
	},
	["org.quest_complete.w18.worth.005"] = {
		"There, the city holds. I'd like some credit for one brick, at least.",
		"Don't mention it. Actually, do mention it. To someone important.",
		"If the walls stay up a while longer, remember who to thank. Partly.",
	},
	["org.quest_complete.w18.worth.006"] = {
		"Nobody remembers the names of the peons who stacked these walls. The walls are still here. That's how work gets remembered, if it's done right.",
		"The walls don't say who built them. They just stand. I'd settle for my work doing the same.",
	},
	["org.quest_complete.w18.worth.007"] = {
		"catches the eye of a grunt on patrol and gets back the curt nod one worker gives another.",
		"shares a look with a troll porter setting down a crate: the brief look of people who both know what work weighs.",
	},
	["org.quest_complete.w18.worth.008"] = {
		"The pay was fair for what I did. What it was worth to them is another number entirely, and nobody's going to tell me.",
		"Fair coin for the work. But a face changed when I said it was done, and that's a sum no purse holds.",
	},
	["org.quest_complete.w18.worth.009"] = {
		"Good work is good work, whether it's for a general or a cook.",
		"Big task or little, it gets the same hands. Glad that's done.",
		"Every job's the same size from the inside. This one's finished.",
	},
	["org.quest_complete.w18.worth.010"] = {
		"Somebody in this city will eat, mend, sleep or sell a little easier because of that. I won't see it. I don't need to.",
		"Down the line, a stranger will be a little better off and never know whom to thank. That's the best kind of work.",
		"None of the people this helps will ever know my face. Good. Help travels lighter without a name on it.",
	},
	["org.quest_complete.w18.worth.011"] = {
		"rests a palm on the nearest wall for a moment after the business is done, as if to feel whether the city is still holding.",
		"lays a hand flat against the rough red stone of a wall in passing, briefly, like greeting someone else who has been working.",
	},
	["org.quest_complete.w18.worth.012"] = {
		"Not long ago the Horde was a dream in a slave camp. Now it's a city that hands out work and pays fairly for it. I'm proud to be on its books.",
		"Whatever it was before, the Horde is this now: a city where work is asked for, done and paid. I'm proud of my small piece of that.",
		"A Horde that pays for honest work instead of taking it by force. Thrall built that, and I've just been part of it working.",
	},
	["org.quest_complete.w18.worth.013"] = {
		"Done right, start to finish. I'll allow myself a little pride on the way out.",
		"Clean work. I don't say that often, so I mean it.",
		"That was done properly. I'll take the nod and leave the songs to someone louder.",
	},
	["org.quest_complete.w18.worth.014"] = {
		"Sometimes I wonder if this is all I'm for: other people's small troubles, in somebody else's city. Then I remember small troubles are most of what there is.",
		"Errands for strangers. Is that a life? Most lives are made of less.",
	},
	["org.quest_complete.w18.worth.015"] = {
		"steps aside to let a train of loaded carts grind past, and watches them go with a new kind of interest, as though reckoning what each one is worth.",
		"watches a peon and a tauren heave a beam into place on a scaffold nearby, and does not look away until it is set.",
	},
	["org.quest_complete.w18.worth.016"] = {
		"Thrall will never hear about what I just did. Good. The Warchief has enough on his table without my errands.",
		"No word of this will reach Grommash Hold. It doesn't have to: the Hold rests on a great many things it never hears about.",
	},
	["org.quest_complete.w18.worth.017"] = {
		"That's one less worry for Orgrimmar. It has plenty left, but one less.",
		"One knot untied. The city's full of them, but this one's gone.",
		"Fewer troubles in the world than a moment ago. Only by one, but I'll count it.",
	},
	["org.quest_complete.w18.worth.018"] = {
		"Right now, all over Orgrimmar, others are handing in work like mine: a crate here, a message there. It's a strange company to belong to, and a good one.",
		"Hundreds of us do this, all over the city, and most will never meet. It still feels like company.",
	},
	["org.quest_complete.w18.worth.019"] = {
		"glances up at a Horde banner hanging above the street once the work is handed in, and stands a shade straighter beneath it.",
		"passes under a Horde banner on the way out and lifts two fingers to the brow toward it, unhurried.",
	},
	["org.quest_complete.w18.worth.020"] = {
		"May it serve whoever needs it. That's all I ask of it.",
		"Let it do some good. Then it was worth the trouble.",
		"Go well, little job. Do your share out there.",
	},
	["org.quest_complete.w18.worth.021"] = {
		"Nobody sings about nails. A smith on the Drag still charges for every one, because without them the doors fall off. I feel a bit like a nail.",
		"I'm a nail in this place: small, plain, and holding something up. There are worse things to be.",
	},
	["org.quest_complete.w18.worth.022"] = {
		"notices a young runner dart through the crowd clutching a sealed message, and follows the small figure with a look of quiet recognition.",
		"watches a young orc haul a bucket twice its size across the street, slopping half of it, and almost smiles.",
	},
	["org.quest_complete.w18.worth.023"] = {
		"The elders say Thrall raised Orgrimmar to show the orcs could build as well as fight. Every errand finished inside it is a little more proof.",
		"Ask a gray-haired grunt why this city exists and the answer comes plainly: to show the world that orcs could make something that lasts. Small work keeps the argument going.",
	},
	["org.quest_complete.w18.worth.024"] = {
		"It mattered to somebody. I saw it in the face. That's my real pay.",
		"You can keep half the thanks. The look on your face covered the rest.",
		"Seeing that relief was the best part of the bargain.",
	},
	["org.quest_complete.w18.worth.025"] = {
		"The torches along the canyon are lit and the city is still working, carts and hammers and voices in the dark. I've just added my small part to the night shift.",
		"Lamps in every doorway, and Orgrimmar not sleeping. Somewhere in all that glow is the little I just finished.",
	},
]==])
